def _drawing_gate_failing(run_dir: str, *keys: str) -> Optional[bool]:
    """True iff drawing_gates.json records a FAILING gate for any of the given drawing keys (e.g.
    'blender' / 'general-arrangement'). False when a verdict exists and none of the keys fail. None
    when no drawing_gates.json exists — absence is not evidence of failure, so it never corroborates."""
    dg = _drawing_gates_verdict(run_dir)
    if not isinstance(dg, dict):
        return None
    drawings = dg.get("drawings") or {}
    seen = False
    for k in keys:
        d = drawings.get(k)
        if isinstance(d, dict):
            seen = True
            # D2 (2026-07-20): a `skipped` card (out-of-scope drawing) also carries
            # pass:false, but it is NOT a failure — only a genuine FAIL corroborates.
            # New drawing-gates.json carries `status`; fall back to the old pass:false
            # meaning for legacy files that predate the status field.
            _status = d.get("status")
            if _status == "fail" or (_status is None and d.get("pass") is False):
                return True
    return False if seen else None


def _aux_tab_score(title: str, run_dir: str):
    """A deterministic quality score for a DRAWING / RENDER / META sheet that the per-tab scorecard
    (the 16 data tabs) doesn't cover — so EVERY sheet shows a quality number (Tristan 2026-06-27).
    Drawings score from parts-ledger drawing coverage (an EMPTY P&ID → 0); renders use coverage as a
    proxy + flag that object-level visual quality is an open check (no fake clean PASS); ⚠ Checks uses
    the invariant pass-rate; ⚠ Audit the ship verdict. Pure navigation tabs (Contents) return None."""
    t = (title or "").lower()
    if title == _AUDIT_SHEET_TITLE:
        # the embedded-operand register scores via its OWN content mechanism (_MECH_ONLY_TABS
        # + per-row Cell check formulas) — the 'audit' keyword branch below is the dossier
        # ship-verdict fallback and must not capture it
        return None
    cov = _ledger_coverage(run_dir)

    def _cov(key: str, label: str, advisory: str = ""):
        # NA-BY-DESIGN (2026-07-11, Grok #1): a dry electrical product legitimately has
        # ZERO process services — its P&ID renders the engineering-standard N/A sheet
        # (draw_pid marker) instead of a fake process train. Coverage of nothing is not
        # a defect; the tab PASSES with the declaration. Signal: the drawing's OWN
        # marker + the contract's sealed sub-1 m³ enclosure.
        try:
            _svg_p = os.path.join(run_dir, "drawings", f"{key}.svg")
            if os.path.exists(_svg_p) and "NA-BY-DESIGN" in open(_svg_p, encoding="utf-8", errors="replace").read():
                _st = load_json(os.path.join(run_dir, "state.json")) or {}
                _qs = {}
                for _ck in ("orchestratorContract", "engineeringContract"):
                    _q0 = (_st.get(_ck) or {}).get("quantities")
                    if isinstance(_q0, dict) and _q0:
                        _qs = _q0
                        break
                _encl = qval(_qs, "enclosure_volume_m3")
                if _encl and 0 < float(_encl) < 1.0:
                    return {"score": 10, "target": 8, "status": "PASS",
                            "issues": [f"{label} not applicable BY DESIGN — dry electrical "
                                       "product (no process services); power on the single-line, "
                                       "thermal path on the GA/render"],
                            "fix": ""}
        except OSError:
            pass
        c = cov.get(key)
        if not isinstance(c, dict):
            return None
        pct = c.get("pct")
        if not isinstance(pct, (int, float)):
            return None
        sc = max(0, min(10, round(pct / 10)))
        # HONEST CAP (Tristan 2026-07-14): part-coverage alone cannot mint a 10.
        # Colorimeter Assembly/Renders scored 10 on "7/7 coverage" while the GA
        # listed a bbox-sized ferrite bead and the hero had no harness — Goodhart.
        # Coverage proves tags are present; a genuine 10 needs more than the ledger.
        if key in ("blender", "general-arrangement") and sc >= 10:
            sc = 9
        iss = []
        if advisory:
            iss.append(advisory)
            # HONEST CAP (Tristan 2026-06-27): an ADVISORY = a dimension the engine did NOT verify
            # (here, object-level VISUAL quality — coverage being 100% says the tags are present, NOT
            # that the picture is right). An unverified dimension means the sheet is NOT verified-perfect
            # and CANNOT score 10; nor can it be a confident ≥8 PASS until something actually LOOKS at it
            # (the SIGHT vision-critic). Cap at 7 (FAIL) so an unverified render never reads as shippable.
            # Earning ≥8 requires a real visual check that clears, which removes the advisory.
            sc = min(sc, 7)
        st = "PASS" if sc >= 8 else "FAIL"
        iss.append(f"{label} part coverage {c.get('present')}/{c.get('expected')} ({pct:.0f}%)"
                   + ("" if pct >= 80 else " — under-covered: the drawing must render its parts so their tags match the BoM"))
        # DECISION (2026-07-09, P&ID/BFD=7 over 100% coverage): only park the
        # UNVERIFIED-visual fix text when an advisory is actually present. Parking
        # it on every coverage-only tab made `_apply_universal_honest_cap` scan the
        # fix blob and hard-cap P&ID/BFD at 7 even with perfect tag coverage and
        # zero visual findings — a false FAIL. Coverage-only tabs score from
        # coverage; renders that pass an explicit advisory still get the cap.
        if advisory:
            fix = ("object-level visual quality is UNVERIFIED — run the vision critic "
                   "on the render so a 5-second human-glance defect is caught before "
                   "ship (then this advisory clears); also keep coverage ≥ 80%")
        elif pct < 80:
            fix = "raise drawing part coverage above 80% so tags match the BoM"
        else:
            fix = ""
        return {"score": sc, "target": 8, "status": st, "issues": iss, "fix": fix}

    if t == "drawings" or "drawing register" in t:
        # DRAWING REGISTER (reviewers 2026-07-02) — deterministic integrity check of the
        # register itself: every A1 sheet PDF it lists must EXIST on disk at build time,
        # and every print set must meet the 2.5 mm ISO 3098 lettering bar. A registered
        # file missing from disk is a broken deliverable → FAIL, honestly flagged.
        regs = _drawing_register_rows(run_dir or "")
        if not regs:
            return None
        listed = [f for rr in regs for f in rr["files"]]
        missing = [f for rr in regs for f in rr["missing"]]
        with_a1 = [rr for rr in regs if rr["files"]]
        if not with_a1:
            return {"score": 2, "target": 8, "status": "FAIL",
                    "issues": ["no print-ready A1 PDF set exists for ANY drawing — the register has nothing to point at"],
                    "fix": "run the drawing generators (a1_print.export_a1 in draw_pid / draw_bfd / draw_single_line / draw_ga)"}
        if missing:
            sc = min(6, max(0, round(10 * (len(listed) - len(missing)) / max(1, len(listed)))))
            return {"score": sc, "target": 8, "status": "FAIL",
                    "issues": [f"{len(missing)} of {len(listed)} registered A1 sheet PDF(s) MISSING on disk: "
                               + ", ".join(missing[:4])],
                    "fix": "re-run the drawing generators so every registered sheet PDF exists next to its SVG"}
        below = [rr["no"] for rr in with_a1 if rr.get("meets_bar") is False]
        if below:
            return {"score": 7, "target": 8, "status": "FAIL",
                    "issues": ["print legibility below the 2.5 mm ISO 3098 bar on: " + ", ".join(below)],
                    "fix": "a1_print pagination must split those drawings onto more A1 sheets"}
        no_a1 = [rr["no"] for rr in regs if not rr["files"]]
        iss = [f"{len(with_a1)} drawing(s) registered with {len(listed)} print-ready A1 sheet PDF(s), "
               f"all present on disk, lettering ≥2.5 mm"]
        # HONEST CAP (Tristan 2026-07-14 adversarial): register integrity ≠ drawing
        # quality. File presence alone cannot mint ≥8 (colorimeter Goodhart ship).
        # Two content bars can lift to 9 (never 10 from presence alone):
        #   (a) handheld: Assembly glance + Interconnect story both pass
        #   (b) plant / product-scale: drawing_gates all_pass + GA coverage ≥80%
        #      (wall ESS has no Assembly/Interconnect tabs — Powerwall 2026-07-15)
        sc = 6
        if no_a1:
            sc = 5
            iss.append("no A1 print set yet for: " + ", ".join(no_a1) + " (PNG/SVG master only)")
        # GOTCHA: Drawings may score BEFORE Assembly/Interconnect fill _TAB_SCORES.
        # Re-evaluate content bars here so order cannot silently keep the register at 6.
        _gl_ok = bool(_assembly_glance_verdict(run_dir or "").get("ok"))
        _lay = _interconnect_layout_verdict(run_dir or "")
        _kinds = set(_lay.get("edge_kinds") or [])
        # GOTCHA: `synth_ratio or 1.0` treats a perfect 0.0 as missing → always FAIL.
        _nets = _lay.get("nets_labeled_ratio")
        _synth = _lay.get("synth_ratio")
        _nets_f = float(_nets) if isinstance(_nets, (int, float)) else 0.0
        _synth_f = float(_synth) if isinstance(_synth, (int, float)) else 1.0
        _ic_ok = (
            bool(_lay.get("ok"))
            and "power" in _kinds
            and _lay.get("optical_path_ok") is not False
            and _nets_f >= 0.5
            and _synth_f <= 0.45
        )
        _plant = _plant_drawings_content_ok(run_dir or "")
        if _gl_ok and _ic_ok and sc >= 6:
            sc = 9
            iss.append("register intact + Assembly glance + Interconnect story earned — "
                       "capped 9 (handheld content bars met; register alone never mints 10)")
            _fix = ("raise Assembly/Interconnect content further for a 10 — "
                     "register alone never mints 10")
        elif _plant.get("ok") and sc >= 6:
            sc = 9
            iss.append(
                "register intact + plant/product-scale content earned "
                f"({_plant.get('detail')}) — capped 9 (drawing_gates + GA coverage; "
                "register alone never mints 10)"
            )
            _fix = ("raise drawing_gates / GA coverage further for a 10 — "
                     "register alone never mints 10")
        else:
            iss.append(
                "register integrity only — capped 6; need Assembly+Interconnect "
                "(handheld) OR drawing_gates all_pass + GA coverage ≥80% (plant/"
                "product-scale). A1 PDF presence ≠ engineer-relyable drawings"
            )
            _fix = ("raise Assembly/Interconnect (handheld) or drawing_gates + GA "
                     "coverage (plant/product-scale) — register cannot mint ≥8 alone")
        return {"score": sc, "target": 8, "status": "PASS" if sc >= 8 else "FAIL",
                "issues": iss, "fix": _fix}
    if "p&id" in t or t == "pid":
        return _cov("pid", "P&ID")
    if "block flow" in t or "bfd" in t:
        return _cov("block-flow-diagram", "Block-flow")
    def _cap_litter(base):
        """A render / GA drawing reflects the parts-manifest geometry, so default-size LITTER and a
        MANIFEST DIVERGENCE (GA reads one manifest, the render another → different layouts) both cap its
        score — it cannot be a genuine ≥8 while most objects are default boxes OR the two top-views can
        legitimately disagree (SIGHT)."""
        if not isinstance(base, dict):
            return base

        def _cur(b):  # current score, treating a legit 0 as 0 (NOT `or 10` — that masks a real 0)
            s = b.get("score")
            return s if isinstance(s, (int, float)) else 10

        # LITTER first, then DIVERGENCE — so the more-fundamental divergence issue leads the banner.
        lit = _manifest_litter(run_dir)
        if isinstance(lit, dict) and isinstance(lit.get("score"), (int, float)) and lit["score"] < _cur(base):
            w = lit.get("worst") or {}
            base["score"] = lit["score"]
            base["status"] = "PASS" if lit["score"] >= 8 else "FAIL"
            base["issues"] = ([f"default-size LITTER: {lit['litter_parts']}/{lit['parts']} parts "
                               f"({int(lit['litter_ratio']*100)}%) share a default box — worst: "
                               f"{w.get('n_distinct','?')} distinct parts @ {w.get('dims','?')} "
                               f"(e.g. {', '.join((w.get('examples') or [])[:3])}); the geometry "
                               f"generator must derive real per-part dims"] + (base.get("issues") or []))[:6]
            base["fix"] = "geometry generator must size each part from its real dims, not a shared default box"
        div = _manifest_div(run_dir)
        if isinstance(div, dict) and div.get("diverged"):
            base["score"] = 0
            base["status"] = "FAIL"
            base["issues"] = ([f"LAYOUT DIVERGENCE: {div.get('detail', '')}"] + (base.get("issues") or []))[:6]
            base["fix"] = div.get("fix", base.get("fix", ""))
        # WRONG-SHAPE (council typed-shape gate 2026-06-27): a render/GA with an electrical part drawn
        # as a process VESSEL (a power feed as a 2.7 m horizontal cylinder = the stray red beam) cannot
        # be a clean pass. Read the DELIVERED manifest, FAIL on any mismatch. Deterministic; the
        # source fix (classify_shape) prevents it, this enforces it on the rendered artefact.
        stm = _manifest_shape_mismatch(run_dir)
        if isinstance(stm, dict) and stm.get("count"):
            ex = ", ".join(f"{p['name']}→{p['shape']}" for p in stm.get("parts", [])[:3])
            base["score"] = min(_cur(base), 4)
            base["status"] = "FAIL"
            base["issues"] = ([f"WRONG SHAPE: {stm['count']} electrical part(s) rendered as a process "
                               f"vessel (the stray-beam defect): {ex}"] + (base.get("issues") or []))[:6]
            base["fix"] = "classify_shape must map an electrical/power-connection part to a cabinet/box, not a vessel"
        # ABSURD MICRO-COMPONENT DIMS (ferrite bead = product bbox): GA/Render cannot
        # be a genuine ≥8 while a discrete electronic is stamped at envelope scale.
        try:
            sys.path.insert(0, os.path.join(os.path.dirname(__file__), "lib"))
            import manifest_sight as _ms_abs
            with open(os.path.join(run_dir, "parts-manifest.json"), "r", encoding="utf-8") as _fh:
                _abs = _ms_abs.absurd_micro_component_dims(json.load(_fh))
        except Exception:  # noqa: BLE001
            _abs = None
        if isinstance(_abs, dict) and _abs.get("count"):
            ex = ", ".join(
                f"{p['name']}@{int(p.get('max_axis_mm') or 0)}mm"
                for p in (_abs.get("parts") or [])[:3]
            )
            base["score"] = min(_cur(base), 3)
            base["status"] = "FAIL"
            base["issues"] = ([f"ABSURD MICRO-COMPONENT DIMS: {ex} — a bead/fuse "
                               f"cannot outsize the product; resolved_dims_mm must clamp"]
                              + (base.get("issues") or []))[:6]
            base["fix"] = "resolved_dims_mm micro-component clamp + re-export parts-manifest"
        return base

    if t == "assembly":
        # Handheld pack renames GA → Assembly (2026-07-14); same coverage key.
        base = _cap_litter(_cov("general-arrangement", "Assembly"))
        if not isinstance(base, dict):
            return base
        _gl = _assembly_glance_verdict(run_dir or "")
        _sc = base.get("score")
        _sc = _sc if isinstance(_sc, (int, float)) else 0
        if not _gl.get("ok"):
            base["score"] = min(_sc, 4)
            base["status"] = "FAIL"
            base["issues"] = ([
                f"ASSEMBLY GLANCE FAIL: {_gl.get('detail')}"
            ] + list(base.get("issues") or []))[:6]
            base["fix"] = (
                "draw_ga.py — cover-removed stack-up must show PCB plane + "
                "≥3 equipment tags (ga_glance_audit proveCatch)"
            )
            return base
        # HONEST CAP (2026-07-14 Tristan adversarial): glance+coverage ≠ a
        # shippable Assembly. Max 6 until a vision critic clears the sheet —
        # the prior cap-8 still Goodharted tag ladders + "36 items" titles.
        # FLOW: drawing_vision_glance.py → drawings/drawing-vision-critique.json
        # → when broken=false + ≥1 image, lift to coverage (still ≤9; 10 needs
        # pin-level manufacturing pack, not a clean glance alone).
        _dv = None
        try:
            with open(os.path.join(run_dir or "", "drawings",
                                   "drawing-vision-critique.json"),
                      encoding="utf-8") as _dvf:
                _dv = json.load(_dvf)
        except Exception:  # noqa: BLE001
            _dv = None
        _vision_clean = (
            isinstance(_dv, dict)
            and _dv.get("ok") is True
            and _dv.get("broken") is False
            and int(len(_dv.get("images") or [])) >= 1
            and not (_dv.get("skipped"))
        )
        _iss = list(base.get("issues") or [])
        if _vision_clean:
            base["score"] = min(_sc, 9)
            _iss.insert(0, "glance ok · drawing vision clean "
                        f"({len(_dv.get('images') or [])} image(s)) — "
                        "capped 9 (Assembly sheet earned, not fab pack)")
        else:
            base["score"] = min(_sc, 6)
            _iss.insert(0, "glance ok · capped 6 (no vision pass — Assembly cannot mint ≥8 "
                           "from coverage+markers alone)")
        base["status"] = "PASS" if base["score"] >= 8 else "FAIL"
        base["issues"] = _iss[:6]
        return base
    if "general arrangement" in t or t.startswith("ga "):
        return _cap_litter(_cov("general-arrangement", "GA"))
    if t == "interconnect":
        _lay = _interconnect_layout_verdict(run_dir or "")
        try:
            _led = load_json(os.path.join(run_dir or "", "parts-ledger.json")) or {}
            _cx = _led.get("connectivity") or {}
        except Exception:  # noqa: BLE001
            _cx = {}
        _n_c = int(_cx.get("n_concerns") or 0)
        # Layout is the hard bar (Tristan 2026-07-14) — connectivity alone must never
        # mint a 10 over an unreadable bird's nest.
        if not _lay.get("ok"):
            _reasons = _lay.get("story_reasons") or []
            _why = (
                "; ".join(str(r) for r in _reasons[:3])
                if _reasons else
                ("thin story" if _lay.get("story_ok") is False else "layout caps / title overlap")
            )
            return {
                "score": 2, "target": 8, "status": "FAIL",
                "issues": [
                    f"INTERCONNECT NOT EARNED ({_why}): nodes={_lay.get('n_nodes')} "
                    f"edges={_lay.get('n_edges')} kinds={_lay.get('edge_kinds')} "
                    f"shell_degree={_lay.get('shell_degree')} "
                    f"synth_ratio={_lay.get('synth_ratio')} "
                    f"optical_path_ok={_lay.get('optical_path_ok')} "
                    f"nets_labeled={_lay.get('nets_labeled_ratio')} "
                    f"title_overlaps={_lay.get('title_overlaps_content')}"
                ],
                "fix": "draw_interconnect.py — optical path LED→detector, named nets, "
                       "real Enclosure Shell edges (layout_metrics proveCatch)",
            }
        # HONEST CAP: layout+story ok is necessary, never a 10 from metrics alone.
        # Require a real Power story when the layout advertises compute-kit columns.
        _kinds = set(_lay.get("edge_kinds") or [])
        _has_power = "power" in _kinds
        _synth = float(_lay.get("synth_ratio") or 0.0)
        if not _has_power:
            return {
                "score": 5, "target": 8, "status": "FAIL",
                "issues": [
                    f"INTERCONNECT MISSING POWER STORY: kinds={_lay.get('edge_kinds')} "
                    f"· nodes={_lay.get('n_nodes')} — USB/LiPo → compute → source must "
                    f"appear as orange power edges (not legend-only)"
                ],
                "fix": "draw_interconnect._collect_graph gold-spine power path",
            }
        if _lay.get("optical_path_ok") is False:
            return {
                "score": 4, "target": 8, "status": "FAIL",
                "issues": [
                    "INTERCONNECT OPTICAL PATH BACKWARDS — LED must precede detector "
                    "on the free-space chain (not alphabetical Optical column)"
                ],
                "fix": "draw_interconnect._rewrite_optical_path",
            }
        _nets = float(_lay.get("nets_labeled_ratio") or 0.0)
        if _nets < 0.5:
            return {
                "score": 5, "target": 8, "status": "FAIL",
                "issues": [
                    f"INTERCONNECT MISSING NET LABELS: nets_labeled_ratio={_nets} "
                    f"— a wiring sheet must name VBUS/I2C/OPT nets, not silent blocks"
                ],
                "fix": "draw_interconnect._stamp_edge_nets",
            }
        if _synth > 0.45:
            return {
                "score": 6, "target": 8, "status": "FAIL",
                "issues": [
                    f"INTERCONNECT OVER-SYNTHESISED: synth_ratio={_synth} "
                    f"(non-mount synthesised edges dominate the story)"
                ],
                "fix": "prefer topology-authored power/signal edges over fiction",
            }
        # INTENT (2026-07-14, refined): for instruments the Interconnect sheet IS the
        # optical+power block diagram with named nets — pin-level netlist lives on PCB.
        # Earned layout (optical path + nets + power + low synth) → 9; never 10 from
        # a block diagram alone. Connectivity concerns still demote.
        # TRIED: hard-cap 6 forever → permanently floored every instrument dossier
        # below ship even when the sheet told a complete instrument story.
        sc = 9 if _n_c == 0 else 7
        return {
            "score": sc, "target": 8,
            "status": "PASS" if sc >= 8 else "FAIL",
            "issues": [
                f"layout+story ok · {_lay.get('n_nodes')} principals · "
                f"{_lay.get('n_edges')} edges · kinds={_lay.get('edge_kinds')} · "
                f"shell_degree={_lay.get('shell_degree')} · "
                f"synth_ratio={_lay.get('synth_ratio')} · "
                f"nets_labeled={_lay.get('nets_labeled_ratio')} · "
                f"connectivity concerns={_n_c} · "
                + ("capped 9 (instrument interconnect earned; pin-level on PCB tab)"
                   if _n_c == 0 else
                   "demoted — clear parts_ledger connectivity concerns")
            ],
            "fix": "" if _n_c == 0 else
                   "clear parts_ledger connectivity concerns",
        }
    if "single-line" in t or "single line" in t:
        return _cov("single-line-diagram", "Single-line")
    if "isometric" in t:
        return _cov("isometric-index", "Isometric")
    if "render" in t or "interior layout" in t or "building exterior" in t:
        # VISION VERDICT — CORROBORATION DOCTRINE (Tristan 2026-06-28, hardened 2026-07-03; same
        # shape as the physics critic 247494a32 and benchmark-net gate 36 284c69c09). The vision CALL
        # is non-deterministic on two axes: EEVEE TAA sampling noise changes the rendered PNG bytes
        # run-to-run by <=8/255 on <6% of pixels even for byte-identical geometry (established
        # 906ea3f39), and the LLM itself can re-roll its verdict on visually-near-identical images —
        # observed as GA/Renders/P&ID/BFD/Overview score DRIFT across two otherwise-matched runs
        # (GA 9.7 vs 9, Renders 9.7 vs 9). The call is now CACHED upstream on the geometry-manifest
        # hash (render_vision_critic.critique_run), so identical geometry reuses ONE stored verdict —
        # but even a genuine, freshly-computed LLM finding must never move a NUMBER by itself: a
        # vision finding SCORES only when a DETERMINISTIC artefact check corroborates it (drawing_gates
        # G1-G9 / manifest litter / manifest shape-mismatch); UNCORROBORATED findings render as an
        # advisory note — visible, never scoring. clean → the visual dimension is VERIFIED, so no
        # advisory and the render earns on its deterministic checks. absent → keep the 'unverified'
        # advisory (honest-cap → 7).
        def _apply_side_elevation_gate(entry: Optional[dict]) -> Optional[dict]:
            # INTENT: Tristan 2026-07-09 — a plant with Blender views but no side elevation
            # cannot show underground tanks/pipes; never score ≥9 (client floor).
            if not isinstance(entry, dict):
                return entry
            if not _gallery_missing_side_elevation(run_dir):
                return entry
            sc = entry.get("score")
            if isinstance(sc, (int, float)) and sc >= 9:
                entry["score"] = 8.5
            entry["status"] = "PASS" if (isinstance(entry.get("score"), (int, float))
                                         and entry["score"] >= 8) else "FAIL"
            note = ("MISSING side elevation (inspect-side.png) — underground tanks/pipes "
                    "not visible from iso/plan alone (Excel gallery requires it)")
            iss = list(entry.get("issues") or [])
            if note not in iss:
                iss.insert(0, note)
            entry["issues"] = iss[:6]
            if not entry.get("fix"):
                entry["fix"] = ("re-run Blender inspect pass so inspect-side.png is written "
                                "with the ground slab hidden")
            return entry

        # DETERMINISTIC PHENOTYPE CONTAINMENT (B5 / V1a, 2026-07-20) — caps the render to 4
        # when the delivered parts SPRAWL outside the product enclosure (the Lego-in-a-box
        # hero: a floating vertical PCB + metre-scale primitives around a 160 mm device). The
        # form-signature gate checks that geometry EXISTS; this checks it is CONTAINED. Runs
        # first so a lenient form-signature (ok:True on a sprawling scene, the 2150 false-9)
        # and a lenient vision critic (broken:false on a glance-rejectable hero) can never lift
        # it. Composes with F1b (which fixes the scale at source — a fresh device fits, silent).
        _ph = _phenotype_containment_verdict(run_dir)
        if isinstance(_ph, dict) and _ph.get("ok") is False:
            base = _cap_litter(_cov("blender", "Render"))
            if isinstance(base, dict):
                base["score"] = min(base.get("score", 10) if isinstance(base.get("score"), (int, float)) else 10, 4)
                base["status"] = "FAIL"
                base["issues"] = ([f"PHENOTYPE: the rendered parts sprawl {_ph.get('ratio')}× outside "
                                   f"the product enclosure (scene {_ph.get('scene_edge_mm')} mm vs "
                                   f"~{_ph.get('enclosure_edge_mm')} mm enclosure) — a device hero must "
                                   f"pack its parts INTO the body, not float them around it (Lego-in-a-box)"]
                                  + (base.get("issues") or []))[:6]
                base["fix"] = ("build_universal_scene.py: size + place parts to FIT the enclosure "
                               "envelope (F1b device-scale proxy + AABB packing), not a sprawling scene")
            return _apply_side_elevation_gate(base)

        # V2 (2026-07-20): a DEVICE render earns ≥8 only on a POSITIVELY-verified containment.
        # `_ph` is None when the phenotype gate could not compute (an instrument device with no
        # parts-manifest scene bbox / no enclosure volume) — the body is UNVERIFIED. Ledger
        # coverage + a flaky vision-clean verdict must NOT mint ≥8 there (the 2150 lesson: the
        # vision critic returned broken=false + 8 checks on a Lego-in-a-box hero; only the
        # DETERMINISTIC containment gate caught it). Plants (phenotype N/A → None but not an
        # instrument) and verified-containment devices (_ph.ok True) are unaffected. Applied as
        # an advisory on the earning path below (→ _cov caps at 7), never overriding the lower
        # FAIL caps (shape / form-signature / named vision defect) which return above.
        _containment_unverified = False
        if _ph is None:
            try:
                _st_ph = load_json(os.path.join(run_dir, "state.json")) or {}
                _containment_unverified = bool(_st_ph.get("isInstrumentDevice"))
            except Exception:  # noqa: BLE001
                _containment_unverified = False
        _v2_adv = ("ADVISORY: containment UNVERIFIED — no parts-manifest scene bbox, so the "
                   "phenotype gate could not confirm the parts pack into the device body; "
                   "coverage + a vision-clean verdict alone cannot mint ≥8 on a device "
                   "(regenerate the render so the manifest carries a scene bbox)"
                   ) if _containment_unverified else ""

        # DETERMINISTIC PRODUCT-IDENTITY backstop (Tristan 2026-07-18) — caps the render to
        # 4 (FAIL) when the SCENE has no product-specific geometry (a generic grey-box
        # skeleton reused across classes, or cutaway-only 'story' props with no exterior
        # body). This is the SIGHT gap that let colorimeter/rodeostat/pioreactor/opendrop
        # ship at floor 9 while rendering an identical generic box + floating module. Runs
        # BEFORE the vision critic so a lenient/absent vision verdict can never lift it.
        _fs = _form_signature_verdict(run_dir)
        if isinstance(_fs, dict) and _fs.get("ok") is False:
            base = _cap_litter(_cov("blender", "Render"))
            if isinstance(base, dict):
                _fsf = _fs.get("findings") or []
                _codes = ", ".join(f.get("code", "?") for f in _fsf[:3])
                _msg0 = _fsf[0].get("message") if _fsf else "no product-specific geometry"
                base["score"] = min(base.get("score", 10) if isinstance(base.get("score"), (int, float)) else 10, 4)
                base["status"] = "FAIL"
                base["issues"] = ([f"PRODUCT IDENTITY: the scene carries no product-specific "
                                   f"geometry ({_codes}) — {_msg0}"] + (base.get("issues") or []))[:6]
                base["fix"] = (_fsf[0].get("fix") if _fsf else
                               "build_universal_scene.py: give this product its signature geometry")
            return _apply_side_elevation_gate(base)

        _vv = _render_vision_verdict(run_dir)
        _vv_defects = (_vv.get("defects") or []) if isinstance(_vv, dict) else []
        # DETERMINISTIC backstop FIRST: a real electrical-part-drawn-as-a-vessel (the stray-beam defect)
        # caps the render to 4 regardless of the vision critic — so relaxing an UNSUBSTANTIATED vision
        # verdict below can never let a genuine structural defect pass.
        _stm = _manifest_shape_mismatch(run_dir)
        if isinstance(_stm, dict) and _stm.get("count"):
            base = _cap_litter(_cov("blender", "Render"))
            if isinstance(base, dict):
                _ex = ", ".join(f"{p['name']}→{p['shape']}" for p in _stm.get("parts", [])[:3])
                base["score"] = min(base.get("score", 10) if isinstance(base.get("score"), (int, float)) else 10, 4)
                base["status"] = "FAIL"
                base["issues"] = ([f"WRONG SHAPE: {_stm['count']} electrical part(s) rendered as a process vessel (the stray-beam defect): {_ex}"] + (base.get("issues") or []))[:6]
                base["fix"] = "classify_shape must map an electrical/power-connection part to a cabinet/box, not a vessel"
            return _apply_side_elevation_gate(base)
        # VISION VERDICT: a 'broken' flag only ever ENTERS this branch when it NAMES a concrete
        # defect. An LLM 'broken=True' with EMPTY defects is unsubstantiated — a false FAIL is as
        # dishonest as a false PASS (Tristan 2026-06-30) — and falls straight to the deterministic-only
        # branch below, same as a clean verdict.
        if isinstance(_vv, dict) and _vv.get("ok") and _vv.get("broken") is True and _vv_defects:
            base = _cap_litter(_cov("blender", "Render"))
            if isinstance(base, dict):
                _df = "; ".join(str(d) for d in _vv_defects[:3])
                # CORROBORATION CHECK: does an INDEPENDENT deterministic artefact check agree
                # something is visibly wrong with this drawing? Shape-mismatch is already the
                # dedicated backstop above; here litter (default-size/degraded geometry) and a
                # failing drawing_gates G1-G9 verdict for this drawing are the corroborating SIGHT
                # mechanisms. Coverage/legibility corroboration is handled separately by _cov's own
                # advisory-cap path (applied regardless of the vision verdict, on the 'absent' branch).
                # 2026-07-10 (Tristan/Grok false-ship review): the corroboration REQUIREMENT
                # inverted the critic's purpose — it exists precisely because deterministic
                # geometry checks are BLIND to the floating-object/stray-connection class, so
                # demanding a deterministic co-signature meant a NAMED defect persisted across
                # three consecutive runs while Renders scored 9.7. The council FLAG-ONLY
                # contract is restored: a named defect ALWAYS caps (<=4); determinism is
                # supplied by the geometry-hash cache (same design -> same cached verdict,
                # no re-roll), and corroboration is quoted as colour when present.
                _lit = _manifest_litter(run_dir)
                _lit_corroborates = (isinstance(_lit, dict)
                                      and isinstance(_lit.get("score"), (int, float))
                                      and _lit["score"] < 8)
                _gate_corroborates = _drawing_gate_failing(run_dir, "blender", "general-arrangement") is True
                _corr = ("default-size litter" if _lit_corroborates
                         else "a failing drawing_gates verdict" if _gate_corroborates
                         else "none (the vision critic is the ONLY check that sees this defect class)")
                base["score"] = min(base.get("score", 10) if isinstance(base.get("score"), (int, float)) else 10, 4)
                base["status"] = "FAIL"
                base["issues"] = ([f"VISION CRITIC flagged a visible defect: {_df} — corroboration: "
                                   f"{_corr} (model: {_vv.get('model', '?')}; geometry-hash cached verdict)"]
                                  + (base.get("issues") or []))[:6]
                base["fix"] = "fix the geometry/routing that produces the flagged defect"
            return _apply_side_elevation_gate(base)
        if isinstance(_vv, dict) and _vv.get("ok") and _vv.get("broken") is True and not _vv_defects:
            # broken=True with NO named defect: unsubstantiated as a specific FAIL, but a broken
            # flag can never read as verified-clean either (run 55 shipped Renders 9.0 over
            # exactly this verdict). Honest state: visual quality UNVERIFIED -> capped at 7.
            base = _cap_litter(_cov("blender", "Render",
                advisory="vision critic returned broken=true with no named defect — visual quality is "
                         "NOT verified clean; capped pending a substantiated verdict or a human look"))
            if isinstance(base, dict) and isinstance(base.get("score"), (int, float)):
                base["score"] = min(base["score"], 7)
                base["status"] = "PASS" if base["score"] >= 8 else "FAIL"
            return _apply_side_elevation_gate(base)
        if isinstance(_vv, dict) and _vv.get("ok") and _vv.get("broken") is False:
            # VERIFIED clean → score on the DETERMINISTIC checks (coverage/litter/shape).
            # GOTCHA (2026-07-14): empty-defect "broken=False" on placeholder CAD still
            # minted Renders 9 — require named defects list OR a real checklist count.
            # V2 (2026-07-20): a device with UNVERIFIED containment (_v2_adv) caps at 7 here —
            # a vision-clean verdict cannot substitute for a deterministic containment pass.
            base = _cap_litter(_cov("blender", "Render", advisory=_v2_adv))
            _chk_n = int(_vv.get("checks_run") or _vv.get("n_checks") or 0)
            if isinstance(base, dict) and _chk_n < 3 and not _vv_defects:
                _sc0 = base.get("score")
                _sc0 = _sc0 if isinstance(_sc0, (int, float)) else 7
                base["score"] = min(_sc0, 6)
                base["status"] = "PASS" if base["score"] >= 8 else "FAIL"
                _iss0 = list(base.get("issues") or [])
                _iss0.insert(0, "vision returned broken=false with no checklist "
                               f"(checks_run={_chk_n}) — capped 6 (empty clean ≠ earned)")
                base["issues"] = _iss0[:6]
            return _apply_side_elevation_gate(base)
        return _apply_side_elevation_gate(_cap_litter(_cov("blender", "Render",
                    advisory="ADVISORY: object-level visual quality is UNVERIFIED — no vision critic has looked at this render (run render_vision_critic)")))
    if "checks" in t:  # ⚠ Checks — deterministic-invariant pass rate
        try:
            import deterministic_checks_lib as _dcl
            _chk = _dcl.run_all_checks(run_dir, None)
            _n = len(_chk)
            _nf = len([c for c in _chk if str(getattr(c, "status", "")).upper() == "FAIL"])
            if _n:
                # ANY failing invariant means this tab is NOT clean — never round a handful of
                # fails away into a green 10 (the fake-8). 0 fails → 10; else a hard FAIL.
                _sc = 10 if _nf == 0 else max(0, 8 - 2 * _nf)
                return {"score": _sc, "target": 8, "status": "PASS" if _sc >= 8 else "FAIL",
                        "issues": [f"{_nf} of {_n} deterministic invariants FAIL — this tab cannot be a clean 10 over failures"] if _nf else [f"{_n}/{_n} invariants pass"],
                        "fix": "fix each failing invariant at source"}
        except Exception:  # noqa: BLE001
            pass
        return None
    if "audit" in t:  # ⚠ Audit — the dossier ship verdict = does every scored tab reach ≥8?
        # ONE FLOOR (fix 3, reviewers 2026-07-02): this fallback score IS the weakest
        # tab score — never a derived max(2, …) number no other surface quotes. (The
        # canonical 'Quality & Audit' entry is set in build() from compute_verdict; this
        # branch only serves a direct _aux_tab_score call before that entry exists.)
        # S5 (2026-07-20): exclude VERIFIED-OUT-OF-SCOPE tabs (`scored is False`) — a tab
        # that proved its own OOS verification is neither a pass nor a fail and must not be
        # counted in the "every tab ≥8" weakest-tab computation (consistency with the
        # canonical compute_verdict path, which already excludes `scored is False`). Keyed on
        # the flag any scorer may set, never a tab name.
        _scored = [v.get("score") for v in _TAB_SCORES.values()
                   if isinstance(v.get("score"), (int, float)) and v.get("scored") is not False]
        if _scored:
            _worst = min(_scored)
            _ok = _worst >= 8
            return {"score": 8 if _ok else _worst, "target": 8, "status": "PASS" if _ok else "FAIL",
                    "issues": [] if _ok else [f"the dossier does NOT ship — the weakest tab scores {_worst}/10; every tab must reach ≥8"],
                    "fix": "resolve the failing tabs (see the per-tab punch-list / Quality & Audit findings)"}
        return None
    if "hvac" in t:
        # Deterministic HVAC check (Tristan 2026-06-27 — close the last UNSCORED tab). The score
        # depends on the design's actual HVAC SCOPE, read from the contract:
        #   • A design with a real HVAC / ventilation / cooling DUTY (an hvac/vent/cooling/heat-load
        #     quantity) must REPRESENT that equipment — score from the HVAC drawing's part coverage.
        #   • A design with NO HVAC duty (a process / fluid plant whose climate hardware is explicitly
        #     supplied by others — the Codema brief states exactly this) has nothing to mis-represent:
        #     the HVAC sheet is an honest building-ventilation / out-of-scope note → PASS (it is
        #     class-correct, not a fake clean — there IS no HVAC equipment to fail on).
        # Universal — keyed on the presence of an HVAC duty signal, no class table.
        st_path = os.path.join(run_dir or "", "state.json")
        has_hvac_duty = False
        try:
            with open(st_path, "r", encoding="utf-8") as _fh:
                _st = json.load(_fh)
            _q = ((_st.get("orchestratorContract") or {}).get("quantities")
                  or (_st.get("engineeringContract") or {}).get("quantities") or {})
            has_hvac_duty = any(
                re.search(r"hvac|ventilation_supply_air|cooling_load|chiller|space_heating|"
                          r"air_change|supply_air_m3_h|extract_air|"
                          # PROCESS DRYING AIR-HANDLING DUTY (CO2-mineralisation cross-val
                          # 2026-07-06): a material dryer moves heated air THROUGH the
                          # process ('hot air for two drying stages' — a real air-handling
                          # duty, engine-sized via tool:dryer:thermal-sizing) — the SAME
                          # climate/air-handling scope this tab exists to represent, not a
                          # building-HVAC-only signal. Missing this made the tab claim "no
                          # HVAC/ventilation/cooling contract duty" over a design carrying
                          # 49 kW + 1,469 kg/h of dryer thermal/air duty — a dishonest
                          # out-of-scope disclosure. Universal: any archetype with a
                          # dryer_*_duty_kw / dryer_*_air_flow_kg_h quantity pair counts.
                          r"dryer_.*(?:duty|air_flow)|drying_air|hot_air",
                          str(k), re.I)
                and isinstance((v or {}).get("value"), (int, float)) and (v or {}).get("value")
                for k, v in _q.items())
        except Exception:  # noqa: BLE001
            pass
        if has_hvac_duty:
            _hc = _cov("hvac", "HVAC")
            if _hc is not None:
                return _hc
            # DIRECT deterministic coverage (BESS cross-val 2026-07-03): the parts-ledger
            # computes no 'hvac' rep yet, but the drawing IS delivered — score the tab on
            # what it shows instead of a flat unscored-6. Coverage = fraction of the
            # design's HVAC/cooling-duty BoM parts named on drawings/hvac-layout.svg
            # (plural-insensitive token overlap, same spirit as parts_ledger.covered).
            # 9/10 CAMPAIGN (2026-07-04): AIR-SIDE (ducting/AHU/ventilation) and
            # COOLANT/REFRIGERATION coverage are scored SEPARATELY — a design can show
            # its coolant loop fully while silently dropping every air-side item (the
            # exact "5 missing air-side items" class of gap Tristan flagged), so the
            # combined family fraction alone hid that failure mode; only COMPLETE
            # air-side coverage (as well as coolant) can reach a genuine 9-10.
            _svgp = os.path.join(run_dir or "", "drawings", "hvac-layout.svg")
            _AIRSIDE_FAM = re.compile(
                r"air[ -]?handl|\bahu\b|air[ -]?condition|\bac unit\b|ventilat|"
                r"vent[ -]?fan|extract|supply[ -]?air|\bduct\b|damper|louvre|fan[ -]?coil|"
                # PROCESS DRYING / AIR-BLOW air-handling equipment (CO2-mineralisation
                # cross-val 2026-07-06): a material dryer's air-heater battery + exhaust
                # heat-recovery exchanger + inlet/air-blow blowers are the SAME air-
                # handling family as ducting/AHU — real equipment moving process air, not
                # building comfort air. Crediting these closes the false "no air-side
                # scope" reading (the has_hvac_duty widening above) with the actual
                # equipment carrying the duty, instead of silently vacuous-passing on
                # zero matched air-side parts.
                r"hot[ -]?air dryer|air[ -]?heater|heat[- ]?recovery exchanger|"
                r"air[- ]?blow|inlet blower",
                re.I)
            _COOLANT_FAM = re.compile(
                r"\bhvac\b|chiller|\bcool|coolant|cold[ -]?plate|condensate|radiator|"
                r"glycol|expansion tank",
                re.I)
            try:
                with open(st_path, "r", encoding="utf-8") as _fh:
                    _st2 = json.load(_fh)
                _all_bom = [r for r in (_st2.get("requirementsBom") or []) if isinstance(r, dict)]
            except Exception:  # noqa: BLE001
                _all_bom = []
            # EQUIPMENT, not routing edges (2026-07-06 fix, exposed by the has_hvac_duty
            # widening above): a process-plant requirementsBom also carries ROUTED rows
            # ('water connection: CaCO3 hot-air dryer -> CaCO3 vacuum belt filter') and
            # SUB-COMPONENT rows — pipe/cable RUNS between two pieces of equipment, drawn
            # as connecting lines, never as their own tagged equipment block. The drawing's
            # own 'equipment schedule' only ever lists principal equipment (r-103, v-113,
            # k-101, …). Counting every connection-edge SENTENCE that happens to name a
            # matched noun as its own "part" inflated the denominator with entries the
            # drawing was never going to tag individually, manufacturing false "MISSING"
            # findings once air-side matching switched on. Universal — ROUTED/SUB-COMPONENT
            # are generic status tags used across every archetype, not a CO2-specific fix.
            _NON_EQUIPMENT_STATUS = {"ROUTED", "ROUTED·REVIEW", "SUB-COMPONENT"}
            def _fam_parts(fam_rx):
                return sorted({str(r.get("requirement") or r.get("part") or "").split("·")[0].strip()
                              for r in _all_bom
                              if str(r.get("status") or "") not in _NON_EQUIPMENT_STATUS
                              and fam_rx.search(str(r.get("requirement") or r.get("part") or ""))} - {""})
            _air_parts = _fam_parts(_AIRSIDE_FAM)
            _cool_parts = _fam_parts(_COOLANT_FAM)
            _svg_texts: List[str] = []
            try:
                _svg_texts = re.findall(r">([^<>]+)<", open(_svgp).read())
            except Exception:  # noqa: BLE001
                _svg_texts = []
            _svg_txt = " ".join(_svg_texts).lower()
            _sing = lambda s: re.sub(r"s\b", "", s.lower())  # noqa: E731
            # PER-SEGMENT (not whole-blob) matching (CO2-mineralisation v2 cross-val
            # 2026-07-05): joining every drawing text node into ONE string before matching
            # let a candidate's tokens be satisfied by UNRELATED labels — 'rich-amine inlet
            # cooler' false-credited via 'inlet' from a DIFFERENT part's label ('K-102 —
            # flue-gas inlet blower') + 'cooler' from ANOTHER unrelated label ('E-108 — dryer
            # condensate cooler'); neither 'rich' nor 'amine' appears anywhere on the
            # drawing. A candidate is only "on the drawing" if its own majority of tokens
            # co-occur WITHIN A SINGLE drawing text segment (an equipment-schedule line or
            # label), never scattered across independent labels that merely share a common
            # word. Universal — no part-name table, same generic-token guard as before.
            _svg_segs_sing = [_sing(t) for t in _svg_texts]
            _generic = {"unit", "system", "main", "panel", "skid", "rack", "plant"}
            def _on_drawing(pn: str) -> bool:
                toks = [w for w in re.findall(r"[a-z]{4,}", pn.lower()) if w not in _generic]
                if not toks:
                    return False
                need = max(1, (len(toks) + 1) // 2)
                return any(sum(1 for w in toks if _sing(w) in seg) >= need
                           for seg in _svg_segs_sing)
            if (_air_parts or _cool_parts) and _svg_txt:
                _air_shown = [p for p in _air_parts if _on_drawing(p)]
                _air_missing = [p for p in _air_parts if p not in _air_shown]
                _cool_shown = [p for p in _cool_parts if _on_drawing(p)]
                _cool_missing = [p for p in _cool_parts if p not in _cool_shown]
                _comp_air = (len(_air_shown), len(_air_parts)) if _air_parts else (1, 1)
                _comp_cool = (len(_cool_shown), len(_cool_parts)) if _cool_parts else (1, 1)
                # LOAD RECONCILIATION — the design's stated ventilation/cooling contract
                # quantity vs an independent BoM-derived total (a second, separately-
                # sourced figure); vacuously satisfied while only one source exists to
                # compare (nothing to diverge FROM), never faked as a false pass.
                _q2 = ((_st2.get("orchestratorContract") or {}).get("quantities")
                      or (_st2.get("engineeringContract") or {}).get("quantities") or {})
                _load_keys = [k for k, v in _q2.items()
                             if re.search(r"cooling_load|ventilation_supply_air|"
                                         r"space_heating|heat_load", str(k), re.I)
                             and isinstance((v or {}).get("value"), (int, float))]
                _comp_load = (1, 1)
                _load_issue = None
                if len(_load_keys) >= 2:
                    _vals = [float(_q2[k]["value"]) for k in _load_keys]
                    _lo, _hi = min(_vals), max(_vals)
                    _ok = _lo > 0 and (_hi / _lo) <= 1.15
                    _comp_load = (1, 1) if _ok else (0, 1)
                    if not _ok:
                        _load_issue = (f"HVAC load reconciliation FAILS: contract quantities "
                                       f"{', '.join(_load_keys)} diverge >15% ({_lo:g}–{_hi:g})")
                # ATEX/DSEAR HAZARDOUS-AREA VENTILATION (honest-gap check, 2026-07-06):
                # a brief citing DSEAR/ATEX for a named handling/drying area asserts a real
                # hazardous-area classification, which normally REQUIRES dedicated forced
                # dilution/area-extract ventilation (IEC 60079-10 / DSEAR ACOP). A design
                # that credits its process air-handling equipment (above) but has NO
                # dedicated area-extract/purge ventilation for that cited hazardous area is
                # a genuine engineering GAP — this must score LOW with a routed note, never
                # be silently dropped and never be dressed up as "out of scope" (the brief
                # never excluded it). Universal: keyed on the brief's own ATEX/DSEAR
                # citation + a generic area-ventilation noun set, no archetype table.
                _orig_brief_txt = ""
                try:
                    with open(os.path.join(run_dir or "", "0-original-brief.md"),
                              "r", encoding="utf-8") as _fh:
                        _orig_brief_txt = _fh.read()
                except Exception:  # noqa: BLE001
                    _orig_brief_txt = ""
                _atex_cited = bool(re.search(
                    r"\bdsear\b|\batex\b|explosion[- ]?proof|hazardous area|explosive atmosphere",
                    _orig_brief_txt, re.I))
                # CROSS-CLASS FIX (2026-07-06): pull the brief's OWN cited hazard-area
                # description out of its DSEAR/ATEX clause instead of a hardcoded CO2
                # phrase — "the MEA handling and drying areas" (CO2-mineralisation) vs
                # "vented battery gases" (BESS) are DIFFERENT hazards; a fixed CO2 string
                # here previously fired verbatim on ANY DSEAR/ATEX brief. Universal: a
                # lazy "…dsear/atex…for <desc>" capture, generic across archetypes; falls
                # back to a neutral phrase when the brief's clause doesn't parse.
                _hazard_desc_m = re.search(
                    r"\b(?:dsear|atex)\b[^\n]{0,160}?\bfor\b\s+(?:the\s+)?([^\n(.;]+)",
                    _orig_brief_txt, re.I)
                _hazard_desc = (_hazard_desc_m.group(1).strip().rstrip(".,")
                                if _hazard_desc_m else "the cited hazardous area(s)")
                # CREDIT existing area-extract/purge/off-gas ventilation equipment
                # (2026-07-06): broadened beyond the original CO2-only phrasing so a
                # design that already HAS dedicated hazardous-area ventilation — under
                # whatever real-world name it carries (BESS's "enclosure ventilation
                # fan" / "off-gas exhaust fan", CO2's "ATEX area extract fan") — PASSES
                # instead of being false-flagged as a gap. Only a design that genuinely
                # has NONE of these still flags. Generic equipment nouns, no per-class
                # table.
                _area_extract_present = any(
                    re.search(r"area extract|extract fan|purge ventilat|zone ventilat|"
                              r"hazardous.{0,25}ventilat|explosion.{0,20}vent|"
                              r"enclosure ventilat|off.?gas.{0,20}(?:exhaust|extract|"
                              r"fan|vent)|exhaust fan|ventilation fan",
                              str(r.get("requirement") or r.get("part") or ""), re.I)
                    for r in _all_bom)
                _comp_atex = ((1 if _area_extract_present else 0, 1) if _atex_cited else None)
                _components = [
                    ("air-side (ducting/AHU/ventilation) parts shown on the HVAC drawing", *_comp_air),
                    ("coolant/refrigeration parts shown on the HVAC drawing", *_comp_cool),
                    ("HVAC load reconciliation across contract quantities", *_comp_load),
                ]
                if _comp_atex is not None:
                    _components.append((
                        f"ATEX/DSEAR hazardous-area ventilation for the brief's cited "
                        f"{_hazard_desc}", *_comp_atex))
                _sc = round(10.0 * min(p / c for _l, p, c in _components if c), 1)
                if _sc == int(_sc):
                    _sc = int(_sc)
                _issues = []
                if _air_missing:
                    _issues.append(f"air-side coverage {len(_air_shown)}/{len(_air_parts)} — "
                                   f"MISSING from the drawing: {', '.join(_air_missing[:5])}")
                if _cool_missing:
                    _issues.append(f"coolant/refrigeration coverage {len(_cool_shown)}/{len(_cool_parts)} "
                                   f"— MISSING from the drawing: {', '.join(_cool_missing[:5])}")
                if _load_issue:
                    _issues.append(_load_issue)
                if _comp_atex is not None and _comp_atex[0] < _comp_atex[1]:
                    _issues.append(
                        f"the brief cites DSEAR/ATEX hazardous-area classification for "
                        f"{_hazard_desc}, but no dedicated area-extract/purge "
                        f"ventilation equipment appears in the design — a genuine hazardous-"
                        f"area ventilation GAP (not an out-of-scope item; the brief never "
                        f"excludes it)")
                # ROUTE EVERY open gap (not just the first) — a run can carry both a
                # missing-coverage AND a missing-ATEX-ventilation defect simultaneously;
                # the fix text must not silently drop the second (2026-07-05 fix).
                _fixes = []
                if _air_missing or _cool_missing:
                    _fixes.append("the HVAC drawing generator must draw the design's full "
                                   "HVAC scope (air-side AC / ventilation / ducting as well "
                                   "as the coolant loop)")
                if _comp_atex is not None and _comp_atex[0] < _comp_atex[1]:
                    _fixes.append("size + add dedicated area-extract/purge ventilation for "
                                  "the brief's cited DSEAR/ATEX hazardous area(s)")
                return {"score": _sc, "target": 8, "status": "PASS" if _sc >= 8 else "FAIL",
                        "issues": _issues or [f"air-side {_comp_air[0]}/{_comp_air[1]}, coolant "
                                               f"{_comp_cool[0]}/{_comp_cool[1]}, load reconciliation "
                                               f"{_comp_load[0]}/{_comp_load[1]}"],
                        "fix": " · ".join(_fixes),
                        "components": [{"check": l, "passed": p, "checked": c}
                                       for l, p, c in _components]}
            return {
                "score": 6, "target": 8, "status": "FAIL",
                "issues": ["the design carries an HVAC duty but the HVAC drawing has no scored coverage — "
                           "the drawing must represent the ventilation / cooling equipment"],
                "fix": "the HVAC drawing generator must emit the ventilation/cooling equipment tags"}
        # HONEST score (9/10 campaign, 2026-07-04 — cap replaced with two REAL, verified
        # checks; no hardcoded flat literal): (1) the design's contract quantities were
        # actually scanned and genuinely carry NO HVAC/ventilation/cooling duty signal
        # (2) the brief's OWN 'Explicitly EXCLUDED' text names the climate/HVAC hardware
        # this sheet declines to size — a disclosure with no supporting brief citation
        # would be an UNSUPPORTED claim, not a verified one. Even a perfect 2/2 stays at
        # the honest ceiling of 8: there is no HVAC engineering ON the sheet to size — a
        # correctly-scoped disclosure of ZERO content cannot be a verified 9-10 "wow".
        orig = ""
        try:
            with open(os.path.join(run_dir or "", "0-original-brief.md"), "r", encoding="utf-8") as _fh:
                orig = _fh.read()
        except Exception:  # noqa: BLE001
            orig = ""
        _excl_hit = any(re.search(r"climate|hvac|heating|ventilat|cooling", s, re.I)
                        for s in _brief_exclusions(orig)) \
            or bool(re.search(r"climate[ /-]?(?:heating|control)?.{0,20}ventilation.{0,20}cooling|"
                              r"hvac hardware.{0,40}(?:out of scope|supplied by others)",
                              orig, re.I))
        _components = [
            ("confirmed no HVAC/ventilation/cooling contract duty (contract quantities scanned)", 1, 1),
            ("brief's own exclusions cite the climate/HVAC hardware this sheet declines to size",
             1 if _excl_hit else 0, 1),
        ]
        _sc = round(min(10.0 * min(p / c for _l, p, c in _components), 8.0), 1)
        if _sc == int(_sc):
            _sc = int(_sc)
        _comps_out = [{"check": l, "passed": p, "checked": c} for l, p, c in _components]
        if not _excl_hit:
            # UNVERIFIED scope claim (Tristan 2026-07-05, Option A — the both-directions
            # proveCatch this generalisation exists to guarantee): the sheet DECLARES itself
            # out of scope, but its own second verification check (the brief citing the
            # excluded hardware) did NOT pass. This is exactly the "unverified scope dodge"
            # the mechanism below must never reward — it stays a NORMAL, LOW-scoring tab
            # (never `scored: False`), so it cannot escape the ≥8 floor by merely CLAIMING
            # inapplicability.
            return {"score": _sc, "target": 8, "status": "FAIL",
                    "issues": ["the sheet claims HVAC is out of scope, but the brief's own "
                               "exclusions do NOT explicitly name the climate/HVAC hardware — "
                               "an unsupported disclosure (stays scored, at this low value, "
                               "until the claim is verified)"],
                    "fix": "cite the excluded climate/HVAC hardware explicitly in the brief's "
                           "own 'Explicitly EXCLUDED' section",
                    "components": _comps_out}
        # VERIFIED OUT-OF-SCOPE (Tristan 2026-07-05, Option A directive): every declared
        # verification check passed (both components 1/1) — this discipline sheet is
        # GENUINELY inapplicable to this archetype, not merely undersized or dodging the
        # floor. GENERIC CONTRACT (not HVAC-specific — any tab's scorer may set `scored:
        # False` on its own return dict when its OWN verification checks all pass; the
        # consumers — compute_verdict, tab_scorecard_summary, the Q&A per-tab table, the
        # chip — key ONLY on this flag, never on a tab name):
        #   • compute_verdict / tab_scorecard_summary EXCLUDE the tab from the floor, the
        #     open-issue count, and the fail/unscored tallies — a verified "not applicable"
        #     is not an open issue.
        #   • the sheet still renders normally with its verification checks visible, a chip
        #     reading "OUT OF SCOPE FOR THIS ARCHETYPE — VERIFIED, NOT SCORED", and the Q&A
        #     per-tab row shows "n/a — verified out of scope" instead of a numeric score.
        #   • tab-scorecard.json carries `scored: false` + this entry's basis (built from
        #     `components` below, same as every other tab) so the verification is auditable.
        return {"score": _sc, "target": 8, "status": "PASS", "scored": False,
                "issues": ["out of scope for this archetype — VERIFIED, not scored: HVAC's "
                           "climate hardware (heating / ventilation / cooling) is supplied by "
                           "others (per the brief), confirmed by both checks below — excluded "
                           "from the ≥8 floor rather than penalised for having no HVAC "
                           "engineering to show."],
                "fix": "none — an HVAC duty would switch this to a coverage-scored check automatically",
                "components": _comps_out}
    return None  # Contents / ⭐ Scorecard navigation tabs


def _tab_quality_banner(title: str):
    """The score-CHIP spec ({text, fill, height}) for a sheet — score + the scoring
    formula with LIVE COUNTS (the tab's own basis) + a pointer to Quality & Audit.
    None only when the tab has no score entry at all (the no-silent-default assertion
    turns that into a build error before any chip is stamped)."""
    v = _TAB_SCORES.get(title)
    if not isinstance(v, dict):
        v = _aux_tab_score(title, _RUN_DIR)   # drawing / render / meta sheets → on-the-fly score
    if not isinstance(v, dict):
        return None
    tgt = v.get("target", 8)
    status = v.get("status")
    if status == "UNSCORED":
        return {
            "text": f"⬤ TAB QUALITY — UNSCORED: no deterministic check covers this tab yet, so it cannot be certified ≥{tgt}. {v.get('fix', '')}",
            "fill": FILL_ADVISORY, "height": 30,
        }
    sc = v.get("score")
    sc_txt = f"{sc:g}" if isinstance(sc, (int, float)) else str(sc)
    basis = str(v.get("basis") or "").strip()
    basis_short = (basis[:170] + "…") if len(basis) > 171 else basis
    issues = v.get("issues") or []
    tail = (f"  →  {issues[0]}" if (status == "FAIL" and issues) else "")
    return {
        "text": (f"⬤ TAB QUALITY {sc_txt}/10 · {status} (target ≥{tgt})"
                 + (f" · {basis_short}" if basis_short else "")
                 + " · full audit: 'Quality & Audit' tab" + tail),
        "fill": FILL_PASS if status == "PASS" else FILL_FAIL,
        "height": 30 if (tail or len(basis_short) > 90) else 18,
    }


# ON-TAB SCORE CHIP (Tristan 2026-07-03: "if they don't have a score how can you score
# it?"). EVERY tab reserves row 2 as its score chip at build time and registers itself in
# _CHIP_SPANS; the chip is RE-STAMPED at the very end of build() from the FINAL
# _TAB_SCORES (score + the formula with live counts + a pointer to Quality & Audit) —
# never at tab-build time, so the banner-timing staleness gap cannot recur. This
# supersedes the 2026-07-02 meta-tabs-only banner rule: an on-tab score is required
# precisely because a score nobody can see on the tab is indistinguishable from no score.
_CHIP_SPANS: Dict[str, int] = {}   # sheet title -> merged span of its reserved chip row
_CHIP_PLACEHOLDER = "⬤ TAB QUALITY — computed from this tab's rendered content at end of build"

# PER-CELL COMPLETENESS CONTRACT registry of every rendered table (populated by header()).
# Each entry: {sheet, row, cols}. The generic walker (_run_cell_contracts) verifies every
# data row × required column of every registered table and refuses a table whose column
# signature has no declared contract (_TABLE_CONTRACTS) — adding an uncontracted table is
# impossible.
_RENDERED_TABLES: List[dict] = []

# ═══ LIVE-FORMULA VERDICT MACHINERY (Tristan 2026-07-03: "if you look at the cell, the
# formula is just 'pass', so that's not a formula … every single column needs to have a
# deterministic check on it which says it was actually passed or not. Just putting 'pass'
# in a column with no formulas is cheating.") ═══════════════════════════════════════════
# EVERY verdict cell in the workbook is a REAL Excel formula over the cells it judges —
# the formula bar IS the check definition. Where a check compares against data not on any
# sheet (contract quantities, drawing-derived values, python-classified evidence), the
# operand is EMBEDDED: either an 'Audit: …' column beside the table (muted) or a
# provenance-labelled row on the 'Audit data' sheet — and the formula reduces to the
# comparison over those operand cells. A check whose classification is genuinely
# python-computed embeds its EVIDENCE (the fault text, '' when clean) and the formula is
# the comparison evidence="" — never a bare literal. Enforced both directions:
# _enforce_live_check_gate refuses the build on any bare PASS/FAIL/✓/✗ literal, and
# _selftest proveCatches a planted literal. ONE TRUTH: after the LibreOffice recalc the
# builder READS BACK the recalculated score cells and tab-scorecard.json carries THOSE
# values, so the python scorecard and the in-cell formulas can never disagree.

_AUDIT_SHEET_TITLE = "Audit data"
_AUDIT_OPERANDS: List[dict] = []       # {"group","label","value","provenance"}
_AUDIT_DATA_START = 6                  # first data row on the Audit data sheet (fixed layout)


def audit_operand(group: str, label: str, value, provenance: str) -> str:
    """Register a NON-SHEET operand a verdict formula depends on; returns its absolute
    ref ('Audit data'!$C$7). The 'Audit data' sheet renders every registered operand with
    its provenance, so the workbook CONTAINS everything its own verdicts depend on."""
    _AUDIT_OPERANDS.append({"group": str(group), "label": str(label), "value": value,
                            "provenance": str(provenance)})
    return f"'{_AUDIT_SHEET_TITLE}'!$D${_AUDIT_DATA_START - 1 + len(_AUDIT_OPERANDS)}"


def _xq(s, cap: int = 180) -> str:
    """Sanitise text for embedding inside an Excel formula STRING literal: double-quotes
    become apostrophes (never a quote-escape headache), newlines collapse, length capped."""
    t = re.sub(r"\s+", " ", str(s or "")).replace('"', "'").strip()
    return (t[: cap - 1] + "…") if len(t) > cap else t


def fx_verdict(conds: List[str], fail_expr: str, pass_text: str = "PASS",
               fail_prefix: str = "FAIL — ") -> str:
    """The canonical verdict formula: =IF(AND(<conds>),"PASS","FAIL — "&<fail_expr>).
    `conds` are Excel boolean terms over the cells the check judges; `fail_expr` is an
    Excel STRING expression naming why (usually the embedded evidence cell)."""
    cond = conds[0] if len(conds) == 1 else "AND(" + ",".join(conds) + ")"
    return f'=IF({cond},"{pass_text}","{fail_prefix}"&{fail_expr})'


def _fx_req_terms(refs: List[str]) -> List[str]:
    """Completeness terms for required cells: non-empty and not the '—' placeholder."""
    out: List[str] = []
    for ref in refs:
        out.append(f'LEN(TRIM({ref}&""))>0')
        out.append(f'TRIM({ref}&"")<>"—"')
    return out


def _fx_evidence_expr(ev_ref: str, structural_label: str) -> str:
    """FAIL-message expression: the embedded python evidence when present, else the
    structural fail label (the live-recompute case — an operand was corrupted)."""
    return (f'IF(LEN(TRIM({ev_ref}&""))>0,TRIM({ev_ref}&""),'
            f'"{_xq(structural_label, 120)}")')


def _compliance_verdict_fx(verd_ref: str, reason_ref: str) -> str:
    """LIVE formula for the Risk & Regulatory compliance-gate verdict cell (Tristan
    2026-07-04, the 4th conditional-literal-family fix — after FAIL(soft), the
    generative-benchmark verdicts, and the Connection-trace bare-'OK'). PASS iff the
    embedded engine verdict word IS EXACTLY 'PASS'; the fail branch echoes the engine's
    own verdict word + reason. NOT re-derived from conflicts.length===0 — proven wrong
    on Codema v79 (water_treatment): compliance-gate.ts has a fail-open THIRD branch
    ("No class-standards registered for <class>") that also carries conflicts=[] but
    returns verdict='WARN', reached by a CODE PATH with no distinguishing field in the
    exposed result — a conflicts-count shortcut would silently paint that WARN green.
    `verd_ref`/`reason_ref` are cell references (or quoted literals in a selftest) to
    the AUDITED engine verdict word + reason — never a python literal is embedded here."""
    return f'=IF(EXACT({verd_ref},"PASS"),"PASS",{verd_ref}&" — "&{reason_ref})'


# ═══ SOFT-MISS DEFECT/ISSUE TEXT → LIVE FORMULA (Tristan 2026-07-04, the v67 escape) ═══
# A quality-scorecard section's `defects`/`issues` list is an opaque, upstream-classified
# STRING (e.g. a soft brief-compliance miss: 'FAIL (soft): ro_working_pressure_bar —
# target 10.6 bar, achieved 1 (ro_high_pressure_pump_served_bar)'). The Overview and
# Quality & Audit tabs rendered that string straight into the cell, so a build that
# happened to carry a SOFT compliance miss painted a bare 'FAIL (soft): …' literal on
# Overview!D and 'Quality & Audit'!E — caught (correctly) by _enforce_live_check_gate,
# but only on a state that actually carries the miss, so it slipped every clean-state
# selftest. _SOFT_MISS_RX recognises the 'VERDICT (soft): label — target T [unit],
# achieved A …' family (PASS/FAIL/WARN); target + achieved + label are parsed out and the
# cell becomes a REAL recompute over them (the 24484fb3f/3b01cb73a standard) — the
# comparison direction (>= or <=) is the one that reproduces the SOURCE verdict from the
# two parsed numbers (deterministic from the data itself, no per-metric direction table).
# The operands are embedded as INLINE formula literals rather than 'Audit data' sheet rows
# — Overview and (especially) Quality & Audit render LATE in build() (Quality & Audit is
# built AFTER tab_audit_data has already fixed the Audit-data row list, per its own
# 'built after every content tab has registered its operands' contract; a late
# audit_operand() call here would return a ref to a row that sheet never actually
# rendered). The target/achieved/label are already fully known at python build time —
# the same footing as the fixed-constant literals baked directly into other formulas in
# this file (e.g. _BOARD_RECON_BAND) — so an inline literal is the correct embed, not a
# workaround. Any other string _BARE_VERDICT_RX would catch (a sibling with no parseable
# target/achieved) still never ships as a literal: it becomes a trivial one-literal
# formula. Ordinary prose (no bare-verdict prefix) is unaffected.
_SOFT_MISS_RX = re.compile(
    r"^(?P<verdict>PASS|FAIL|WARN)\s*\(soft\)\s*:\s*(?P<label>.+?)\s*[—-]\s*target\s+"
    r"(?P<target>-?[\d,]*\.?\d+)\s*(?P<tunit>[^\s,]*)\s*,\s*achieved\s+"
    r"(?P<achieved>-?[\d,]*\.?\d+)\s*(?P<tail>.*)$",
    re.IGNORECASE)


def _verdict_expr(text: str) -> str:
    """EXCEL EXPRESSION (no leading '=') for ONE verdict-prefixed defect/issue STRING —
    used both as a whole-cell formula (_write_defect_cell) and as a join component when
    several defects render in one cell (_write_defect_join_cell). Only called once the
    caller has confirmed `text` matches _BARE_VERDICT_RX."""
    m = _SOFT_MISS_RX.match(text.strip())
    if m:
        try:
            tgt = float(m.group("target").replace(",", ""))
            ach = float(m.group("achieved").replace(",", ""))
        except ValueError:
            m = None
    if m:
        verdict = m.group("verdict").upper()
        label = m.group("label").strip()
        tunit = (m.group("tunit") or "").strip()
        tail = (m.group("tail") or "").strip()
        target_disp = f"{m.group('target')} {tunit}".strip()
        achieved_disp = f"{m.group('achieved')} {tail}".strip()
        # direction inferred FROM THE DATA: whichever comparison reproduces the recorded
        # verdict for these two numbers (no hardcoded higher-/lower-is-better table).
        ge_reads_pass = ach >= tgt
        cmp_op = ">=" if ge_reads_pass == (verdict == "PASS") else "<="
        return (f'IF({ach:g}{cmp_op}{tgt:g},"PASS","{verdict} (soft) — "&"{_xq(label, 120)}"&'
                f'": target "&"{_xq(target_disp, 60)}"&", achieved "&"{_xq(achieved_disp, 60)}")')
    # sibling / unparsed bare-verdict string — still never a literal: a trivial formula
    # that reduces to the escaped text.
    return f'"{_xq(text, 300)}"'


def _write_defect_cell(ws: Worksheet, row: int, col: int, text: str):
    """Write a SINGLE defect/issue string to a cell: a LIVE formula the moment the text
    is verdict-prefixed (_BARE_VERDICT_RX), else the plain text unchanged. Returns the
    cell so the caller can still style it (font/fill/border/alignment) as before."""
    t = clean_cell(text) if text is not None else ""
    t = t if isinstance(t, str) else str(t)
    if t and _BARE_VERDICT_RX.match(t.strip()):
        return ws.cell(row, col, "=" + _verdict_expr(t))
    return ws.cell(row, col, t)


def _write_defect_join_cell(ws: Worksheet, row: int, col: int, items: List[str]):
    """Write a list of defect/issue strings, joined with '; ', to ONE cell. Falls back to
    the original plain join when none of the items is verdict-prefixed; otherwise builds
    ONE formula concatenating every item (a verdict-prefixed item becomes a live
    recompute / escaped-literal sub-expression, a plain item becomes a quoted literal) —
    so a soft miss buried among several defects still never ships as a bare literal."""
    cleaned = [clean_cell(d) for d in (items or []) if clean_cell(d)]
    if not any(_BARE_VERDICT_RX.match(s.strip()) for s in cleaned):
        return ws.cell(row, col, "; ".join(cleaned))
    parts = [_verdict_expr(s) if _BARE_VERDICT_RX.match(s.strip())
             else f'"{_xq(s, 300)}"' for s in cleaned]
    if not parts:
        return ws.cell(row, col, "")
    return ws.cell(row, col, "=" + '&"; "&'.join(parts))


def _cf_range_is_empty(rng: str) -> bool:
    """True when a cell-range string is BACKWARDS/empty (end row < start row) — e.g.
    'O10:O9', produced when a section header renders at row1 but ZERO data rows follow
    (r stays == row1, so 'O{row1}:O{r-1}' inverts). openpyxl's conditional-formatting /
    merge machinery raises 'N must be greater than M' → 'expected MultiCellRange' on such
    a range, which the add_tab guard swallows as a whole-tab SKIP (the Engineering Analysis
    tab vanished on the OpenDrop instrument, whose EA sections can be empty). Universal:
    any tab that builds a verdict range over a possibly-empty section is protected."""
    import re as _re
    m = _re.match(r"^\$?[A-Z]+\$?(\d+)(?::\$?[A-Z]+\$?(\d+))?$", rng.strip())
    if not m:
        return False                       # unrecognised shape — let openpyxl judge it
    r1 = int(m.group(1))
    r2 = int(m.group(2)) if m.group(2) else r1
    return r2 < r1


def _cf_verdict(ws: Worksheet, rng: str) -> None:
    """Conditional formatting for a live verdict column: green on PASS, red on FAIL —
    so a formula that FLIPS on recalc recolours itself (the static build-time fill only
    reflects the build-time evaluation)."""
    if _cf_range_is_empty(rng):
        return                             # empty section — nothing to colour, skip cleanly
    from openpyxl.formatting.rule import CellIsRule
    ws.conditional_formatting.add(rng, CellIsRule(
        operator="beginsWith", formula=['"FAIL"'], fill=FILL_FAIL, font=FONT_FAIL))
    ws.conditional_formatting.add(rng, CellIsRule(
        operator="equal", formula=['"PASS"'], fill=FILL_PASS, font=FONT_PASS))
    ws.conditional_formatting.add(rng, CellIsRule(
        operator="beginsWith", formula=['"✗"'], fill=FILL_FAIL, font=FONT_FAIL))
    ws.conditional_formatting.add(rng, CellIsRule(
        operator="beginsWith", formula=['"✓"'], fill=FILL_PASS, font=FONT_PASS))


# Check-column ranges per sheet — every rendered verdict/check column registers here so
# (a) the Q&A per-tab score formulas can COUNTIF over the live verdicts, and (b) the
# no-cheating gate + selftests can walk every check cell.
_CHECK_RANGES: Dict[str, List[dict]] = {}   # sheet -> [{col,r1,r2,n_pass,n_total}]


def _register_check_range(sheet_title: str, col_letter: str, r1: int, r2: int,
                          n_pass: Optional[int] = None,
                          n_total: Optional[int] = None) -> None:
    """Register a rendered check column (verdict formulas in col_letter, rows r1..r2).
    n_pass/n_total = the build-time PASS tally, when the column carries PASS/FAIL
    verdicts — the live per-tab score formulas COUNTIF over these ranges."""
    if r2 >= r1:
        _CHECK_RANGES.setdefault(sheet_title, []).append(
            {"col": col_letter, "r1": r1, "r2": r2, "n_pass": n_pass, "n_total": n_total})


# Q&A per-tab score cells (tab title -> 'Quality & Audit'!$B$<row>) + the live floor /
# open-issue cells — registered when the Quality & Audit tab renders; the live score
# formulas + chips + verdict formulas reference them; the post-recalc read-back reads them.
_QA_SCORE_CELLS: Dict[str, str] = {}
_QA_FLOOR_CELL: List[str] = []      # single absolute ref, list for mutability
_QA_OPEN_CELL: List[str] = []
_QA_SHIP_AXIS_CELLS: List[str] = []  # S7: the APPLICABLE ship-gate axes' Met operand cells (col B of the card)


def _contiguous_col_ranges(col_letter: str, rows: List[int]) -> List[str]:
    """A sorted list of non-contiguous row numbers in one column -> the FEWEST plain
    range/cell tokens that cover them EXACTLY, e.g. [33,34,35,40,41] with col 'B' ->
    ['$B$33:$B$35', '$B$40:$B$41']. NEVER emits a '(ref1,ref2,ref3)' reference-UNION —
    that construct is what round-trips broken (Tristan 2026-07-05, Excel repair round 2):
    recalc_and_cache()'s LibreOffice headless '--convert-to xlsx' pass rewrites the OOXML
    union operator ',' inside a parenthesised reference list into the ODFF reference-
    CONCATENATION operator '~' (verified: a minimal (B4,B5,B6) formula round-tripped through
    the exact same soffice invocation comes back as (B4~B5~B6)) — real Excel does not
    recognise '~' as a formula operator and silently DROPS the whole formula on open
    ('Removed Records: Formula from .../sheetNN.xml part'). Plain ranges/cells returned
    here are safe as (a) separate MIN()/COUNT()/COUNTA() arguments (those functions are
    variadic — no union needed) and (b) separate per-run COUNTIF() calls summed together
    (COUNTIF takes exactly one range, so a caller with multiple runs must call it once per
    run, never wrap them together). See ooxml_strict_check.py :: check_reference_union_tilde
    (proveCatch: flags the pre-fix v10 file's literal '~' inside a formula; passes a rebuild
    using only this helper's output)."""
    out: List[str] = []
    rows = sorted(set(rows))
    i = 0
    while i < len(rows):
        j = i
        while j + 1 < len(rows) and rows[j + 1] == rows[j] + 1:
            j += 1
        out.append(f"${col_letter}${rows[i]}" if i == j
                    else f"${col_letter}${rows[i]}:${col_letter}${rows[j]}")
        i = j + 1
    return out



_FONT_AUDIT = Font(name="Calibri", size=8, color="808080")

def _round1(x: float) -> float:
    """HALF-UP 1-dp rounding matching Excel's ROUND(x,1) — python round() is banker's
    rounding (round(8.25,1)=8.2, Excel=8.3), and the live score formulas must reproduce
    the python scorecard exactly (ONE TRUTH read-back assert)."""
    return math.floor(float(x) * 10 + 0.5) / 10.0


def _is_invalid_formula(_s: str) -> bool:
    """A string openpyxl will store as a formula that is NOT a valid Excel formula —
    engine PROSE ("= 3.91 t/day …"), chemical formulas, OR a formula left with an UNBOUND
    symbol (a bare letter like "E" in "=B187/(2*B189*E-…)"; bare TRUE/FALSE — use
    TRUE()/FALSE()). Strip every VALID formula token; if ANY letter remains it cannot be
    a real formula → defang/refuse. Safe for genuine formulas (=…*8000/1e9, =IF(…),
    ='Inputs & Assumptions'!$B$5, =CO2 cell-ref, COUNTIF('⚠ Checks'!$F:$F,…))."""
    _t = re.sub(r'"[^"]*"', "", _s)                     # string literals — letters here are VALID
    _t = re.sub(r"'[^']*'!", "", _t)                    # sheet refs
    _t = re.sub(r"\$?[A-Z]{1,3}\$?:\$?[A-Z]{1,3}(?![A-Za-z0-9])", "", _t)  # whole-column refs ($F:$F)
    _t = re.sub(r"\$?[A-Z]{1,3}\$?\d+", "", _t)         # cell refs (incl CO2-style)
    _t = re.sub(r"[A-Za-z][A-Za-z0-9.]*\s*\(", "(", _t)  # function calls -> (
    _t = re.sub(r"\bin_[a-z0-9_]+\b", "", _t)           # known defined names (Inputs & Assumptions)
    _t = re.sub(r"\bINP_[A-Z0-9_]+\b", "", _t)          # known defined names (M0 — Phase B, drawer
                                                          # 047565b65ce05148: a bare '=INP_FOO' M0
                                                          # cross-sheet reference is a genuine formula,
                                                          # not prose — without this the guard defangs
                                                          # every direct M0 name reference workbook-wide)
    _t = re.sub(r"\d+\.?\d*([eE][+\-]?\d+)?", "", _t)   # numbers incl scientific (1e9)
    _t = re.sub(r"[\s+\-*/^%(),:.=&<>​]", "", _t)  # operators / whitespace / zero-width
    return bool(re.search(r"[A-Za-z]", _t))


def title_row(ws: Worksheet, text: str, span: int, subtitle: str = "") -> int:
    """Write a full-width title band + reserve the row-2 score chip (re-stamped from the
    FINAL scores at end of build — every tab carries its visible score); return next free row."""
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=span)
    c = ws.cell(1, 1, text)
    c.font = FONT_TITLE
    c.fill = FILL_TITLE
    c.alignment = Alignment(vertical="center", horizontal="left", indent=1)
    ws.row_dimensions[1].height = 26
    nxt = 2
    # Score chip — EVERY tab. Reserved (placeholder) now, stamped from FINAL scores later.
    ws.merge_cells(start_row=nxt, start_column=1, end_row=nxt, end_column=span)
    bc = ws.cell(nxt, 1, _CHIP_PLACEHOLDER)
    bc.font = FONT_NOTE
    bc.alignment = LEFT_TOP
    ws.row_dimensions[nxt].height = 16
    _CHIP_SPANS[ws.title] = span
    nxt += 1
    if subtitle:
        ws.merge_cells(start_row=nxt, start_column=1, end_row=nxt, end_column=span)
        s = ws.cell(nxt, 1, subtitle)
        s.font = FONT_NOTE
        s.alignment = LEFT_TOP
        # Grow the merged subtitle row so a 2-3 line purpose note never clips
        # (Excel does NOT auto-grow a MERGED wrapped cell). Estimate lines from
        # the text length vs the merged width (~5.5 chars per column-width unit).
        approx_cols_wide = max(1, sum(_col_width(ws, ci) for ci in range(1, span + 1)))
        chars_per_line = max(40, approx_cols_wide * 1.05)
        lines = max(1, int(_math.ceil(len(subtitle) / chars_per_line)))
        ws.row_dimensions[nxt].height = 15 + 13 * min(lines, 4)
        nxt += 1
    return nxt + 1  # leave a blank spacer row


def _col_width(ws: Worksheet, col_idx: int) -> float:
    """Best-effort current width of a column (default 8.43 if unset)."""
    try:
        from openpyxl.utils import get_column_letter
        cd = ws.column_dimensions.get(get_column_letter(col_idx))
        if cd is not None and cd.width:
            return float(cd.width)
    except Exception:  # noqa: BLE001
        pass
    return 8.43


def header(ws: Worksheet, row: int, cols: List[str]) -> None:
    # PER-CELL COMPLETENESS CONTRACT (Tristan 2026-07-03): EVERY rendered table is
    # REGISTERED here, so the generic cell-contract walker can verify every row ×
    # required column after the build — and a table with no declared contract entry
    # is IMPOSSIBLE to ship (the walker refuses, naming the sheet + columns).
    _RENDERED_TABLES.append({"sheet": ws.title, "row": row,
                             "cols": [str(c) if c is not None else "" for c in cols]})
    for i, name in enumerate(cols, start=1):
        c = ws.cell(row, i, name)
        c.font = FONT_HEADER
        c.fill = FILL_HEADER
        c.border = BORDER
        c.alignment = Alignment(vertical="center", wrap_text=True)


def sub_banner(ws: Worksheet, row: int, text: str, span: int) -> None:
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=span)
    # A deliberate "=..." live-formula heading (e.g. a Spec-sheet banner referencing the
    # master tag) is written raw; everything else is defanged for display.
    val = text if (isinstance(text, str) and text.startswith("=")) else clean_cell(text)
    c = ws.cell(row, 1, val)
    c.font = FONT_SUB
    c.fill = FILL_SUB
    c.alignment = LEFT_TOP


def unverified_banner(ws: Worksheet, row: int, span: int, text: str) -> int:
    """A red, wrapped warning band spanning `span` columns at `row` — used to flag an
    economics tab as presenting an UNVERIFIED model (no real sale price derivable for
    this class). Returns the next free row. Two rows tall for the wrapped message."""
    ws.merge_cells(start_row=row, start_column=1, end_row=row + 1, end_column=span)
    c = ws.cell(row, 1, clean_cell(text))
    c.fill = FILL_FAIL
    c.font = FONT_FAIL
    c.alignment = WRAP_TOP
    return row + 2


