def _generative_tag_prefix_entries(state: dict) -> List[Tuple[str, str]]:
    """GENERATIVE tag-prefix glossary (2026-07-05, the BESS 18-missing-prefix fix — see the
    matching comment in dossier_audit.py::check_glossary, the ONE source of truth this
    mirrors). Every tag-prefix the bill uses that isn't already covered by a curated
    `_GLOSSARY` category gets a real definition here: the CURATED override's canonical
    expansion when the abbreviation is an acronym (BMS, PCS, …), else the ledger's own
    first-occurrence part name — a genuine citation to the engine's own data, never an
    invented formula/definition. A brand-new archetype's fresh tag families self-document
    without a manual glossary edit; `check_glossary` accepts the IDENTICAL derivation so
    the render and the check can never disagree."""
    rows = [r for r in (state.get("requirementsBom") or []) if isinstance(r, dict)]
    first_by_prefix: Dict[str, str] = {}
    for r in rows:
        raw = str(r.get("tag") or "").strip()
        m = re.match(r"^([A-Z]{1,4})-?\d", raw)
        if not m:
            continue
        pref = m.group(1)
        if pref not in first_by_prefix:
            name = str(r.get("requirement") or r.get("part") or "").split("·")[0].strip()
            if name:
                first_by_prefix[pref] = name
    _known = {str(t).split("(")[0].strip().upper()
              for _cat, entries in _GLOSSARY for t, _m in entries}
    out: List[Tuple[str, str]] = []
    for pref, name in sorted(first_by_prefix.items()):
        if pref.upper() in _known:
            continue
        canon = _TAG_PREFIX_OVERRIDES.get(pref)
        if canon:
            meaning = f"{canon} — tag prefix for this equipment family (e.g. '{name}', {pref}-101 …)."
        else:
            meaning = (f"Tag prefix for '{name}' and its numbered siblings ({pref}-101, {pref}-102, "
                       f"…) — self-documented from the bill of materials' own first occurrence.")
        out.append((f"{pref} (tag)", meaning))
    return out


def _workbook_text_blob(wb: Workbook, exclude: str = "") -> str:
    """Lower-cased concatenation of every string cell on every sheet except `exclude` —
    the usage corpus for the glossary term matcher."""
    parts: List[str] = []
    for other in wb.worksheets:
        if other.title == exclude:
            continue
        for row in other.iter_rows(values_only=True):
            for v in row:
                if isinstance(v, str):
                    parts.append(v.lower())
    return "\n".join(parts)


def _term_used_in(term: str, blob: str) -> bool:
    """ONE matcher for 'is this glossary term used anywhere?' — shared by the renderer
    (which drops orphan terms at source) and the Glossary scorer (which verifies none
    remain), so the two can never disagree (honest-scoring rule). Slash/comma variants
    each count; alpha terms tolerate an adjacent digit ('50NB', 'DN50'); numeric terms
    keep the strict boundary so '304' never matches inside a number."""
    for v in (x.strip().lower() for x in re.split(r"[/,]", str(term).split("(")[0]) if x.strip()):
        if re.search(r"\d", v):
            pat = r"(?<![a-z0-9])" + re.escape(v) + r"(?![a-z0-9])"
        else:
            pat = r"(?<![a-z])" + re.escape(v) + r"(?![a-z])"
        if re.search(pat, blob):
            return True
    return False


# ═══ ENGINEERING ANALYSIS — allowable stress / safety factor / stress-strain ═══════════
# (Tristan 2026-07-06, priorities #3 SAFETY FACTOR + #6 STRESS-STRAIN): a chartered
# engineer's first question of any pressure/structural part is "what's it rated to, and
# by how much margin?" — no tab in the dossier answered that. UNIVERSAL: keyed on the
# SAME fabrication-physics fields _bom_row_kind() already uses to call a BoM row
# 'fabricated' (wall_mm + mass_kg + diameter_m — a materials take-off's own geometry,
# never a per-class table) + the row's own `material` field + `basis` string (the SAME
# materials-take-off sentence requirements_bom.py::_materials_takeoff() emits — "...
# P=<N> kPa head · σ=<N> MPa → ..." — the engine's own design pressure + the allowable
# stress it sized the wall to). Works for a RAS softener vessel, a CO2 absorber shell or
# a BESS enclosure alike — no product class is ever named here.

# The universal material-property reference (E / yield / UTS / elongation) — keyed by a
# SMALL set of MATERIAL FAMILIES, matched against the BoM row's own `material` string
# (never a per-class part table). 'family' selects the allowable-stress code route: a
# METALLIC part gets the ASME BPVC VIII Div.1 UTS/yield safety-factor route; a
# COMPOSITE/CONCRETE part has no UTS/yield ratio code — its allowable is the design
# stress the engine's own wall-sizing physics already used (requirements_bom.py::
# _wall_physics()), shown directly and honestly labelled as such.
