# ASME BPVC Section II Part D basis for a metallic pressure part: the code allowable is
# the LOWER of UTS/SF_UTS and Yield/SF_YIELD — both safety factors are EXPLICIT, shown,
# labelled inputs (never buried in a formula) so a reader can see and challenge them.
_EA_SF_UTS = 3.5
_EA_SF_YIELD = 1.5

_EA_HDR = ["Tag", "Part", "Qty", "Family", "Material", "Yield (MPa)", "UTS (MPa)",
           "SF applied — UTS", "SF applied — yield", "Allowable (MPa)",
           "Actual stress (MPa)", "Utilisation %", "Verdict", "Code basis", "Row check"]
_EA_MAT_HDR = ["Material", "Family", "E (GPa)", "Yield (MPa)", "UTS (MPa)",
               "Elongation (%)", "Code / reference"]
_EA_CURVE_HDR = ["#", "X (Strain %)", "Y (Stress MPa)"]


def _ea_match_material(material_label: str) -> Tuple[Optional[str], Optional[dict]]:
    """(material key, properties) for a BoM row's own `material` string — substring
    match against the label _material() in requirements_bom.py already emits. (None,
    None) when the label matches nothing in the reference table — honest 'not in
    contract', never a fabricated guess."""
    m = str(material_label or "").lower()
    if not m:
        return None, None
    if "concrete" in m:
        return "concrete", _EA_MATERIALS["concrete"]
    if "frp" in m or "grp" in m:
        return "frp/grp", _EA_MATERIALS["frp/grp"]
    if "316" in m:
        return "316l stainless", _EA_MATERIALS["316l stainless"]
    if "304" in m:
        return "304 stainless", _EA_MATERIALS["304 stainless"]
    if "structural" in m or "s275" in m or "s355" in m:
        return "structural steel", _EA_MATERIALS["structural steel"]
    if "alumin" in m:
        return "aluminium", _EA_MATERIALS["aluminium"]
    if "carbon steel" in m or "carbon" in m:
        return "carbon steel", _EA_MATERIALS["carbon steel"]
    return None, None


_EA_BASIS_RE = re.compile(r"P=([\d.,]+)\s*kPa.*?σ=([\d.,]+)\s*MPa", re.I | re.S)


def _build_engineering_analysis_rows(state: dict) -> List[dict]:
    """Every PRINCIPAL pressure-containing / structural part in this BoM: a fabricated
    shell with its own take-off geometry (wall_mm + mass_kg + diameter_m — the SAME
    fabrication signal _bom_row_kind() uses; a vessel, tank or shell, whatever the
    class). For each: the material + allowable stress (explicit SF) + an independent
    thin-wall actual/design stress at the adopted wall + utilisation. UNIVERSAL — no
    product class is ever named; a class whose BoM carries no such take-off row (e.g.
    all bought-out equipment) legitimately returns []."""
    rows = state.get("requirementsBom") or []
    out: List[dict] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        wall_mm = num(row.get("wall_mm"))
        mass_kg = num(row.get("mass_kg"))
        dia_m = num(row.get("diameter_m"))
        if not (wall_mm and mass_kg and dia_m):
            continue                      # not a physics-sized shell — nothing to analyse
        material = str(row.get("material") or "").strip()
        basis = str(row.get("basis") or "")
        bm = _EA_BASIS_RE.search(basis)
        p_kpa = float(bm.group(1).replace(",", "")) if bm else None
        sigma_engine_mpa = float(bm.group(2).replace(",", "")) if bm else None
        mat_key, props = _ea_match_material(material)
        rec: dict = {
            "tag": str(row.get("tag") or "").strip() or "—",
            "name": str(row.get("requirement") or "").strip() or "—",
            "qty": num(row.get("qty")) or 1,
            "material": material or "—", "material_key": mat_key,
            "wall_mm": wall_mm, "mass_kg": mass_kg, "diameter_m": dia_m,
            "p_kpa": p_kpa, "sigma_engine_mpa": sigma_engine_mpa,
        }
        if props is None:
            rec.update(
                family=None, e_gpa=None, yield_mpa=None, uts_mpa=None, elong_pct=None,
                allowable_mpa=None, sf_uts=None, sf_yield=None,
                code_basis=(f"material '{material or 'unstated'}' not in the universal "
                            "reference table — allowable stress NOT computed (data not "
                            "in contract)"),
                actual_mpa=None, utilisation_pct=None, verdict="DATA NOT IN CONTRACT")
            out.append(rec)
            continue
        rec.update(family=props["family"], e_gpa=props["e_gpa"],
                   yield_mpa=props["yield_mpa"], uts_mpa=props["uts_mpa"],
                   elong_pct=props["elong_pct"])
        if props["family"] == "metallic":
            cands = [v for v in (
                (props["uts_mpa"] / _EA_SF_UTS) if props["uts_mpa"] else None,
                (props["yield_mpa"] / _EA_SF_YIELD) if props["yield_mpa"] else None,
            ) if v is not None]
            rec["allowable_mpa"] = min(cands) if cands else None
            rec["sf_uts"], rec["sf_yield"] = _EA_SF_UTS, _EA_SF_YIELD
            rec["code_basis"] = (f"{props['code']} — allowable S = min(UTS/{_EA_SF_UTS:g}, "
                                 f"Yield/{_EA_SF_YIELD:g})")
        else:
            rec["allowable_mpa"] = sigma_engine_mpa
            rec["sf_uts"], rec["sf_yield"] = None, None
            rec["code_basis"] = (
                f"{props['code']} — this design's own wall-sizing stress "
                f"(σ={sigma_engine_mpa:g} MPa), no UTS/yield SF ratio applies"
                if sigma_engine_mpa is not None else
                f"{props['code']} — no design-stress figure in this row's own basis "
                "(data not in contract)")
        # ACTUAL/DESIGN STRESS — independent thin-wall (Barlow) hoop-stress cross-check
        # from the row's OWN P, D, adopted wall t (the same 'thin-wall cylinder' basis
        # the pressure-vessel:design tool itself states) — never the engine's own sigma
        # parroted back; a genuine second calculation from the row's own numbers.
        if p_kpa is not None and wall_mm:
            p_mpa = p_kpa / 1000.0
            rec["actual_mpa"] = p_mpa * (dia_m * 1000.0 / 2.0) / wall_mm
        else:
            rec["actual_mpa"] = None
        if rec["allowable_mpa"] and rec["actual_mpa"] is not None:
            rec["utilisation_pct"] = 100.0 * rec["actual_mpa"] / rec["allowable_mpa"]
            rec["verdict"] = ("PASS" if rec["utilisation_pct"] <= 100.0
                              else "FAIL — actual stress exceeds the code allowable")
        else:
            rec["utilisation_pct"] = None
            rec["verdict"] = "DATA NOT IN CONTRACT — actual/allowable stress not derivable"
        out.append(rec)
    return out


def _eval_engineering_analysis_rows(rows: List[dict]) -> Optional[dict]:
    """Column-contract arithmetic for the Engineering Analysis tab: a principal
    pressure/structural part PASSES only when it carries a real material match, a
    computed allowable, an independent actual/design stress AND a utilisation ≤100% —
    a part with any of those missing (honest 'data not in contract') or over-utilised
    FAILS. No rows at all (a BoM with no physics-sized shell) is None — an honest
    'nothing to analyse', never a fabricated score over zero parts."""
    if not rows:
        return None
    contract = [
        ("Material", "computed", "matched against the universal material reference table"),
        ("Allowable (MPa)", "computed", "ASME UTS/yield SF route (metallic) or the engine's "
         "own wall-sizing design stress (composite/concrete)"),
        ("Actual stress (MPa)", "computed", "independent thin-wall (Barlow) hoop stress from "
         "the row's own design pressure, diameter and adopted wall thickness"),
        ("Utilisation %", "computed", "actual ÷ allowable — PASS only at ≤100%"),
    ]
    per_row: Dict[int, dict] = {}
    n_pass = 0
    for idx, rec in enumerate(rows):
        reasons = []
        if rec.get("material_key") is None:
            reasons.append(f"material '{rec.get('material')}' not in the universal reference "
                           "table — allowable not computed")
        if rec.get("allowable_mpa") is None:
            reasons.append("no allowable stress derivable")
        if rec.get("actual_mpa") is None:
            reasons.append("no design pressure in the row's own basis — actual stress not "
                           "derivable")
        if rec.get("utilisation_pct") is not None and rec["utilisation_pct"] > 100.0:
            reasons.append(f"utilisation {rec['utilisation_pct']:.0f}% exceeds the code "
                           "allowable")
        verdict = "PASS" if not reasons else "FAIL"
        if verdict == "PASS":
            n_pass += 1
        per_row[idx] = {"verdict": verdict, "reasons": reasons}
    n_total = len(per_row)
    score = _contract_score(n_pass, n_total)
    issues: List[str] = []
    if n_pass < n_total:
        ex = [f"{rows[i]['tag'] or rows[i]['name']} ({'; '.join(r['reasons'][:1])})"
              for i, r in per_row.items() if r["verdict"] == "FAIL"][:3]
        issues.append(f"{n_total - n_pass}/{n_total} principal pressure/structural part(s) "
                      f"missing an allowable/actual/utilisation or over-stressed: "
                      + " · ".join(ex))
    return {"tab": "Engineering Analysis", "contract": contract, "rows": per_row,
            "n_pass": n_pass, "n_total": n_total, "score": score,
            "status": "PASS" if (score or 0) >= 8 else "FAIL", "issues": issues,
            "fix": ("add the missing material to the universal reference table "
                    "(_EA_MATERIALS) or the missing P=/σ= figures to the row's own "
                    "materials-take-off basis string (requirements_bom.py::"
                    "_materials_takeoff) — never hand-type a value into this tab")}




# ═══ PUMP / ROTATING-EQUIPMENT PERFORMANCE — efficiency + H-Q curve + NPSH ═════════════
# (Tristan priority #4 PUMP EFFICIENCIES/CURVES). SAME idiom as the stress-strain block
# above: UNIVERSAL (data-shape/family keyed off the row's own requirement noun + duty
# fields, never a per-class table). A pump is detected from the noun alone; a fan/
# blower/compressor needs its OWN row to carry flow + head/pressure + power TOGETHER
# before it is even a candidate (the priority target is pumps — a bare fan/blower/
# compressor with no duty data anywhere would otherwise clutter the tab with a FAIL for
# an equipment family this feature isn't chasing). Duty fields are pulled from the row's
# own requirement text FIRST (an inline 'N kW' / 'N m³/h' on a real catalogue-matched
# part is the row's own most authoritative field), else a contract quantity the row's
# own name joins to — the SAME name-join idiom Line & velocity's `_flow_qty_for_part`
# already uses (exact snake+suffix, then a unique snake-prefixed candidate), extended
# with the SAME token-overlap fallback requirements_bom.py::`_contract_motor_kw` already
# uses elsewhere in the engine to find a line's own motor kW from the contract (generic
# equipment/metric tokens excluded; a genuinely ambiguous top-tie is NEVER guessed).
# Missing data -> 'DATA NOT IN CONTRACT', never a fabricated number.
_PUMP_NOUN_RE = re.compile(r"\bpump\b", re.I)
_FAN_NOUN_RE = re.compile(r"\bfan\b|\bblower\b|\bcompressor\b", re.I)
_PUMP_FLOW_TEXT_RE = re.compile(r"([\d.,]+)\s*m[³3]\s*/\s*h\b", re.I)
_PUMP_POWER_TEXT_RE = re.compile(r"([\d.,]+)\s*kW\b", re.I)
_PUMP_BAR_TEXT_RE = re.compile(r"([\d.,]+)\s*bar\b", re.I)

_PUMP_FLOW_SUFFIXES = ("_throughput_m3_h", "_flow_m3_h", "_demand_m3_h", "_capacity_m3_h",
                       "_throughput_m3_per_hr", "_flow_m3_per_hr", "_demand_m3_per_hr",
                       "_flow_m3_per_hour", "_m3_per_hour", "_flow_lpm")
_PUMP_HEAD_SUFFIXES = ("_head_m", "_total_dynamic_head_m", "_tdh_m")
_PUMP_PRESSURE_SUFFIXES = ("_discharge_pressure_bar", "_pressure_bar",
                          "_working_pressure_bar", "_delivery_pressure_bar")
_PUMP_POWER_SUFFIXES = ("_power_kw", "_motor_kw", "_shaft_kw", "_shaft_power_kw",
                        "_hydraulic_power_kw", "_brake_power_kw")

# Tokens that carry no identity for the join (every pump/fan shares them) — mirrors
# requirements_bom.py::_GENERIC_EQUIP_TOKENS' discipline exactly.
_PUMP_QTY_GENERIC_TOKENS = {"pump", "fan", "blower", "compressor", "motor", "power",
                           "drive", "kw", "unit", "system", "electrical", "elec",
                           "head", "pressure", "discharge", "working", "delivery",
                           "bar", "flow", "throughput", "demand", "capacity", "m3",
                           "per", "hour", "hr", "lpm", "shaft", "hydraulic", "brake",
                           "total", "dynamic", "tdh"}


def _pump_contract_join(name: str, quantities: dict, suffixes: Tuple[str, ...]
                        ) -> Optional[Tuple[str, float, dict, str]]:
    """(key, value, quantity-dict, stage) for a pump/fan/blower/compressor's OWN duty
    field (flow / head / pressure / power) joined from state.orchestratorContract.
    quantities by NAME — never invented. Exact snake(name)+suffix ('exact'), then a
    UNIQUE snake-prefixed candidate ('prefix'), then a token-overlap fallback
    ('fallback') for the frequent case where the contract's quantity stem drops a
    descriptive word the BoM requirement text keeps (e.g. 'MEA circulation pump' ->
    quantity stem 'mea_pump'). A genuinely ambiguous top-tie is NEVER guessed (returns
    None) — honest 'not derivable' beats a wrong attribution. The 'fallback' stage is
    the WEAKEST evidence (a generic-token match, not this row's own distinguishing
    name) — `_build_pump_rows` cross-checks it against every OTHER candidate row so
    the SAME fallback key can never be silently claimed by two different pumps (e.g.
    'MEA circulation pump' and 'MEA recycle pump' both token-overlapping the one
    'mea_pump_head_m' key — the caller nulls BOTH rather than duplicate-attribute)."""
    if not isinstance(quantities, dict) or not name:
        return None
    s = _snake_part(name)
    if not s:
        return None

    def _qd(key: str) -> Optional[dict]:
        v = quantities.get(key)
        return v if isinstance(v, dict) else None

    for suf in suffixes:
        qd = _qd(s + suf)
        if qd is not None:
            v = num(qd.get("value"))
            if v is not None and v > 0:
                return (s + suf, float(v), qd, "exact")
    cands = [(k, num(v.get("value")), v) for k, v in quantities.items()
             if isinstance(v, dict) and k.startswith(s + "_")
             and any(k.endswith(x) for x in suffixes)]
    cands = [(k, v, qd) for k, v, qd in cands if v is not None and v > 0]
    if len(cands) == 1:
        return (cands[0][0], cands[0][1], cands[0][2], "prefix")
    if len(cands) > 1:
        return None                       # genuinely ambiguous — never guess
    toks = {t for t in re.split(r"[^a-z0-9]+", s) if len(t) >= 2}
    dist = toks - _PUMP_QTY_GENERIC_TOKENS
    if not dist:
        return None

    def _hit(t: str, kt: str) -> bool:
        return t == kt or (min(len(t), len(kt)) >= 4 and (t.startswith(kt) or kt.startswith(t)))

    fcands = []
    for k, v in quantities.items():
        if not isinstance(v, dict):
            continue
        kl = str(k).lower()
        if not any(kl.endswith(x) for x in suffixes):
            continue
        ktoks = set(re.split(r"[^a-z0-9]+", kl))
        overlap = sum(1 for t in dist if any(_hit(t, kt) for kt in ktoks))
        if overlap == 0:
            continue
        val = num(v.get("value"))
        if val is None or val <= 0:
            continue
        fcands.append((overlap, kl, float(val), v))
    if not fcands:
        return None
    fcands.sort(key=lambda c: (-c[0], c[1]))
    top = [c for c in fcands if c[0] == fcands[0][0]]
    if len({c[2] for c in top}) > 1:
        return None                       # ambiguous top-tie — never guess
    return (top[0][1], top[0][2], top[0][3], "fallback")


def _pump_mine_bar(text: str) -> Optional[float]:
    """A bar pressure value embedded in prose (a row's own basis/requirement text, or a
    JOINED contract quantity's own source_detail) — e.g. '25 m³/h @ 3 bar' or '10.6 bar
    working pressure'. Never a separate invented figure; only ever text already present
    on data this row/join already carries."""
    m = _PUMP_BAR_TEXT_RE.search(text or "")
    return float(m.group(1).replace(",", "")) if m else None


_PUMP_HDR = ["Tag", "Part", "Qty", "Family", "Duty flow Q (m³/h)",
            "Head H (m, water-equivalent)", "Hydraulic power (kW)",
            "Shaft/motor power (kW)", "Efficiency %", "NPSHr (m) — parametric",
            "NPSH margin (m)", "Verdict", "Basis / source", "Row check"]
_PUMP_CURVE_HDR = ["#", "X (Flow m³/h)", "Y (Head m)"]

_RHO_WATER = 1000.0      # kg/m3
_G_ACCEL = 9.81          # m/s2


def _build_pump_rows(state: dict) -> List[dict]:
    """Every rotating-equipment PRINCIPAL (pump always; fan/blower/compressor ONLY when
    ALL THREE duty fields are derivable together) this BoM specifies a duty for — its OWN
    duty flow Q, head/pressure H and shaft/electrical power, pulled from the row's own
    fields/basis (never invented). UNIVERSAL — no product class is ever named. A bought-
    out stub carrying NO duty signal anywhere legitimately has no candidate row — the
    SAME 'no take-off signal -> no row' idiom the stress section above uses.

    TWO-PASS cross-row de-duplication (the 'MEA circulation pump' vs 'MEA recycle pump'
    catch): the token-overlap fallback inside `_pump_contract_join` only ever checks
    ambiguity WITHIN one row's own candidate search — it cannot see that a DIFFERENT
    pump row also token-overlaps the SAME generic-stem quantity key (e.g. both 'MEA
    circulation pump' and 'MEA recycle pump' overlap the one 'mea_pump_head_m' key on
    the shared token 'mea'). Pass 1 collects every row's raw joins; pass 2 nullifies
    any 'fallback'-stage join whose key was independently claimed by MORE than one
    row — honest 'not derivable' for every claimant beats guessing which one it
    belongs to."""
    bom = state.get("requirementsBom") or []
    contract = state.get("orchestratorContract") or {}
    quantities = contract.get("quantities") or {}

    # ── PASS 1 — collect every candidate row's raw joins (never finalised yet). ──
    prelim: List[dict] = []
    fallback_users: Dict[Tuple[str, str], List[int]] = {}   # (field, key) -> [prelim idx]
    for row in bom:
        if not isinstance(row, dict):
            continue
        if row.get("connection") or str(row.get("status") or "").upper() in ("SUB-COMPONENT", "ROUTED"):
            continue
        req = str(row.get("requirement") or "")
        is_pump = bool(_PUMP_NOUN_RE.search(req))
        is_fan = (not is_pump) and bool(_FAN_NOUN_RE.search(req))
        if not (is_pump or is_fan):
            continue
        head_noun = re.split(r"[·\-(]", req)[0].strip()
        basis = str(row.get("basis") or "")

        qm = _PUMP_FLOW_TEXT_RE.search(req)
        q_inline = float(qm.group(1).replace(",", "")) if qm else None
        q_join = None if q_inline is not None else _pump_contract_join(head_noun, quantities, _PUMP_FLOW_SUFFIXES)

        pm = _PUMP_POWER_TEXT_RE.search(req)
        p_inline = float(pm.group(1).replace(",", "")) if pm else None
        p_join = None if p_inline is not None else _pump_contract_join(head_noun, quantities, _PUMP_POWER_SUFFIXES)

        bar_inline = _pump_mine_bar(req) or _pump_mine_bar(basis)
        h_join = None if bar_inline is not None else _pump_contract_join(head_noun, quantities, _PUMP_HEAD_SUFFIXES)
        pr_join = (None if (bar_inline is not None or h_join is not None)
                  else _pump_contract_join(head_noun, quantities, _PUMP_PRESSURE_SUFFIXES))
        # INTENT: when the brief states a plant-wide pump discharge pressure once
        # (`pump_pressure_bar` / `fertigation_pump_pressure_bar`) and this row has no
        # family-specific pressure of its own, join that shared pressure — the SAME
        # discipline reconcilePumpMotorAgainstStatedPressure already applies to motor
        # sizing. GOTCHA: never apply plant-wide pressure to a DRAIN/SUMP/TRANSFER lift
        # pump — those are short-head submersibles whose motor was sized for ~1 bar, not
        # the fertigation delivery pressure (joining 2.9 bar → 191% efficiency FAIL).
        _hn_low = head_noun.lower()
        _is_short_lift = bool(re.search(r"\b(?:drain|sump|transfer|bilge|effluent)\b", _hn_low))
        if (pr_join is None and bar_inline is None and h_join is None
                and not _is_short_lift):
            for _pk in ("pump_pressure_bar", "fertigation_pump_pressure_bar",
                        "discharge_pressure_bar", "system_pressure_bar"):
                _pq = quantities.get(_pk) if isinstance(quantities, dict) else None
                if isinstance(_pq, dict):
                    _pv = num(_pq.get("value"))
                    if _pv is not None and _pv > 0:
                        pr_join = (_pk, float(_pv), _pq, "plant_wide")
                        break

        idx = len(prelim)
        for field, jd in (("q", q_join), ("p", p_join), ("h", h_join), ("pr", pr_join)):
            if jd is not None and jd[3] == "fallback":
                fallback_users.setdefault((field, jd[0]), []).append(idx)
        prelim.append(dict(row=row, is_pump=is_pump, is_fan=is_fan, head_noun=head_noun,
                           basis=basis, q_inline=q_inline, p_inline=p_inline,
                           bar_inline=bar_inline, q_join=q_join, p_join=p_join,
                           h_join=h_join, pr_join=pr_join))

    dup_keys = {key for key, users in fallback_users.items() if len(users) > 1}

    def _degen(field: str, jd):
        """A 'fallback' join whose key is claimed by >1 row is nulled — never guessed."""
        if jd is not None and jd[3] == "fallback" and (field, jd[0]) in dup_keys:
            return None
        return jd

    # ── PASS 2 — finalise each row from its (de-duplicated) joins. ──
    out: List[dict] = []
    for p in prelim:
        is_fan = p["is_fan"]
        q_join = _degen("q", p["q_join"])
        p_join = _degen("p", p["p_join"])
        h_join = _degen("h", p["h_join"])
        pr_join = _degen("pr", p["pr_join"])

        q_val = p["q_inline"]
        q_src = "the row's own requirement text" if q_val is not None else None
        if q_val is None and q_join:
            q_val, q_src = q_join[1], f"contract quantity '{q_join[0]}'"

        p_val = p["p_inline"]
        p_src = "the row's own requirement text" if p_val is not None else None
        if p_val is None and p_join:
            p_val, p_src = p_join[1], f"contract quantity '{p_join[0]}'"

        bar_val = p["bar_inline"]
        head_src = "the row's own requirement/basis text" if bar_val else None
        if bar_val is None:
            for jd in (q_join, p_join):
                if jd is not None:
                    bv = _pump_mine_bar(str(jd[2].get("source_detail") or ""))
                    if bv:
                        bar_val, head_src = bv, f"contract quantity '{jd[0]}' source detail"
                        break
        head_m = None
        if bar_val is None and h_join:
            head_m, head_src = h_join[1], f"contract quantity '{h_join[0]}'"
        if bar_val is None and head_m is None and pr_join:
            bar_val, head_src = pr_join[1], f"contract quantity '{pr_join[0]}'"

        if is_fan and not (q_val and (bar_val or head_m) and p_val):
            continue          # fan/blower/compressor: ALL THREE required to even be a row
        _n_signals = sum(1 for v in (q_val, (bar_val or head_m), p_val) if v is not None)
        if _n_signals < 2:
            continue          # a bare mention (at most ONE duty dimension) — not a specified
                              # duty this BoM sized, the SAME 'no take-off signal -> no row'
                              # idiom the stress section uses (there, ALL THREE geometry
                              # fields must co-occur); a genuine two-of-three row still
                              # renders and honestly FAILs on the missing third dimension.

        if bar_val is not None:
            dp_pa = bar_val * 1e5
            head_used_m = dp_pa / (_RHO_WATER * _G_ACCEL)
            head_note = f"{bar_val:g} bar (→ {head_used_m:.1f} m water-equivalent)"
        elif head_m is not None:
            dp_pa = _RHO_WATER * _G_ACCEL * head_m
            head_used_m = head_m
            head_note = f"{head_m:g} m"
        else:
            dp_pa = None
            head_used_m = None
            head_note = None

        p_hyd_kw = None
        if q_val is not None and dp_pa is not None:
            p_hyd_kw = (q_val / 3600.0) * dp_pa / 1000.0

        eta_pct = None
        if p_hyd_kw is not None and p_val:
            eta_pct = 100.0 * p_hyd_kw / p_val

        npshr_m = (2.0 + 0.05 * math.sqrt(p_val)) if p_val else None

        # Wording note: deliberately avoids the "no <X> derivable/verifiable" and "cannot/
        # could not verify" phrasing the shared _apply_universal_honest_cap's _VERIF_GAP_RX
        # scans tab-level issue text for (that pattern is reserved for a genuine open
        # VERIFICATION gap, e.g. an uncorroborated vision finding) — this row's own
        # arithmetic ALREADY prices a missing duty field into n_pass/n_total (the SAME
        # self-priced-caveat idiom _SELF_PRICED_RX/_CELL_CONTRACT_RX carve out elsewhere),
        # so a second, coincidental cap here would double-penalise the same gap.
        reasons: List[str] = []
        if q_val is None:
            reasons.append("duty flow (Q) is absent from this row's own text and no contract quantity name-joins to it")
        if head_used_m is None:
            reasons.append("head/pressure (H) is absent from this row's own text and no contract quantity name-joins to it")
        if p_val is None:
            reasons.append("shaft/electrical power is absent from this row's own text and no contract quantity name-joins to it")
        if eta_pct is not None and not (0.0 < eta_pct <= 100.0):
            reasons.append(f"computed efficiency {eta_pct:.0f}% falls outside the physically possible 0-100% "
                           "band — check the joined duty fields' basis")
        if not reasons:
            verdict = "PASS"
        elif eta_pct is not None:
            verdict = "FAIL — " + "; ".join(reasons)
        else:
            verdict = "DATA NOT IN CONTRACT — " + "; ".join(reasons)

        row = p["row"]
        out.append(dict(
            tag=str(row.get("tag") or "").strip() or "—",
            name=str(row.get("requirement") or "").strip() or "—",
            qty=num(row.get("qty")) or 1,
            family=("fan/blower/compressor" if is_fan else "pump"),
            q_m3h=q_val, head_used_m=head_used_m, head_note=head_note,
            p_shaft_kw=p_val, p_hyd_kw=p_hyd_kw, eta_pct=eta_pct, npshr_m=npshr_m,
            verdict=verdict, reasons=reasons,
            basis=(f"Q: {q_src or 'DATA NOT IN CONTRACT'} · H: {head_src or 'DATA NOT IN CONTRACT'}"
                   f"{(' (' + head_note + ')') if (head_note and head_src and 'text' not in head_src) else ''}"
                   f" · shaft/motor power: {p_src or 'DATA NOT IN CONTRACT'}"),
        ))
    return out


def _eval_pump_rows(rows: List[dict]) -> Optional[dict]:
    """Column-contract arithmetic for the pump-performance rows: a candidate PASSES only
    when its efficiency + H-Q curve are fully derivable (Q, head/pressure and shaft power
    all present and the resulting efficiency sits in a physically sane 0-100% band) — a
    row with any duty field honestly missing ('DATA NOT IN CONTRACT') or an impossible
    computed efficiency FAILS. No candidate rows at all (no pump/fan/blower/compressor
    duty anywhere in this BoM) is None — an honest 'nothing to analyse'."""
    if not rows:
        return None
    contract = [
        ("Duty flow Q (m³/h)", "extracted", "the row's own requirement text or a name-joined contract quantity"),
        ("Head H / pressure", "extracted", "the row's own requirement/basis text or a name-joined contract quantity"),
        ("Shaft/motor power (kW)", "extracted", "the row's own requirement text or a name-joined contract quantity"),
        ("Efficiency %", "computed", "hydraulic power (ρ·g·Q·H) ÷ shaft power — PASS only within 0-100%"),
    ]
    per_row: Dict[int, dict] = {}
    n_pass = 0
    for idx, rec in enumerate(rows):
        row_ok = rec.get("verdict") == "PASS"
        if row_ok:
            n_pass += 1
        per_row[idx] = {"verdict": "PASS" if row_ok else "FAIL", "reasons": rec.get("reasons") or []}
    n_total = len(per_row)
    score = _contract_score(n_pass, n_total)
    issues: List[str] = []
    if n_pass < n_total:
        ex = [f"{rows[i]['tag'] or rows[i]['name']} ({'; '.join(r['reasons'][:1])})"
              for i, r in per_row.items() if r["verdict"] == "FAIL"][:3]
        issues.append(f"{n_total - n_pass}/{n_total} pump/rotating-equipment row(s) missing a "
                      f"derivable efficiency/curve: " + " · ".join(ex))
    return {"tab": "Engineering Analysis", "contract": contract, "rows": per_row,
            "n_pass": n_pass, "n_total": n_total, "score": score,
            "status": "PASS" if (score or 0) >= 8 else "FAIL", "issues": issues,
            "fix": ("add the missing Q/head/power figure to the row's own requirement text "
                    "or a contract quantity its name joins to (requirements_bom.py / "
                    "engineering-contract.ts) — never hand-type a value into this tab")}


# ═══ DESIGN & TOLERANCE — ISO 2768 general tolerances for every fabricated part ═══════
# (Tristan priority #5 DESIGN & TOLERANCE). Keyed on the SAME 'fabricated' data shape
# _bom_row_kind() already uses (never a per-class table): a physical part sized to a
# geometry (wall/mass/diameter/height/footprint/length) or a made-to-spec/structural/
# fabricated basis — a bought-out ASSEMBLY, and a mere ROUTED pipe/cable run (toleranced
# by its own DN/schedule, not a general shop tolerance), are both excluded. ISO 2768-1
# linear + angular class is an EXPLICIT editable input (default 'm' medium); ISO 2768-2
# straightness/flatness follows the SAME governing dimension. GD&T general notes
# (position, surface finish) are fixed shop defaults. The block COVERS every fabricated
# part (its coverage IS the scoring gate) — the specific millimetre figure additionally
# needs the row's own take-off dimension; when that is absent the row still renders,
# covered by the dimension-independent GD&T notes, honestly 'DATA NOT IN CONTRACT' only
# for the dimension-keyed figures.
_ISO2768_LINEAR = [   # (lo_mm, hi_mm, class_f, class_m, class_c, class_v) — ISO 2768-1 Table 1
    (0.5, 3, 0.05, 0.10, 0.20, None),
    (3, 6, 0.05, 0.10, 0.30, 0.50),
    (6, 30, 0.10, 0.20, 0.50, 1.00),
    (30, 120, 0.15, 0.30, 0.80, 1.50),
    (120, 400, 0.20, 0.50, 1.20, 2.50),
    (400, 1000, 0.30, 0.80, 2.00, 4.00),
    (1000, 2000, 0.50, 1.20, 3.00, 6.00),
    (2000, 4000, None, 2.00, 4.00, 8.00),
]
_ISO2768_ANGULAR = [   # (lo_mm, hi_mm, class_f, class_m, class_c, class_v) — degrees, ISO 2768-1 Table 2
    (0, 10, 1.0, 1.0, 1.5, 3.0),
    (10, 50, 0.5, 0.5, 1.0, 1.5),
    (50, 120, 0.333, 0.333, 0.5, 1.0),
    (120, 400, 0.167, 0.167, 0.333, 0.5),
    (400, 1e9, 0.083, 0.083, 0.167, 0.333),
]
_ISO2768_2_FLATNESS = [   # (lo_mm, hi_mm, class_H, class_K, class_L) — ISO 2768-2 straightness/flatness
    (0, 10, 0.02, 0.05, 0.10),
    (10, 30, 0.05, 0.10, 0.20),
    (30, 100, 0.10, 0.20, 0.40),
    (100, 300, 0.20, 0.40, 0.80),
    (300, 1000, 0.30, 0.60, 1.20),
    (1000, 3000, 0.40, 0.80, 1.60),
]
_ISO2768_CLASS_DEFAULT = "m"
_TOL_HDR = ["Tag", "Part", "Material", "Governing dimension (mm)", "ISO 2768-1 class",
           "Linear tolerance (±mm)", "Angular tolerance (±°)", "Flatness/straightness (mm)",
           "Position default (±mm)", "Surface finish Ra default (µm)", "Verdict", "Row check"]
_ISO_RANGE_HDR = ["Range low (mm)", "Range high (mm)", "f", "m", "c", "v"]
_ISO_FLAT_HDR = ["Range low (mm)", "Range high (mm)", "H", "K", "L"]


def _fab_governing_dim_mm(row: dict) -> Optional[float]:
    """The row's OWN largest linear take-off dimension, in mm — never invented; None
    when the row's fabrication signal is basis-text/connection-only with no numeric
    geometry (still a fabricated part, just no size to key a specific band from)."""
    cands = [c * 1000.0 for c in
             (num(row.get("diameter_m")), num(row.get("height_m")), num(row.get("length_m")))
             if c]
    fp = num(row.get("footprint_m2"))
    if fp:
        cands.append(math.sqrt(fp) * 1000.0)
    wm = num(row.get("wall_mm"))
    if wm:
        cands.append(wm)
    return max(cands) if cands else None


def _build_tolerance_rows(state: dict) -> List[dict]:
    """Every FABRICATED part in this BoM (never a bought-out assembly, never a mere
    routed pipe/cable run — toleranced by its own DN/schedule, not ISO 2768): the
    general-tolerance block a manufacturing drawing needs. UNIVERSAL — the SAME
    _bom_row_kind() fabrication signal the stress section + BoM ledger already use,
    no product class is ever named."""
    bom = state.get("requirementsBom") or []
    out: List[dict] = []
    for row in bom:
        if not isinstance(row, dict):
            continue
        if row.get("connection"):
            continue
        if _bom_row_kind(row) != "fabricated":
            continue
        out.append(dict(
            tag=str(row.get("tag") or "").strip() or "—",
            name=str(row.get("requirement") or "").strip() or "—",
            material=_bom_row_material(row) or "—",
            dim_mm=_fab_governing_dim_mm(row),
        ))
    return out


def _eval_tolerance_rows(rows: List[dict]) -> Optional[dict]:
    """Column-contract: the tolerance block must COVER every fabricated part — a row
    PASSES once it carries its ISO 2768-1 class + GD&T notes (always achievable, the
    SAME 'general note applies regardless of size' idiom a released drawing uses); the
    dimension-keyed band is an honesty column, not a separate scoring gate."""
    if not rows:
        return None
    contract = [
        ("ISO 2768-1 class", "computed", "the shared editable class (default m) applied to every row"),
        ("Linear/angular/flatness bands", "computed",
         "ISO 2768-1 / ISO 2768-2 table lookup at the row's own governing dimension, when derivable"),
    ]
    n_total = len(rows)
    per_row = {idx: {"verdict": "PASS", "reasons": []} for idx in range(n_total)}
    n_pass = n_total
    score = _contract_score(n_pass, n_total)
    return {"tab": "Engineering Analysis", "contract": contract, "rows": per_row,
            "n_pass": n_pass, "n_total": n_total, "score": score,
            "status": "PASS" if (score or 0) >= 8 else "FAIL", "issues": [],
            "fix": ""}


def _build_thermal_rows(state: dict) -> List[dict]:
    """THERMAL duty / stability analysis rows, sourced ENTIRELY from contract quantities.

    INTENT (2026-07-26): the Engineering Analysis tab declared itself out-of-scope on a
    STRUCTURAL test alone ("no pressure/structural principals"), which excluded it from
    the dossier floor. That is only half an applicability assessment: a device whose core
    function is holding a culture at a setpoint has a THERMAL duty path, and a chartered
    engineer expects to see it closed. The engine already DERIVES these figures — this
    renders the analysis it had computed and was silently discarding.

    Every value is READ from orchestratorContract.quantities; nothing is invented and no
    datasheet number is assumed. A design that carries none of these quantities returns []
    (universal — keyed on the quantity nouns, never on a product class).

    Rows are (claim, target, achieved, verdict) tuples over the duty chain:
      demand   — steady-state heat loss the design must replace at setpoint
      capacity — installed heating/cooling power
      margin   — capacity / demand (the row that actually proves the design closes)
      stability— achieved control band against the brief's requirement
    """
    q = (state.get("orchestratorContract") or {}).get("quantities") or {}

    def _qv(key):
        v = q.get(key)
        if isinstance(v, dict):
            return num(v.get("value")), str(v.get("unit") or "")
        n = num(v)
        return (n, "") if n is not None else (None, "")

    _setpoint, _u_sp = _qv("culture_temperature_c")
    if _setpoint is None:
        _setpoint, _u_sp = _qv("incubation_temperature_c")
    _loss, _u_loss = _qv("vessel_heat_loss_w")
    _net, _ = _qv("net_heating_required_w")
    _cap, _u_cap = _qv("peak_heater_power_w")
    _stab, _u_stab = _qv("temperature_stability_k")
    _amb, _ = _qv("enclosure_internal_temp_c")
    _agit, _ = _qv("agitation_power_w")
    _demand = _net if _net is not None else _loss
    if _setpoint is None or _demand is None or _cap is None:
        return []          # no thermal duty path in this design — nothing to analyse

    # Each row carries NUMERIC target/achieved plus a comparator so the rendered Verdict
    # is a LIVE Excel formula over its own two cells, never a baked "PASS" string (the
    # live-check gate rejects bare verdict literals — correctly: a hardcoded verdict is
    # exactly the kind of unfalsifiable claim this dossier must not ship).
    rows: List[dict] = []
    if _amb is not None:
        rows.append({
            "claim": "Driving ΔT — setpoint above enclosure ambient",
            "basis": "culture_temperature_c − enclosure_internal_temp_c (contract)",
            "target_num": 0.0, "achieved_num": round(_setpoint - _amb, 2),
            "unit": "K", "cmp": "ge",
            "note": f"setpoint {_setpoint:.1f} °C over ambient {_amb:.1f} °C — heating duty",
        })
    rows.append({
        "claim": "Steady-state heat demand at setpoint",
        "basis": ("net_heating_required_w (contract)" if _net is not None
                  else "vessel_heat_loss_w (contract)"),
        "target_num": round(_cap, 3), "achieved_num": round(_demand, 3),
        "unit": "W", "cmp": "le",
        "note": (f"vessel loss {_loss:.3f} W" if _loss is not None else "")
                + (f", agitation gain {_agit:.3f} W" if _agit is not None else "")
                + " — must not exceed installed capacity",
    })
    _margin = (_cap / _demand) if _demand > 0 else None
    if _margin is not None:
        rows.append({
            "claim": "Capacity margin — installed ÷ demand",
            "basis": "peak_heater_power_w ÷ demand — the row that proves the duty closes",
            "target_num": 1.20, "achieved_num": round(_margin, 2),
            "unit": "×", "cmp": "ge",
            "note": f"{_cap:.2f} W installed against {_demand:.3f} W demand",
        })
    if _stab is not None:
        rows.append({
            "claim": "Closed-loop temperature stability",
            "basis": "temperature_stability_k (contract) vs the control requirement",
            "target_num": 0.5, "achieved_num": round(_stab, 3),
            "unit": "K", "cmp": "le",
            "note": f"achieved band about the {_setpoint:.1f} °C setpoint",
        })
    for _r in rows:
        _r["verdict"] = ("PASS" if (
            (_r["achieved_num"] >= _r["target_num"]) if _r["cmp"] == "ge"
            else (_r["achieved_num"] <= _r["target_num"])) else "FAIL")
    return rows


def _eval_thermal_rows(rows: List[dict]) -> Optional[dict]:
    """Column-contract for the thermal duty section: a row PASSES when its own verdict
    is PASS. Unlike the ISO 2768 tolerance block this is NOT auto-pass boilerplate — an
    under-powered design (capacity < 1.2 × demand) or a control band wider than the
    requirement FAILS here and drags the tab down, which is the point."""
    if not rows:
        return None
    contract = [
        ("Claim", "computed", "the thermal duty chain: ΔT → demand → capacity → margin → stability"),
        ("Achieved", "computed", "read from orchestratorContract.quantities — no assumed datasheet values"),
        ("Verdict", "computed", "capacity ≥ 1.20 × demand; stability within the brief's band"),
    ]
    n_total = len(rows)
    per_row = {idx: {"verdict": str(r.get("verdict") or "FAIL"),
                     "reasons": ([] if str(r.get("verdict")) == "PASS"
                                 else [str(r.get("claim") or "thermal row")])}
               for idx, r in enumerate(rows)}
    n_pass = sum(1 for r in rows if str(r.get("verdict")) == "PASS")
    score = _contract_score(n_pass, n_total)
    return {"tab": "Engineering Analysis", "contract": contract, "rows": per_row,
            "n_pass": n_pass, "n_total": n_total, "score": score,
            "status": "PASS" if (score or 0) >= 8 else "FAIL", "issues": [],
            "fix": ""}


def _eval_engineering_analysis_contract(_run_dir: str, state: dict) -> Optional[dict]:
    """Registry adapter — build() calls this BEFORE any tab renders (the same idiom as
    the Risk & Regulatory / Line & velocity / BoM ledger contracts). Combines the THREE
    Engineering Analysis sections (stress-strain / pump performance / design & tolerance)
    into ONE tab-level arithmetic score — namespaced row keys ('stress'|'pump'|
    'tolerance', idx) so the renderer's per-section Row-check lookups can never collide,
    while n_pass/n_total (and therefore the sheet's single quality chip) blend all three,
    the same 'one score per sheet' rule every other tab follows."""
    sections = [
        ("stress", _eval_engineering_analysis_rows(_build_engineering_analysis_rows(state))),
        ("pump", _eval_pump_rows(_build_pump_rows(state))),
        ("thermal", _eval_thermal_rows(_build_thermal_rows(state))),
        ("tolerance", _eval_tolerance_rows(_build_tolerance_rows(state))),
    ]
    present = [(tag, res) for tag, res in sections if res]
    if not present:
        return None
    # ── S8 (council M6, 2026-07-20): the tolerance section auto-PASSes every fab row (ISO
    # 2768-1 "applies regardless of size" boilerplate), so on a design with NO stress and
    # NO pump substance it alone mints a 10 over an EMPTY stress table (the 2150 Goodhart:
    # "Engineering Analysis 10/10" while zero parts were stress-checked). Boilerplate cannot
    # carry this tab to a clean ≥8 by itself. Universal — keyed on which sections have real
    # content, never a class name.
    if {tag for tag, _ in present} == {"tolerance"}:
        _eq = (state.get("engineeringContract") or {}).get("shared_quantities") or {}
        _encl = _eq.get("enclosure_volume_m3")
        _encl_v = num(_encl.get("value")) if isinstance(_encl, dict) else num(_encl)
        _dev = bool(state.get("isInstrumentDevice")) or (_encl_v is not None and 0 < float(_encl_v) < 1.0)
        _tol_res = next(res for tag, res in present if tag == "tolerance")
        _note = ("this tab performed NO stress/structural or performance analysis — only the "
                 "ISO 2768-1 general-tolerance boilerplate (which passes every fabricated row "
                 "regardless of size); the stress/allowables table is empty")
        _tol_rows = {("tolerance", i): rv for i, rv in (_tol_res.get("rows") or {}).items()}
        _tol_contract = _tol_res.get("contract") or []
        _tol_np = _tol_res.get("n_pass") or 0
        _tol_nt = _tol_res.get("n_total") or 0
        # PRINCIPALS-EXIST CHECK (Cursor afternoon audit, 2026-07-20): a device is OOS ONLY
        # when it has NO pressure-containing / structural principal to stress-analyse. If the
        # BoM DOES carry such a principal (a pressure vessel / reactor / load-bearing member)
        # but the stress section is empty, that is a real GAP (the sizing didn't emit P=/σ=),
        # not out-of-scope — cap it like a plant, never OOS. Keyed on the part noun, not class.
        _PRESSURE_STRUCT_RX = re.compile(
            r"pressure\s*vessel|reactor|autoclave|\bboiler\b|accumulator|receiver|"
            r"load[\s-]?bearing|structural\s*(?:frame|member|beam|column)|pressuris|"
            r"\bmanifold\b.*pressure|high[\s-]?pressure", re.I)
        _has_principal = any(
            _PRESSURE_STRUCT_RX.search(str((rv or {}).get("name") or rv or ""))
            for rv in ((_build_tolerance_rows(state)) or []))
        # DOMAIN-APPLICABILITY, NOT JUST STRESS (2026-07-26, council unanimous). The old
        # rule declared the WHOLE tab out-of-scope on a STRUCTURAL test alone — "no
        # pressure/structural principals" — which excluded it from the dossier floor
        # entirely. Stress being inapplicable does not make ENGINEERING ANALYSIS
        # inapplicable: the organoid carries a Peltier TEC, heater block, thermal
        # insulation, interface pad and a 37 °C closed-loop requirement, so its thermal
        # duty is squarely in scope and its absence is a real gap, not a non-applicability.
        # A tab may claim OOS only when NO applicable analysis domain remains; the thermal
        # section above returns [] exactly when there is no duty path to close, so its
        # presence here is the deterministic "thermal domain applies" signal.
        _thermal_applies = bool(_build_thermal_rows(state))
        if _dev and not _has_principal and not _thermal_applies:
            # A device with no pressure-containing / structural principal AND no thermal
            # duty path genuinely has nothing to analyse → VERIFIED OUT-OF-SCOPE (excluded
            # from the floor, like the other device-scale OOS tabs), never a fake 10.
            # Full-shape dict so the generic contract consumer never KeyErrors.
            return {"tab": "Engineering Analysis", "scored": False, "score": 8, "status": "PASS",
                    "rows": _tol_rows, "contract": _tol_contract, "n_pass": _tol_np, "n_total": _tol_nt,
                    "issues": [_note + " — VERIFIED out of scope for this device (no pressure/"
                               "structural principals); general tolerances apply per ISO 2768-1"],
                    "mech": "engineering analysis — verified out of scope (no principals to stress-analyse)",
                    "fix": ""}
        # A NON-device (structural/plant) design — OR a device that DOES carry a pressure/
        # structural principal — that produced ZERO stress rows is a REAL gap, not a
        # boilerplate pass or an out-of-scope: cap below the ship floor with an honest issue.
        return {"tab": "Engineering Analysis", "score_cap": 4.0, "score": 4.0, "status": "FAIL",
                "rows": _tol_rows, "contract": _tol_contract, "n_pass": _tol_np, "n_total": _tol_nt,
                "issues": [_note + " — a structural/plant design must carry a real "
                           "stress/allowables analysis of its principal parts"],
                "mech": "engineering analysis — tolerance boilerplate only (no stress/performance)",
                "fix": ("emit principal pressure/structural parts with P=/σ= figures in their "
                        "materials-take-off basis (requirements_bom.py::_materials_takeoff)")}
    n_pass = sum(res["n_pass"] for _, res in present)
    n_total = sum(res["n_total"] for _, res in present)
    rows: Dict[Any, dict] = {}
    contract: List[tuple] = []
    issues: List[str] = []
    fixes: List[str] = []
    for tag, res in present:
        for idx, rv in (res.get("rows") or {}).items():
            rows[(tag, idx)] = rv
        contract.extend(res.get("contract") or [])
        issues.extend(res.get("issues") or [])
        if res.get("fix"):
            fixes.append(res["fix"])
    score = _contract_score(n_pass, n_total)
    return {"tab": "Engineering Analysis", "contract": contract, "rows": rows,
            "n_pass": n_pass, "n_total": n_total, "score": score,
            "status": "PASS" if (score or 0) >= 8 else "FAIL", "issues": issues,
            "fix": " · ".join(dict.fromkeys(fixes))}


def tab_engineering_analysis(wb: Workbook, state: dict, run_dir: str) -> bool:
    """Engineering Analysis — safety factor / allowables + stress-strain (Tristan
    2026-07-06, priorities #3 + #6). UNIVERSAL: keyed on the BoM's own fabrication-
    physics fields + material string (never a per-class table); a class with no
    physics-sized shell in its BoM legitimately skips (returns False), same idiom as
    Electrical / Process schedules."""
    rows = _build_engineering_analysis_rows(state)
    pump_rows = _build_pump_rows(state)
    tol_rows = _build_tolerance_rows(state)
    if not rows and not pump_rows and not tol_rows:
        return False
    cres = _CONTRACT_RESULTS.get("Engineering Analysis") or _eval_engineering_analysis_contract(run_dir, state) or {}
    crows = cres.get("rows") or {}

    ws = wb.create_sheet("Engineering Analysis")
    set_widths(ws, {"A": 10, "B": 30, "C": 6, "D": 12, "E": 20, "F": 11, "G": 11,
                    "H": 11, "I": 11, "J": 13, "K": 14, "L": 12, "M": 34, "N": 46,
                    "O": 34})
    subtitle = (
        "Every PRINCIPAL pressure-containing / structural part this BoM sized from its "
        "own take-off geometry (wall thickness, mass, diameter — never a per-class "
        "table): the material's allowable stress with an EXPLICIT safety factor (edit "
        "B5/B6 below — metallic rows recompute live), the independent thin-wall actual/"
        "design stress at the adopted wall, and the utilisation. A material outside the "
        "reference table, or a part whose take-off carries no design pressure, renders "
        "'DATA NOT IN CONTRACT' — never a fabricated number."
    )
    if cres:
        subtitle += " " + _contract_note(cres)
    title_row(ws, "Engineering Analysis — safety factor, allowables & stress-strain", 15,
              subtitle)
    r = 4

    # ── EXPLICIT safety-factor inputs — live-editable; every metallic row below
    # recomputes its Allowable/Utilisation/Verdict from these two cells. ──
    sub_banner(ws, r, "Safety factor — explicit, editable input (ASME BPVC VIII Div.1 "
                      "UG-23 basis)", 15)
    r += 1
    ws.cell(r, 1, "SF applied to UTS").font = FONT_SUB
    sf_uts_cell = ws.cell(r, 2, _EA_SF_UTS)
    sf_uts_cell.fill = FILL_RESULT
    sf_uts_ref = f"$B${r}"
    nt = ws.cell(r, 3, "Allowable (metallic) = MIN(UTS ÷ SF-UTS, Yield ÷ SF-yield) — "
                       "edit either cell and every metallic row below recomputes.")
    nt.font = FONT_NOTE
    r += 1
    ws.cell(r, 1, "SF applied to yield").font = FONT_SUB
    sf_yield_cell = ws.cell(r, 2, _EA_SF_YIELD)
    sf_yield_cell.fill = FILL_RESULT
    sf_yield_ref = f"$B${r}"
    r += 2

    sub_banner(ws, r, "Safety factor & allowables — per principal part", 15)
    r += 1
    header(ws, r, _EA_HDR)
    r += 1
    n_ok = 0
    row1 = r
    for idx, rec in enumerate(rows):
        cr = crows.get(("stress", idx)) or {}
        row_ok = cr.get("verdict") == "PASS"
        if row_ok:
            n_ok += 1
        ws.cell(r, 1, clean_cell(rec["tag"])).border = BORDER
        pc = ws.cell(r, 2, clean_cell(rec["name"])); pc.alignment = WRAP_TOP; pc.border = BORDER
        ws.cell(r, 3, rec["qty"]).border = BORDER
        ws.cell(r, 4, clean_cell(rec["family"] or "—")).border = BORDER
        ws.cell(r, 5, clean_cell(rec["material"])).border = BORDER
        yc = ws.cell(r, 6, rec["yield_mpa"]); yc.border = BORDER
        if rec["yield_mpa"] is not None:
            yc.number_format = FMT_DEC1
        uc = ws.cell(r, 7, rec["uts_mpa"]); uc.border = BORDER
        if rec["uts_mpa"] is not None:
            uc.number_format = FMT_DEC1
        if rec["family"] == "metallic":
            sfu = ws.cell(r, 8, f"={sf_uts_ref}")
            sfy = ws.cell(r, 9, f"={sf_yield_ref}")
            alw = ws.cell(r, 10, f"=MIN(G{r}/{sf_uts_ref},F{r}/{sf_yield_ref})")
            alw.number_format = FMT_DEC1
        else:
            sfu = ws.cell(r, 8, "n/a — no UTS/yield SF ratio for this material family")
            sfy = ws.cell(r, 9, "n/a")
            alw = ws.cell(r, 10, rec["allowable_mpa"])
            if rec["allowable_mpa"] is not None:
                alw.number_format = FMT_DEC1
        sfu.border = BORDER; sfy.border = BORDER; alw.border = BORDER
        act = ws.cell(r, 11, rec["actual_mpa"]); act.border = BORDER
        if rec["actual_mpa"] is not None:
            act.number_format = FMT_DEC2
        util = ws.cell(r, 12, f'=IF(AND(ISNUMBER(K{r}),ISNUMBER(J{r}),J{r}<>0),'
                              f'100*K{r}/J{r},"")')
        util.number_format = FMT_DEC1
        util.border = BORDER
        vc = ws.cell(r, 13, f'=IF(ISNUMBER(L{r}),IF(L{r}<=100,"PASS",'
                            f'"FAIL — actual stress exceeds the code allowable"),'
                            f'"DATA NOT IN CONTRACT — actual/allowable stress not derivable")')
        vc.border = BORDER
        vc.font = FONT_PASS if row_ok else FONT_FAIL
        vc.fill = FILL_PASS if row_ok else FILL_FAIL
        cb = ws.cell(r, 14, clean_cell(rec["code_basis"])); cb.alignment = WRAP_TOP
        cb.border = BORDER
        _reasons = "; ".join(cr.get("reasons") or [])
        rc = ws.cell(r, 15, fx_verdict(
            [f"ISNUMBER(J{r})", f"ISNUMBER(K{r})", f"ISNUMBER(L{r})",
             f"IFERROR(ABS(L{r}-100*K{r}/J{r})<0.5,FALSE())", f'EXACT(M{r},"PASS")'],
            f'"{_xq(_reasons or "see Verdict / Code basis", 160)}"'))
        rc.alignment = WRAP_TOP
        rc.border = BORDER
        rc.font = FONT_PASS if row_ok else FONT_FAIL
        rc.fill = FILL_PASS if row_ok else FILL_FAIL
        if not row_ok:
            for col in range(1, 13):
                ws.cell(r, col).fill = FILL_FAIL
        longest = max(len(str(rec["name"])), len(str(rec["code_basis"])), len(_reasons))
        if longest > 46:
            ws.row_dimensions[r].height = min(-(-longest // 46), 5) * 14.5
        r += 1
    _register_check_range(ws.title, "O", row1, r - 1, n_pass=n_ok, n_total=len(rows))
    _cf_verdict(ws, f"O{row1}:O{r - 1}")
    ws.auto_filter.ref = f"A{row1 - 1}:O{r - 1}"
    r += 1

    # ── STRESS-STRAIN CHARACTERISATION — the universal material table + per-material
    # idealised curve with THIS run's own design operating point(s) marked. ──
    sub_banner(ws, r, "Stress-strain characterisation — material curve with the design "
                      "operating point marked", 15)
    r += 1
    note = ws.cell(r, 1, clean_cell(
        "A universal material-property lookup (E, yield, UTS, elongation — never a "
        "per-class table), keyed by the material each part above actually uses. The "
        "curve is an idealised engineering stress-strain line (elastic origin → yield "
        "→ UTS at the material's stated elongation; a non-metallic composite/concrete "
        "has no distinct yield so the line runs straight to its ultimate/characteristic "
        "strength). The design operating point(s) plotted on each curve are this run's "
        "own actual stress from the table above — how far below its material's limit "
        "each part sits."))
    note.font = Font(italic=True, size=9, color="555555")
    note.alignment = WRAP_TOP
    ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=15)
    ws.row_dimensions[r].height = 46
    r += 2

    seen_mats: List[str] = []
    for rec in rows:
        if rec.get("material_key") and rec["material_key"] not in seen_mats:
            seen_mats.append(rec["material_key"])

    if seen_mats:
        sub_banner(ws, r, "Material property reference (universal — keyed by material, "
                          "not class)", 7)
        r += 1
        header(ws, r, _EA_MAT_HDR)
        r += 1
        for mk in seen_mats:
            props = _EA_MATERIALS[mk]
            ws.cell(r, 1, clean_cell(props["display"])).border = BORDER
            ws.cell(r, 2, clean_cell(props["family"])).border = BORDER
            ec = ws.cell(r, 3, props["e_gpa"]); ec.number_format = FMT_DEC1; ec.border = BORDER
            yc = ws.cell(r, 4, props["yield_mpa"]); yc.border = BORDER
            if props["yield_mpa"] is not None:
                yc.number_format = FMT_DEC1
            uc = ws.cell(r, 5, props["uts_mpa"]); uc.border = BORDER
            if props["uts_mpa"] is not None:
                uc.number_format = FMT_DEC1
            pc2 = ws.cell(r, 6, props["elong_pct"]); pc2.number_format = FMT_DEC2
            pc2.border = BORDER
            cc = ws.cell(r, 7, clean_cell(props["code"])); cc.alignment = WRAP_TOP
            cc.border = BORDER
            r += 1
        r += 1

    from openpyxl.chart import ScatterChart, Reference, Series
    charts_added = 0
    for mk in seen_mats:
        props = _EA_MATERIALS[mk]
        e_mpa = props["e_gpa"] * 1000.0
        parts_here = [rc for rc in rows
                      if rc.get("material_key") == mk and rc.get("actual_mpa") is not None]
        sub_banner(ws, r, f"{props['display']} — stress-strain", 6)
        r += 1
        header(ws, r, _EA_CURVE_HDR)
        curve_hdr = r
        r += 1
        curve_first = r
        if props["yield_mpa"]:
            pts = [(0.0, 0.0),
                   (props["yield_mpa"] / e_mpa * 100.0, props["yield_mpa"]),
                   (props["elong_pct"], props["uts_mpa"])]
        else:
            pts = [(0.0, 0.0), (props["elong_pct"], props["uts_mpa"])]
        for i, (x, y) in enumerate(pts):
            ws.cell(r, 1, i + 1)
            xcell = ws.cell(r, 2, x); xcell.number_format = FMT_DEC2
            ycell = ws.cell(r, 3, y); ycell.number_format = FMT_DEC1
            r += 1
        curve_last = r - 1
        r += 1
        op_first = op_last = None
        op_labels: List[str] = []
        if parts_here:
            header(ws, r, _EA_CURVE_HDR)
            r += 1
            op_first = r
            for i, prt in enumerate(parts_here):
                strain = prt["actual_mpa"] / e_mpa * 100.0
                ws.cell(r, 1, i + 1)
                xcell = ws.cell(r, 2, strain); xcell.number_format = "0.0000"
                ycell = ws.cell(r, 3, prt["actual_mpa"]); ycell.number_format = FMT_DEC2
                r += 1
                util_txt = (f"{prt['utilisation_pct']:.1f}%"
                           if prt.get("utilisation_pct") is not None else "—")
                op_labels.append(f"#{i + 1} = {prt.get('tag') or prt.get('name')} "
                                 f"(utilisation {util_txt})")
            op_last = r - 1
        src_txt = (f"Curve: idealised engineering stress-strain from the universal "
                  f"material table ({props['code']}). Operating point(s): this run's own "
                  f"actual/design stress for every '{props['display']}' part above" +
                  (" — " + "; ".join(op_labels) if op_labels else " (none derivable).") )
        src = ws.cell(r, 1, clean_cell(src_txt))
        src.font = FONT_NOTE
        src.alignment = WRAP_TOP
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=8)
        ws.row_dimensions[r].height = 32
        r += 1

        ch = ScatterChart()
        ch.title = f"{props['display']} — stress vs strain (operating point marked)"
        ch.height, ch.width = 8, 14
        ch.x_axis.title = "Strain (%)"
        ch.y_axis.title = "Stress (MPa)"
        xref = Reference(ws, min_col=2, min_row=curve_first, max_row=curve_last)
        yref = Reference(ws, min_col=3, min_row=curve_first, max_row=curve_last)
        s1 = Series(yref, xref, title="Material curve (idealised)")
        ch.series.append(s1)
        if op_first is not None:
            xref2 = Reference(ws, min_col=2, min_row=op_first, max_row=op_last)
            yref2 = Reference(ws, min_col=3, min_row=op_first, max_row=op_last)
            s2 = Series(yref2, xref2, title="Design operating point(s)")
            ch.series.append(s2)
        style_chart(ch, legend=True)
        # style_chart blanks every marker/line to one hygiene default — re-apply the
        # operating-point's marker-only style AFTER it (it would otherwise be wiped).
        if op_first is not None:
            s2 = ch.series[-1]
            s2.marker.symbol = "diamond"
            s2.marker.size = 9
            s2.graphicalProperties.line.noFill = True
        ws.add_chart(ch, f"E{curve_hdr}")
        charts_added += 1
        r = max(r, curve_hdr + 16)

    # ── THERMAL DUTY & CONTROL (2026-07-26) ───────────────────────────────────────────
    # The tab used to declare itself out-of-scope whenever no pressure/structural
    # principal existed, which excluded it from the dossier floor. For a device whose
    # core function is holding a culture at a setpoint the thermal duty IS the
    # engineering analysis, and the engine already derived every figure below — it was
    # simply never rendered. Values are READ from orchestratorContract.quantities; a
    # design with no duty path renders nothing (universal, noun-keyed).
    _therm_rows = _build_thermal_rows(state)
    if _therm_rows:
        sub_banner(ws, r, "Thermal duty & closed-loop control — demand, installed "
                          "capacity, margin & stability", 15)
        r += 1
        _tnote = ws.cell(r, 1, clean_cell(
            "The duty chain this design must close to hold its setpoint: the driving ΔT, "
            "the steady-state heat the design must replace, the installed capacity, the "
            "margin between them (the row that actually proves the design works), and the "
            "achieved closed-loop stability. Every figure is read from the engineering "
            "contract — no assumed datasheet performance, no fabricated coefficients."))
        _tnote.font = FONT_NOTE
        _tnote.alignment = WRAP_TOP
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=15)
        r += 2
        header(ws, r, ["Claim", "Basis / source", "Target", "Achieved", "Unit",
                       "Verdict", "Notes", "Row check"])
        r += 1
        _t_first = r
        _n_therm_ok = 0
        for _ti, _tr in enumerate(_therm_rows):
            _cr_t = crows.get(("thermal", _ti)) or {}
            _ok_t = _cr_t.get("verdict") == "PASS"
            if _ok_t:
                _n_therm_ok += 1
            ws.cell(r, 1, clean_cell(_tr.get("claim"))).border = BORDER
            _bc = ws.cell(r, 2, clean_cell(_tr.get("basis")))
            _bc.alignment = WRAP_TOP
            _bc.border = BORDER
            _tc = ws.cell(r, 3, _tr.get("target_num"))
            _tc.number_format = FMT_NUM
            _tc.border = BORDER
            _acn = ws.cell(r, 4, _tr.get("achieved_num"))
            _acn.number_format = FMT_NUM
            _acn.border = BORDER
            ws.cell(r, 5, clean_cell(_tr.get("unit"))).border = BORDER
            # LIVE verdict over THIS row's own target/achieved cells — edit D and the
            # verdict recomputes. A baked "PASS" string is rejected by the live-check gate.
            _cmp_op = ">=" if _tr.get("cmp") == "ge" else "<="
            _tv = ws.cell(r, 6, f'=IF(D{r}{_cmp_op}C{r},"PASS","FAIL")')
            _tv.border = BORDER
            _tv.fill, _tv.font = ((FILL_PASS, FONT_PASS) if str(_tr.get("verdict")) == "PASS"
                                  else (FILL_FAIL, FONT_FAIL))
            _nc = ws.cell(r, 7, clean_cell(_tr.get("note")))
            _nc.alignment = WRAP_TOP
            _nc.border = BORDER
            _rc_t = ws.cell(r, 8, fx_verdict(
                [f'LEN(TRIM(A{r}&""))>0', f'ISNUMBER(D{r})',
                 f'EXACT(TRIM(F{r}),"PASS")'],
                '"thermal row unproven — missing claim, achieved value, or verdict"'))
            _rc_t.border = BORDER
            _rc_t.font = FONT_PASS if _ok_t else FONT_FAIL
            _rc_t.fill = FILL_PASS if _ok_t else FILL_FAIL
            r += 1
        _register_check_range(ws.title, "H", _t_first, r - 1,
                              n_pass=_n_therm_ok, n_total=len(_therm_rows))
        r += 1

    # ── PUMP / ROTATING-EQUIPMENT PERFORMANCE (Tristan priority #4) ────────────────────
    if pump_rows:
        sub_banner(ws, r, "Pump / rotating-equipment performance — duty, efficiency & "
                          "H-Q curve", 15)
        r += 1
        pnote = ws.cell(r, 1, clean_cell(
            "Every pump this BoM specifies a duty for (plus any fan/blower/compressor "
            "whose OWN row carries flow, head/pressure AND power together): duty flow Q, "
            "head H (converted to a water-equivalent metre figure when the row's own duty "
            "is stated as a pressure), and shaft/electrical power — pulled from the row's "
            "own requirement text first, else a contract quantity its own name joins to; "
            "never invented. Hydraulic power = ρ·g·Q·H (SI, water ρ=1000 kg/m³) and "
            "efficiency η = hydraulic ÷ shaft power are LIVE formulas (edit Q/H/power and "
            "every row recomputes). A duty field genuinely absent from this run's own data "
            "renders 'DATA NOT IN CONTRACT' — never a fabricated number."))
        pnote.font = Font(italic=True, size=9, color="555555")
        pnote.alignment = WRAP_TOP
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=15)
        ws.row_dimensions[r].height = 46
        r += 2

        header(ws, r, _PUMP_HDR)
        r += 1
        prow1 = r
        n_pump_ok = 0
        pump_curves: List[Tuple[str, float, float]] = []   # (name, q_duty_m3h, h_duty_m)
        for idx, rec in enumerate(pump_rows):
            cr = crows.get(("pump", idx)) or {}
            row_ok = cr.get("verdict") == "PASS"
            if row_ok:
                n_pump_ok += 1
            ws.cell(r, 1, clean_cell(rec["tag"])).border = BORDER
            pc = ws.cell(r, 2, clean_cell(rec["name"])); pc.alignment = WRAP_TOP; pc.border = BORDER
            ws.cell(r, 3, rec["qty"]).border = BORDER
            ws.cell(r, 4, clean_cell(rec["family"])).border = BORDER
            qc = ws.cell(r, 5, rec["q_m3h"] if rec["q_m3h"] is not None else "DATA NOT IN CONTRACT")
            if rec["q_m3h"] is not None:
                qc.number_format = FMT_DEC2
            qc.border = BORDER
            hc = ws.cell(r, 6, rec["head_used_m"] if rec["head_used_m"] is not None else "DATA NOT IN CONTRACT")
            if rec["head_used_m"] is not None:
                hc.number_format = FMT_DEC2
            hc.border = BORDER
            if rec["q_m3h"] is not None and rec["head_used_m"] is not None:
                phyd = ws.cell(r, 7, f"=1000*9.81*E{r}/3600*F{r}/1000")
                phyd.number_format = FMT_DEC2
            else:
                phyd = ws.cell(r, 7, "DATA NOT IN CONTRACT")
            phyd.border = BORDER
            psh = ws.cell(r, 8, rec["p_shaft_kw"] if rec["p_shaft_kw"] is not None else "DATA NOT IN CONTRACT")
            if rec["p_shaft_kw"] is not None:
                psh.number_format = FMT_DEC2
            psh.border = BORDER
            eta = ws.cell(r, 9, f'=IF(AND(ISNUMBER(G{r}),ISNUMBER(H{r}),H{r}<>0),'
                                f'100*G{r}/H{r},"DATA NOT IN CONTRACT")')
            eta.number_format = FMT_DEC1
            eta.border = BORDER
            npshr = ws.cell(r, 10, rec["npshr_m"] if rec["npshr_m"] is not None else "DATA NOT IN CONTRACT")
            if rec["npshr_m"] is not None:
                npshr.number_format = FMT_DEC2
            npshr.border = BORDER
            # INTENT: NPSHa margin needs suction elevation + vapour pressure the
            # contract does not yet carry. An honest N/A-with-basis (passes the cell
            # contract) — never 'DATA NOT IN CONTRACT', which is an identified gap that
            # must block a perfect 10 (grade-inflation ban 2026-07-09).
            marg = ws.cell(r, 11, "N/A — suction-side elevation / vapour pressure "
                                  "not in this run's own contract")
            marg.alignment = WRAP_TOP
            marg.border = BORDER
            vc = ws.cell(r, 12, f'=IF(AND(ISNUMBER(E{r}),ISNUMBER(F{r}),ISNUMBER(H{r}),ISNUMBER(I{r})),'
                                f'IF(AND(I{r}>0,I{r}<=100),"PASS",'
                                f'"FAIL — computed efficiency outside the physically possible 0-100% band"),'
                                f'"N/A — see Basis/source for the missing duty field")')
            vc.border = BORDER
            vc.alignment = WRAP_TOP
            vc.font = FONT_PASS if row_ok else FONT_FAIL
            vc.fill = FILL_PASS if row_ok else FILL_FAIL
            bc = ws.cell(r, 13, clean_cell(rec["basis"])); bc.alignment = WRAP_TOP; bc.border = BORDER
            _preasons = "; ".join(rec.get("reasons") or [])
            rc = ws.cell(r, 14, fx_verdict([f'EXACT(L{r},"PASS")'],
                                           f'"{_xq(_preasons or "see Verdict / Basis", 160)}"'))
            rc.alignment = WRAP_TOP
            rc.border = BORDER
            rc.font = FONT_PASS if row_ok else FONT_FAIL
            rc.fill = FILL_PASS if row_ok else FILL_FAIL
            if not row_ok:
                for col in range(1, 12):
                    ws.cell(r, col).fill = FILL_FAIL
            if rec["q_m3h"] is not None and rec["head_used_m"] is not None:
                pump_curves.append((f"{rec['tag']} {rec['name']}", rec["q_m3h"], rec["head_used_m"]))
            longest = max(len(str(rec["name"])), len(str(rec["basis"])), len(_preasons))
            if longest > 46:
                ws.row_dimensions[r].height = min(-(-longest // 46), 5) * 14.5
            r += 1
        _register_check_range(ws.title, "N", prow1, r - 1, n_pass=n_pump_ok, n_total=len(pump_rows))
        _cf_verdict(ws, f"N{prow1}:N{r - 1}")
        ws.auto_filter.ref = f"A{prow1 - 1}:N{r - 1}"
        r += 1

        if pump_curves:
            sub_banner(ws, r, "Pump curve — representative system + pump curve marked at "
                              "the duty point (BEP)", 6)
            r += 1
            note3 = ws.cell(r, 1, clean_cell(
                "SYSTEM curve modelled as a pure friction-dominated quadratic through the "
                "origin and the duty point: H = H_duty × (Q/Q_duty)² — no separate static-"
                "head split is stated in this row's own basis. PUMP curve is a "
                "representative centrifugal shape falling from an assumed shutoff head "
                "1.2 × H_duty to the SAME duty point (an affinity-law quadratic): H = "
                "H_shutoff − (H_shutoff − H_duty) × (Q/Q_duty)². The duty point itself "
                "(the Best Efficiency Point, BEP, for this exercise) is this run's own Q "
                "and H — marked as a separate series."))
            note3.font = FONT_NOTE
            note3.alignment = WRAP_TOP
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=8)
            ws.row_dimensions[r].height = 40
            r += 2

            for name, q_duty, h_duty in pump_curves:
                sub_banner(ws, r, f"{name} — H-Q curve", 6)
                r += 1
                header(ws, r, _PUMP_CURVE_HDR)
                curve_hdr = r
                r += 1
                sys_first = r
                for i in range(9):
                    q = q_duty * (i / 4.0)
                    h_sys = h_duty * ((q / q_duty) ** 2 if q_duty else 0.0)
                    ws.cell(r, 1, i + 1)
                    ws.cell(r, 2, round(q, 3)).number_format = FMT_DEC2
                    ws.cell(r, 3, round(h_sys, 3)).number_format = FMT_DEC2
                    r += 1
                sys_last = r - 1
                r += 1
                header(ws, r, _PUMP_CURVE_HDR)
                r += 1
                pump_first = r
                h_shutoff = h_duty * 1.2
                for i in range(9):
                    q = q_duty * (i / 4.0)
                    h_pump = h_shutoff - (h_shutoff - h_duty) * ((q / q_duty) ** 2 if q_duty else 0.0)
                    ws.cell(r, 1, i + 1)
                    ws.cell(r, 2, round(q, 3)).number_format = FMT_DEC2
                    ws.cell(r, 3, round(h_pump, 3)).number_format = FMT_DEC2
                    r += 1
                pump_last = r - 1
                r += 1
                header(ws, r, _PUMP_CURVE_HDR)
                r += 1
                bep_row = r
                ws.cell(r, 1, 1)
                ws.cell(r, 2, round(q_duty, 3)).number_format = FMT_DEC2
                ws.cell(r, 3, round(h_duty, 3)).number_format = FMT_DEC2
                r += 2

                ch2 = ScatterChart()
                ch2.title = f"{name} — H-Q curve (BEP marked)"
                ch2.height, ch2.width = 8, 14
                ch2.x_axis.title = "Flow Q (m³/h)"
                ch2.y_axis.title = "Head H (m)"
                sxref = Reference(ws, min_col=2, min_row=sys_first, max_row=sys_last)
                syref = Reference(ws, min_col=3, min_row=sys_first, max_row=sys_last)
                ch2.series.append(Series(syref, sxref, title="System curve (modelled)"))
                pxref = Reference(ws, min_col=2, min_row=pump_first, max_row=pump_last)
                pyref = Reference(ws, min_col=3, min_row=pump_first, max_row=pump_last)
                ch2.series.append(Series(pyref, pxref, title="Pump curve (representative)"))
                bxref = Reference(ws, min_col=2, min_row=bep_row, max_row=bep_row)
                byref = Reference(ws, min_col=3, min_row=bep_row, max_row=bep_row)
                ch2.series.append(Series(byref, bxref, title="Duty point (BEP)"))
                style_chart(ch2, legend=True)
                s3 = ch2.series[-1]
                s3.marker.symbol = "diamond"
                s3.marker.size = 9
                s3.graphicalProperties.line.noFill = True
                ws.add_chart(ch2, f"E{curve_hdr}")
                r = max(r, curve_hdr + 16)

    # ── DESIGN & TOLERANCE (Tristan priority #5) ───────────────────────────────────────
    if tol_rows:
        sub_banner(ws, r, "Design & tolerance — general manufacturing tolerances (ISO "
                          "2768) for every fabricated part", 15)
        r += 1
        ws.cell(r, 1, "ISO 2768-1 general-tolerance class").font = FONT_SUB
        cls_cell = ws.cell(r, 2, _ISO2768_CLASS_DEFAULT)
        cls_cell.fill = FILL_RESULT
        cls_ref = f"$B${r}"
        tnt = ws.cell(r, 3, "f=fine · m=medium (default) · c=coarse · v=very coarse — edit "
                           "and every row below recomputes its linear/angular/flatness band.")
        tnt.font = FONT_NOTE
        r += 2

        sub_banner(ws, r, "ISO 2768-1 linear tolerance (±mm) reference table", 6)
        r += 1
        header(ws, r, _ISO_RANGE_HDR)
        r += 1
        lin_first = r
        for lo, hi, f_, m_, c_, v_ in _ISO2768_LINEAR:
            ws.cell(r, 1, lo); ws.cell(r, 2, hi)
            for ci, val in enumerate((f_, m_, c_, v_), start=3):
                cc = ws.cell(r, ci, val if val is not None else "n/a")
                if val is not None:
                    cc.number_format = FMT_DEC2
            r += 1
        lin_last = r - 1
        r += 1

        sub_banner(ws, r, "ISO 2768-1 angular tolerance (±°) reference table", 6)
        r += 1
        header(ws, r, _ISO_RANGE_HDR)
        r += 1
        ang_first = r
        for lo, hi, f_, m_, c_, v_ in _ISO2768_ANGULAR:
            ws.cell(r, 1, lo); ws.cell(r, 2, hi)
            for ci, val in enumerate((f_, m_, c_, v_), start=3):
                cc = ws.cell(r, ci, val)
                cc.number_format = "0.000"
            r += 1
        ang_last = r - 1
        r += 1

        sub_banner(ws, r, "ISO 2768-2 straightness/flatness (mm) reference table (class "
                          "pairing f/m→H/K, c/v→L — common shop convention)", 5)
        r += 1
        header(ws, r, _ISO_FLAT_HDR)
        r += 1
        flat_first = r
        for lo, hi, h_, k_, l_ in _ISO2768_2_FLATNESS:
            ws.cell(r, 1, lo); ws.cell(r, 2, hi)
            for ci, val in enumerate((h_, k_, l_), start=3):
                cc = ws.cell(r, ci, val)
                cc.number_format = FMT_DEC2
            r += 1
        flat_last = r - 1
        r += 1

        note4 = ws.cell(r, 1, clean_cell(
            "GD&T general notes (shop-default, applied to every fabricated part below "
            "unless the released manufacturing drawing states otherwise): position ±0.5 "
            "mm; surface finish Ra 3.2 µm on machined interfaces, Ra 12.5 µm as-fabricated/"
            "as-welded general surfaces (ISO 1302 general-machining convention)."))
        note4.font = Font(italic=True, size=9, color="555555")
        note4.alignment = WRAP_TOP
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=15)
        ws.row_dimensions[r].height = 32
        r += 2

        header(ws, r, _TOL_HDR)
        r += 1
        trow1 = r
        n_tol_ok = 0
        for idx, rec in enumerate(tol_rows):
            cr = crows.get(("tolerance", idx)) or {}
            row_ok = cr.get("verdict") == "PASS"
            if row_ok:
                n_tol_ok += 1
            ws.cell(r, 1, clean_cell(rec["tag"])).border = BORDER
            pc = ws.cell(r, 2, clean_cell(rec["name"])); pc.alignment = WRAP_TOP; pc.border = BORDER
            ws.cell(r, 3, clean_cell(rec["material"])).border = BORDER
            dc = ws.cell(r, 4, rec["dim_mm"] if rec["dim_mm"] is not None else "DATA NOT IN CONTRACT")
            if rec["dim_mm"] is not None:
                dc.number_format = FMT_DEC1
            dc.border = BORDER
            clc = ws.cell(r, 5, f"={cls_ref}")
            clc.border = BORDER
            if rec["dim_mm"] is not None:
                lin_f = (f'=IFERROR(SUMPRODUCT(($A${lin_first}:$A${lin_last}<=D{r})*'
                        f'($B${lin_first}:$B${lin_last}>D{r})*'
                        f'INDEX($C${lin_first}:$F${lin_last},0,MATCH({cls_ref},$C${lin_first - 1}:'
                        f'$F${lin_first - 1},0))),"DATA NOT IN CONTRACT — dimension out of table range")')
                ang_f = (f'=IFERROR(SUMPRODUCT(($A${ang_first}:$A${ang_last}<=D{r})*'
                        f'($B${ang_first}:$B${ang_last}>D{r})*'
                        f'INDEX($C${ang_first}:$F${ang_last},0,MATCH({cls_ref},$C${ang_first - 1}:'
                        f'$F${ang_first - 1},0))),"DATA NOT IN CONTRACT — dimension out of table range")')
                flat_f = (f'=IFERROR(SUMPRODUCT(($A${flat_first}:$A${flat_last}<=D{r})*'
                         f'($B${flat_first}:$B${flat_last}>D{r})*'
                         f'INDEX($C${flat_first}:$E${flat_last},0,MATCH(IF({cls_ref}="f","H",'
                         f'IF({cls_ref}="m","K","L")),$C${flat_first - 1}:$E${flat_first - 1},0))),'
                         f'"DATA NOT IN CONTRACT — dimension out of table range")')
            else:
                lin_f = ang_f = flat_f = "DATA NOT IN CONTRACT — no take-off dimension on this row"
            lf = ws.cell(r, 6, lin_f); lf.border = BORDER
            af = ws.cell(r, 7, ang_f); af.border = BORDER
            ff = ws.cell(r, 8, flat_f); ff.border = BORDER
            if rec["dim_mm"] is not None:
                lf.number_format = FMT_DEC2
                af.number_format = "0.000"
                ff.number_format = FMT_DEC2
            posc = ws.cell(r, 9, 0.5); posc.number_format = FMT_DEC2; posc.border = BORDER
            rafc = ws.cell(r, 10, "3.2 (machined) / 12.5 (as-fabricated)")
            rafc.border = BORDER
            vc = ws.cell(r, 11, "COVERED — general tolerance class + GD&T notes applied")
            vc.alignment = WRAP_TOP
            vc.border = BORDER
            vc.font = FONT_PASS
            vc.fill = FILL_PASS
            rc = ws.cell(r, 12, fx_verdict(
                [f'LEN(TRIM(A{r}&""))>0', f'LEN(TRIM(E{r}&""))>0'],
                '"row missing tag or class"'))
            rc.border = BORDER
            rc.font = FONT_PASS if row_ok else FONT_FAIL
            rc.fill = FILL_PASS if row_ok else FILL_FAIL
            r += 1
        _register_check_range(ws.title, "L", trow1, r - 1, n_pass=n_tol_ok, n_total=len(tol_rows))
        _cf_verdict(ws, f"L{trow1}:L{r - 1}")
        ws.auto_filter.ref = f"A{trow1 - 1}:L{r - 1}"
        r += 1

    back_link(ws, 15)
    return True


def tab_glossary(wb: Workbook, state: dict) -> bool:
    """Reference glossary of every abbreviation used across the dossier tabs and
    drawings. Universal (standard engineering nomenclature, identical for any
    archetype). Tristan flagged DN / ISA / PT / FC-FO / status-codes / Z-zones as
    undefined."""
    ws = wb.create_sheet("Glossary")
    set_widths(ws, {"A": 20, "B": 104})
    title_row(ws, "Glossary — abbreviations & symbols", 2,
              "Plain-English meaning of every abbreviation used on the schedule, "
              "drawing, bill-of-materials and cost tabs. Standard engineering "
              "nomenclature (British spelling); the same reference applies to any plant.")
    # ORPHAN FILTER (Tristan 2026-07-03 glossary contract: every rendered term defined +
    # NO orphan terms): only render terms actually USED somewhere in the workbook — the
    # SAME matcher the Glossary scorer verifies with, so renderer and score cannot
    # disagree. (Glossary is built after the drawing/schedule tabs, so the corpus is the
    # full deliverable text.)
    _blob = _workbook_text_blob(wb, exclude="Glossary")
    _gloss = [(cat, [(t, m) for (t, m) in entries if _term_used_in(t, _blob)])
              for cat, entries in _GLOSSARY]
    # GENERATIVE tag-prefix category (2026-07-05) — any BoM tag-prefix not already in a
    # curated _GLOSSARY entry self-documents from the ledger's own data (see
    # _generative_tag_prefix_entries). Appended as its own category so the curated groups
    # above stay hand-authored prose; the SAME orphan filter applies (a generated entry for
    # a prefix that ends up unused anywhere else in the workbook is dropped, same as any
    # other term) — never rendered as a false 'documented' claim.
    _generated = [(t, m) for (t, m) in _generative_tag_prefix_entries(state) if _term_used_in(t, _blob)]
    if _generated:
        _gloss.append(("Tag-prefix families (self-documented from the bill of materials)", _generated))
    _gloss = [(cat, entries) for cat, entries in _gloss if entries]
    r = 4
    for category, entries in _gloss:
        sub_banner(ws, r, category, 2)
        r += 1
        for term, meaning in entries:
            tc = ws.cell(r, 1, term)
            tc.font = FONT_SUB
            tc.alignment = WRAP_TOP
            tc.border = BORDER
            mc = ws.cell(r, 2, meaning)
            mc.alignment = WRAP_TOP
            mc.border = BORDER
            # grow the row when the meaning wraps (col B ≈ 102 chars/line)
            lines = max(1, -(-len(meaning) // 102))
            if lines > 1:
                ws.row_dimensions[r].height = lines * 14.5
            r += 1
        r += 1  # spacer between categories
    ws.freeze_panes = "A4"
    back_link(ws, 2)
    return True


