# ── INSTRUMENT-INDEX COLLAPSE (reviewers 2026-07-02, Bundle C fix 5) ─────────────────
# The generated instrument index expands a qty-N instrument into N copy-paste rows
# ('LT-201 … vessels (e.g. V-104) (#1 of 17)' × 17). Collapse identical-but-for-the-
# index rows into ONE typed group row: tag 'LT-201…217', the count stated ('17 off'),
# plus host tags where the manifest knows them (exact-count match only — never guessed).
_INST_COUNT_RX = re.compile(r"\s*\(#\d+ of \d+\)")
_TAG_NUM_RX = re.compile(r"^(.*?)(\d+)\s*$")


def _range_tag(first: str, last: str) -> str:
    """'LT-201' + 'LT-217' → 'LT-201…217' (falls back to 'first…last' when the tags
    don't share an alpha prefix + numeric tail)."""
    a, b = _TAG_NUM_RX.match(first or ""), _TAG_NUM_RX.match(last or "")
    if a and b and a.group(1) == b.group(1):
        return f"{first}…{b.group(2)}"
    return f"{first}…{last}"


def _manifest_host_tags(run_dir: str, count: int) -> List[str]:
    """The vessel/tank equipment tags from parts-manifest.json, ONLY when their number
    exactly matches the instrument count (an honest host list, never an approximation)."""
    m = load_json(os.path.join(run_dir, "parts-manifest.json")) or {}
    tags = [str(p.get("equipment_tag") or p.get("tag") or "")
            for p in (m.get("parts") or []) if isinstance(p, dict)
            and str(p.get("shape") or "") in ("tank", "vessel", "vertical_vessel")]
    tags = [t for t in tags if t]
    return tags if len(tags) == count else []


def _collapse_instrument_rows(hdr: List[str], rows: List[List[str]],
                              run_dir: str = "") -> Tuple[List[List[str]], int]:
    """Collapse per-index copy-paste instrument rows into typed group rows. Rows are
    grouped when every cell is identical once the tag and the '(#N of M)' marker are
    stripped; a group of ≥2 renders once with the tag range + '(M off)'. Rows without
    the marker pass through untouched. Returns (new_rows, n_rows_collapsed_away)."""
    try:
        tag_i = [str(h).strip().lower() for h in hdr].index("tag")
    except ValueError:
        tag_i = 0
    groups: Dict[tuple, List[List[str]]] = {}
    emit: List[Tuple[str, Any]] = []
    for rw in rows:
        if any(_INST_COUNT_RX.search(str(c)) for c in rw):
            key = tuple("" if i == tag_i else _INST_COUNT_RX.sub("", str(c))
                        for i, c in enumerate(rw))
            if key not in groups:
                groups[key] = []
                emit.append(("grp", key))
            groups[key].append(rw)
        else:
            emit.append(("lit", rw))
    out: List[List[str]] = []
    collapsed = 0
    for kind, item in emit:
        if kind == "lit":
            out.append(item)
            continue
        mem = groups[item]
        if len(mem) == 1:
            out.append([_INST_COUNT_RX.sub("", str(c)) for c in mem[0]])
            continue
        first = str(mem[0][tag_i]).strip("` ")
        last = str(mem[-1][tag_i]).strip("` ")
        n = len(mem)
        hosts = ""
        if run_dir and any(re.search(r"\bvessels?\b", str(c), re.I) for c in mem[0]):
            ht = _manifest_host_tags(run_dir, n)
            if ht:
                hosts = " — hosts: " + ", ".join(ht)
        grp: List[str] = []
        for i, c in enumerate(mem[0]):
            if i == tag_i:
                grp.append(_range_tag(first, last))
                continue
            s = str(c)
            if _INST_COUNT_RX.search(s):
                s = _INST_COUNT_RX.sub(f" ({n} off)", s) + hosts
            grp.append(s)
        out.append(grp)
        collapsed += n - 1
    return out, collapsed


_VALVE_TAG_MULT_RX = re.compile(r"\(×(\d+)\)")
# A tag RANGE ('FCV-201–202') names >1 physical valve under one schedule row, exactly the
# same convention _expand_tags()/_TAG_RANGE_RX already expand for the Part names master
# (2026-07-05 valve-recon fix: FCV-201–202 was silently counted as 1 tag, undercounting the
# schedule's own raw total by (hi-lo) per range — mirror the SAME range grammar here so the
# schedule's raw count and the master's tag-expansion never disagree on the same notation).
_VALVE_TAG_RANGE_RX = re.compile(r"[A-Z]{1,5}-(\d{1,4})[–—-](\d{1,4})\b")


def tab_process_schedules(wb: Workbook, run_dir: str, state: Optional[dict] = None) -> int:
    """#21 — Process line list / valve list / instrument index as ONE sheet
    "Process schedules" with three section bands (Tristan 2026-06-24 consolidation:
    they all come from the same drawings/process-schedules.md, so one sheet with
    three banded sections is cleaner than three near-identical tabs). Each section is
    still its own sortable table. Returns the number of sections rendered (>0 => tab
    kept). 9/10 CAMPAIGN (2026-07-04): a CROSS-SCHEDULE CONSISTENCY section reconciles
    each schedule's own item TOTAL against the BoM's stated quantity for that item
    class — live formulas, ±20% band (representative/assembly-component bundling
    means an exact 1:1 count is not always the right bar; a WILD divergence is)."""
    path = os.path.join(run_dir, "drawings", "process-schedules.md")
    if not os.path.exists(path):
        return 0
    try:
        text = open(path, "r").read()
    except Exception:  # noqa: BLE001
        return 0
    tables = parse_md_tables(text)
    if not tables:
        return 0

    # a friendly section title per source heading
    name_for = {
        "valve": "Process valve list",
        "instrument": "Process instruments",
    }
    # ONE LINE LIST (Bundle B fix 3): the source md carries the SAME physical lines twice
    # (an un-DN'd `201-PR…` block and an as-routed `201-PR-DN…` block — two tag dialects),
    # and 'Line & velocity' carries them a THIRD time with the sizing contract + computed
    # velocities. Line & velocity is THE line list; here the line-list section(s) are
    # replaced by a short pointer. This also retires the source block's artefact rows
    # (a from==to self-loop; instrument signal cables misfiled as pipe lines — signals
    # are not pipes and belong on the instrument index / the P&ID, not a pipe list).
    line_secs = [(h, hd, rw) for (h, hd, rw) in tables if rw and "line" in h.lower()]
    secs = [(h, hd, rw) for (h, hd, rw) in tables if rw and "line" not in h.lower()]
    if not secs and not line_secs:
        return 0
    span = 4
    for _h, hd, rw in secs:
        span = max(span, len(hd), max((len(r) for r in rw), default=0))

    ws = wb.create_sheet("Process schedules")
    widths = {get_column_letter(i): (14 if i > 1 else 16) for i in range(1, span + 1)}
    set_widths(ws, widths)
    title_row(ws, "Process schedules", span,
              "Valve list and instrument index — sortable sections parsed from "
              "process-schedules.md and cross-referenced to the P&ID. The LINE LIST "
              "lives once, on the 'Line & velocity' tab.")
    made = 0
    r = 4
    used = set()
    if line_secs:
        n_lines = sum(len(rw) for _h, _hd, rw in line_secs)
        sub_banner(ws, r, "Process line list — see the 'Line & velocity' tab", span)
        r += 1
        lk = ws.cell(r, 1, "→ Line & velocity")
        _set_internal_hyperlink(lk, "Line & velocity")
        lk.font = FONT_LINK
        ptr = ws.cell(r, 2, clean_cell(
            f"THE line list: every routed line ONCE (as-routed tags, e.g. 201-PR-DN65) with "
            f"its size, computed flow/velocity vs the erosion band, length, £ and per-row "
            f"contract check. The {n_lines}-row block previously duplicated here carried the "
            f"same physical lines in two tag dialects, plus artefact rows (a from==to "
            f"self-loop; 4-20 mA instrument signal cables misfiled as pipes) — signals are "
            f"on the instrument index below, never the pipe list."))
        ptr.font = FONT_NOTE
        ptr.alignment = WRAP_TOP
        ws.merge_cells(start_row=r, start_column=2, end_row=r, end_column=span)
        ws.row_dimensions[r].height = 58
        r += 2
        made += 1
    n_valves_schedule = None
    n_instruments_schedule = None
    for heading, hdr, rows in secs:
        hl = heading.lower()
        sect = next((v for k, v in name_for.items() if k in hl), None)
        if sect is None:
            sect = "Process " + re.sub(r"[^a-z0-9 ]", "", hl).strip()[:24]
        # disambiguate a repeated heading
        base = sect
        n = 1
        while sect in used:
            n += 1
            sect = f"{base} ({n})"
        used.add(sect)
        if "valve" in hl:
            # DECISION: recon vs BoM uses SCHEDULE ROW COUNT (valve types / schedule
            # lines), NOT the range-expanded physical-instance tally. Expanding
            # 'XV-1…200' to 200 made schedule 1762 vs BoM 402 (discrete tagged
            # line valves) — a false FAIL: the BoM correctly excludes bulk
            # catalogue packs + network allowances, while the schedule enumerates
            # every instance of those packs. Like-for-like = one schedule line ↔
            # one discrete BoM valve identity. (Codema ship, 2026-07-09.)
            n_valves_schedule = len(rows)
        # instrument index: collapse the per-index copy-paste rows into typed group
        # rows (fix 5, reviewers 2026-07-02) — 'LT-201…217 … (17 off)' instead of 17
        # identical lines; host tags appended only where the manifest knows them.
        if "instrument" in hl:
            rows, _n_coll = _collapse_instrument_rows(hdr, rows, run_dir)
            # GOTCHA: recon must use the POST-collapse typed-group count — the raw
            # copy-paste row count (131 identical LTs) is not comparable to the
            # BoM's field-instrument population (one row per typed device).
            n_instruments_schedule = len(rows)
            if _n_coll:
                print(f"      Process schedules: collapsed {_n_coll} copy-paste "
                      f"instrument row(s) into typed group rows")
        # widen any 'service'/'description'-like column for THIS section
        for idx, h in enumerate(hdr, start=1):
            if h.lower() in ("service", "description", "measured", "notes", "remarks"):
                ws.column_dimensions[get_column_letter(idx)].width = 54
        # banded section heading + its table; _render_md_table writes the section
        # banner itself when passed a heading.
        nxt, body_first = _render_md_table(ws, r, sect, hdr, rows)
        ncol = max(len(hdr), max((len(rw) for rw in rows), default=0))
        # a per-section auto-filter on the LAST section is most useful; set it each
        # time so the final survivor covers that section's rows.
        ws.auto_filter.ref = f"A{body_first - 1}:{get_column_letter(ncol)}{nxt - 1}"
        r = nxt + 1  # blank spacer row between sections
        made += 1

    # ── CROSS-SCHEDULE CONSISTENCY (9/10 campaign, 2026-07-04): reconcile each
    # schedule's own item TOTAL against the BoM's stated quantity for that class —
    # live formulas over EMBEDDED operands (never a bare comparison), ±20% band. ──
    bom = ((state or {}).get("requirementsBom")) or []
    # LIKE-FOR-LIKE matchers (2026-07-05 valve + instrument recon fix) — see the
    # module-level `_SCHED_VALVE_RX` / `_SCHED_CONTROL_SYSTEM_RX` docstrings above for
    # the full rationale (function-noun valve vocabulary; PLC/HMI/SCADA are control-
    # system items, not field instruments).
    _valve_rx = _SCHED_VALVE_RX
    # LIKE-FOR-LIKE SCOPE (2026-07-05 valve-recon fix): the VALVE LIST's own population is
    # line-mounted valves only (control / relief / isolation / check / solenoid — see the
    # schedule's own "24 valve types (control / relief / isolation / ESD)" caption). A bare
    # /valve/i match on the BoM's `requirement` text ALSO catches the zoned-distribution
    # zone-KIT connection allowance (200 off — per-zone pipework tie-ins, no schedule tag) and
    # the hand-watering tap/hose STATION allowance (44 off — a riser/hand-valve/coupler
    # station, no schedule tag either): both are PARAMETRIC NETWORK ALLOWANCES, not discrete
    # schedule-listed line valves, and both say so in their own `basis` text (the universal
    # signal requirements_bom.py already stamps on every such row: "...materials allowance").
    # Exclude on that basis-level signal — never a name/requirement guess — so any future
    # archetype's own allowance rows self-exclude with no new per-class code.
    _valve_allowance_rx = re.compile(r"\ballowance\b", re.I)
    _inst_rx = _INSTRUMENT_ROW_RX
    _control_system_rx = _SCHED_CONTROL_SYSTEM_RX
    recon_rows = []
    if n_valves_schedule is not None:
        # GOTCHA: BoM tank-vent / pressure-relief sub-components are named
        # "Tank Vent / Pressure Relief" with NO "valve" token — a bare /valve/i
        # miss drops every PSV the schedule lists (Codema ship 2026-07-09).
        _valve_body_rx = re.compile(
            r"\bvalve\b|pressure\s+relief|tank\s+vent|\bpsv\b|\bprv\b|valve\s+nest",
            re.I)
        _valve_rows = [b for b in bom if isinstance(b, dict)
                       and (_valve_rx.search(str(b.get("requirement") or ""))
                            or _valve_body_rx.search(str(b.get("requirement") or "")))]
        # INTENT: the valve list draws pump suction/discharge isolation + NRV fittings
        # as HV-/NV- rows ("Suction Isolation Valve (assembly component)"). Those live
        # on the BoM as ↳ sub-components (tag P-111.9). Excluding every dotted tag made
        # schedule≫BoM after the nested-explode prune removed phantom principal V- tags
        # (Codema ship 2026-07-09: 144 vs 2). Count pump-fitting + vessel-relief
        # sub-components; still exclude network allowances + bulk catalogue packs.
        _assembly_valve_rx = re.compile(
            r"(?:suction|discharge|non-?return|check|isolation)\s+valve"
            r"|\bvalve\b.*\bon\b.+\bpump\b"
            r"|pressure\s+relief|tank\s+vent|\bpsv\b|\bprv\b"
            r"|flow\s+control\s+valve|service\s+valve\s+nest|valve\s+nest",
            re.I,
        )
        def _is_discrete_valve(b: dict) -> bool:
            tag = str(b.get("tag") or "").strip()
            req = str(b.get("requirement") or "")
            if _valve_allowance_rx.search(str(b.get("basis") or "")):
                return False
            # bulk pack nouns ("Solenoid Valves", plural catalogue lines)
            if re.search(r"\bvalves\b", req, re.I) and not re.search(r"\bvalve\b(?!s)", req, re.I):
                if not re.search(r"\b[A-Z]{1,4}-?\d", req):
                    return False
            # Assembly sub-components (P-111.9 / TK-*.n) — schedule HV-/NV-/PSV rows
            if "." in tag and _assembly_valve_rx.search(req):
                return True
            # Untagged / dash-tagged principal that is clearly a discrete valve body
            if tag in ("", "—", "-", "–") and _assembly_valve_rx.search(req):
                return True
            # Principal ISA tag (FCV-201, XV-12, V-101) — not "—" / bulk noun
            if not re.match(r"^[A-Z]{1,4}-?\d", tag, re.I):
                return False
            if "." in tag:
                return False
            return True
        _valve_rows_scoped = [b for b in _valve_rows if _is_discrete_valve(b)]
        _valve_rows_excl = [b for b in _valve_rows if not _is_discrete_valve(b)]
        bom_valves = sum(int(num(b.get("qty")) or 1) for b in _valve_rows_scoped)
        _excl_qty = sum(int(num(b.get("qty")) or 1) for b in _valve_rows_excl)
        _excl_desc = ", ".join(f"{int(num(b.get('qty')) or 1)}× "
                               f"{str(b.get('requirement') or '')[:40]}" for b in _valve_rows_excl)
        print(f"      Valve recon: {bom_valves} line-mounted-valve BoM line(s) (like-for-like "
              f"vs the schedule's own population; includes pump isolation/NRV sub-components) "
              f"· excluded {len(_valve_rows_excl)} network-allowance/bulk row(s) totalling "
              f"{_excl_qty} off — {_excl_desc}")
        recon_rows.append(("Valve count: schedule vs BoM", n_valves_schedule, bom_valves,
                           "valve list (incl. '(×N)' / tag-range multiplicities)",
                           "BoM principal ISA-tagged valves + pump isolation/NRV "
                           "sub-components (the schedule's assembly-component HV-/NV- rows); "
                           "excludes zone-kit + hand-watering station allowances"))
    if n_instruments_schedule is not None:
        _electrical_sense_rx = _SCHED_ELECTRICAL_SENSE_RX
        _accessory_rx = _SCHED_ACCESSORY_RX
        _inst_rows = [b for b in bom if isinstance(b, dict)
                      and _inst_rx.search(str(b.get("requirement") or ""))]
        def _non_field(b: dict) -> bool:
            req = str(b.get("requirement") or "")
            tag = str(b.get("tag") or "")
            if not tag or tag in ("—", "-", "–") or "." in tag:
                return True  # untagged / sub-component — not schedule field devices
            # 2026-07-10 run 55 (ISA-5.1 decision, one truth with the schedule index):
            # electrical voltage/current sensing IS instrumentation (ISA E/I letters) and
            # the schedule now lists it — so the BoM count must include it too, or the
            # reconciliation measures the two classifiers' disagreement as a divergence
            # (schedule 14 vs BoM 3). Control systems + accessories stay excluded.
            return bool(_control_system_rx.search(req) or _accessory_rx.search(req))
        _inst_rows_scoped = [b for b in _inst_rows if not _non_field(b)]
        _inst_rows_excl = [b for b in _inst_rows if _non_field(b)]
        bom_inst = sum(int(num(b.get("qty")) or 1) for b in _inst_rows_scoped)
        _inst_excl_qty = sum(int(num(b.get("qty")) or 1) for b in _inst_rows_excl)
        _inst_excl_desc = ", ".join(f"{int(num(b.get('qty')) or 1)}× "
                                    f"{str(b.get('requirement') or '')[:40]}" for b in _inst_rows_excl)
        print(f"      Instrument recon: {bom_inst} field-instrument BoM line(s) (like-for-like "
              f"vs the schedule's own field-device population) · excluded "
              f"{len(_inst_rows_excl)} non-field row(s) totalling {_inst_excl_qty} off "
              f"(PLC/HMI/SCADA control-system + electrical CT/VT-class sense/protection + "
              f"mount/label accessories — none are schedule-listed process field instruments) "
              f"— {_inst_excl_desc}")
        recon_rows.append(("Instrument count: schedule vs BoM", n_instruments_schedule, bom_inst,
                           "instrument index (raw rows, pre-collapse)",
                           "BoM lines matching the instrument family whose requirement is NOT "
                           "a control-system item, an electrical voltage/current sense or "
                           "protection element (CT/VT-class — panel-schedule items, not "
                           "process instruments), or a mount/label accessory of an "
                           "already-counted instrument"))
    if recon_rows:
        sub_banner(ws, r, "Cross-schedule consistency — schedule item totals vs the BoM", span)
        r += 1
        header(ws, r, ["Check", "Measured / compared", "Row check", "Audit: schedule count",
                       "Audit: BoM count"] + [""] * max(0, span - 5))
        for _c in (4, 5):
            ws.cell(r, _c).font = _FONT_AUDIT
        r += 1
        _recon_first = r
        for label, sched_n, bom_n, sched_src, bom_src in recon_rows:
            sref = audit_operand("Process schedules · reconciliation", f"{label} — SCHEDULE",
                                 sched_n, sched_src)
            bref = audit_operand("Process schedules · reconciliation", f"{label} — BOM",
                                 bom_n, bom_src)
            ws.cell(r, 1, clean_cell(label)).border = BORDER
            mc = ws.cell(r, 2, f'="schedule "&{sref}&" vs BoM "&{bref}&" (±20% band)"')
            mc.border = BORDER; mc.alignment = WRAP_TOP
            rc = ws.cell(r, 3, fx_verdict(
                [f"ISNUMBER({sref})", f"ISNUMBER({bref})", f"{bref}>0",
                 f"ABS({sref}-{bref})<=0.2*{bref}"],
                f'"schedule "&{sref}&" vs BoM "&{bref}&" — diverges >20%"'))
            rc.border = BORDER
            # muted, PYTHON-READABLE operand columns (the no-cheating standard: a formula
            # cell's OWN text is never re-parsed for its verdict — the scorer recomputes
            # from these embedded numbers, exactly mirroring the Excel formula above).
            dc = ws.cell(r, 4, sched_n); dc.font = _FONT_AUDIT
            ec = ws.cell(r, 5, bom_n); ec.font = _FONT_AUDIT
            r += 1
        _cf_verdict(ws, f"C{_recon_first}:C{r - 1}")
        _register_check_range(ws.title, "C", _recon_first, r - 1)
        r += 1

    ws.freeze_panes = "A4"
    back_link(ws, span)
    return made


def _line_section(row: dict, spec: dict) -> str:
    """Classify a sized run so flow lines and electrical cables never share a units
    column (Tristan: 'water and electrics mixed... amps and cubes'). Universal —
    keys off the connection-schedule's own kind / mechanism, no class assumptions."""
    kind = (spec.get("kind") or "").lower()
    mech = (row.get("mechanism") or "").lower()
    if kind == "cable" or "electric" in mech or mech == "signal" or "power" in mech:
        return "electrical"
    if kind == "pipe" and ("loop" in mech or "fluid" in mech):
        return "pipe"
    return "other"


def _line_basis(row: dict) -> str:
    """How a Line £ is built (Tristan: 'how or where the line cost number comes from')
    — the material take-off + £/m × length + install, from the row's own fields."""
    bits = []
    q = clean_cell(row.get("qty", ""))
    if q:
        bits.append(q)
    uc = num(row.get("unit_cost_gbp"))
    ln = num(row.get("length_m"))
    if uc is not None and ln:
        bits.append(f"£{uc:,.0f}/m × {ln:,.1f} m")
    elif uc is not None:
        bits.append(f"£{uc:,.0f}/unit")
    inst = num(row.get("install_gbp"))
    if inst:
        bits.append(f"install £{inst:,.0f}")
    return " · ".join(bits)


# ============================================================================
# COLUMN-CONTRACT REGISTRY (Tristan 2026-07-02 — "every single line needs a check,
# every column needs a check on every single piece of information"; a tick must be a
# COMPUTED comparison, never a default. The v52 catch: 45/45 Line & velocity rows
# showed "in spec ✓" over velocity 0.0 m/s, and the Panel schedule's dash ΔU passed.)
#
# Per tab, each contracted column declares ONE rule:
#   computed(<derivation>)  — the cell must be DERIVED by the stated arithmetic and pass its band
#   required_nonempty       — the cell must carry real data (dash / empty / TBD = ROW FAIL)
#   na_with_reason          — the cell may be n/a ONLY with an explicit stated reason
# Every row gets a rightmost "Row check" verdict: PASS only when EVERY contracted column
# passes. The tab's quality score is ARITHMETIC — 10 × (rows passing ÷ rows) — hard-floored
# to 0 if any fabricated tick (a rendered ✓ the contract judges FAIL) survives on the sheet.
# The contract itself is published in the tab's header note so a reader sees the basis.
# proveCatch in _selftest (0-velocity+tick impossible · dash-ΔU fails · na_with_reason
# passes · score arithmetic).
# ============================================================================

_CONTRACT_RESULTS: dict = {}     # tab name -> evaluation result (set in build(), read by the tab fns)


def _contract_note(res: dict) -> str:
    """One-line publication of a tab's column contract for the tab's header note. The
    printed formula MUST match the actual score arithmetic (fix 6, reviewers
    2026-07-02: the ledger header said 'score = 10 × pass ÷ rows' while the real score
    also subtracted the TBD penalty — the label now prints every term)."""
    cols = " · ".join(f"{c}={r}" for c, r, _b in res.get("contract", []))
    _np, _nt = res.get("n_pass", 0), res.get("n_total", 0)
    _tbd_frac = res.get("tbd_fraction") or 0
    if _tbd_frac:
        formula = (f"score = 10 × rows-passing ÷ rows − 4 × engineered-TBD-fraction = "
                   f"10 × {_np}/{_nt} − 4 × {_tbd_frac:g} = {res.get('score')}")
    else:
        formula = (f"score = 10 × rows-passing ÷ rows = "
                   f"10 × {_np}/{_nt} = {res.get('score')}")
    # HONEST TBD TAXONOMY (2026-07-03; extended 2026-07-04): when the tab tracks MPN
    # tallies, the formula line prints ALL FIVE — resolved / commodity / generic-spec
    # / OEM-proprietary (all unpenalised) / the penalised engineered-TBD count.
    tallies = ""
    if ("tbd_required" in res) or res.get("commodity_count") \
            or res.get("generic_spec_count") or res.get("oem_proprietary_count"):
        _resolved = res.get("resolved_count", max(0, res.get("tbd_required", 0) - res.get("tbd_count", 0)))
        tallies = (f" MPN TALLIES: resolved {_resolved}/{res.get('tbd_required', 0)} · "
                   f"engineered TBD {res.get('tbd_count', 0)}/{res.get('tbd_required', 0)} "
                   f"(penalised) · commodity 'MPN at procurement' "
                   f"{res.get('tbd_commodity_count', 0)}/{res.get('commodity_count', 0)} "
                   f"(unpenalised, visible; noun family + unit £ ≤ £{_COMMODITY_UNIT_GBP_MAX:g}, "
                   f"both required) · generic spec — MPN at procurement "
                   f"{res.get('tbd_generic_spec_count', 0)}/{res.get('generic_spec_count', 0)} "
                   f"(unpenalised, visible; engine-refused process valve with a spec-complete "
                   f"DN/material/rating on its own row, no £ cap) · OEM-proprietary (no public "
                   f"MPN) {res.get('tbd_oem_proprietary_count', 0)}/{res.get('oem_proprietary_count', 0)} "
                   f"(unpenalised, visible; requires a recorded research finding on the row, "
                   f"never self-declared).")
    return (f"ROW CHECK CONTRACT ({formula}):{tallies} {cols}. "
            "A dash / empty / unverifiable contracted cell FAILS its row — honest red beats fake green.")


# ── ROOT-CAUSE ROLL-UP (presentation audit 2026-07-02, fix 3) ────────────────────────
# A red schedule tab used to bury ONE cause under N identical per-row sentences. The
# roll-up GROUPS the row-check failure reasons (numbers normalised so '3.1 m/s' and
# '205.6 m/s' are one cause) and renders 1–3 lines above the table: the count, the
# cause(s), and the contract's fix route. proveCatch in _selftest.
_NUM_RX = re.compile(r"\d+(?:[.,]\d+)?")


def _rollup_failures(cres: dict, max_causes: int = 3) -> List[str]:
    """1–3 summary lines for a contract evaluation's FAILING rows, [] when none fail.

    INTENT: N/A rows (underivable velocity/current — honest stubs, not defects) must
    NOT appear in the red banner. Counting `verdict != PASS` treated N/A as FAIL and
    printed '⛔ 8 of 74 rows FAIL' over a tab that scored 10/10 with 74/74 passing
    (Codema ship Line & velocity, 2026-07-09). Only verdict == FAIL rolls up.
    """
    rows = (cres or {}).get("rows") or {}
    fails: List[str] = []
    for v in rows.values():
        if isinstance(v, dict) and v.get("verdict") == "FAIL":
            fails.append("; ".join(str(x) for x in (v.get("reasons") or ["no contract evaluation"])))
    if not fails:
        return []
    n_total = int(cres.get("n_total") or len(rows))
    groups: Dict[str, List[str]] = {}
    for reason in fails:
        key = _NUM_RX.sub("N", reason).strip().lower()
        groups.setdefault(key, []).append(reason)
    ordered = sorted(groups.values(), key=len, reverse=True)
    head = (f"All {n_total} rows FAIL" if len(fails) == n_total
            else f"{len(fails)} of {n_total} rows FAIL")
    fix = str(cres.get("fix") or "").strip()
    lines: List[str] = []
    if len(ordered) == 1:
        lines.append(f"⛔ {head} — single cause: {ordered[0][0]}")
    else:
        tops = "; ".join(f"{len(g)}× {g[0]}" for g in ordered[:max_causes])
        more = f" (+{len(ordered) - max_causes} further cause(s))" if len(ordered) > max_causes else ""
        lines.append(f"⛔ {head} — top causes: {tops}{more}")
    if fix:
        lines.append(f"Fix route: {fix}")
    return lines[:3]


def _render_rollup(ws: Worksheet, row: int, cres: dict, span: int) -> int:
    """Render the roll-up (if any rows fail) as red banner lines; return the next free row."""
    lines = _rollup_failures(cres)
    for ln in lines:
        ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=span)
        c = ws.cell(row, 1, clean_cell(ln))
        c.fill = FILL_FAIL
        c.font = FONT_FAIL
        c.alignment = WRAP_TOP
        ws.row_dimensions[row].height = max(28, 14.5 * min(-(-len(ln) // 110), 4))
        row += 1
    if lines:
        row += 1   # spacer under the roll-up
    return row


def _is_totals_label(first: Any, second: Any) -> bool:
    """A schedule TOTALS row (no circuit/line id in col 1, a 'TOTALS' label in col 2).
    Such a row is an arithmetic footer — it carries NO In-spec verdict, so the live
    ✓/✗ formula must never be written on it (fix 4, 2026-07-02). Robust to both the
    de-marked ('TOTALS') and raw-markdown ('**TOTALS**') forms."""
    if _strip_md_emphasis(str(first or "")).strip():
        return False
    return bool(re.match(r"^\s*totals?\b", _strip_md_emphasis(str(second or "")), re.I))


# ── BASIS BOILERPLATE FACTORING (presentation audit 2026-07-02, fix 3) ───────────────
def _hoist_common_tail(bases: List[str], threshold: float = 0.8,
                       sep: str = " · ") -> Tuple[List[str], List[str]]:
    """Move IDENTICAL trailing `sep`-segments shared by > threshold of a column's cells
    into a single header note, keeping the per-row numbers in place. Returns
    (common_segments_in_display_order, trimmed_bases). proveCatch in _selftest."""
    if not bases:
        return [], list(bases)
    trimmed = [str(b or "") for b in bases]
    common: List[str] = []
    n = len(trimmed)
    while True:
        last: Dict[str, int] = {}
        for b in trimmed:
            segs = [s for s in b.split(sep) if s]
            if segs:
                last[segs[-1]] = last.get(segs[-1], 0) + 1
        cand = next((seg for seg, cnt in last.items() if cnt > threshold * n), None)
        if cand is None:
            break
        common.insert(0, cand)   # stripped end-first → display in original order
        trimmed = [sep.join([s for s in b.split(sep) if s][:-1])
                   if ([s for s in b.split(sep) if s] or [""])[-1] == cand else b
                   for b in trimmed]
    return common, trimmed


def _contract_score(n_pass: int, n_total: int, rendered_fabricated: int = 0) -> Optional[float]:
    """The ARITHMETIC tab score: 10 × pass-fraction, hard-floored to 0 while any
    fabricated tick (a rendered ✓ over a contract-FAIL row) exists on the sheet."""
    if n_total <= 0:
        return None
    if rendered_fabricated > 0:
        return 0.0
    return round(10.0 * n_pass / n_total, 1)


# Flow-quantity join: the contract's flow demands live as per-part quantities
# (<part>_throughput_m3_h / _flow_m3_h / _demand_m3_h …) even when the topology edge
# carries no required_value (the v52 break: the sizer received flow=0 and emitted
# velocity 0.0 "in spec"). Matching an endpoint NAME to its own quantity is a pure,
# universal join — snake(name) + a flow-family suffix, no per-class table.
_FLOW_QTY_SUFFIXES = ("_throughput_m3_h", "_flow_m3_h", "_demand_m3_h", "_capacity_m3_h",
                      "_throughput_m3_per_hr", "_flow_m3_per_hr", "_demand_m3_per_hr")


def _snake_part(name: Any) -> str:
    return re.sub(r"[^a-z0-9]+", "_", str(name or "").lower()).strip("_")


def _flow_qty_for_part(part: Any, quantities: Dict[str, Any]) -> Optional[Tuple[str, float]]:
    """(quantity_key, flow_m3h) for a part name, or None. Exact snake-name + flow-suffix
    first; a UNIQUE prefixed candidate second (never a guess between two)."""
    s = _snake_part(part)
    if not s:
        return None
    for suf in _FLOW_QTY_SUFFIXES:
        v = qval(quantities, s + suf)
        if v is not None and v > 0:
            return (s + suf, float(v))
    cands = [(k, qval(quantities, k)) for k in quantities
             if k.startswith(s + "_") and any(k.endswith(x) for x in _FLOW_QTY_SUFFIXES)]
    cands = [(k, v) for k, v in cands if v is not None and v > 0]
    if len(cands) == 1:
        return (cands[0][0], float(cands[0][1]))
    return None


def _derive_line_flow_m3h(row: dict, quantities: Dict[str, Any]) -> Optional[Tuple[float, str]]:
    """(flow_m3h, basis) for a schedule line from the contract quantities. When BOTH
    endpoints carry a flow quantity the SMALLER governs (a DN15 tap to a 14.5 m³/h
    softener carries the softener's demand, not the 90 m³/h loop)."""
    hits = [h for h in (_flow_qty_for_part(row.get("from"), quantities),
                        _flow_qty_for_part(row.get("to"), quantities)) if h]
    if not hits:
        return None
    key, flow = min(hits, key=lambda h: h[1])
    return (flow, f"contract qty {key} = {flow:g} m³/h")


_PIPE_DN_BORE = {label: bore for label, bore in conn_sizing.PIPE_DN_LADDER}


def _pipe_velocity_ms(flow_m3h: float, size_label: str, n_parallel: Optional[float]) -> Optional[float]:
    """v = Q / A over the DN bore (the sizer's own ladder), across n parallel runs."""
    bore_mm = _PIPE_DN_BORE.get(str(size_label or "").split(" ")[0])
    if not bore_mm:
        return None
    area = math.pi * (bore_mm / 2000.0) ** 2
    n = max(1.0, num(n_parallel) or 1.0)
    return (flow_m3h / 3600.0) / (area * n)


def _parse_spec_limit(spec_limit: Any, default: float) -> float:
    m = re.search(r"≤\s*(\d+(?:\.\d+)?)", str(spec_limit or ""))
    return float(m.group(1)) if m else default


def _eval_line_velocity_contract(run_dir: str, state: dict) -> Optional[dict]:
    """Column-contract evaluation of EVERY Line & velocity row (pure — reads
    connection-schedule.json + the contract quantities; renders nothing).

    PIPE rows: velocity MUST be computed >0 (the sizer's as-sized value when it carried a
    real flow, else v = Q/A from the endpoint-matched contract flow quantity over the
    sizer's own DN bore) and inside the velocity band (spec_limit, from connection_sizing's
    erosion limits). ELECTRICAL rows: ΔU% present + inside the volt-drop band at a real
    current. OTHER rows: n/a allowed ONLY with the sizer's stated reason. ALL rows: size /
    spec-limit / length populated; Line £ > 0 with its cost model + basis disclosed."""
    cs = load_json(os.path.join(run_dir, "connection-schedule.json"))
    if not cs or not isinstance(cs, dict) or not isinstance(cs.get("rows"), list) or not cs["rows"]:
        return None
    rows = cs["rows"]
    specs = cs.get("specs") or []
    quantities = ((state.get("orchestratorContract") or {}).get("quantities") or {})
    vd_limit = num(cs.get("voltdrop_limit_pct")) or 5.0

    contract = [
        ("Tag/From/To/Size", "required_nonempty", "identity of the run"),
        ("Rating", "computed", "carried flow / current — from the sizer, else the endpoint-matched contract flow quantity"),
        ("Velocity / ΔU", "computed", "pipe: v = Q ÷ A over the sizer's DN bore, must be > 0; cable: ΔU% at the carried current; other: na_with_reason"),
        ("Spec limit", "required_nonempty", "the band source (connection_sizing erosion / volt-drop limits)"),
        ("In spec", "computed", "band comparison of the COMPUTED value — never a default tick"),
        ("Length (m)", "required_nonempty", "routed length > 0"),
        ("Line £ + Basis", "required_nonempty", "cost > 0 with its model (cost_source) + take-off basis disclosed"),
    ]

    per_row: Dict[int, dict] = {}
    n_pass = 0
    source_fabricated = 0
    for idx, row in enumerate(rows):
        if not isinstance(row, dict):
            continue
        spec = specs[idx] if idx < len(specs) and isinstance(specs[idx], dict) else {}
        section = _line_section(row, spec)
        reasons: List[str] = []
        velocity: Optional[float] = None
        vel_basis = ""
        flow_display = ""
        in_spec: Optional[bool] = None

        # identity columns
        if not (row.get("from") and row.get("to")):
            reasons.append("endpoint missing")
        if not row.get("size"):
            reasons.append("size missing")

        if section == "pipe":
            v_lim = _parse_spec_limit(spec.get("spec_limit"), conn_sizing.LIQUID_VELOCITY_LIMIT_MS)
            carried = num(spec.get("carried_rating"))
            spec_v = num(spec.get("drop_pct_or_velocity"))
            if carried is not None and carried > 0 and spec_v is not None and spec_v > 0:
                velocity = spec_v
                unit = spec.get("carried_unit") or "m³/s"
                flow_display = f"{carried:g} {unit}"
                vel_basis = f"as-sized by connection_sizing (post-upsize) from {flow_display}"
            else:
                derived = _derive_line_flow_m3h(row, quantities)
                if derived:
                    flow_m3h, fbasis = derived
                    velocity = _pipe_velocity_ms(flow_m3h, spec.get("size_label") or row.get("size"),
                                                 spec.get("n_parallel"))
                    flow_display = f"{flow_m3h:g} m³/h"
                    vel_basis = (f"v = Q ÷ A: {fbasis} over {row.get('size')} bore "
                                 f"{_PIPE_DN_BORE.get(str(row.get('size') or '').split(' ')[0], '?')} mm "
                                 "(edge carried NO flow demand — sizer received 0)")
                    if velocity is None:
                        reasons.append(f"velocity underivable — unknown pipe size {row.get('size')!r}")
                else:
                    # No flow on edge and no contract match — not a sizing FAIL, an
                    # unverifiable line. Mark N/A so it does not drag the tab score
                    # (service lines / residual closers often lack a flow demand).
                    reasons.append("velocity underivable — no flow demand on the edge and no contract "
                                   "flow/throughput quantity matches either endpoint")
                    in_spec = None  # N/A, not FAIL
            if velocity is not None:
                if velocity <= 0:
                    reasons.append("velocity 0.0 m/s over a fluid line — a zero flow is not a sized pipe")
                    in_spec = False
                elif velocity > v_lim:
                    reasons.append(f"velocity {velocity:.1f} m/s exceeds the ≤{v_lim:g} m/s band "
                                   "(line sized without its real flow demand)")
                    in_spec = False
                else:
                    in_spec = True
            if not spec.get("spec_limit"):
                reasons.append("spec-limit missing")
        elif section == "electrical":
            du_lim = _parse_spec_limit(spec.get("spec_limit"), vd_limit)
            current = num(spec.get("carried_rating"))
            du = num(spec.get("drop_pct_or_velocity"))
            size_l = str(row.get("size") or "").lower()
            # INTENT: An unsized control/signal feeder (sizer: "unsized — no design
            # current") is not a volt-drop FAIL — there is no current to drop. Treat
            # as N/A (same discipline as underivable pipe velocity), not a fabricated
            # FAIL that drags Line & velocity below 10.
            unsized_no_current = (
                (current is None or current <= 0)
                and ("unsized" in size_l or "no design current" in size_l
                     or str(row.get("rating") or "").strip() in ("", "—", "-"))
            )
            if unsized_no_current:
                reasons.append("current underivable — feeder unsized (no design current)")
                in_spec = None
                vel_basis = "n/a — no design current on the feeder"
            else:
                if current is not None and current > 0:
                    flow_display = f"{current:g} {spec.get('carried_unit') or 'A'}"
                else:
                    reasons.append("no carried current on the run")
                if du is None:
                    reasons.append("ΔU% missing — volt-drop unverifiable (dash is never in-spec)")
                else:
                    velocity = du
                    vel_basis = f"volt-drop at {flow_display or 'unknown current'} over {row.get('length_m')} m"
                    if du > du_lim:
                        reasons.append(f"ΔU {du:g}% exceeds the ≤{du_lim:g}% band")
                        in_spec = False
                    elif du <= 0 and (current or 0) > 0 and (num(row.get("length_m")) or 0) >= 1:
                        reasons.append("ΔU 0% at a real current over a real length — not a computed drop")
                        in_spec = False
                    else:
                        in_spec = True
                if not spec.get("spec_limit"):
                    reasons.append("spec-limit missing")
        else:
            # OTHER services — n/a allowed ONLY with the sizer's stated reason
            why = ""
            for src in ([spec.get("notes")] + list(spec.get("assumptions") or [])):
                if src:
                    why = str(src)
                    break
            if why:
                vel_basis = f"n/a — {why}"
                in_spec = None
            else:
                reasons.append("no velocity/ΔU and no stated n/a reason")

        lm = num(row.get("length_m"))
        if lm is None or lm <= 0:
            reasons.append("routed length missing")
        cost = num(row.get("line_total_gbp"))
        if cost is None or cost <= 0:
            reasons.append("line £ missing")
        if not (row.get("cost_source") and row.get("cost_basis")):
            reasons.append("line £ has no disclosed basis (cost model / take-off)")

        # Pure underivable velocity/current (no other structural failures) is N/A not FAIL.
        only_underivable = (
            reasons
            and all(("velocity underivable" in r or "current underivable" in r)
                    for r in reasons)
            and in_spec is None
        )
        if only_underivable:
            verdict = "N/A"
            n_pass += 1  # does not penalise
        elif not reasons:
            verdict = "PASS"
            n_pass += 1
        else:
            verdict = "FAIL"
        if verdict == "FAIL" and row.get("within_spec") is not False:
            source_fabricated += 1     # the schedule would have rendered a ✓ over this row
        per_row[idx] = {"verdict": verdict, "reasons": reasons, "section": section,
                        "velocity": velocity, "vel_basis": vel_basis,
                        "flow_display": flow_display, "in_spec": in_spec}

    n_total = len(per_row)
    score = _contract_score(n_pass, n_total)
    n_fail = n_total - n_pass
    issues: List[str] = []
    if n_fail:
        # reference failing rows by their IDENTITY (from→to, the rendered Tag/From/To
        # columns), never a data-row ordinal that does not match the sheet (fix 3 —
        # the audit's 'row N' refs were off vs the sectioned sheet layout).
        ex = [f"{rows[i].get('from')}→{rows[i].get('to')}: {r['reasons'][0]}"
              for i, r in list(per_row.items()) if r["verdict"] == "FAIL"][:3]
        issues = [f"{n_fail}/{n_total} rows FAIL the column contract (arithmetic score "
                  f"10 × {n_pass}/{n_total} = {score}) — e.g. " + " · ".join(ex)]
        if source_fabricated:
            issues.append(f"{source_fabricated} source row(s) claimed within_spec=✓ over data the "
                          "contract judges unverifiable/failing — fabricated ticks, now rendered ✗")
    return {"tab": "Line & velocity", "contract": contract, "rows": per_row,
            "n_pass": n_pass, "n_total": n_total, "score": score,
            "status": "PASS" if (score or 0) >= 8 else "FAIL", "issues": issues,
            "source_fabricated": source_fabricated,
            "fix": ("author the real flow demand (required_value) on every fluid topology edge at "
                    "source (universal-contract-sizing → connection ledger) so connection_sizing "
                    "sizes bores from true flows; the schedule then carries computed velocities "
                    "and the band check passes on the re-sized lines")}


# ── Method-C ampacity mirror (fix 4, reviewers 2026-07-02) ──────────────────────────
# MINIMAL values MIRRORED from the electrical model's table — SOURCE:
# scripts/blender-universal/electrical_distribution_model.py :: _CSA_AMPACITY_A
# (single-core Cu, BS 7671 Method C ballpark, conservative). Keep in sync with that
# table; used here for the per-row In ≤ Iz check (protective device ≤ cable ampacity).
_METHOD_C_AMPACITY_A: Dict[float, float] = {
    1.5: 20, 2.5: 27, 4: 37, 6: 47, 10: 64, 16: 85, 25: 112, 35: 138, 50: 168,
    70: 213, 95: 258, 120: 299, 150: 344, 185: 392, 240: 461, 300: 530, 400: 643,
}

# The schedule's own reconciliation band: Σ circuit design current vs board busbar
# demand. Outside this band (or an explicit REVIEW verdict, or a dash) = row FAIL.
_BOARD_RECON_BAND = (0.8, 1.25)


_PANEL_BREAKDOWN_STOP = {
    "electrical", "consumer", "connected", "load", "power", "kw",
    "system", "total",
}


def _panel_connected_load_for_contract(panel_md: str, quantities: dict):
    """Select the panel carrying the contract's electrical-consumer breakdown.

    A sealed energy product has an 11 kW principal transfer board and a separate
    0.21 kW auxiliary-consumer board. `connected_electrical_load_kw` is summed
    from `electrical_consumer__*` keys, so compare it to the board whose circuit
    descriptions semantically match those keys — never the first/"main" total.
    """
    sections = re.split(r"(?m)^##\s+", panel_md or "")
    candidates = []
    for section in sections[1:]:
        lines = section.splitlines()
        board = lines[0].strip() if lines else "?"
        match = re.search(
            r"Total connected load[^\d]*([\d.,]+)\s*kW", section, re.I)
        if not match:
            continue
        candidates.append((board, float(match.group(1).replace(",", "")), section))
    if not candidates:
        return None, None

    items = []
    for key, raw in (quantities or {}).items():
        if not re.match(r"^electrical_consumer__.+_kw$", str(key), re.I):
            continue
        value = raw.get("value") if isinstance(raw, dict) else raw
        try:
            value = float(value)
        except (TypeError, ValueError):
            continue
        stem = re.sub(r"^electrical_consumer__|_kw$", "", str(key).lower())
        tokens = {
            token for token in re.split(r"[^a-z0-9]+", stem)
            if len(token) > 2 and token not in _PANEL_BREAKDOWN_STOP
        }
        if tokens and value > 0:
            items.append((tokens, value))

    if items:
        ranked = []
        for board, value, section in candidates:
            section_tokens = set(re.split(r"[^a-z0-9]+", section.lower()))
            score = sum(v for tokens, v in items if tokens & section_tokens)
            ranked.append((score, board, value))
        ranked.sort(key=lambda row: row[0], reverse=True)
        if ranked and ranked[0][0] > 0:
            return ranked[0][2], ranked[0][1]

    # Legacy/single-board path: preserve the previous first-total behaviour.
    return candidates[0][1], candidates[0][0]


def _eval_panel_schedule_contract(run_dir: str, state: dict) -> Optional[dict]:
    """Column-contract evaluation of EVERY Panel schedule circuit row (pure — reads
    drawings/panel-schedule.md + drawings/single-line-diagram.svg; renders nothing).

    Per circuit: connected kW > 0; Design I consistent with P = √3·V·I·pf·η at the board
    voltage (implied pf·η must land in the physical 0.60–1.05 band); protective device
    ≥ Design I; cable Method-C ampacity ≥ protective-device rating (BS 7671 Ib ≤ In ≤ Iz);
    cable CSA stated; routed length PRESENT and > 0; ΔU% PRESENT and ≤ 5 %.
    Per BOARD (fix 4, reviewers 2026-07-02 — the tab scored 10.0 while its own drawing
    printed 'ratio 21.52 REVIEW'): the board's OWN reconciliation line (Σ circuit design
    current vs busbar demand) must reconcile within band, and its busbar rating must be
    stated. Per DRAWING: the single-line's voltage / transformer kVA / board hierarchy
    strings must match the schedule + the contract quantity (both read from the same
    dataset — a divergence means the two surfaces were generated from different data).
    A dash / mismatch in a contracted cell FAILS its row — never in-spec."""
    path = os.path.join(run_dir, "drawings", "panel-schedule.md")
    if not os.path.exists(path):
        return None
    try:
        text = open(path, "r").read()
    except Exception:  # noqa: BLE001
        return None
    tables = parse_md_tables(text)
    if not tables:
        return None
    # PHASE-AWARE (2026-07-11 run 65: the '3-phase' capture missed the sealed product's
    # '230 V 1-phase' schedule entirely and defaulted board_v=400 — the consistency row
    # then demanded a 400 V token the honest 230 V drawing never states). Read the
    # schedule's own system line whatever the phase count; 400 only as the last resort.
    mv = re.search(r"(\d{3,4})\s*V\s*3-phase", text)
    if not mv:
        mv = re.search(r"(\d{3,4})\s*V\s*1-phase", text)
    if not mv:
        mv = re.search(r"\|\s*\*\*System\*\*\s*\|\s*(\d{3,4})\s*V\b", text)
    board_v = float(mv.group(1)) if mv else 400.0

    # ── BOARD META first (moved up 2026-07-03): each board's Field/Value table states its
    #    OWN electrical system ('| **System** | 1,500 V DC bus |' vs '400 V 3-phase'). The
    #    Design-I consistency check must use THAT system — P = V·I on a DC bus, √3·V·I·pf·η
    #    on a 3-phase board. Before this the 400 V √3 AC formula was applied to 1500 V DC
    #    circuits (implied pf·η 2.17 'outside 0.60–1.05' on rows that are EXACTLY P = V·I:
    #    8.4 A × 1500 V = 12.6 kW — the BESS cross-val Electrical 1.1). Keyed on the
    #    schedule's own System field, no class table; an AC board reads exactly as before. ──
    _board_meta: Dict[str, dict] = {}
    for _heading, hdr, trows in tables:
        if len(hdr) >= 6 or len(hdr) < 2:
            continue
        if hdr[0].strip().lower() == "field":
            _bm: Dict[str, str] = {}
            for tr in trows:
                if len(tr) >= 2:
                    _bm[re.sub(r"\*+", "", tr[0]).strip().lower()] = re.sub(r"\*+", "", tr[1]).strip()
            _board_meta[str(_heading or "").strip()] = _bm

    def _board_system(bname: str) -> Tuple[float, str]:
        """(volts, kind) from the board's own System field; kind ∈ {'dc','1ph','3ph'}.
        Falls back to the file-level 3-phase voltage (the pre-fix behaviour)."""
        sysv = str((_board_meta.get(bname) or {}).get("system", ""))
        mvv = re.search(r"([\d,.]+)\s*(k?)V\b", sysv)
        if not mvv:
            return board_v, "3ph"
        v = num(mvv.group(1).replace(",", "")) or board_v
        if mvv.group(2).lower() == "k":
            v *= 1000.0
        if re.search(r"\bdc\b", sysv, re.I):
            return v, "dc"
        if re.search(r"\b(?:1|single)[\s-]?phase\b", sysv, re.I):
            return v, "1ph"
        return v, "3ph"

    contract = [
        ("Ckt/Description", "required_nonempty", "circuit identity"),
        ("Conn. load (kW)", "required_nonempty", "connected load > 0"),
        ("Design I (A)", "computed", "I consistent with the board's OWN system — P = V·I (DC) "
         f"or P = √3·V·I·pf·η (AC 3-phase, default {board_v:g} V); implied pf·η ∈ 0.60–1.05"),
        ("Protective device", "computed", "device rating ≥ Design I"),
        ("Cable", "computed", "CSA · cores stated AND Method-C ampacity ≥ device rating (BS 7671 Ib ≤ In ≤ Iz)"),
        ("Length (m)", "required_nonempty", "routed cable length > 0 (dash = FAIL)"),
        ("ΔU (%)", "computed", "volt-drop over the routed length at Design I, ≤ 5 % (dash = FAIL)"),
        ("In spec", "computed", "= (ΔU ≤ 5 %) of a PRESENT ΔU — a dash is never in-spec"),
        ("Board reconciliation", "computed",
         "Σ circuit design current ≈ board busbar demand (ratio within 0.8–1.25, the "
         "schedule's own OK band) + busbar rating stated — a REVIEW/dash row FAILS"),
        ("Drawing ↔ schedule", "computed",
         "single-line voltage + board hierarchy strings + transformer kVA must match "
         "the schedule and the contract quantity (one dataset, two projections)"),
    ]

    def _col(hdr: List[str], *keys: str) -> Optional[int]:
        for i, h in enumerate(hdr):
            hl = h.lower()
            if any(k in hl for k in keys):
                return i
        return None

    per_row: Dict[str, dict] = {}
    n_pass = 0
    source_fabricated = 0
    for _heading, hdr, trows in tables:
        if len(hdr) < 6:
            continue          # board key-value header tables are not circuit tables
        _board = str(_heading or "").strip()
        c_ckt, c_kw = 0, _col(hdr, "load (kw)", "conn. load", "kw")
        c_i = _col(hdr, "design i", "current (a)")
        c_dev = _col(hdr, "device")
        c_cab = _col(hdr, "cable")
        c_len = _col(hdr, "length")
        c_du = _col(hdr, "δu", "volt", "drop")
        c_sp = _col(hdr, "spec")
        for trow in trows:
            ckt = (trow[c_ckt] if c_ckt < len(trow) else "").strip()
            if not ckt or "TOTALS" in " ".join(trow).upper():
                continue
            cell = lambda ci: (trow[ci].strip() if ci is not None and ci < len(trow) else "")  # noqa: E731
            reasons: List[str] = []
            kw = num(cell(c_kw))
            if kw is None or kw <= 0:
                reasons.append("connected load (kW) missing")
            amps = num(cell(c_i))
            if amps is None or amps <= 0:
                reasons.append("Design I missing")
            elif kw:
                _bv, _bkind = _board_system(_board)
                if _bkind == "dc":
                    pf_eta = (kw * 1000.0) / (_bv * amps)              # P = V·I (no √3, no pf)
                    _sys_lbl = f"{_bv:g} V DC"
                elif _bkind == "1ph":
                    pf_eta = (kw * 1000.0) / (_bv * amps)              # P = V·I·pf
                    _sys_lbl = f"{_bv:g} V 1-phase"
                else:
                    pf_eta = (kw * 1000.0) / (math.sqrt(3.0) * _bv * amps)
                    _sys_lbl = f"{_bv:g} V 3-phase"
                # Sub-kW motors: Design I rounds to 0.1 A and implied pf·η leaves the
                # 0.60–1.05 band by pure rounding (acid dosing 0.04 kW). Skip band for
                # kw < 1 — same floor as the live Excel formula (P1-E Sam/Codema).
                if kw >= 1.0 and not (0.60 <= pf_eta <= 1.05):
                    reasons.append(f"Design I {amps:g} A inconsistent with {kw:g} kW at {_sys_lbl} "
                                   f"(implied pf·η {pf_eta:.2f} outside 0.60–1.05)")
            dev_a = num(cell(c_dev))
            if dev_a is None:
                reasons.append("protective device rating missing")
            elif amps and dev_a < amps:
                reasons.append(f"protective device {dev_a:g} A below Design I {amps:g} A")
            _cab_txt = cell(c_cab)
            if "mm²" not in _cab_txt and "mm2" not in _cab_txt:
                reasons.append("cable CSA missing")
            else:
                # CABLE AMPACITY ≥ DEVICE RATING (fix 4): BS 7671 Ib ≤ In ≤ Iz — the
                # protective device must not out-rate the cable it protects.
                _csa_m = re.search(r"(\d+(?:\.\d+)?)\s*mm[²2]", _cab_txt)
                if _csa_m and dev_a is not None:
                    _iz = _METHOD_C_AMPACITY_A.get(float(_csa_m.group(1)))
                    if _iz is not None and dev_a > _iz:
                        reasons.append(f"protective device {dev_a:g} A exceeds the "
                                       f"{_csa_m.group(1)} mm² cable's Method-C ampacity "
                                       f"{_iz:g} A (BS 7671 In ≤ Iz)")
            ln = num(cell(c_len))
            if ln is None or ln <= 0:
                reasons.append("routed cable length missing (dash is not data — the run's electrical "
                               "circuits were never routed, so no length exists to verify ΔU against)")
            du = num(cell(c_du))
            if du is None:
                reasons.append("ΔU% missing — volt-drop unverifiable (a dash is never in-spec)")
            elif du > 5.0:
                reasons.append(f"ΔU {du:g}% exceeds the ≤5% band")
            verdict = "PASS" if not reasons else "FAIL"
            if verdict == "PASS":
                n_pass += 1
            if verdict == "FAIL" and "✓" in cell(c_sp):
                source_fabricated += 1
            # KEY = (board, circuit ref) — a multi-board schedule reuses circuit refs
            # ("W1" on the MDB *and* on an MCC sub-board); keying by the bare ref
            # collided the rows and mis-counted the arithmetic (v52: true 16/17 read
            # 16/16). A residual collision (same board, same ref) falls back to a
            # positional suffix so NO row is ever silently dropped from the count.
            _key = f"{_board} · {ckt}" if _board else ckt
            if _key in per_row:
                _key = f"{_key} #{len(per_row)}"
            per_row[_key] = {"verdict": verdict, "reasons": reasons, "du": du,
                             "length_m": ln, "board": _board, "ckt": ckt}

    if not per_row:
        return None

    # ── BOARD RECONCILIATION rows (fix 4): the schedule prints its OWN per-board
    #    'Reconciliation: Σ circuit design current = X A vs board busbar demand = Y A
    #    (ratio Z) → REVIEW/OK' line + a 'Busbar rating' field. A REVIEW verdict, a
    #    ratio outside the band, or a dash busbar rating = a FAILING contract row —
    #    the tab can no longer score 10.0 over its own printed REVIEW. ──
    recon_rows: List[dict] = []
    # (_board_meta is parsed ONCE above, before the circuit loop — 2026-07-03.)
    _recon_rx = re.compile(
        r"Reconciliation:\*{0,2}\s*Σ circuit design current = ([\d.,]+)\s*A vs board "
        r"busbar demand = ([\d.,]+)\s*A \(ratio ([\d.,]+)\) → \*{0,2}(\w+)")
    _chunks = re.split(r"^##\s+", text, flags=re.M)[1:]
    for _ch in _chunks:
        _bname = _ch.splitlines()[0].strip() if _ch.splitlines() else ""
        if not _bname:
            continue
        _meta = _board_meta.get(_bname, {})
        _rs: List[str] = []
        _detail = ""
        _mrec = _recon_rx.search(_ch)
        if _mrec:
            _sig, _dem, _ratio, _verd = (_mrec.group(1), _mrec.group(2),
                                         num(_mrec.group(3)) or 0.0,
                                         _mrec.group(4).upper())
            _detail = (f"Σ circuit design current {_sig} A vs busbar demand {_dem} A "
                       f"(ratio {_ratio:g}); busbar rating: {_meta.get('busbar rating', '—')}")
            if _verd != "OK":
                _rs.append(f"the schedule's own reconciliation says {_verd} "
                           f"(ratio {_ratio:g})")
            elif not (_BOARD_RECON_BAND[0] <= _ratio <= _BOARD_RECON_BAND[1]):
                # ABSOLUTE micro-board tolerance (2026-07-11 run 65 — ONE MINT with the
                # schedule's own verdict): at magnitudes under one real 6 A device the
                # ratio is meaningless; a gap within a single MCB of diversity is never
                # a design defect. Mirrors draw_panel_schedule's rule exactly.
                _sig_a, _dem_a = num(_sig) or 0.0, num(_dem) or 0.0
                if abs(_sig_a - _dem_a) > 6.0:
                    _rs.append(f"ratio {_ratio:g} outside the "
                               f"{_BOARD_RECON_BAND[0]:g}–{_BOARD_RECON_BAND[1]:g} band")
        else:
            _rs.append("no reconciliation line printed for this board")
            _detail = f"busbar rating: {_meta.get('busbar rating', '—')}"
        _bb = _meta.get("busbar rating", "")
        if not _bb or _bb in ("—", "-", ""):
            _rs.append("busbar rating missing (dash) — the board's Σ current has no "
                       "stated capacity to reconcile against")
        _key = f"{_bname} · [board reconciliation]"
        _v = "PASS" if not _rs else "FAIL"
        if _v == "PASS":
            n_pass += 1
        per_row[_key] = {"verdict": _v, "reasons": _rs, "board": _bname,
                         "ckt": "[board reconciliation]"}
        recon_rows.append({"check": _key, "detail": _detail, "verdict": _v,
                           "reasons": _rs,
                           # structured operands → the renderer EMBEDS these as audit
                           # cells and the Row check becomes a live formula over them
                           "op": "board-recon",
                           "ratio": (num(_mrec.group(3)) if _mrec else None),
                           "sched_verdict": (_mrec.group(4).upper() if _mrec else None),
                           # Σ + demand as NUMBERS so the live formula can state the SAME
                           # micro-board absolute clause python applies above (run-73
                           # one-truth breach: in-cell ratio band alone FAILed 0.17 while
                           # python passed |4−1|≤6 → workbook floor 8.9 vs python 9.2)
                           "sum_a": (num(_mrec.group(1)) if _mrec else None),
                           "demand_a": (num(_mrec.group(2)) if _mrec else None),
                           "busbar": _meta.get("busbar rating", "")})

    # ── DRAWING ↔ SCHEDULE consistency rows (fix 4): the single-line diagram and the
    #    schedule must project the SAME dataset — voltage, board hierarchy strings and
    #    transformer kVA (also checked against the CONTRACT quantity). ──
    _svg_path = os.path.join(run_dir, "drawings", "single-line-diagram.svg")
    _svg_texts: List[str] = []
    if os.path.exists(_svg_path):
        try:
            _svg_texts = [t.strip() for t in
                          re.findall(r">([^<>]{1,120})<", open(_svg_path).read())
                          if t.strip()]
        except Exception:  # noqa: BLE001
            _svg_texts = []
    if _svg_texts:
        # GOTCHA: SVG text nodes HTML-escape '&' as '&amp;' (e.g. 'TP&amp;N').
        # The panel schedule heading is the unescaped form ('TP&N'). Comparing
        # raw SVG text to schedule board names false-FAILs board hierarchy even
        # when both projections used the same canonical_board_name mint.
        import html as _html
        _svg_join = _html.unescape(" | ".join(_svg_texts))

        def _consistency_row(key: str, ok: bool, detail: str, reason: str,
                             op: Optional[dict] = None) -> None:
            nonlocal n_pass
            _v = "PASS" if ok else "FAIL"
            if ok:
                n_pass += 1
            per_row[key] = {"verdict": _v, "reasons": ([] if ok else [reason]),
                            "board": "single-line ↔ schedule", "ckt": key}
            recon_rows.append({"check": key, "detail": detail, "verdict": _v,
                               "reasons": [] if ok else [reason], **(op or {})})

        # 1 — system voltage: the schedule's LV system voltage must appear on the drawing
        # as its OWN token (exact-token SET membership — NOT a substring test: "400" is a
        # substring of "14000"/"1400", so a naive `in " ".join(tokens)` can false-PASS on
        # an unrelated larger number that happens to contain the same digits). The live
        # formula mirrors this with SEARCH(" "&needle&" "," "&haystack&" ") — the padding
        # spaces are added AT FORMULA-EVAL TIME on BOTH operands (never stored baked into
        # the cell's VALUE): clean_cell() strips leading/trailing whitespace off every
        # 'Audit data' operand on write (control-char/markdown hygiene), which silently
        # ate a pre-padded stored value and broke the delimiter search (ONE-TRUTH
        # divergence 2026-07-03: python said PASS, the recalculated formula said FAIL for
        # the identical single-token case — a rendering-plumbing bug, not a real check
        # disagreement). Padding the operands in the FORMULA text is immune to any future
        # trim/clean pass over the stored cell value.
        _draw_v_tokens = sorted(set(re.findall(r"(\d{3,5})\s*V", _svg_join)))
        _v_ok = f"{board_v:g}" in _draw_v_tokens
        _consistency_row(
            "single-line ↔ schedule · system voltage", _v_ok,
            f"schedule system {board_v:g} V 3-phase; drawing voltages: "
            + (", ".join(sorted(set(re.findall(r"\d{3,5}(?:/\d{3,5})?\s*V", _svg_join)))[:4]) or "none"),
            f"the drawing never states the schedule's {board_v:g} V system voltage",
            op={"op": "voltage", "sched_v": f"{board_v:g}",
                "draw_v": " ".join(_draw_v_tokens)})
        # 2 — board hierarchy strings: every schedule board reference must appear on
        #     the drawing (same dataset → same names; 'MAIN LV BOARD' vs 'Motor
        #     Control Center' means the two were generated from different data).
        # GOTCHA (Powerwall 2026-07-15): canonical_board_name stamps the SLD main
        # as 'MAIN DC BUS' while the panel schedule may still echo a BoM hub id
        # ('Busbar Assembly' / 'DC Busbar Assembly') as a sub-board heading — the
        # SAME physical DC bus. When MAIN DC BUS is on the drawing, those busbar-
        # named board refs are satisfied (alias), not a real divergence.
        _svg_has_main_dc = "main dc bus" in _svg_join.lower()

        def _board_ref_on_sld(b: str) -> bool:
            if not b:
                return True
            if b.lower() in _svg_join.lower():
                return True
            if _svg_has_main_dc and re.search(r"\bbus(?:bar)?\b", b, re.I):
                return True
            return False

        _missing_boards = [b for b in _board_meta if not _board_ref_on_sld(b)]
        _consistency_row(
            "single-line ↔ schedule · board hierarchy", not _missing_boards,
            f"schedule boards: {', '.join(_board_meta) or '—'}",
            "board reference(s) absent from the single-line drawing: "
            + ", ".join(_missing_boards[:3]),
            op={"op": "boards", "missing": ", ".join(_missing_boards),
                "named": ", ".join(_board_meta)})
        # 3 — transformer kVA: the drawing's transformer rating vs the CONTRACT quantity
        _q = ((state.get("orchestratorContract") or {}).get("quantities") or {})
        _kva_contract = None
        # ('transformer_rating_kva' added 2026-07-03: the BESS contract emits the rating
        #  under that key — the join must not report 'contract missing' over a present one.)
        for _k in ("transformer_kva", "main_transformer_kva", "transformer_rating_kva"):
            _kv = _q.get(_k)
            if isinstance(_kv, dict) and isinstance(_kv.get("value"), (int, float)):
                _kva_contract = float(_kv["value"])
                break
        _kva_drawing = None
        for _ti, _t in enumerate(_svg_texts):
            if re.match(r"^TX\d*\b", _t) or re.search(r"\btransformer\b", _t, re.I):
                for _t2 in _svg_texts[_ti:_ti + 3]:
                    _km = re.search(r"([\d.,]+)\s*kVA", _t2)
                    if _km:
                        _kva_drawing = num(_km.group(1))
                        break
                if _kva_drawing is not None:
                    break
        # 4 — PANEL vs CONTRACT power authority (2026-07-10 Tristan/Grok false-ship
        # review: the panel schedule shipped 195.5 kW / 696 A on an 11.04 kW product and
        # NOTHING failed). The schedule's connected-load total must reconcile with the
        # contract's own connected_electrical_load_kw (±25% — feeder margins are real);
        # a contradiction is WRONGNESS and fails the row (and with it the tab's >=8).
        _q_conn = None
        for _ck in ("connected_electrical_load_kw", "total_connected_load_kw", "total_electrical_demand_kw"):
            _cv = _q.get(_ck)
            if isinstance(_cv, dict) and isinstance(_cv.get("value"), (int, float)):
                _q_conn = float(_cv["value"]); break
        _sched_kw = None
        _sched_board = None
        _ps_md = os.path.join(run_dir, "drawings", "panel-schedule.md")
        if os.path.exists(_ps_md):
            try:
                _sched_kw, _sched_board = _panel_connected_load_for_contract(
                    open(_ps_md).read(), _q)
            except Exception:  # noqa: BLE001
                _sched_kw = None
                _sched_board = None
        if _q_conn is not None and _sched_kw is not None:
            _pw_ok = (_q_conn > 0 and abs(_sched_kw - _q_conn) <= 0.25 * max(_q_conn, 0.001))
            _consistency_row(
                "panel schedule ↔ contract · connected load", _pw_ok,
                f"schedule board {_sched_board or '?'} total {_sched_kw:g} kW vs "
                f"contract connected_electrical_load_kw {_q_conn:g} kW",
                f"the {_sched_board or 'selected'} schedule board's {_sched_kw:g} kW "
                f"connected load contradicts the contract's "
                f"{_q_conn:g} kW — an invented load table (fix the feeder derivation, not the row)",
                op={"op": "panel_kw", "sched": _sched_kw, "contract": _q_conn,
                    "board": _sched_board})
        elif _sched_kw is not None:
            _consistency_row(
                "panel schedule ↔ contract · connected load", False,
                f"schedule total {_sched_kw:g} kW; contract carries NO connected-load quantity",
                "the contract emits no connected_electrical_load_kw — the panel total is unverifiable "
                "(emit the quantity in the class contract so this row can reconcile)",
                op={"op": "panel_kw", "sched": _sched_kw, "contract": None})
        if _kva_contract is not None or _kva_drawing is not None:
            _kva_ok = (_kva_contract is not None and _kva_drawing is not None
                       and abs(_kva_drawing - _kva_contract) <= 0.10 * _kva_contract)
            _consistency_row(
                "single-line ↔ schedule · transformer kVA", _kva_ok,
                f"drawing transformer {_kva_drawing if _kva_drawing is not None else '—'} kVA "
                f"vs contract quantity {_kva_contract if _kva_contract is not None else '—'} kVA",
                f"transformer kVA mismatch: drawing "
                f"{_kva_drawing if _kva_drawing is not None else 'missing'} vs contract "
                f"{_kva_contract if _kva_contract is not None else 'missing'} "
                f"(must match within 10% — one dataset)",
                op={"op": "kva", "d": _kva_drawing, "c": _kva_contract})

    n_total = len(per_row)
    score = _contract_score(n_pass, n_total)
    n_fail = n_total - n_pass
    issues: List[str] = []
    if n_fail:
        ex = [f"{k}: {v['reasons'][0]}" for k, v in per_row.items() if v["verdict"] == "FAIL"][:3]
        issues = [f"{n_fail}/{n_total} circuit/board/drawing rows FAIL the column contract "
                  f"(arithmetic score 10 × {n_pass}/{n_total} = {score}) — e.g. " + " · ".join(ex)]
        if source_fabricated:
            issues.append(f"{source_fabricated} source row(s) rendered ✓ over a dash/failing contracted "
                          "column — fabricated ticks, now rendered ✗")
    return {"tab": "Panel schedule", "contract": contract, "rows": per_row,
            "n_pass": n_pass, "n_total": n_total, "score": score,
            "status": "PASS" if (score or 0) >= 8 else "FAIL", "issues": issues,
            "source_fabricated": source_fabricated,
            "recon_rows": recon_rows,
            # per-board electrical system (V, kind, pf·η factor) — the renderer embeds
            # these as audit operands so the circuit Row-check formulas are live
            "board_system": {b: {"v": _board_system(b)[0], "kind": _board_system(b)[1],
                                 "factor": (math.sqrt(3.0) if _board_system(b)[1] == "3ph"
                                            else 1.0)}
                             for b in _board_meta},
            "fix": ("route the electrical circuits in the scene (wire the electrical_bus edges) so "
                    "route-manifest / connection-schedule carry real cable lengths, compute ΔU% "
                    "= f(length, CSA, Design I) in draw_panel_schedule at source, and generate the "
                    "single-line + schedule from the ONE distribution dataset so kVA / voltage / "
                    "board names cannot diverge")}


# ── BoM LEDGER column contract (Tristan 2026-07-02, issue 7) ─────────────────────────────
# Material lexicon — a material the row ALREADY carries: its `material` field, an 'MoC:'
# clause, or a material token inside its basis / requirement string (a pipe line's
# "(HDPE/PVC-U)", a "Painted Carbon Steel Skid Frame"). UNIVERSAL — a lexicon of
# engineering materials, never a per-class part table.
_MATERIAL_TOKEN_RE = re.compile(
    r"MoC:\s*[^·;|]+|\b(?:316L?|304L?|904L|duplex|super[- ]?duplex|stainless(?:\s+steel)?|"
    r"carbon\s+steel|mild\s+steel|galvani[sz]ed(?:\s+steel)?|weathering\s+steel|"
    r"aluminium|aluminum|copper|brass|bronze|cast\s+iron|ductile\s+iron|titanium|hastelloy|"
    r"HDPE|MDPE|LDPE|PVC(?:-[UC])?|uPVC|CPVC|PP[RH]?\b|PTFE|PVDF|PFA|ABS|PMMA|POM|"
    r"FRP|GRP|EPDM|NBR|nitrile|viton|silicone|polycarbonate|polyethylene|polypropylene|"
    r"polyurethane|rubber|ceramic|concrete)\b", re.I)


def _bom_row_material(row: dict) -> str:
    """The material the row itself discloses: the `material` field first, else the
    MoC / material token in its basis or requirement text. '' = none stated."""
    m = str(row.get("material") or "").strip()
    if m:
        return m
    for src in (row.get("basis"), row.get("requirement")):
        hit = _MATERIAL_TOKEN_RE.search(str(src or ""))
        if hit:
            return re.sub(r"^MoC:\s*", "", hit.group(0).strip()).strip()
    return ""


# Fabrication signals — data the row already carries that says "this is a PHYSICAL part
# fabricated / sized to a geometry" (a vessel shell, a routed pipe run, a structural
# frame): physics-sized dimension / mass fields, a take-off or made-to-spec basis, a
# routed connection. Everything else is a bought-out ASSEMBLY / PACKAGE priced as a unit.
_FAB_FIELDS = ("wall_mm", "mass_kg", "diameter_m", "height_m", "footprint_m2", "length_m")
_FAB_BASIS_RE = re.compile(
    r"take-?off|made-to-spec|tapered wall|structural|steelwork|fabricat|"
    r"\bpipe £|\bduct £|\bcable £|/m @|"
    # SITEWORKS take-off (Codema BoM 8.5, 2026-07-14): below-grade civils rows are
    # excavated/poured to a parametric model — fabricated sitework, never an MPN-bearing
    # bought-out assembly. Signal is the BASIS vocabulary (excavation / groundworks),
    # never a per-class table.
    r"below-grade civils|groundworks|bulk excavation|\bexcavation\b|\bbackfill\b",
    re.I)


# fabricated-to-the-drawing NAME families (2026-07-10, Powerwall run-38 Ledger 7.5):
# busbar work, thermal manifolds/bays, coolant loops, vent panels, structural frames,
# compartmentalised internals, insulation — copper/sheet-metal specified BY DRAWING,
# never by MPN; their honest MPN column is the fabrication disclosure, not a TBD
# penalty. MIRRORS parts_ledger.py _FABRICATED_PACK_WORK_RE (kept in sync by hand,
# same convention as the compliance matcher pair).
_FABRICATED_NAME_FAMILY_RX = re.compile(
    r"busbar\s+(?:interconnects?|connectors?|assembl(?:y|ies))|"
    r"thermal\s+management\s+(?:manifolds?|bays?|plenums?)|"
    r"(?:liquid\s+)?coolant\s+loops?|"
    r"deflagration\s+vent\s+panels?|"
    r"(?:auxiliary\s+)?power\s+distribution\s+unit|"
    r"structural\s+(?:base\s+)?frames?|compartmentali[sz]ed\s+internal|"
    r"(?:fireproof|thermal|acoustic)\s+insulation(?:\s+panels?)?", re.I)

# battery pack STRUCTURE — fabricated ONLY while unpinned (a TBD module/rack is the OEM's
# own cell-to-pack assembly work; a row with a REAL module MPN was genuinely bought and
# stays an assembly). 2026-07-10 run 51: TI BQ28400PW (a £5 gauge IC) + Sungrow ST2752UX
# (a 2.75 MWh utility container) were mis-pinned onto these words — the honest state is
# fabricated pack work, tallied unpenalised like the busbar/manifold families.
_FABRICATED_PACK_STRUCTURE_RX = re.compile(
    r"battery\s+modules?\b|(?:battery\s+)?module\s+racks?\b|pack\s+frames?\b|cell\s+stacks?\b", re.I)


def _bom_row_kind(row: dict, instrument_device: bool = False) -> str:
    """'fabricated' (physical part sized to a geometry — material REQUIRED) or
    'assembly' (bought-out unit/package — material n/a WITH reason). Derived ONLY from
    data the row already carries (shape fields / basis / connection / fabricated name
    family), never a class table.

    INTENT: on a device-scale instrument, BoM lines whose `part` is still a placeholder
    ('requirement stated') or status NOT FOUND are custom electronics / optics / printed
    enclosure — fabricated at concept stage, not ENGINEERED bought-out with a TBD MPN
    penalty (colorimeter 0819: 25/35 engineered-TBD floored BoM at 7.1)."""
    if instrument_device:
        part = str(row.get("part") or "").strip().lower()
        status = str(row.get("status") or "").strip().upper()
        if part in _MPN_PLACEHOLDER or status in ("NOT FOUND", "BESPOKE"):
            return "fabricated"
    if any((num(row.get(f)) or 0) > 0 for f in _FAB_FIELDS):
        return "fabricated"
    if _FAB_BASIS_RE.search(str(row.get("basis") or "")):
        return "fabricated"
    if _FABRICATED_NAME_FAMILY_RX.search(str(row.get("requirement") or "")):
        return "fabricated"
    if _FABRICATED_PACK_STRUCTURE_RX.search(str(row.get("requirement") or "")) \
            and str(row.get("part") or "").strip().lower() in _MPN_PLACEHOLDER | {"tbd (detailed design)"}:
        return "fabricated"
    if row.get("connection") or row.get("service"):
        return "fabricated"          # a routed line — a pipe/duct/cable take-off
    return "assembly"


_INSTRUMENT_MATERIAL_RULES = (
    (re.compile(r"enclosure|housing|shell|lid|shroud|chassis|case\b|cuvette\s+holder", re.I),
     "ABS / polycarbonate (injection-moulded enclosure)"),
    (re.compile(r"optic|lens|collimat|filter|window|photodiode|led\b|wavelength", re.I),
     "optical glass / polymer optic"),
    (re.compile(r"pcb|microcontroller|amplifier|adc|tia|regulator|fuse|esd|polyfuse|"
                r"connector|battery|charge|display|button|switch|annunciator|ferrite|"
                r"firmware|thermal\s+cutoff|status\s+indicator|membrane", re.I),
     "FR4 / electronic component (PCB-mounted)"),
)


def _instrument_row_material(row: dict) -> str:
    """Honest default MoC for a fabricated instrument part when the row states none."""
    text = f"{row.get('requirement') or ''} {row.get('part') or ''}"
    for rx, mat in _INSTRUMENT_MATERIAL_RULES:
        if rx.search(text):
            return mat
    return "custom fabricated (device assembly — material at detailed design)"


# `part` strings that are template placeholders, NOT a real part / datasheet reference.
_MPN_PLACEHOLDER = {"", "—", "-", "n/a", "na", "tbd", "requirement stated", "assembly detail"}


def _bom_row_mpn(row: dict, mpn_by_word: Dict[str, str]) -> str:
    """The row's real / DB-sourced part reference: partVerifications by tag, then by the
    requirement head noun (the SAME join tab_bom renders) — literal first, then the
    FOLD-TOLERANT join key (Bar C 2026-07-03: 'Pneumatic Actuated Valves' joins the
    verified singular 'Pneumatic Actuated Valve'; 'emergency stop button' joins
    'Emergency Stop Switch'; head-noun families never cross) — then the row's own
    `part` text when it is not a placeholder. '' = none. A partVerifications entry
    whose part_number is ITSELF a 'TBD …' marker (the engine emits 'TBD (detailed
    design)' for unresolved parts — 316/326 on codema v52) is NOT a resolved
    reference: it maps to '' here so the contract counts it as a TBD, never a fake
    real MPN — and as a BLOCKER it stops the `row.part` fallback (a generic class
    description must not masquerade as a reference for a word the engine explicitly
    deferred)."""
    _tbd = lambda s: bool(re.match(r"^\s*TBD\b", s, re.I))  # noqa: E731
    mpn = mpn_by_word.get(str(row.get("tag", "")).strip().lower()) or ""
    req = str(row.get("requirement") or "").strip()
    if (not mpn or _tbd(mpn)) and req:
        head = re.split(r"[·\-(]", req)[0].strip().lower()
        # INTENT: progressive family truncation — 'emergency stop button' (folded to
        # 'emergency stop switch') must still join a verified sibling pinned as
        # 'emergency stop'. A TBD twin on the longer key must not block the shorter
        # family pin (Codema 2026-07-14: Eaton 216516 on 'Emergency Stop' never
        # reached the 'Emergency Stop Button' ledger row). NEVER drops the last
        # remaining token alone into a different head-noun family — truncation
        # stops at ≥2 tokens so 'pressure switch' cannot reach 'pressure' alone
        # and then a 'pressure transmitter' pin.
        keys: List[str] = []
        if head:
            keys.append(head)
        for alt in _mpn_join_key_alts(re.split(r"[·(]", req)[0]):
            if alt and alt not in keys:
                keys.append(alt)
            toks = alt.split()
            for n in range(len(toks) - 1, 1, -1):
                short = " ".join(toks[:n])
                if short not in keys:
                    keys.append(short)
        cands = [mpn_by_word.get(k, "") for k in keys if k]
        resolved = next((c for c in cands if c and not _tbd(c)), "")
        mpn = resolved or mpn or (cands[0] if cands else "") or (cands[1] if len(cands) > 1 else "")
    if not mpn:
        part = str(row.get("part") or "").strip()
        if part.lower() not in _MPN_PLACEHOLDER:
            mpn = part
    if _tbd(mpn):
        mpn = ""
    if not mpn:
        # INTENT: concept-stage panel/safety hardware with a single canonical MPN in
        # the forge-truth seed (Eaton e-stop, Bender IMD) — pin by noun family so a
        # Powerwall 'Emergency Stop Button' / 'Insulation Monitoring Device' does not
        # stay engineered-TBD when the DB already has the authoritative part. Never
        # invents MPNs for pumps/filters (proveCatch: dosing pump stays unresolved).
        mpn = _catalogue_fallback_mpn(req)
    return mpn


# Seeded from forge-truth `pretraining_extracted_parts` (Eaton 216516, Bender iso-PV1685P)
# — noun-keyed, never a per-class table. Only fires when partVerifications left a gap.
_CATALOGUE_FALLBACK_MPN = (
    (re.compile(r"\bemergency\s+stop\b", re.I), "Eaton 216516"),
    (re.compile(r"\binsulation\s+monitoring\b", re.I), "Bender iso-PV1685P"),
)


def _catalogue_fallback_mpn(requirement: str) -> str:
    """Authoritative panel/safety MPN for a concept-stage noun, or ''."""
    text = str(requirement or "")
    for rx, mpn in _CATALOGUE_FALLBACK_MPN:
        if rx.search(text):
            return mpn
    return ""


_TBD_MPN_TEXT = "TBD (detailed design)"

# S10 (council H10): catalogue-electronic noun families — a part whose noun names a catalogue
# electronic component (never a machined-to-drawing mechanical part). If such a part has no
# resolved MPN, "bespoke fabrication to drawing" is a false-satisfied claim → UNRESOLVED.
_ELECTRONIC_NOUN_RX = re.compile(
    r"\bmcu\b|microcontroller|\bmpu\b|\bcpu\b|processor|\bfpga\b|\bic\b|\badc\b|\bdac\b|"
    r"\bafe\b|amplifier|op[- ]?amp|\bregulator\b|\bldo\b|\bpmic\b|\bdc[- ]?dc\b|transceiver|"
    r"\bsensor\b|thermistor|thermocouple|photodiode|phototransistor|\bled\b|\bdiode\b|"
    r"\bmosfet\b|transistor|\bbjt\b|\bfuse\b|polyfuse|\btvs\b|\besd\b|varistor|"
    r"connector|receptacle|\bheader\b|\busb\b|ethernet|\brj45\b|\bhdmi\b|crystal|oscillator|"
    r"\beeprom\b|\bflash\b|memory|\bram\b|isolat(?:or|ion)|opto|relay|\bpcb\b|"
    r"resistor|capacitor|inductor|ferrite|\bbead\b|reference|comparator|\bgpio\b|"
    r"peltier|thermoelectric|\btec\s+module\b|tachometer|protocol\s+bridge|"
    r"debug\s+header|firmware\s+storage|voltage\s+reference|\btia\b", re.I)

# ── HONEST TBD TAXONOMY (2026-07-03; extended 2026-07-04 round-3 dissection). Real
# concept-stage EPC practice: several classes of bought-out line do NOT carry MPNs
# at concept stage FOR HONEST REASONS — nobody expects a manufacturer part number on
# a £2 terminal block until procurement; the engine DELIBERATELY refuses an MPN pin
# on a generic-spec process valve (bought by DN/material/rating, never a single
# part number); an OEM-integral controller can genuinely have no published part
# number at all. Penalising any of those exactly like an unidentified ENGINEERED
# pump/analyser/VFD would be dishonest scorer-softening in the OTHER direction —
# these are engine-refused-by-design or verified gaps, not skipped research. The
# taxonomy therefore splits the bought-out lines into FIVE tallies (all printed in
# the tab header — resolved / commodity / generic-spec / OEM-proprietary /
# engineered-TBD), evaluated in that priority order so no row double-counts:
#   • COMMODITY — requires BOTH signals (proveCatch: neither alone can reclassify):
#       (a) a commodity NOUN family match (_COMMODITY_NOUN_RX — a universal
#           small-parts lexicon, never a per-class table), AND
#       (b) a class-basis unit price under the STATED threshold
#           (_COMMODITY_UNIT_GBP_MAX, printed in the tab header), with a stated
#           pricing basis on the row.
#     Renders 'commodity — MPN at procurement'; tallied SEPARATELY, NEVER penalised.
#   • GENERIC-SPEC PROCESS VALVE — requires BOTH (proveCatch both directions):
#       (a) the engine's own refusal vocabulary (_commodity_process_valve — mirrors
#           isCommodityProcessValve exactly), AND
#       (b) the row's OWN cells carry the FULL procurable spec — DN/size + material
#           + rating/PN (_valve_spec_complete, formula-checked from the row, no £ cap).
#     A spec-INCOMPLETE engine-refused valve stays engineered-TBD — the gap is real.
#     Renders 'generic spec — MPN at procurement'; tallied SEPARATELY (distinct from
#     COMMODITY — not price-gated), NEVER penalised.
#   • OEM-PROPRIETARY (no public MPN) — requires a RECORDED research finding on the
#     row's own `basis` (_oem_proprietary_row) — never self-declared by a merely
#     absent price/part. Renders 'OEM-proprietary (no public MPN)'; tallied
#     SEPARATELY, NEVER penalised.
#   • ENGINEERED — every other bought-out line; a missing MPN stays the explicit
#     'TBD (detailed design)' and keeps the FULL proportional score penalty.
# proveCatch in _selftest: an engineered pump with TBD still penalises (noun family
# fails even under the price threshold); a £5k 'gland plate' package still
# penalises (price threshold fails even with the noun); a spec-complete valve
# qualifies generic-spec, a spec-incomplete one stays TBD; a researched
# no-public-MPN row qualifies OEM-proprietary, a merely-unpriced one never does. ──
_COMMODITY_MPN_TEXT = "commodity — MPN at procurement"
_COMMODITY_UNIT_GBP_MAX = 100.0
_COMMODITY_NOUN_RX = re.compile(
    r"\b(?:cable\s+)?glands?\b|\bunions?\b|\bcouplings?\b|\bdin\s+rail\b|"
    r"\bterminal\s+(?:block|strip)s?\b|"
    r"\b(?:fastener|bolt|nut|washer|screw|stud|anchor|rivet)s?\b|"
    r"\b(?:gasket|o-?ring|ferrule|lug|crimp)s?\b|"
    r"\b(?:cable\s+tie|tie-?wrap|label|marker)s?\b|"
    r"\b(?:spacer|standoff|shim)s?\b|\blevell?ing\s+(?:feet|foot|pads?)\b|"
    # enclosure hardware (2026-07-10 — mirrors parts_ledger._ENCLOSURE_HARDWARE_RE):
    r"warning\s+sign|signage|(?:internal|service|cabinet)\s+lighting|"
    r"service\s+(?:outlets?|sockets?)|(?:grounding|earthing)\s+terminals?|"
    r"(?:service\s+)?access\s+doors?(?:\s+and\s+locks?)?|"
    r"\bconnectors?\b|\b(?:cabling|wiring|conduit|trunking|cable\s+tray)\b|"
    # pipe-joint CLOSURE hardware + bare pipe-stub CONNECTION POINTS (Codema v63
    # residual, 2026-07-03): a FLANGE + its GASKET are the bolted joint on a pipe
    # run; an END CAP / blanking cap is the closure fitting on a spool/manifold
    # end; a bare HOSE (no 'assembly'/'flexible' qualifier — e.g. 'CIP Hose') is
    # routed flexible pipework, the same commodity class as a hose assembly; a
    # bare stream OUTLET/inlet ('Permeate Outlet') is a pipe-stub connection
    # point, priced as a nominal fitting allowance, never a catalogue-pinned part.
    # Every one still needs BOTH legs of the triple guard (noun AND unit £ ≤
    # threshold AND a stated basis) — a real engineered item wearing one of
    # these words at a real price never reclassifies (proveCatch in _selftest).
    r"\bflanges?\b|\bend\s+caps?\b|\bhoses?\b|\boutlets?\b|"
    r"\bfittings?\b|"
    # FIELD SENSORS / PANEL INDICATORS (Powerwall BoM 7.5, 2026-07-14): concept-stage
    # ESS dossiers pin CTs/thermistors/alarms/pilot lights BY SPEC, not MPN — same
    # commodity discipline as glands. Still gated by unit £ ≤ £100 + stated basis so a
    # £2k insulation-monitor or £246 E-stop never escapes the engineered-TBD penalty.
    r"\bshunts?\b|\bthermistors?\b|\bprobes?\b|\bsensors?\b|\banaly[sz]ers?\b|"
    r"audible\s+alarms?|\balarms?\b|indicator\s+lights?|status\s+(?:lights?|leds?|indicators?)|"
    r"pilot\s+(?:lights?|lamps?)|"
    r"\barc\s+fault\b|\barc\s+flash\b|"
    r"bypass\s+switch(?:es)?|\bmodbus\b|"
    # PANEL PROTECTION / SMALL ELECTRONICS (Codema BoM 8.5, 2026-07-14): motor-overload
    # relays, pressure-relief valves priced as fittings, and a bare MCU allowance are
    # procured by spec/family at concept stage — still BOTH-gated (noun + unit £ ≤ £100
    # + stated basis). A £218 E-stop or £1.6k DO analyser stays engineered-TBD.
    r"(?:motor\s+)?overload(?:\s+protections?|\s+relays?)?|thermal\s+overloads?|"
    r"pressure\s+relief\s+valves?|"
    r"\b(?:microcontrollers?|mcus?)\b", re.I)


# ── COMMODITY PROCESS VALVE (Bar B, 2026-07-03; SPLIT OUT to its own GENERIC-SPEC
# taxonomy 2026-07-04 — round-3 dissection): the ENGINE refuses MPNs on a simple
# mechanical process valve by design (emitter-completion isCommodityProcessValve —
# a DN50 ball valve is bought BY SPEC: size + rating + material, never by a single
# name-matched MPN). Mirrors the engine's vocabulary exactly (+ manual/sample). An
# ACTUATED / control / solenoid / dosing / relief valve stays ENGINEERED (it has a
# real pin path — e.g. Bürkert Type 2000 — or a set pressure to certify) and keeps
# the full TBD penalty.
# 2026-07-04 CORRECTION: this valve family is NO LONGER folded into the £-capped
# COMMODITY bucket (_commodity_bought_out below) — a DN300 isolation valve refused
# an MPN by the engine is not a £2 gland, and gating it on the commodity PRICE cap
# was dishonest in the other direction (a £500 ball valve used to stay penalised
# TBD purely because it cleared the price cap, even though the engine refuses it
# an MPN regardless of price). It is now its OWN tally, GATED ON SPEC COMPLETENESS
# instead of price — see _GENERIC_SPEC taxonomy below.
_VALVE_ACTUATION_RX = re.compile(
    r"actuat|automat|solenoid|motoris|motoriz|\bcontrol\b|dosing|metering|modulat|"
    r"throttl|pneumatic|electric|relief|safety", re.I)
_COMMODITY_VALVE_NOUN_RX = re.compile(
    r"\b(check|non.?return|swing|ball|gate|globe|needle|wafer|lift|foot|"
    r"isolation|isolat\w*|manual|sample)\b", re.I)


def _commodity_process_valve(text: str) -> bool:
    n = str(text or "")
    if not re.search(r"\bvalves?\b|\bnon.?return\b", n, re.I):
        return False
    if _VALVE_ACTUATION_RX.search(n):
        return False
    return bool(_COMMODITY_VALVE_NOUN_RX.search(n))


# INTENT: cost-repair corpus lifts (e.g. Access Doors £40→£300 to p25) must not
# convert an honest commodity line into engineered-TBD. The PRE-lift amount is the
# class-basis signal the commodity gate cares about; the printed unit £ stays the
# lifted figure for the bill arithmetic.
_CORPUS_LIFT_RX = re.compile(
    r"lifted\s*£\s*([0-9]+(?:\.[0-9]+)?)\s*(?:→|->)\s*£\s*([0-9]+(?:\.[0-9]+)?)",
    re.I,
)


def _commodity_unit_for_gate(row: dict, unit: Optional[float]) -> Optional[float]:
    """Unit £ for the commodity price gate. Prefer the pre-lift corpus amount when the
    basis records a lift from a sub-threshold parametric price — proveCatch: Access
    Doors lifted £40→£300 still commodity-qualifies; a lift from £150→£300 does not."""
    if unit is None or unit <= 0:
        return unit
    m = _CORPUS_LIFT_RX.search(str(row.get("basis") or ""))
    if m:
        pre = float(m.group(1))
        if 0 < pre <= _COMMODITY_UNIT_GBP_MAX:
            return pre
    return unit


def _commodity_bought_out(row: dict, unit: Optional[float]) -> bool:
    """True only when BOTH commodity signals hold: a commodity small-parts noun family
    AND a stated class-basis unit price under the threshold. An engineered pump can
    never be reclassified by price alone; a £5k 'gland' package never by noun alone.
    Engine-refused PROCESS VALVES are handled separately (_generic_spec_valve, gated
    on spec completeness, never on this £ cap — 2026-07-04).
    DECISION: the price leg uses `_commodity_unit_for_gate` so a corpus lift past the
    cap cannot erase an otherwise-honest commodity classification."""
    gate_unit = _commodity_unit_for_gate(row, unit)
    if gate_unit is None or gate_unit <= 0 or gate_unit > _COMMODITY_UNIT_GBP_MAX:
        return False
    if not str(row.get("basis") or "").strip():
        return False        # class-basis priced small parts only — never an unpriced mystery
    text = f"{row.get('requirement') or ''} {row.get('part') or ''}"
    return bool(_COMMODITY_NOUN_RX.search(text))


# ── GENERIC-SPEC PROCESS VALVE taxonomy (2026-07-04, round-3 dissection). An
# engine-refused process valve (_commodity_process_valve, above) is procured BY
# SPEC — DN/size + material + pressure/class rating — never by a single MPN. The
# scorer honours that ONLY when the row's OWN cells actually carry that full
# procurable spec (formula-checked, never assumed): a spec-INCOMPLETE valve row
# stays engineered-TBD, because the spec work is then genuinely missing — the
# penalty is honest. Distinct from the COMMODITY-PRICE class above: no £ cap here
# at all, a £2,000 DN300 isolation valve with a complete spec still qualifies.
# proveCatch both directions in _selftest.
_VALVE_DN_SIZE_RX = re.compile(
    r"\bDN\s*\d{2,4}\b|\b\d+(?:\.\d+)?\s*(?:\"|in(?:ch)?)\b", re.I)
_VALVE_RATING_RX = re.compile(
    r"\bPN\s*\d{1,3}\b|\bclass\s*\d{2,4}\s*#?\b|\bANSI\s*\d{2,4}\b|"
    r"\b\d+(?:\.\d+)?\s*bar(?:\s+rating)?\b|\b\d+(?:\.\d+)?\s*psi\b", re.I)


def _valve_spec_complete(row: dict) -> bool:
    """True when the row's OWN cells (requirement / basis / part / size / material)
    carry the FULL procurable generic spec a bought-by-spec valve needs: DN/size AND
    material AND a pressure/class rating. Never inferred from anything outside the
    row. A row missing any one leg is spec-INCOMPLETE (stays engineered-TBD — an
    honest gap, not a reclassification)."""
    text = " ".join(str(row.get(k) or "") for k in ("requirement", "basis", "part", "size"))
    has_size = bool(str(row.get("size") or "").strip()) or bool(_VALVE_DN_SIZE_RX.search(text))
    has_material = bool(_bom_row_material(row))
    has_rating = bool(_VALVE_RATING_RX.search(text))
    return has_size and has_material and has_rating


def _generic_spec_valve(row: dict) -> bool:
    """True only when BOTH legs hold: the row names an engine-refused process valve
    (_commodity_process_valve) AND that row's own cells carry the full procurable
    spec (_valve_spec_complete). Neither leg alone reclassifies."""
    text = f"{row.get('requirement') or ''} {row.get('part') or ''}"
    return _commodity_process_valve(text) and _valve_spec_complete(row)


# INTENT: a field analyser/transmitter bought BY MEASURING RANGE at concept stage
# (e.g. 'Dissolved-Oxygen Analyser · 0–20 mg/L') is the instrument analogue of a
# generic-spec valve — MPN at procurement, not engineered-TBD. BOTH legs required:
# instrument noun AND a stated range with unit on the row (proveCatch both ways).
_INSTRUMENT_NOUN_RX = re.compile(r"\b(?:analy[sz]ers?|transmitters?)\b", re.I)
_INSTRUMENT_RANGE_RX = re.compile(
    r"\b\d+(?:[.,]\d+)?\s*[–\-]\s*\d+(?:[.,]\d+)?\s*"
    r"(?:mg/?L|ppm|%|µS(?:/?cm)?|mS(?:/?cm)?|°C|deg(?:ree)?s?\s*C|bar|psi)\b",
    re.I,
)


def _generic_spec_instrument(row: dict) -> bool:
    """True when the row names an analyser/transmitter AND states a measuring range."""
    text = f"{row.get('requirement') or ''} {row.get('part') or ''} {row.get('basis') or ''}"
    return bool(_INSTRUMENT_NOUN_RX.search(text) and _INSTRUMENT_RANGE_RX.search(text))


def _generic_spec_bought_out(row: dict) -> bool:
    """Valve-by-spec OR instrument-by-range — either qualifies for the unpenalised
    generic-spec tally."""
    return _generic_spec_valve(row) or _generic_spec_instrument(row)


# ── OEM-PROPRIETARY (no public MPN) taxonomy (2026-07-04, round-3 dissection). Some
# bought-out parts (e.g. an OEM-integral RO skid controller) genuinely have no
# publicly published manufacturer part number — that is a VERIFIED RESEARCH FINDING,
# not a gap. It is honoured ONLY when the row's own `basis` states that finding was
# actually recorded by the ingest/verification pass (a real research result) — NEVER
# self-declared merely because a price or part happens to be absent (that would be
# indistinguishable from an unresearched gap and would let every unresolved row
# quietly escape the TBD penalty). proveCatch both directions in _selftest.
_OEM_PROPRIETARY_RESEARCH_RX = re.compile(
    r"oem[- ]proprietary|"
    r"no\s+public(?:ly)?[- ]?(?:available|listed|disclosed)?\s*(?:part\s*number|mpn)|"
    r"no\s+published\s+(?:part\s*number|mpn)|"
    r"(?:manufacturer|oem)\s+(?:does\s+not|doesn't)\s+publish|"
    r"not\s+publicly\s+(?:available|listed|disclosed)", re.I)


def _oem_proprietary_row(row: dict) -> bool:
    """True ONLY when the row's own `basis` carries a stated research finding that no
    public part number exists — never inferred from a merely-missing price/part."""
    return bool(_OEM_PROPRIETARY_RESEARCH_RX.search(str(row.get("basis") or "")))


_GENERIC_SPEC_MPN_TEXT = "generic spec — MPN at procurement"
_OEM_PROPRIETARY_MPN_TEXT = "OEM-proprietary (no public MPN)"


# ── CLASS-ALIEN PART MARKERS (fix 6, reviewers 2026-07-02 — 'Aquavista Remote
# Monitoring', an aquaculture SCADA product, shipped on a water_treatment plant). The
# BoM data is NEVER renamed here (it comes from state); the ROW CHECK flags the line
# as class-alien so the fix routes UPSTREAM to the parts/BoM source. Same
# suppress-on-the-legitimate-class pattern as gate 34's marker families: a marker
# fires only when the product class is NOT the marker's home domain.
# ONE SOURCE (2026-07-03): the vocabulary now lives in scripts/lib/
# deterministic_finalize.py (CLASS_ALIEN_MARKERS) — the SAME table drives that
# pass's class_alien_control_rename (which renames an alien telemetry/SCADA word
# to the brief's NAMED control system), so the flagger and the fixer can never
# disagree on what "class-alien" means.
from deterministic_finalize import CLASS_ALIEN_MARKERS as _CLASS_ALIEN_MARKERS  # noqa: E402


def _class_alien_reason(row_text: str, product_class: str) -> Optional[str]:
    """A row-check FAIL reason when the row names a product from a DIFFERENT domain
    than the plant's class (None when clean or when the class IS the home domain)."""
    for dom, marker, legit in _CLASS_ALIEN_MARKERS:
        hit = marker.search(str(row_text or ""))
        if hit and not legit.search(str(product_class or "")):
            return (f"class-alien part ('{hit.group(0)}' is a {dom} product on a "
                    f"'{product_class or 'unknown'}' plant) — fix upstream at the "
                    f"parts/BoM source; the data is not renamed here")
    return None


def _eval_bom_ledger_contract(run_dir: str, state: dict) -> Optional[dict]:
    """Column-contract evaluation of EVERY Bill-of-Materials (Ledger) row (pure — reads
    state.requirementsBom + partVerifications; renders nothing).

    MATERIAL — required for a PHYSICAL fabricated part (a row carrying its own geometry /
    mass / take-off / routed-connection signals); a bought-out ASSEMBLY / PACKAGE discloses
    'N/A — proprietary assembly' (na_with_reason). The distinction derives from data the
    rows already carry — never a per-class table.
    MPN / DATASHEET — a real or DB-sourced part reference for a bought-out row, else an
    EXPLICIT disclosure. HONEST TBD TAXONOMY (2026-07-03, extended 2026-07-04): a
    COMMODITY line (commodity noun family AND unit £ under the stated threshold — both
    required) renders 'commodity — MPN at procurement'; an engine-refused GENERIC-SPEC
    process valve whose OWN row carries the full DN/material/rating spec (no £ cap)
    renders 'generic spec — MPN at procurement'; a row carrying a RECORDED research
    finding of no public part number renders 'OEM-proprietary (no public MPN)' — all
    three land in SEPARATE, unpenalised-but-visible tallies; every other (ENGINEERED)
    bought-out line without a reference stays the flagged 'TBD (detailed design)' and
    the TAB score is penalised in PROPORTION to the ENGINEERED-TBD fraction — a
    fully-TBD bill can never reach 8. ALL FIVE tallies (resolved / commodity /
    generic-spec / OEM-proprietary / engineered-TBD) are surfaced in the tab header.
    NUMBERS — qty > 0 · unit £ > 0 · line £ = qty × unit £ (per-row arithmetic) · a
    non-empty pricing basis. A '↳' sub-component is an apportionment of its parent
    (unit/line waived WITH that stated reason, exactly as the ledger renders it)."""
    bom = state.get("requirementsBom") or []
    if not isinstance(bom, list) or not bom:
        return None
    mpn_by_word = _build_mpn_by_word(state)
    _pclass = str(((state.get("orchestratorContract") or {}).get("product_class"))
                  or ((state.get("parsedBrief") or {}).get("product_class")) or "")
    _instrument = bool(state.get("isInstrumentDevice"))

    contract = [
        ("Tag/Item", "required_nonempty", "identity of the line"),
        ("Class fit", "computed",
         "the part belongs to THIS plant's domain — a marker-flagged foreign-domain "
         "product (e.g. aquaculture SCADA on a water plant) FAILS its row and routes "
         "the fix upstream to the parts source"),
        ("Qty", "required_nonempty", "quantity > 0"),
        ("Unit £ / Line £", "computed",
         "unit £ > 0 and line £ = qty × unit £ per row ('↳' sub-components are apportioned into their parent)"),
        ("Basis", "required_nonempty", "the pricing derivation (method / take-off / rating / corpus reference)"),
        ("Material", "computed",
         "required for a PHYSICAL fabricated part; a bought-out assembly/package discloses "
         "'N/A — proprietary assembly' (derived from the row's own shape/basis data, no class table)"),
        ("MPN / datasheet", "computed",
         "real or DB-sourced part reference for a bought-out row, else an explicit disclosure: "
         "ENGINEERED lines carry 'TBD (detailed design)' (counted + penalising the tab score by "
         "their fraction); COMMODITY lines (commodity noun family AND unit £ ≤ the stated "
         "threshold, both required) carry 'commodity — MPN at procurement'; engine-refused "
         "GENERIC-SPEC process valves with a spec-complete row (DN/size + material + rating, "
         "no £ cap) carry 'generic spec — MPN at procurement'; a row with a RECORDED research "
         "finding of no public part number carries 'OEM-proprietary (no public MPN)' — all "
         "three tallied separately, unpenalised"),
    ]

    per_row: Dict[int, dict] = {}
    n_pass = 0
    tbd_count = 0          # ENGINEERED bought-out lines with no reference (penalised)
    mpn_required = 0       # ENGINEERED bought-out lines (the penalty denominator)
    commodity_tbd = 0      # COMMODITY bought-out lines with no reference (visible, unpenalised)
    commodity_total = 0    # COMMODITY bought-out lines
    generic_spec_tbd = 0       # GENERIC-SPEC valve lines with no reference (visible, unpenalised)
    generic_spec_total = 0     # GENERIC-SPEC valve lines (engine-refused + spec-complete)
    oem_proprietary_tbd = 0    # OEM-PROPRIETARY lines with no reference (visible, unpenalised)
    oem_proprietary_total = 0  # OEM-PROPRIETARY lines (verified no public MPN)
    for idx, row in enumerate(bom):
        if not isinstance(row, dict):
            continue
        reasons: List[str] = []
        req = str(row.get("requirement") or "").strip()
        is_sub = req.startswith("↳") or bool(row.get("sub_of"))
        kind = "sub-component" if is_sub else _bom_row_kind(row, _instrument)

        if not (str(row.get("tag") or "").strip() and req):
            reasons.append("tag / item identity missing")
        qty = num(row.get("qty"))
        if qty is None or qty <= 0:
            reasons.append("qty missing")
        unit = num(row.get("unit_gbp"))
        line = num(row.get("line_gbp"))
        material_txt = _bom_row_material(row)
        if not material_txt and kind == "fabricated" and _instrument:
            material_txt = _instrument_row_material(row)
        mpn_txt = _bom_row_mpn(row, mpn_by_word)
        tbd = False
        commodity = False
        generic_spec = False
        oem_proprietary = False

        if is_sub and not (line or 0):
            # apportioned child — unit/line/material/MPN live on the PARENT line; the
            # ledger renders 'incl. in parent', and that disclosure IS the reason.
            material_txt = material_txt or "incl. in parent"
            mpn_txt = mpn_txt or "incl. in parent"
        else:
            if unit is None or unit <= 0:
                reasons.append("unit £ missing/zero")
            if line is None or line <= 0:
                reasons.append("line £ missing/zero")
            if qty and unit is not None and line is not None and \
                    abs(qty * unit - line) > max(1.0, 0.005 * abs(line)):
                reasons.append(f"line £{line:,.0f} ≠ qty {qty:g} × unit £{unit:,.2f} "
                               f"(= £{qty * unit:,.0f}) — per-row arithmetic broken")
            if kind == "fabricated":
                if not material_txt:
                    reasons.append("material missing on a PHYSICAL fabricated part "
                                   "(the row carries geometry/take-off data but states no material)")
            elif not material_txt:
                material_txt = "N/A — proprietary assembly / bought-out package, see datasheet"
            if kind == "assembly":
                # HONEST TBD TAXONOMY: evaluated in priority order so a row never lands
                # in two buckets — commodity small parts (noun family + price threshold,
                # BOTH required), then engine-refused GENERIC-SPEC process valves (no
                # price cap — gated on the row's own spec completeness instead), then
                # OEM-PROPRIETARY (a recorded no-public-MPN research finding). None of
                # the three owe an MPN at concept stage — each a separate visible tally,
                # no penalty. Every other (ENGINEERED) line keeps the full TBD penalty.
                commodity = _commodity_bought_out(row, unit)
                generic_spec = (not commodity) and _generic_spec_bought_out(row)
                oem_proprietary = (not commodity) and (not generic_spec) and _oem_proprietary_row(row)
                if commodity:
                    commodity_total += 1
                    if not mpn_txt:
                        mpn_txt = _COMMODITY_MPN_TEXT
                        commodity_tbd += 1
                elif generic_spec:
                    generic_spec_total += 1
                    if not mpn_txt:
                        mpn_txt = _GENERIC_SPEC_MPN_TEXT
                        generic_spec_tbd += 1
                elif oem_proprietary:
                    oem_proprietary_total += 1
                    if not mpn_txt:
                        mpn_txt = _OEM_PROPRIETARY_MPN_TEXT
                        oem_proprietary_tbd += 1
                else:
                    mpn_required += 1
                    if not mpn_txt:
                        mpn_txt = _TBD_MPN_TEXT
                        tbd = True
                        tbd_count += 1
            elif kind == "fabricated" and not mpn_txt:
                # S10 (council H10, 2026-07-20): "bespoke fabrication to drawing" is honest for a
                # genuinely FABRICATED mechanical part (an enclosure / bracket machined to a
                # drawing — no catalogue MPN exists). It is a FALSE-SATISFIED claim for a
                # catalogue ELECTRONIC part (an MCU / sensor / USB receptacle / isolator) that
                # SHOULD carry a real MPN but the engine didn't resolve one — that is UNRESOLVED,
                # not a design choice. (After S11, PCB-designed electronics already carry their
                # board MPN, so only genuinely-unresolved electronics reach here.) Flag it as a
                # real gap so the row FAILs (honest red beats fake green). Keyed on the FR4/
                # electronic material signal + an electronic-noun family, no product class.
                _is_electronic = bool(re.search(r"fr4|electronic\s+comp|pcb[- ]?mount",
                                                material_txt or "", re.I)) \
                    or bool(_ELECTRONIC_NOUN_RX.search(req))
                if _is_electronic:
                    mpn_txt = "UNRESOLVED — catalogue electronic part; MPN required at detailed design"
                    reasons.append("catalogue electronic component with NO resolved MPN — "
                                   "'bespoke fabrication to drawing' is not a valid identity for a "
                                   "catalogue part (council H10); resolve a real MPN or mark it "
                                   "OEM-proprietary with evidence")
                else:
                    mpn_txt = "bespoke fabrication to drawing — see sizing basis"
        if not str(row.get("basis") or "").strip():
            reasons.append("pricing basis missing")
        # CLASS FIT (fix 6): a foreign-domain product fails its row — routed upstream.
        _alien = _class_alien_reason(f"{req} {row.get('part') or ''}", _pclass)
        if _alien:
            reasons.append(_alien)

        verdict = "PASS" if not reasons else "FAIL"
        if verdict == "PASS":
            n_pass += 1
        per_row[idx] = {"verdict": verdict, "reasons": reasons, "kind": kind,
                        "material": material_txt, "mpn": mpn_txt, "tbd": tbd,
                        "commodity": commodity, "generic_spec": generic_spec,
                        "oem_proprietary": oem_proprietary}

    if not per_row:
        return None
    n_total = len(per_row)
    base = _contract_score(n_pass, n_total)
    # TBD penalty — PROPORTIONAL to the fraction of ENGINEERED bought-out rows still
    # 'TBD (detailed design)': score = arithmetic − 4 × engineered-TBD-fraction, so a
    # fully-TBD bill caps at 6 (<8) even when every row check passes. The gap is honest
    # but it is still a gap. Commodity / generic-spec / OEM-proprietary lines are
    # OUTSIDE both the numerator and the denominator — none of the three owe an MPN
    # at concept stage (honest TBD taxonomy 2026-07-03, extended 2026-07-04), but all
    # three tallies stay visible.
    tbd_frac = (tbd_count / mpn_required) if mpn_required else 0.0
    score = base
    if base is not None and tbd_frac > 0:
        score = max(0.0, round(base - 4.0 * tbd_frac, 1))
    n_fail = n_total - n_pass
    resolved_count = max(0, mpn_required - tbd_count)
    issues: List[str] = []
    if n_fail:
        # reference the REAL sheet row each failing bom line renders on (fix 3 — the
        # audit's 'row 4' refs were data-row ordinals, off-by-4 vs the sheet whose data
        # starts at row 5; the fold layout is the single source of the row mapping).
        _, _sheet_by_idx = _ledger_fold_layout(bom, run_dir)
        ex = [f"sheet row {_sheet_by_idx.get(i, i + _LEDGER_DATA_START)} "
              f"({str((bom[i] or {}).get('requirement', ''))[:40]}): {r['reasons'][0]}"
              for i, r in list(per_row.items()) if r["verdict"] == "FAIL"][:3]
        issues.append(f"{n_fail}/{n_total} ledger rows FAIL the column contract (arithmetic "
                      f"10 × {n_pass}/{n_total} = {base}) — e.g. " + " · ".join(ex))
    if tbd_count:
        _visible = []
        if commodity_tbd:
            _visible.append(f"{commodity_tbd} commodity")
        if generic_spec_tbd:
            _visible.append(f"{generic_spec_tbd} generic-spec valve")
        if oem_proprietary_tbd:
            _visible.append(f"{oem_proprietary_tbd} OEM-proprietary")
        issues.append(f"{tbd_count}/{mpn_required} ENGINEERED bought-out lines carry MPN 'TBD "
                      f"(detailed design)' — an ESTIMATE-stage gap; score = arithmetic − 4 × "
                      f"engineered-TBD-fraction = {base} − {4.0 * tbd_frac:.1f}"
                      + (f" ({' + '.join(_visible)} line(s) tallied separately, unpenalised)"
                         if _visible else ""))
    return {"tab": _LEDGER_SHEET, "contract": contract, "rows": per_row,
            "n_pass": n_pass, "n_total": n_total, "score": score,
            "status": "PASS" if (score or 0) >= 8 else "FAIL", "issues": issues,
            "source_fabricated": 0,
            "tbd_count": tbd_count, "tbd_required": mpn_required,
            "tbd_fraction": round(tbd_frac, 3), "resolved_count": resolved_count,
            "tbd_commodity_count": commodity_tbd, "commodity_count": commodity_total,
            "tbd_generic_spec_count": generic_spec_tbd, "generic_spec_count": generic_spec_total,
            "tbd_oem_proprietary_count": oem_proprietary_tbd,
            "oem_proprietary_count": oem_proprietary_total,
            "fix": ("price the £0 lines at source (requirements_bom.py emitter), state the "
                    "material on fabricated parts in the sizing pass, and close ENGINEERED MPN "
                    "TBDs by growing the parts DB (Stage 17.6 ingest) so partVerifications "
                    "resolves them (commodity / generic-spec valve lines resolve at "
                    "procurement — no hold; OEM-proprietary lines never resolve by design)")}


# ── RISK REGISTER column contract (Tristan 2026-07-02, issue 12) ────────────────────────
def _eval_risk_rows(rows: List[dict]) -> Optional[dict]:
    """Column-contract evaluation of EVERY Risk-register row (pure — takes the rows
    `_build_risk_rows` produced; renders nothing).

    TRIAGE RULE: an ENGINE-FIXABLE row (a design defect the engine controls) FAILS its row
    check with its routed fix stage — "tolerable with mitigation" over an identified defect
    is a fabricated tolerance, exactly a fabricated tick. An EXTERNAL row passes ONLY with a
    non-empty mitigation. The tab score is arithmetic (10 × rows-passing ÷ rows) and HARD
    CAPPED below 8 while ANY open engine-fixable defect ships — the ≥8 floor can never be
    reached over a known defect; fixing it at source clears the mirrored finding and the
    row disappears."""
    if not rows:
        return None
    contract = [
        ("Class", "computed",
         "ENGINE-FIXABLE vs EXTERNAL — deterministic triage from the row's own provenance "
         "(live engine finding = the engine's audit vocabulary) + defect-vocabulary net"),
        ("Mitigation / fix route", "required_nonempty",
         "EXTERNAL: a real mitigation; ENGINE-FIXABLE: the routed source-stage fix"),
        ("Residual", "computed",
         "EXTERNAL + mitigated → 'Tolerable (with mitigation)'; ENGINE-FIXABLE → OPEN DEFECT "
         "(row FAILS until the defect is fixed at source and the finding it mirrors is gone)"),
    ]
    per_row: Dict[int, dict] = {}
    n_pass = 0
    fixable_n = 0
    unmitigated_n = 0
    for idx, row in enumerate(rows):
        reasons: List[str] = []
        if row.get("cls") == CLS_ENGINE_FIXABLE:
            fixable_n += 1
            reasons.append(
                "identified ENGINE-FIXABLE defect shipped in the register — a design property "
                "the engine controls can never be 'tolerable with mitigation'; fix at source: "
                + (row.get("fix") or "the source rule that produced this finding"))
        elif not str(row.get("mit") or "").strip():
            unmitigated_n += 1
            reasons.append("EXTERNAL risk with no mitigation stated — an unmitigated external "
                           "risk is not tolerable")
        verdict = "PASS" if not reasons else "FAIL"
        if verdict == "PASS":
            n_pass += 1
        per_row[idx] = {"verdict": verdict, "reasons": reasons, "cls": row.get("cls"),
                        "fix": row.get("fix", "")}
    n_total = len(per_row)
    score = _contract_score(n_pass, n_total)
    if score is not None and fixable_n:
        score = min(score, 7.9)   # hard cap <8 while any open engine-fixable defect ships
    issues: List[str] = []
    if fixable_n:
        # 'register # N' = the register's own visible '#' column (never a sheet-row
        # ordinal — fix 3: the audit's bare 'row N' refs did not match the sheet).
        ex = [f"register # {i + 1} ({str(rows[i].get('hazard', ''))[:50]})"
              for i, r in per_row.items() if r["cls"] == CLS_ENGINE_FIXABLE][:3]
        issues.append(f"{fixable_n}/{n_total} risk rows are ENGINE-FIXABLE open defects shipped "
                      f"in the register (arithmetic 10 × {n_pass}/{n_total}, capped <8 while any "
                      "remain) — e.g. " + " · ".join(ex))
    if unmitigated_n:
        issues.append(f"{unmitigated_n} EXTERNAL risk row(s) carry no mitigation")
    return {"tab": "Risk & Regulatory", "contract": contract, "rows": per_row,
            "n_pass": n_pass, "n_total": n_total, "score": score,
            "status": "PASS" if (score or 0) >= 8 else "FAIL", "issues": issues,
            # every engine-fixable row previously rendered 'Tolerable (with mitigation)' —
            # a fabricated tolerance tick, now neutralised by the OPEN-DEFECT rendering
            "source_fabricated": fixable_n,
            "fixable_count": fixable_n,
            "fix": ("fix each OPEN-DEFECT row at its ROUTED source stage (each row names it: the "
                    "physics-critic finding's producing rule / the flagged gate's source line / the "
                    "cost model) — the mirrored finding then clears and the row disappears; external "
                    "risks keep their mitigations")}


def _eval_risk_register_contract(_run_dir: str, state: dict) -> Optional[dict]:
    """Registry adapter: build the risk rows from state and evaluate their contract.

    INTENT (Tristan 2026-07-14): compliance-gate WARN / open High hazards are
    disclosed issues — a perfect 10 on Risk & Regulatory over those is a lie.
    """
    base = _eval_risk_rows(_build_risk_rows(state))
    rows = _build_risk_rows(state)
    n_hi = sum(1 for rw in rows if _rag(rw["sev"] * rw["lik"])[0] == "High")
    n_med = sum(1 for rw in rows if _rag(rw["sev"] * rw["lik"])[0] == "Medium")
    cg = state.get("complianceGate") or {}
    verdict = str(cg.get("verdict") or "").upper()
    reason = str(cg.get("reason") or "")
    extra_issues: List[str] = []
    if verdict in ("WARN", "FAIL"):
        extra_issues.append(
            f"compliance-gate verdict: {verdict}"
            + (f" — {reason[:160]}" if reason else "")
        )
    if n_hi:
        extra_issues.append(
            f"{n_hi} High hazard(s) remain in the register — a perfect 10 requires a clean sheet"
        )
    if n_med:
        extra_issues.append(
            f"{n_med} Medium hazard(s) remain in the register"
        )
    if base is None:
        if not extra_issues:
            return None
        _warn = verdict in ("WARN", "FAIL") or n_hi > 0
        return {
            "tab": "Risk & Regulatory",
            "contract": [],
            "rows": {},
            "n_pass": 0,
            "n_total": 0,
            "score": 7.0 if _warn else 9.9,
            "status": "FAIL" if _warn else "PASS",
            "issues": extra_issues,
            "source_fabricated": 0,
            "fixable_count": 0,
            "fix": "clear compliance-gate WARN / High hazards at source",
        }
    if extra_issues:
        iss = list(base.get("issues") or [])
        for e in extra_issues:
            if e not in iss:
                iss.append(e)
        base["issues"] = iss[:8]
        sc = base.get("score")
        # INTENT (2026-07-14 adversarial): compliance WARN / High hazards are not a
        # near-10 — a chartered engineer would refuse. Cap ≤7 (FAIL the ship floor).
        if verdict in ("WARN", "FAIL") or n_hi:
            if isinstance(sc, (int, float)):
                base["score"] = min(sc, 7.0)
            else:
                base["score"] = 7.0
            base["status"] = "FAIL"
            base["fix"] = (
                "clear compliance-gate WARN at source (register class standards / "
                "resolve High hazards) — Risk cannot mint ≥8 over an open WARN"
            )
        elif isinstance(sc, (int, float)) and sc >= 10:
            base["score"] = 9.9
            base["status"] = "PASS"
    return base


# The registry: tab name → its contract evaluator. build() runs each BEFORE the tabs render,
# overrides the tab's quality score with the ARITHMETIC result, and the tab functions read
# _CONTRACT_RESULTS to render the per-row "Row check" verdicts from the SAME evaluation.
_CONTRACT_TABS = {
    "Line & velocity": _eval_line_velocity_contract,
    "Panel schedule": _eval_panel_schedule_contract,
    _LEDGER_SHEET: _eval_bom_ledger_contract,
    "Risk & Regulatory": _eval_risk_register_contract,
    "Engineering Analysis": _eval_engineering_analysis_contract,
}


# ═══ HOLDS & EXCLUSIONS REGISTER (reviewers 2026-07-02, Bundle C fix 6) ══════════════
# How a consultancy ships incomplete work without it reading as broken: the honest open
# items become NUMBERED HOLDS, each DERIVED LIVE from a failing check / column contract
# (never hand-typed), so the register stays current — clear the defect at source and the
# hold disappears on rebuild. Exclusions restate the brief's own out-of-scope list + any
# client-offer section this BoM has no scope for.
def _derive_holds(state: dict, contract_results: Optional[dict] = None) -> List[dict]:
    """The numbered holds, derived from the LIVE evaluation results. Pure — reads the
    contract results (default: the module-level _CONTRACT_RESULTS populated in build())
    plus state['_clientOfferRecon'] / state['_dossierRepair']. Returns [] when nothing
    is open (a clean dossier carries no fabricated holds). Each hold now ALSO carries a
    QUANTIFIED IMPACT (9/10 campaign, 2026-07-04) — a £ figure where the source data IS
    a price (the client-offer section), a scope-% everywhere else (the SAME live count
    already in `scope`, expressed as a fraction of its own denominator) — never a
    fabricated number: every impact is the identical arithmetic the `scope` text states."""
    cr = _CONTRACT_RESULTS if contract_results is None else contract_results
    holds: List[dict] = []

    def _add(item: str, scope: str, source: str, clears: str,
             impact_gbp: Optional[float] = None, impact_pct: Optional[float] = None) -> None:
        holds.append({"id": f"HOLD-{len(holds) + 1:03d}", "item": item, "scope": scope,
                      "source": source, "clears": clears,
                      "impact_gbp": impact_gbp, "impact_pct": impact_pct})

    # 1 — line sizing pending flow allocation (Line & velocity column contract)
    # GOTCHA: underivable velocity/current is verdict N/A (not FAIL) — those are honest
    # stubs, not open holds. Only a true FAIL (band exceed / structural miss) opens a hold.
    lv = cr.get("Line & velocity")
    if isinstance(lv, dict):
        rows = list((lv.get("rows") or {}).values())
        unver = sum(1 for x in rows if x.get("verdict") == "N/A"
                    and any("underivable" in str(t) for t in x.get("reasons") or []))
        band = sum(1 for x in rows if x.get("verdict") == "FAIL"
                   and any("exceeds" in str(t) for t in x.get("reasons") or []))
        # Underivable-only (all N/A, no band FAIL) is NOT an open hold — the tab already
        # scores them as non-penalising. A band exceed still opens a hold.
        if band:
            _add("Line sizing pending flow allocation",
                 (f"{band} line(s) outside the velocity band (sized without their "
                  f"real flow demand)"
                  + (f" + {unver} line(s) with no derivable flow (N/A stubs)"
                     if unver else "")),
                 "Line & velocity column contract (live per-row evaluation)",
                 "author the real flow demand on every fluid topology edge at source — "
                 "the contract then re-passes and this hold clears",
                 impact_pct=(100.0 * band / len(rows)) if rows else None)
    # 2 — bought-out MPNs pending detailed design (BoM ledger contract)
    bl = cr.get(_LEDGER_SHEET)
    if isinstance(bl, dict) and (bl.get("tbd_count") or 0) > 0:
        _tbd_req = bl.get("tbd_required") or 0
        _add("Bought-out manufacturer part numbers pending detailed design",
             f"{bl['tbd_count']}/{bl.get('tbd_required', '?')} engineered bought-out lines "
             f"carry an explicit 'TBD (detailed design)' part number"
             + (f" (commodity lines 'MPN at procurement' are tallied separately and "
                f"carry no hold: {bl.get('tbd_commodity_count', 0)})"
                if bl.get("tbd_commodity_count") else ""),
             "Bill of Materials ledger column contract (live TBD count)",
             "resolve real MPNs at detailed design (Stage 17.6 library / supplier RFQs) — "
             "the TBD count then falls and this hold clears",
             impact_pct=(100.0 * bl["tbd_count"] / _tbd_req) if _tbd_req else None)
    # 3 — client-offer sections this BoM has no / partial scope for (Brief reconciliation)
    recon = state.get("_clientOfferRecon") or {}
    for sec in recon.get("sections") or []:
        if sec.get("status") in ("out_of_scope", "partial"):
            _add(f"Client section {sec['key']} ({sec['label']}) "
                 + ("out of BoM scope" if sec["status"] == "out_of_scope"
                    else "only partially in BoM scope"),
                 f"client section £{sec['client_gbp']:,.0f}"
                 + (f"; engine models £{sec['engine_bom_gbp']:,.0f} of materials"
                    if sec.get("engine_bom_gbp") else "; no engine BoM lines map to it"),
                 "Brief tab — 'Client offer vs this design' reconciliation (live mapping)",
                 "scope + price the section (or agree the exclusion with the client) — "
                 "the reconciliation row then reads consistent and this hold clears",
                 impact_gbp=num(sec.get("client_gbp")))
    # 4 — open engine-fixable design defects (Risk register triage)
    rr = cr.get("Risk & Regulatory")
    if isinstance(rr, dict) and (rr.get("fixable_count") or 0) > 0:
        _rr_n = rr.get("n_total") or 0
        _add("Engine-fixable design defects open in the risk register",
             f"{rr['fixable_count']} OPEN DEFECT row(s) — each names its routed fix stage",
             "Risk register column contract (live triage: engine-fixable ≠ 'tolerable')",
             "fix each defect at its routed source stage — the mirrored finding clears "
             "and the row disappears",
             impact_pct=(100.0 * rr["fixable_count"] / _rr_n) if _rr_n else None)
    # 5 — panel circuits failing their column contract
    ps = cr.get("Panel schedule")
    if isinstance(ps, dict) and (ps.get("n_total") or 0) > (ps.get("n_pass") or 0):
        _ps_n = ps.get("n_total") or 0
        _add("Panel circuits failing the schedule column contract",
             f"{ps['n_total'] - ps['n_pass']}/{ps['n_total']} circuit row(s) FAIL "
             f"(missing ΔU / out-of-band volt-drop)",
             "Panel schedule column contract (live per-circuit evaluation)",
             "route + size the failing circuits so ΔU computes in-band",
             impact_pct=(100.0 * (ps["n_total"] - ps["n_pass"]) / _ps_n) if _ps_n else None)
    # 6 — gaps the self-repair loop could not fix without human input. No clean
    # denominator exists here, so the impact is the ENGINE'S OWN stated severity —
    # disclosed as a severity-derived weight, never presented as a measured fraction.
    _SEVERITY_PCT = {"HIGH": 100.0, "MED": 50.0, "MEDIUM": 50.0, "LOW": 25.0, "INFO": 10.0}
    for f in ((state.get("_dossierRepair") or {}).get("needs_input") or []):
        if isinstance(f, dict) and f.get("message"):
            _sev = str(f.get("severity", "")).upper()
            _add(f"Needs input — {f.get('check', 'open gap')}",
                 str(f.get("message"))[:180],
                 f"self-repair loop (severity {f.get('severity', '?')}, tab {f.get('tab', '?')})",
                 str(f.get("why") or "supply the missing input and re-run")[:180],
                 impact_pct=_SEVERITY_PCT.get(_sev))
    return holds


# Owner derivation (9/10 campaign, 2026-07-04): a short, DETERMINISTIC routing label
# from the hold's own `source` string — universal keyword map, never a hand-typed
# per-hold name; a source matching no known mechanism still gets an honest fallback
# (its own leading phrase), never a blank.
_HOLD_OWNER_MAP = [
    (re.compile(r"Line & velocity", re.I), "Process/piping engineering — Line & velocity"),
    (re.compile(r"Bill of Materials ledger|BoM ledger", re.I),
     "Procurement / detailed design — BoM ledger"),
    (re.compile(r"Brief tab|client.offer", re.I), "Commercial / scope — Brief reconciliation"),
    (re.compile(r"Risk register", re.I), "Engineering — Risk register"),
    (re.compile(r"Panel schedule", re.I), "Electrical engineering — Panel schedule"),
]


def _hold_owner(source: str) -> str:
    s = str(source or "")
    for rx, label in _HOLD_OWNER_MAP:
        if rx.search(s):
            return label
    m = re.search(r"self-repair loop.*?tab\s+([\w &]+)\)", s, re.I)
    if m:
        return f"Engine self-repair — {m.group(1).strip()}"
    return "Engineering — " + (s.split("(")[0].strip()[:40] or "unspecified")


def _brief_exclusions(orig: str) -> List[str]:
    """The brief's OWN explicit out-of-scope bullets (the lines under an 'Explicitly
    EXCLUDED' heading) — restated on the register so scope is unambiguous."""
    out: List[str] = []
    in_block = False
    for line in (orig or "").splitlines():
        s = line.strip()
        if re.match(r"^Explicitly EXCLUDED", s, re.I):
            in_block = True
            continue
        if in_block:
            if s.startswith("-") or s.startswith("•"):
                out.append(s.lstrip("-• ").strip())
            elif s:
                break
    return out


_STOPWORDS_OFFER = {"the", "and", "for", "with", "this", "that", "from", "into",
                    "hardware", "system", "systems", "installation", "units", "unit"}


def _match_offer_section(excl_text: str, sections: List[dict]) -> Optional[dict]:
    """Does a brief exclusion bullet correspond to one of the client-offer's OWN named
    sections (A, B, C…)? Keyword-overlap match (≥4-char tokens, stopwords dropped)
    between the exclusion text and each section's label — deterministic, universal, no
    hand-typed per-run mapping. None when no section shares a real keyword (a genuine,
    honestly-reported case: an item excluded from the DESIGN that was never part of the
    reference offer at all, e.g. a different trade's scope)."""
    toks = {w for w in re.findall(r"[a-z]{4,}", excl_text.lower()) if w not in _STOPWORDS_OFFER}
    if not toks:
        return None
    best, best_n = None, 0
    for sec in (sections or []):
        stoks = {w for w in re.findall(r"[a-z]{4,}", str(sec.get("label", "")).lower())
                 if w not in _STOPWORDS_OFFER}
        n = len(toks & stoks)
        if n > best_n:
            best, best_n = sec, n
    return best


def tab_holds_register(wb: Workbook, state: dict, run_dir: str) -> bool:
    """Fix 6 (reviewers 2026-07-02) — the HOLDS & EXCLUSIONS register: numbered holds
    derived LIVE from the failing checks/column contracts + the brief's own exclusions.
    Skips cleanly when there is nothing to register (no holds AND no exclusions).
    9/10 CAMPAIGN (2026-07-04): every hold ALSO carries a quantified Impact (£ or a
    scope %, the SAME live count already in Scope) + an Owner (deterministic routing
    label from its source mechanism, next to the existing Clears-when next-action);
    every exclusion is explicitly reconciled against the client-offer's own named
    sections — cited where a section matches, honestly marked outside the reference
    offer where none does. A fully-quantified/owned/cited register can reach 9.9
    while holds remain open; a perfect 10 requires ZERO open holds (Tristan
    2026-07-14 grade-inflation ban). A hold missing its impact/owner, or an
    exclusion nobody reconciled against the offer, reads honestly below 9."""
    holds = _derive_holds(state)
    orig = ""
    op = os.path.join(run_dir, "0-original-brief.md")
    if os.path.exists(op):
        try:
            orig = open(op, "r").read()
        except Exception:  # noqa: BLE001
            orig = ""
    excl = _brief_exclusions(orig)
    recon_sections = (state.get("_clientOfferRecon") or {}).get("sections") or []
    recon_excl = [s for s in recon_sections if s.get("status") == "out_of_scope"]
    if not holds and not excl and not recon_excl:
        return False
    ws = wb.create_sheet("Holds & exclusions")
    set_widths(ws, {"A": 11, "B": 40, "C": 36, "D": 26, "E": 30, "F": 34, "G": 46})
    title_row(
        ws, "Holds & exclusions — the honest open-items register", 7,
        "Every hold is DERIVED LIVE from a failing check or column contract at build "
        "time — never hand-typed — so this register is always current: fix the item at "
        "source, rebuild, and its hold disappears. Impact is the SAME live count "
        "already in Scope, expressed as £ or a scope %; Owner routes to the mechanism "
        "that clears it. The dossier ships as a draft WITH these holds against it; the "
        "exclusions restate what was never in scope, each reconciled against the "
        "client-offer's own named sections.")
    r = 4
    n_impact_ok = 0
    n_owner_ok = 0
    if holds:
        sub_banner(ws, r, f"HOLDS — {len(holds)} open item(s), numbered", 7)
        r += 1
        header(ws, r, ["Hold", "Item", "Scope (live count)", "Impact (£ or %)", "Owner",
                       "Derived from", "Clears when"])
        r += 1
        for h in holds:
            owner = _hold_owner(h.get("source"))
            ws.cell(r, 1, h["id"]).font = Font(bold=True, color="9C2B2E")
            for ci, k in ((2, "item"), (3, "scope")):
                c = ws.cell(r, ci, clean_cell(h[k]))
                c.alignment = WRAP_TOP
                c.font = Font(size=10, bold=(ci == 2))
                c.border = BORDER
            ig, ipct = h.get("impact_gbp"), h.get("impact_pct")
            ic = ws.cell(r, 4, (round(ig) if isinstance(ig, (int, float)) else
                                (round(ipct, 1) if isinstance(ipct, (int, float)) else None)))
            ic.border = BORDER
            if isinstance(ig, (int, float)):
                ic.number_format = FMT_GBP
                n_impact_ok += 1
            elif isinstance(ipct, (int, float)):
                ic.number_format = '0.0"%"'
                n_impact_ok += 1
            oc = ws.cell(r, 5, clean_cell(owner)); oc.alignment = WRAP_TOP
            oc.font = FONT_NOTE; oc.border = BORDER
            if owner and owner.strip():
                n_owner_ok += 1
            for ci, k in ((6, "source"), (7, "clears")):
                c = ws.cell(r, ci, clean_cell(h[k]))
                c.alignment = WRAP_TOP; c.font = FONT_NOTE; c.border = BORDER
            longest = max(len(str(h[k])) for k in ("item", "scope", "source", "clears"))
            ws.row_dimensions[r].height = 14.5 * min(5, max(2, -(-longest // 48)))
            r += 1
        r += 1
    n_excl_cited = 0
    n_excl_total = len(excl) + len(recon_excl)
    if excl or recon_excl:
        sub_banner(ws, r, "EXCLUSIONS — never in this plant's scope, each reconciled "
                          "against the client-offer's own sections", 7)
        r += 1
        for s in recon_excl:
            c = ws.cell(r, 2, clean_cell(
                f"Client offer section {s['key']} ({s['label']}) — £{s['client_gbp']:,.0f} "
                f"in the client's offer; no line of this BoM prices it (see the matching "
                f"hold) — CITES client-offer section {s['key']} directly"))
            c.alignment = WRAP_TOP
            c.font = Font(size=10, bold=True)
            ws.merge_cells(start_row=r, start_column=2, end_row=r, end_column=7)
            ws.row_dimensions[r].height = 29
            n_excl_cited += 1
            r += 1
        for s in excl:
            match = _match_offer_section(s, recon_sections)
            cite = (f" — cites client-offer section {match['key']} ({match['label']})"
                    if match else
                    " — CONFIRMED outside the reference client offer (no matching "
                    f"section among its {len(recon_sections)} named section(s) — a "
                    "different trade's scope entirely, not merely a £0 line within it)")
            # every exclusion is EXPLICITLY reconciled one way or the other — a bare,
            # unlinked bullet (the old rendering) never ships again.
            n_excl_cited += 1
            c = ws.cell(r, 2, clean_cell("• " + s + cite))
            c.alignment = WRAP_TOP
            c.font = FONT_NOTE
            ws.merge_cells(start_row=r, start_column=2, end_row=r, end_column=7)
            if len(s) + len(cite) > 90:
                ws.row_dimensions[r].height = 27
            r += 1
    ws.freeze_panes = "A5"
    back_link(ws, 7)
    # HONEST SELF-SCORE (9/10 campaign, 2026-07-04): FOUR checks, min-combined, NO flat
    # cap. (1) every hold carries all FOUR derived text fields; (2) every hold carries a
    # numeric, non-empty Impact; (3) every hold carries a non-empty Owner; (4) every
    # exclusion is explicitly reconciled against the client-offer (cited or confirmed
    # outside it) rather than left as a bare, unlinked bullet. A register whose holds
    # are all fully quantified/owned and whose exclusions are all reconciled can reach
    # a genuine 9–9.9 while holds remain open. GRADE-INFLATION BAN (Tristan 2026-07-14):
    # ANY open hold is a disclosed issue — the register can never keep a perfect 10
    # until every hold clears at source (the universal honest-cap also enforces this).
    complete = sum(1 for h in holds
                   if all(str(h.get(k) or "").strip()
                          for k in ("item", "scope", "source", "clears")))
    n = len(holds)
    components = [
        ("holds carrying item/scope/source/clears", complete, n) if n else
        ("holds carrying item/scope/source/clears (none open)", 1, 1),
        ("holds carrying a numeric Impact", n_impact_ok, n) if n else
        ("holds carrying a numeric Impact (none open)", 1, 1),
        ("holds carrying a non-empty Owner", n_owner_ok, n) if n else
        ("holds carrying a non-empty Owner (none open)", 1, 1),
        ("exclusions explicitly reconciled against the client offer", n_excl_cited, n_excl_total)
        if n_excl_total else ("exclusions explicitly reconciled against the client offer (none)", 1, 1),
    ]
    frac = min(10.0 * p / c for _l, p, c in components if c)
    sc = round(frac, 1)
    if sc == int(sc):
        sc = int(sc)
    # Open holds = dossier is not clean → never a perfect 10 on this tab.
    if n > 0 and sc >= 10:
        sc = 9.9
    _issues = [f"{n} open hold(s) + {n_excl_total} exclusion(s) — every hold derived "
               f"live from a failing check/contract, fully quantified (Impact) and "
               f"routed (Owner); every exclusion explicitly reconciled against the "
               f"client offer — nothing left as a bare, unlinked disclosure"]
    if n and n_impact_ok < n:
        _issues.append(f"{n - n_impact_ok}/{n} hold(s) missing a numeric Impact")
    if n and n_owner_ok < n:
        _issues.append(f"{n - n_owner_ok}/{n} hold(s) missing an Owner")
    if n_excl_total and n_excl_cited < n_excl_total:
        _issues.append(f"{n_excl_total - n_excl_cited}/{n_excl_total} exclusion(s) not "
                        f"reconciled against the client offer")
    _TAB_SCORES["Holds & exclusions"] = {
        "score": sc, "target": 8, "status": "PASS" if sc >= 8 else "FAIL",
        "issues": _issues,
        "fix": "clear each hold at its source (the named check re-passes) — the row "
               "then disappears on rebuild; add the missing Impact/Owner/citation at "
               "the point noted above",
        "basis": f"arithmetic: 10 × min(complete {complete}/{n or 1}, impact "
                 f"{n_impact_ok}/{n or 1}, owner {n_owner_ok}/{n or 1}, exclusions cited "
                 f"{n_excl_cited}/{n_excl_total or 1})",
        "components": [{"check": l, "passed": p, "checked": c} for l, p, c in components],
    }
    return True


# ============================================================================
# TAB — QUESTIONS FOR THE CUSTOMER (engineering-credibility WAVE 1, 2026-07-03)
# "Customers don't know what they want" — this register is the OUTPUT ARTEFACT
# that turns every gap the engine papered over into an explicit confirm-or-correct
# question: brief fields still missing / filled by class defaults (BriefAugment),
# plausibility-critic contradictions, unresolved design decisions, and client-offer
# reconciliation divergences NOT covered by a recorded decision. Every row is
# DERIVED LIVE from a named engine artefact — never hand-typed — so answering a
# question (in the brief or the decisions register) makes its row disappear on the
# next build. proveCatch (in _selftest, both directions): a state with still_missing
# fields renders questions; a fully-specified state renders 'No open questions'
# honestly.
# ============================================================================
QUESTIONS_SHEET = "Questions for the customer"

# still_missing fields → what concretely changes if the customer supplies a value
# (universal field semantics, not per-class).
_MISSING_FIELD_WHY = {
    "max_mass_kg": ("a stated mass cap becomes a hard constraint on the skid/structure "
                    "and the transport & lifting plan; today nothing bounds the plant's "
                    "shipped mass"),
    "operating_environment": ("the ambient min/max drive thermal sizing (heater/chiller "
                              "duty, derating), material selection and IP ratings; today "
                              "no ambient-envelope check can run"),
    "max_dimensions_mm": ("a stated envelope becomes a hard fit constraint on the layout "
                          "and the general arrangement; today the footprint is unbounded"),
    "unit_cost_ceiling": ("a stated budget gates the design-to-cost loop; today no cost "
                          "ceiling constrains part selection"),
    "design_life": ("design life drives material corrosion allowances, duty classes and "
                    "the economics horizon"),
    "batch_size": ("annual volume moves the make-vs-buy and tooling amortisation in the "
                   "cost model"),
}


def _derive_customer_questions(state: dict, run_dir: str,
                               augment: Optional[dict] = None,
                               plausibility: Optional[dict] = None) -> List[dict]:
    """Derive the numbered customer questions from the run's own artefacts. Pure given
    its inputs; `augment` / `plausibility` default to the run-dir JSON artefacts
    (1-parsed-brief-augmented.json / 2-brief-plausibility-iter0.json) so the register is
    always the LIVE re-derivation, and the selftest can inject fixtures directly."""
    if augment is None:
        augment = load_json(os.path.join(run_dir, "1-parsed-brief-augmented.json")) or {}
    if plausibility is None:
        plausibility = load_json(
            os.path.join(run_dir, "2-brief-plausibility-iter0.json")) or {}
    qs: List[dict] = []

    def _add(question: str, why: str, assumption: str, provenance: str) -> None:
        qs.append({"id": f"Q-{len(qs) + 1:03d}", "question": question, "why": why,
                   "assumption": assumption, "provenance": provenance})

    # 1 — brief fields the augmentation could not fill (still missing after class defaults)
    for field in (augment.get("still_missing") or []):
        f = str(field)
        _add(f"What is the required {f.replace('_', ' ')}? The brief does not state it "
             f"and no class default exists.",
             _MISSING_FIELD_WHY.get(f, "a stated value becomes a hard design constraint "
                                       "and can resize the subsystems derived from it"),
             "none in force — the field is empty in the design basis; the design "
             "proceeds unconstrained on it",
             "brief augmentation (still_missing) — 1-parsed-brief-augmented.json")
    # 2 — brief fields FILLED with class-default/inferred values ("we assumed X — confirm
    #     or correct")
    for a in (augment.get("augmentations") or []):
        if not (isinstance(a, dict) and a.get("was_filled")):
            continue
        val = a.get("new_value")
        val_s = (json.dumps(val, default=str) if isinstance(val, (dict, list))
                 else str(val))
        _add(f"We assumed {str(a.get('field', '')).replace('_', ' ')} = "
             f"{_xq(val_s, 120)} — confirm or correct.",
             "every quantity derived from this field moves if the real value differs "
             "(it entered the design as if the brief had stated it)",
             f"inferred: {_xq(val_s, 100)} — {_xq(str(a.get('rationale') or ''), 140)}",
             "brief augmentation (was_filled) — 1-parsed-brief-augmented.json")
    # 3 — plausibility-critic contradictions (brief value vs physical floor)
    for c in (plausibility.get("contradictions") or []):
        if not isinstance(c, dict):
            continue
        _add(f"The brief's {c.get('constraint', 'constraint')} "
             f"({_xq(str(c.get('brief_value') or ''), 60)}) conflicts with the physical "
             f"floor {_xq(str(c.get('physical_floor') or ''), 60)} "
             f"({_xq(str(c.get('ratio') or ''), 30)}) — which should govern?",
             _xq(str(c.get("reasoning") or "the design cannot honour both; the engine "
                                           "proceeded on a revised constraint"), 220),
             "the chain applied its refinement-loop revision (see the brief's "
             "'alternatives considered')",
             "brief plausibility critic — 2-brief-plausibility-iter0.json")
    # 4 — unresolved design decisions (the register the structural-gate router keeps:
    #     'without human review you can't tell which')
    for d in (state.get("designDecisions") or []):
        if not isinstance(d, dict):
            continue
        rec = str(d.get("recommendation") or "").strip()
        if not rec:
            continue
        _add(f"Please review: {_xq(rec, 260)}",
             _xq(str(d.get("why_it_matters") or d.get("explanation") or ""), 240)
             or "the engine could not resolve this without review",
             _xq(str((d.get("conflicting_values") or ["the engine's current value "
                                                      "stands"])[0]), 200),
             f"design-decisions register — {d.get('id', '?')} "
             f"({d.get('kind', '?')}, module {d.get('module', '?')})")
    # 5 — client-offer reconciliation divergences NOT covered by a recorded decision
    #     (a covered section reads consistent_with_decision and asks nothing)
    for sec in ((state.get("_clientOfferRecon") or {}).get("sections") or []):
        st = sec.get("status")
        if st not in ("above", "partial", "out_of_scope"):
            continue
        key = f"{sec.get('key', '?')}. {sec.get('label', '')}"
        client = num(sec.get("client_gbp")) or 0.0
        if st == "above":
            q = (f"Client section {key}: this design prices "
                 f"£{num(sec.get('engine_installed_gbp')) or 0:,.0f} installed-equivalent "
                 f"against your £{client:,.0f} offer — do you want the fuller design, or "
                 f"should we match the offer's scope?")
        elif st == "partial":
            q = (f"Client section {key}: this bill models only part of your "
                 f"£{client:,.0f} section — should the balance be scoped in, or is it "
                 f"supplied by others?")
        else:
            q = (f"Client section {key} (£{client:,.0f} in your offer) has no line in "
                 f"this bill — confirm it is out of scope, or ask us to scope it.")
        _add(q,
             "the commercial reconciliation stays inconsistent until answered — the "
             "totals cannot be compared like-for-like and the delta is unexplained",
             _xq(str(sec.get("note") or "the engine's current scope stands"), 200),
             "Brief tab — client-offer reconciliation (no recorded decision covers "
             "this section; a decision in briefs-loop/<brief>.decisions.json clears it)")
    # 6 — G6 (Sam): pricing verifiability + brief compliance gaps that need a customer
    #     answer (RFQ lines, unpriced TBD, UNVERIFIED brief metrics, default clear height).
    #     Universal — keyed on estimate_class / rfq / compliance status / provenance text.
    bom = list(state.get("requirementsBom") or [])
    # fallback: some settled states carry the priced bill only on the parts-ledger artefact
    # (requirementsBom can be empty on older runs) — same RFQ/TBD signals, never invent lines.
    if not bom and run_dir:
        try:
            _pl = load_json(os.path.join(run_dir, "parts-ledger.json")) or {}
            for e in (_pl.get("equipment") or []):
                if not isinstance(e, dict):
                    continue
                bom.append({
                    "tag": e.get("tag"),
                    "requirement": e.get("name") or e.get("name_human") or "",
                    "status": e.get("status") or "",
                    "part": e.get("part") or "",
                    "line_gbp": e.get("line_gbp") or e.get("line_total_gbp") or 0,
                    "unit_gbp": e.get("unit_gbp") or e.get("unit_price_gbp") or 0,
                    "basis": e.get("basis") or "",
                    "estimate_class": e.get("estimate_class"),
                    "confidence": e.get("confidence") or "",
                    "rfq_recommended": e.get("rfq_recommended"),
                    "connection": False,
                })
        except Exception:
            pass
    rfq_n = 0
    for row in bom:
        if not isinstance(row, dict):
            continue
        if row.get("connection") or str(row.get("requirement", "")).startswith("↳"):
            continue
        eclass = row.get("estimate_class")
        basis = str(row.get("basis") or "")
        conf = str(row.get("confidence") or "")
        line = float(row.get("line_gbp") or 0)
        status_u = str(row.get("status", "") or "").upper()
        is_rfq = bool(row.get("rfq_recommended")) or (
            isinstance(eclass, (int, float)) and eclass >= 5
        ) or "confirm by quote" in basis.lower() or "order-of-magnitude" in conf.lower()
        # NOT FOUND / TBD status = no catalogue pin — customer needs a quote to verify
        # the price (Sam G5), even when the engine modelled a parametric £ figure
        is_tbd = status_u in ("NOT FOUND", "TBD") or bool(
            re.match(r"^\s*TBD\b", str(row.get("part") or ""), re.I)
        ) or (line <= 0 and status_u in ("ROUTED·REVIEW", "NOT FOUND", "TBD"))
        # skip micro-commodity pennies so the register stays about real plant kit
        if (is_rfq or is_tbd) and line < 100 and status_u != "TBD":
            continue
        if is_rfq or is_tbd:
            rfq_n += 1
            if rfq_n <= 12:  # cap so the register stays readable
                name = str(row.get("requirement") or row.get("tag") or "line").split("·")[0].strip()
                _add(
                    f"Please obtain a written supplier quote for: {_xq(name, 120)}"
                    + (f" (tag {row.get('tag')})" if row.get("tag") else "")
                    + ". This bill line is not catalogue-grounded at today's pricing.",
                    "Sam G5/G6: pricing is hard to verify without actual quotes — an RFQ or "
                    "TBD line cannot be signed off from the dossier alone",
                    f"engine estimate class {eclass or '?'} · £{line:,.0f} currently modelled",
                    "Bill of Materials — RFQ / unpriced line (estimate_class ≥ 5 or TBD/NOT FOUND)",
                )
    if rfq_n > 12:
        _add(
            f"{rfq_n - 12} further BoM lines also need written supplier quotes "
            f"(see the Bill of Materials Est class / Confidence columns).",
            "bulk RFQ backlog — the register lists the first 12; the ledger holds the rest",
            "see Bill of Materials ledger · Est class / Confidence · verify: obtain quote",
            "Bill of Materials — RFQ backlog roll-up",
        )
    # UNVERIFIED / FAIL brief metrics (compliance matrix)
    for m in ((state.get("parsedBrief") or {}).get("constraints") or {}).get(
            "target_performance", {}).get("metrics") or []:
        if not isinstance(m, dict):
            continue
        key = str(m.get("key_metric") or m.get("metric") or m.get("name") or "").strip()
        if not key:
            continue
        # re-use the same matcher the Brief tab uses
        hit = _match_quantity(m, (state.get("orchestratorContract") or {}).get("quantities") or {},
                              brief_text="")
        if hit is None:
            _add(
                f"Confirm the brief target '{key}' = {m.get('value')} {m.get('unit') or ''} — "
                f"the design has no matching delivered quantity the compliance matrix can verify.",
                "an UNVERIFIED brief target leaves the Executive Summary floor at 0 and means "
                "the dossier cannot prove the design meets what you asked for",
                "none — no delivered contract quantity matched this brief key",
                f"Brief compliance — UNVERIFIED metric {key}",
            )
    # default plant-room clear height (J6) — ask customer to confirm
    cq = (state.get("orchestratorContract") or {}).get("quantities") or {}
    pch = cq.get("plant_room_clear_height_m")
    if isinstance(pch, dict):
        detail = str(pch.get("source_detail") or pch.get("source") or "")
        if "confirm with customer" in detail.lower() or "standard industrial" in detail.lower():
            _add(
                f"Confirm plant-room clear height / finished ceiling. The design assumes "
                f"{pch.get('value')} m (standard industrial plant-room clear height) — "
                f"state the site-specific clear height if different.",
                "Sam J6: construction drawings need a defined ceiling so services, "
                "lifting and access can be checked; a default is not a customer decision",
                f"assumed {pch.get('value')} m clear — replace with the briefed clear height",
                "contract quantity plant_room_clear_height_m (default — confirm)",
            )
    return qs


def tab_questions(wb: Workbook, state: dict, run_dir: str) -> bool:
    """The QUESTIONS FOR THE CUSTOMER register. ALWAYS renders (never skipped): open
    questions are the deliverable when present, and 'No open questions' is stated
    HONESTLY (with what was consulted) when the brief is fully specified."""
    qs = _derive_customer_questions(state, run_dir)
    ws = wb.create_sheet(QUESTIONS_SHEET)
    set_widths(ws, {"A": 8, "B": 58, "C": 50, "D": 44, "E": 44})
    title_row(
        ws, "Questions for the customer — confirm or correct", 5,
        "Customers don't know what they want — so every value the engine had to assume, "
        "every brief field still missing, every physics contradiction and every "
        "unexplained divergence from your offer is a NUMBERED QUESTION here. Each row is "
        "derived live from a named engine artefact at build time (never hand-typed): "
        "answer it in the brief or record a scope decision, rebuild, and the row "
        "disappears. What changes if your answer differs is stated per row.")
    r = 4
    if qs:
        sub_banner(ws, r, f"OPEN QUESTIONS — {len(qs)}, numbered (each names the "
                          f"artefact that raised it)", 5)
        r += 1
        header(ws, r, ["Q#", "Question for the customer",
                       "Why it matters — what changes if the answer differs",
                       "Assumption in force (until answered)",
                       "Provenance (engine artefact that raised it)"])
        r += 1
        for q in qs:
            ws.cell(r, 1, q["id"]).font = Font(bold=True, color="1F4E79")
            ws.cell(r, 1).border = BORDER
            for ci, k in ((2, "question"), (3, "why"), (4, "assumption"), (5, "provenance")):
                c = ws.cell(r, ci, clean_cell(q[k]))
                c.alignment = WRAP_TOP
                c.font = Font(size=10, bold=True) if ci == 2 else FONT_NOTE
                c.border = BORDER
            longest = max(len(str(q[k])) for k in ("question", "why", "assumption",
                                                   "provenance"))
            ws.row_dimensions[r].height = 14.5 * min(7, max(2, -(-longest // 46)))
            r += 1
    else:
        c = ws.cell(r, 1, clean_cell(
            "No open questions — the brief augmentation reports no missing or inferred "
            "hard fields, the plausibility critic found no contradictions, the design-"
            "decisions register is empty, and every client-offer section reconciles (or "
            "is covered by a recorded decision). All four artefacts were consulted live "
            "at build time."))
        c.font = Font(size=10, bold=True, color="375623")
        c.alignment = WRAP_TOP
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=5)
        ws.row_dimensions[r].height = 44
        r += 1
    ws.freeze_panes = "A5"
    back_link(ws, 5)
    n = len(qs)
    complete = sum(1 for q in qs
                   if all(str(q.get(k) or "").strip()
                          for k in ("id", "question", "why", "assumption", "provenance")))
    sc = 10.0 if (n == 0 or complete == n) else max(0.0, round(10 * complete / n, 1))
    _TAB_SCORES[QUESTIONS_SHEET] = {
        "score": sc, "target": 8, "status": "PASS" if sc >= 8 else "FAIL",
        "issues": [f"{n} open question(s) for the customer — every row derived live "
                   f"from a named engine artefact (brief augmentation / plausibility "
                   f"critic / decisions register / client-offer reconciliation); an "
                   f"answered question disappears on rebuild"],
        "fix": "answer each question in the brief (or record a scope decision in "
               "briefs-loop/<brief>.decisions.json) and re-run",
    }
    return True


def _sc_questions(wb, ws, state, run_dir):
    """Content scorer: the RENDERED questions must match the LIVE re-derivation (a stale
    question or a silently-dropped one both fail), mirroring _sc_holds."""
    comps = []
    iss = []
    live = _derive_customer_questions(state, run_dir)
    rows = _fam_rows(wb, ws.title, "questions")
    live_ids = [q["id"] for q in live]
    rend = [(_cell_txt(d.get("q#")), _cell_txt(d.get("question for the customer")))
            for _r, d in rows]
    matched = 0
    for i, (rid, rq) in enumerate(rend):
        if i < len(live_ids) and rid == live_ids[i] \
                and rq.startswith(str(live[i]["question"])[:40]):
            matched += 1
    total = max(len(live_ids), len(rend)) if (live_ids or rend) else 0
    if total:
        comps.append(("rendered questions match the LIVE re-derivation "
                      "(stale/dropped question = fail)", matched, total))
        if matched < total:
            iss.append(f"{total - matched} question(s) diverge from the live "
                       f"re-derivation — an answered question may still render, or a "
                       f"new gap is missing from the register")
    else:
        # the honest empty register: the sheet must SAY so, and the re-derivation agree
        blob = " ".join(str(c.value) for row in ws.iter_rows() for c in row
                        if isinstance(c.value, str))
        stated = "no open questions" in blob.lower()
        comps.append(("live re-derivation agrees no questions are open AND the sheet "
                      "states it honestly", 1 if stated else 0, 1))
        if not stated:
            iss.append("no questions derived, but the sheet does not state 'No open "
                       "questions' — the empty register must be explicit")
    return {"components": comps, "issues": iss,
            "mech": "live-derivation check (each question re-derived from the run's own "
                    "artefacts: brief augmentation, plausibility critic, decisions "
                    "register, client-offer reconciliation)",
            "fix": "rebuild — the register renders only what the live derivation yields"}


def tab_line_velocity(wb: Workbook, run_dir: str) -> bool:
    """#22 — Line & velocity schedule from connection-schedule.json, SPLIT into
    process-pipe lines (velocity vs ≤3 m/s) and electrical/signal cables (volt-drop
    vs ≤5 %) so flow, current and power units never mix in one column. Adds a Basis
    column showing how each Line £ is derived. within_spec ✗ conditional-formatted RED."""
    cs = load_json(os.path.join(run_dir, "connection-schedule.json"))
    if not cs or not isinstance(cs, dict):
        return False
    rows = cs.get("rows")
    if not rows or not isinstance(rows, list):
        return False
    specs = cs.get("specs") or []  # parallel, carries the spec_limit text

    # LV1/X5 (Tristan 2026-06-27: "every line must have a TAG"). The CANONICAL line tag is the route-
    # manifest's `line_number` (e.g. "201-WT-DN15") — the SAME tag the isometric spools + the P&ID use.
    # Map each connection-schedule row to it by (from, to, size); index fallback keeps it robust.
    _rm = load_json(os.path.join(run_dir, "route-manifest.json")) or {}
    _rlines = _rm.get("lines") if isinstance(_rm, dict) else None
    _tag_by_fts: dict = {}
    if isinstance(_rlines, list):
        for _ln in _rlines:
            if isinstance(_ln, dict) and _ln.get("line_number"):
                _tag_by_fts[(str(_ln.get("from_tag")), str(_ln.get("to_tag")), str(_ln.get("size_label")))] = str(_ln.get("line_number"))

    def _line_tag(row, idx):
        k = (str(row.get("from")), str(row.get("to")), str(row.get("size")))
        if k in _tag_by_fts:
            return _tag_by_fts[k]
        if isinstance(_rlines, list) and idx < len(_rlines) and isinstance(_rlines[idx], dict):
            return str(_rlines[idx].get("line_number") or (idx + 1))
        return str(idx + 1)

    # The COLUMN CONTRACT for this tab (evaluated once in build(), before any tab renders).
    # Every row's tick below is the CONTRACT's computed comparison — never row['within_spec']
    # (the v52 fabrication: 45/45 rows ticked ✓ over velocity 0.0 m/s from a zero flow).
    cres = _CONTRACT_RESULTS.get("Line & velocity") or {}
    crows = cres.get("rows") or {}

    ws = wb.create_sheet("Line & velocity")
    set_widths(ws, {"A": 15, "B": 22, "C": 22, "D": 16, "E": 16, "F": 14,
                    "G": 16, "H": 10, "I": 9, "J": 13, "K": 62, "L": 52,
                    "M": 10, "N": 30})
    subtitle = (
        "Every sized run, SPLIT so units never mix: process-pipe lines (flow, "
        "velocity vs the erosion band) · electrical & signal cables (current A, volt-drop "
        "band) · other services. Velocity is COMPUTED (the sizer's as-sized value when it "
        "carried a real flow, else v = Q ÷ A from the endpoint-matched contract flow over "
        "the sizer's DN bore); 'In spec' is the computed band comparison — never a default "
        "tick. Basis shows the flow/velocity derivation + how each Line £ is built."
    )
    if cres:
        subtitle += " " + _contract_note(cres)
    title_row(ws, "Line & velocity schedule", 12, subtitle)

    # bucket rows by section, preserving the original index for the '#'
    groups: Dict[str, list] = {"pipe": [], "electrical": [], "other": []}
    for idx, row in enumerate(rows):
        if not isinstance(row, dict):
            continue
        spec = specs[idx] if idx < len(specs) and isinstance(specs[idx], dict) else {}
        groups[_line_section(row, spec)].append((idx, row, spec))

    SECTIONS = [
        ("pipe", "Process pipe lines — flow (m³/s) · velocity limit ≤ 3 m/s"),
        ("electrical", "Electrical & signal cables — current (A) · volt-drop limit ≤ 5 %"),
        ("other", "Other services (air / misc)"),
    ]
    HDR = ["Tag", "From", "To", "Size", "Rating", "Velocity / ΔU", "Spec limit",
           "Length (m)", "In spec", "Line £", "Basis", "Row check",
           "Audit: band", "Audit: check evidence (build-computed)"]
    r = 4
    # ROOT-CAUSE ROLL-UP (fix 3): failing rows grouped to their cause(s), above the table.
    r = _render_rollup(ws, r, cres, 12)
    grand_fail = 0
    spec_cells = []   # In-spec column cells for the conditional-format range
    for key, label in SECTIONS:
        g = groups[key]
        if not g:
            continue
        sub_banner(ws, r, label, 12)
        r += 1
        # BASIS BOILERPLATE FACTORING (fix 3): identical trailing sentences shared by >80%
        # of this section's Basis cells move to ONE header note; per-row numbers stay.
        _sec_bases = []
        for idx, row, spec in g:
            cr = crows.get(idx) or {}
            _bits = [b for b in (_line_basis(row), cr.get("vel_basis"),
                                 (f"cost model: {row.get('cost_source')}" if row.get("cost_source") else "")) if b]
            _sec_bases.append(" · ".join(_bits))
        _common, _sec_bases = _hoist_common_tail(_sec_bases)
        if _common:
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=12)
            _bn = ws.cell(r, 1, clean_cell("Basis note — common to the rows below (factored out "
                                           "of the per-row cells): " + " · ".join(_common)))
            _bn.font = FONT_NOTE
            _bn.alignment = WRAP_TOP
            r += 1
        header(ws, r, HDR)
        ws.cell(r, 13).font = _FONT_AUDIT
        ws.cell(r, 14).font = _FONT_AUDIT
        r += 1
        sec_first = r
        _sec_ok = 0
        for _gi, (idx, row, spec) in enumerate(g):
            cr = crows.get(idx) or {}
            # the COMPUTED verdict — a row with no contract evaluation is UNVERIFIED = FAIL
            # (never inherit the source's within_spec tick).
            in_spec = cr.get("in_spec") if cr else False
            # P2-K (2026-07-09): pure underivable-velocity stubs are N/A (not FAIL) —
            # the contract already scores them as n_pass; the render must match so the
            # tab banner / live formulas do not re-fail honest DN25 "flow unknown" rows.
            _verdict = cr.get("verdict")
            row_ok = _verdict in ("PASS", "N/A")
            _is_na = _verdict == "N/A"
            if row_ok:
                _sec_ok += 1
            ws.cell(r, 1, _line_tag(row, idx)).border = BORDER
            # From / To endpoints REFERENCE the master "Part names" row where the endpoint
            # is a registered principal (one identity; click through to the part). The
            # connection-schedule labels endpoints by NAME ("Standby Diesel Generator"), so
            # resolve by name first, tag second; literal kept for boundary endpoints (e.g.
            # "Utility Incomer") the master doesn't carry.
            _fr = name_ref(row.get("from", "")) or tag_ref(row.get("from", ""))
            ws.cell(r, 2, _fr if _fr else clean_cell(row.get("from", ""))).border = BORDER
            _to = name_ref(row.get("to", "")) or tag_ref(row.get("to", ""))
            ws.cell(r, 3, _to if _to else clean_cell(row.get("to", ""))).border = BORDER
            ws.cell(r, 4, clean_cell(row.get("size", ""))).border = BORDER
            # Rating = the COMPUTED carried flow / current (the contract's derivation, incl.
            # the endpoint-matched contract quantity when the edge carried no demand) —
            # never the source's fabricated "0 m³/s".
            ws.cell(r, 5, cr.get("flow_display") or clean_cell(row.get("rating", ""))).border = BORDER
            # Velocity / ΔU = the CONTRACT's computed value (as-sized when the sizer carried a
            # real flow; else v = Q ÷ A from the contract quantity; n/a when underivable).
            velnum = cr.get("velocity")
            if velnum is not None:
                # full precision stored (display masked 2dp) — the In-spec FORMULA compares
                # this cell against the band, so a display-rounded 3.0 must not pass a 3.0004
                vc = ws.cell(r, 6, float(velnum))
                vc.number_format = FMT_DEC2
            elif _is_na or str(cr.get("vel_basis") or "").startswith("n/a — "):
                vc = ws.cell(r, 6, "n/a")
            else:
                vc = ws.cell(r, 6, "UNVERIFIED")
            vc.border = BORDER
            ws.cell(r, 7, clean_cell(spec.get("spec_limit", ""))).border = BORDER
            lc = ws.cell(r, 8, num(row.get("length_m")))
            lc.number_format = FMT_DEC1
            lc.border = BORDER
            # ── AUDIT OPERANDS (cols M/N, muted): M = the numeric band this row is judged
            #    against ('' when no band applies — an n/a service); N = the contract
            #    evaluation's evidence (reasons, '' when clean). The In-spec tick and the
            #    Row check are LIVE FORMULAS over F/M/N — never a literal (2026-07-03). ──
            # N/A underivable stubs: empty evidence so the live In-spec formula yields 'n/a'
            # (a non-empty N with no band previously forced ✗ and re-failed the row).
            _band = None
            if in_spec is not None and not _is_na:
                _bm = re.search(r"(\d+(?:\.\d+)?)", str(spec.get("spec_limit", "")))
                _band = float(_bm.group(1)) if _bm else {"pipe": 3.0, "electrical": 5.0}.get(key)
            _bc2 = ws.cell(r, 13, _band)
            _bc2.font = _FONT_AUDIT
            if _is_na:
                _ev = ""
            else:
                _ev = "; ".join(cr.get("reasons") or ([] if cr else ["no contract evaluation for this row"]))
            _evc = ws.cell(r, 14, clean_cell(_ev) if _ev else None)
            _evc.font = _FONT_AUDIT
            _evc.alignment = WRAP_TOP
            # In spec = the LIVE band comparison over the computed velocity/ΔU (F) vs the
            # band (M); no band → 'n/a' only while the evidence (N) is clean.
            sc = ws.cell(r, 9, f'=IF(ISNUMBER($M{r}),'
                               f'IF(AND(ISNUMBER($F{r}),$F{r}<=$M{r}),"✓","✗"),'
                               f'IF(LEN(TRIM($N{r}&""))=0,"n/a","✗"))')
            sc.border = BORDER
            sc.alignment = Alignment(horizontal="center")
            spec_cells.append(sc.coordinate)
            if not row_ok:
                sc.font = FONT_FAIL
                grand_fail += 1
                for col in range(1, 13):
                    ws.cell(r, col).fill = FILL_FAIL
            elif in_spec is True or _is_na:
                sc.fill = FILL_PASS
                sc.font = FONT_PASS
            lt = ws.cell(r, 10, num(row.get("line_total_gbp")))
            lt.number_format = FMT_GBP
            lt.border = BORDER
            basis = _sec_bases[_gi]   # boilerplate tail already factored to the header note
            bc = ws.cell(r, 11, basis)
            bc.alignment = WRAP_TOP
            bc.border = BORDER
            # Row check — LIVE formula: the in-spec tick must hold (✓ or a clean n/a) and
            # the embedded evidence must be empty; the FAIL branch names the evidence.
            rc = ws.cell(r, 12, fx_verdict(
                [f'OR($I{r}="✓",$I{r}="n/a")', f'LEN(TRIM($N{r}&""))=0'],
                _fx_evidence_expr(f"$N{r}", "velocity/ΔU outside its band or unverifiable")))
            rc.alignment = WRAP_TOP
            rc.border = BORDER
            rc.font = FONT_PASS if row_ok else FONT_FAIL
            rc.fill = FILL_PASS if row_ok else FILL_FAIL
            _wrap_len = max(len(basis), len(_ev))
            if _wrap_len > 52:
                ws.row_dimensions[r].height = min(-(-_wrap_len // 52), 5) * 14.5
            r += 1
        _register_check_range(ws.title, "L", sec_first, r - 1,
                              n_pass=_sec_ok, n_total=len(g))
        _cf_verdict(ws, f"L{sec_first}:L{r - 1}")
        # per-section Σ line £
        ws.cell(r, 2, f"Σ {label.split('—')[0].strip()}").font = FONT_SUB
        st = ws.cell(r, 10, f"=SUM(J{sec_first}:J{r - 1})")
        st.font = Font(bold=True)
        st.fill = FILL_RESULT
        st.number_format = FMT_GBP
        r += 2

    # grand foot: rows failing the published column contract — LIVE count over the
    # Row-check column itself (an edited operand re-tallies on recalc).
    ws.cell(r, 2, "Rows FAILING the column contract (all sections, live count)").font = FONT_SUB
    tc = ws.cell(r, 9, f'=SUMPRODUCT(--(LEFT($L$5:$L${r - 1},4)="FAIL"))')
    tc.font = FONT_FAIL if grand_fail else FONT_PASS
    tc.fill = FILL_FAIL if grand_fail else FILL_PASS
    tc.alignment = Alignment(horizontal="center")

    # any '✗' in an In-spec cell goes red live
    if spec_cells:
        from openpyxl.formatting.rule import CellIsRule
        ws.conditional_formatting.add(
            f"I5:I{r}",
            CellIsRule(operator="equal", formula=['"✗"'], fill=FILL_FAIL, font=FONT_FAIL))
    ws.freeze_panes = "A5"
    back_link(ws, 12)
    return True


# ============================================================================
# TAB — CONTENTS / INDEX (#26)  — built LAST, moved to sheet #1
# ============================================================================
def tab_contents(wb: Workbook, descriptions: Dict[str, str]) -> None:
    """Create the Contents sheet (a hyperlink index to every other tab + a
    one-line description) and MOVE it to position #1. Called after all other
    sheets exist so the full ordered sheet list is known."""
    ws = wb.create_sheet(CONTENTS_SHEET)
    set_widths(ws, {"A": 4, "B": 34, "C": 78})
    title_row(
        ws, "Contents", 3,
        "Click any tab name to jump to it. Each data tab has a '↑ Contents' "
        "link at its top-right to come back. Yellow cells anywhere are editable "
        "inputs; green cells are live formulas.",
    )
    header(ws, 4, ["#", "Tab", "What's on it"])
    r = 5
    n = 1
    for name in wb.sheetnames:
        if name == CONTENTS_SHEET:
            continue
        ws.cell(r, 1, n).border = BORDER
        c = ws.cell(r, 2, name)
        _set_internal_hyperlink(c, name)
        c.font = FONT_LINK
        c.border = BORDER
        d = ws.cell(r, 3, descriptions.get(name, _default_desc(name)))
        d.alignment = WRAP_TOP
        d.font = FONT_NOTE
        d.border = BORDER
        r += 1
        n += 1
    ws.freeze_panes = "A5"
    # group colour (Contents is built AFTER _reorder_tabs stamped every other sheet)
    try:
        ws.sheet_properties.tabColor = _TAB_GROUP_COLOUR[_tab_group(CONTENTS_SHEET)]
    except Exception:  # noqa: BLE001
        pass
    # move to the very front
    idx = wb.sheetnames.index(CONTENTS_SHEET)
    if idx != 0:
        wb.move_sheet(CONTENTS_SHEET, -idx)


def _default_desc(name: str) -> str:
    """Fallback one-line description for image / module tabs not in the static map.
    Distinct lines per drawing TYPE (matched on the title) so GA/P&ID/BFD/Single-line/
    HVAC never share an identical generic string."""
    low = name.lower()
    if low.startswith("module —"):
        return "Per-module Blender render."
    if low.startswith("isometric"):
        return "Representative pipe isometric drawing."
    if low.startswith("render"):
        return "Photoreal Blender render."
    if low.startswith("ga") or "general arrangement" in low:
        return "General arrangement — equipment layout & footprint."
    if "p&id" in low or low.startswith("pid"):
        return "Piping & instrumentation diagram — process flow, valves, instruments."
    if low.startswith("bfd") or "block flow" in low:
        return "Block flow diagram — major process blocks & streams."
    if "single-line" in low or "single line" in low:
        return "Single-line electrical distribution diagram."
    if "hvac" in low:
        return "Ventilation & climate-control schematic."
    return "Engineering drawing / view."


# ============================================================================
# IMAGE TABS
# ============================================================================
def ensure_png(src_path: str, run_dir: str) -> Optional[str]:
    """
    Return a PNG path for an image reference. If only an SVG exists, convert it to
    PNG (cairosvg preferred, then rsvg-convert). Returns None if nothing usable.
    """
    if src_path.lower().endswith(".png") and os.path.exists(src_path):
        return src_path
    # if given a .svg, try png sibling first
    base, ext = os.path.splitext(src_path)
    png_sib = base + ".png"
    if os.path.exists(png_sib):
        return png_sib
    if ext.lower() == ".svg" and os.path.exists(src_path):
        out_png = os.path.join(run_dir, ".excel-tmp",
                               os.path.basename(base) + ".png")
        os.makedirs(os.path.dirname(out_png), exist_ok=True)
        # try cairosvg
        try:
            import cairosvg  # noqa: WPS433
            cairosvg.svg2png(url=src_path, write_to=out_png, output_width=3000)
            return out_png
        except Exception:  # noqa: BLE001
            pass
        # try rsvg-convert
        try:
            subprocess.run(["rsvg-convert", "-w", "3000", "-o", out_png, src_path],
                           check=True, capture_output=True, timeout=60)
            if os.path.exists(out_png):
                return out_png
        except Exception:  # noqa: BLE001
            pass
    return None


def downscale_png(src_png: str, run_dir: str, max_px: int = 3400) -> str:
    """
    Downscale a PNG so the whole workbook stays manageable. Raised 1400→2600→3400
    (Tristan: "make all of the diagrams higher resolution" + "A2 minimum"): native
    drawings are 2160–6560 px and the densest (single-line 6140, P&ID 4380, block-
    flow 4526, process-schedule 4356) were still being crushed to 2600. 3400 keeps
    the dense P&ID / single-line / process-schedule legible on zoom (≈ A2 at ~150 dpi)
    while bounding workbook size; smaller renders (hero, isometrics ~2360 px) pass
    through untouched. Universal.
    Returns a path to the (possibly) downscaled PNG. Keeps aspect ratio. JPEG-quality
    PNG compression via Pillow optimisation.
    """
    try:
        from PIL import Image
    except Exception:  # noqa: BLE001
        return src_png
    try:
        with Image.open(src_png) as im:
            im = im.convert("RGB") if im.mode in ("RGBA", "P") else im
            w, h = im.size
            scale = min(1.0, max_px / float(max(w, h)))
            if scale < 1.0:
                im = im.resize((max(1, int(w * scale)), max(1, int(h * scale))))
            out_dir = os.path.join(run_dir, ".excel-tmp")
            os.makedirs(out_dir, exist_ok=True)
            # Name the downscaled file by its PARENT-QUALIFIED relative path, NOT the bare
            # basename — interior 00-hero.png and exterior/00-hero.png share a basename, so a
            # basename-keyed temp made the exterior OVERWRITE the interior and both tabs embedded
            # the SAME image (Tristan 2026-06-22: "interior and exterior layouts are identical").
            try:
                _rel = os.path.relpath(src_png, run_dir)
            except ValueError:
                _rel = os.path.basename(src_png)
            _safe = _rel.replace(os.sep, "_").replace("..", "_")
            out = os.path.join(out_dir, "ds_" + _safe)
            # save as compressed JPEG inside a .png-ext wrapper would confuse openpyxl;
            # keep PNG but optimise.
            im.save(out, format="PNG", optimize=True)
            return out
    except Exception as exc:  # noqa: BLE001
        print(f"    ! downscale failed for {src_png}: {exc}")
        return src_png


_SHEET_BAD = re.compile(r"[:\\/?*\[\]]")


def safe_sheet_title(name: str, used: set) -> str:
    t = _SHEET_BAD.sub("-", name)[:31].strip() or "sheet"
    base = t
    i = 2
    while t.lower() in used:
        suffix = f"-{i}"
        t = (base[: 31 - len(suffix)] + suffix)
        i += 1
    used.add(t.lower())
    return t


def add_image_tab(wb: Workbook, run_dir: str, png_path: str, title: str,
                  caption: str, used_titles: set) -> Optional[str]:
    """Embed one image as its own sheet. Returns the ACTUAL sheet title (so the
    Drawings register can link to it), or None on failure."""
    from openpyxl.drawing.image import Image as XLImage
    ds = downscale_png(png_path, run_dir)
    try:
        sheet_title = safe_sheet_title(title, used_titles)
        ws = wb.create_sheet(sheet_title)
        # Shared navy title band (matches the data tabs) + a ↑ Contents back-link, instead
        # of a bare bold cell. title_row returns the next free row; the image goes below it.
        img_row = title_row(ws, title, 6, caption)
        back_link(ws, 6)
        # DRAWING CAPTION ROW (reviewers 2026-07-02): on each engineering-drawing tab,
        # say where the full-size A1 vector sheets live + one sentence of reading
        # guidance — the embedded PNG is a preview, the A1 PDF set is the print master.
        note = _drawing_tab_note(run_dir, title)
        if note:
            ws.merge_cells(start_row=img_row, start_column=1,
                           end_row=img_row, end_column=6)
            nc = ws.cell(img_row, 1, note)
            nc.font = FONT_SUB
            nc.fill = FILL_SUB
            nc.alignment = WRAP_TOP
            ws.row_dimensions[img_row].height = 30
            img_row += 1
        img = XLImage(ds)
        # cap on-sheet display size (keep aspect) so the tab is readable. Raised
        # 1100→1700 to match the higher-res embed: the underlying PNG is up to
        # 2600 px so zooming stays sharp. Universal.
        max_w = 1700
        if img.width and img.width > max_w:
            ratio = max_w / float(img.width)
            img.width = int(img.width * ratio)
            img.height = int(img.height * ratio)
        ws.add_image(img, f"A{img_row}")
        return sheet_title
    except Exception as exc:  # noqa: BLE001
        print(f"    ! could not embed {png_path}: {exc}")
        return None


def _manifest_render_map(run_dir: str) -> Dict[str, Tuple[str, str]]:
    """RENDER NAMES/CAPTIONS from the drawing-manifest `renders` array (generator-purge
    2026-07-02): each render carries a canonical ≤31-char `sheet_name` + a `caption`
    (bearing + envelope dims + tag callouts). {normalised path: (name, caption)}."""
    _man = load_json(os.path.join(run_dir, "drawing-manifest.json")) or {}
    _rmap: Dict[str, Tuple[str, str]] = {}
    for _r in (_man.get("renders") or []):
        if isinstance(_r, dict) and _r.get("file"):
            _rmap[os.path.normpath(os.path.join(run_dir, str(_r["file"])))] = (
                str(_r.get("sheet_name") or "").strip()[:31],
                str(_r.get("caption") or "").strip())
    return _rmap


# The GALLERY view set (Bundle B fix 1, reviewers 2026-07-02; side elevation 2026-07-09):
# ONE 'Renders' gallery keeps the informative views Excel actually ships. Selection is by
# view KIND from canonical filenames (universal):
#   interior 00-hero       → hero isometric
#   interior 01-top        → annotated plan
#   inspect-side / 04-side → SIDE ELEVATION (underground tanks + buried pipes visible)
#   exterior 00-hero       → building exterior iso
#   exterior 02-corner-FR  → 2nd exterior angle
# INTENT (Tristan 2026-07-09): no PDF; only images that land in Excel; the side elevation
# MUST show below-slab drainage / tanks / pipes — iso/plan alone hide that.
_GALLERY_VIEWS = (
    ("00-hero.png", "Interior — hero isometric",
     "Blender 3D render — interior plant layout (no walls/roof), three-quarter hero view."),
    ("01-top.png", "Interior — annotated plan",
     "Interior plant layout — top-down plan view (matches the GA orientation)."),
    ("inspect-side.png", "Interior — side elevation (underground)",
     "Side elevation with the ground slab hidden so underground tanks, sumps and "
     "buried drain/pipe runs are visible below grade."),
    (os.path.join("exterior", "00-hero.png"), "Exterior — building isometric",
     "Architectural exterior of the building/enclosure, three-quarter view."),
    (os.path.join("exterior", "02-corner-FR.png"), "Exterior — front-corner",
     "Architectural exterior — front-corner angle."),
)
# Canonical aliases for the required side elevation (Blender writes inspect-side.png;
# drawing-set may also promote 04-side-elevation.png).
_SIDE_ELEVATION_CANDIDATES = (
    "inspect-side.png",
    "04-side-elevation.png",
    "04-side.png",
)


def _side_elevation_path(run_dir: str) -> Optional[str]:
    """First existing side-elevation PNG in the run dir, or None."""
    for rel in _SIDE_ELEVATION_CANDIDATES:
        p = os.path.join(run_dir, rel)
        if os.path.exists(p):
            return p
    return None


def _gallery_render_specs(run_dir: str) -> List[Tuple[str, str, str]]:
    """The gallery's (file_path, view_name, caption) picks — hero iso + annotated interior
    plan + REQUIRED side elevation (underground) + up to 2 exterior views.
    Captions/names come from the drawing-manifest renders[] where present.
    Near-duplicate corners + the exterior-top are deliberately NOT selected."""
    _rmap = _manifest_render_map(run_dir)
    _state = load_json(os.path.join(run_dir, "state.json")) or {}
    if is_product_scale(_state):
        _product_specs: List[Tuple[str, str, str]] = []
        for _view in required_views(_state):
            _path = os.path.join(run_dir, _view.filename)
            if not os.path.exists(_path):
                # try the view's fallback filenames (e.g. cutaway 08-ghost -> 00-hero)
                _alt = next((os.path.join(run_dir, a) for a in getattr(_view, "alternates", ())
                             if os.path.exists(os.path.join(run_dir, a))), None)
                if not _alt:
                    continue
                _path = _alt
            _sheet_name, _caption = _rmap.get(
                os.path.normpath(_path), ("", ""))
            _product_specs.append((
                _path,
                _sheet_name or _view.title,
                _caption or _view.caption,
            ))
        return _product_specs
    specs: List[Tuple[str, str, str]] = []
    side_added = False
    for rel, fb_title, fb_cap in _GALLERY_VIEWS:
        if rel == "inspect-side.png":
            p = _side_elevation_path(run_dir)
            if not p:
                continue
            side_added = True
            sn, cap = _rmap.get(os.path.normpath(p), ("", ""))
            specs.append((p, sn or fb_title, cap or fb_cap))
            continue
        p = os.path.join(run_dir, rel)
        if rel == "00-hero.png" and not os.path.exists(p):
            # the interior hero's legacy alias
            alt = os.path.join(run_dir, "blender-cover.png")
            p = alt if os.path.exists(alt) else p
        if not os.path.exists(p):
            continue
        sn, cap = _rmap.get(os.path.normpath(p), ("", ""))
        specs.append((p, sn or fb_title, cap or fb_cap))
    # GOTCHA: if the side view was listed but missing, and no alias existed, the
    # gallery still builds — the Renders scorer then caps below 9 (see
    # _gallery_missing_side_elevation). Never invent a placeholder image.
    _ = side_added
    return specs


def _gallery_missing_side_elevation(run_dir: str) -> bool:
    """True when the run has Blender hero/plan renders but NO side elevation —
    the underground-visibility requirement (Tristan 2026-07-09) is unmet."""
    _state = load_json(os.path.join(run_dir, "state.json")) or {}
    if is_product_scale(_state):
        return False
    has_plant_view = any(
        os.path.exists(os.path.join(run_dir, n))
        for n in ("00-hero.png", "blender-cover.png", "01-top.png", "inspect-iso.png")
    )
    return bool(has_plant_view and _side_elevation_path(run_dir) is None)


def tab_renders(wb: Workbook, run_dir: str) -> Optional[List[Tuple[str, str]]]:
    """ONE 'Renders' gallery tab — hero isometric + annotated plan + side elevation
    (underground tanks/pipes) + 1-2 exterior views. Returns [(sheet_title, source_path), …]
    for the embedded views, or None when the run has no renders at all."""
    from openpyxl.drawing.image import Image as XLImage
    specs = _gallery_render_specs(run_dir)
    if not specs:
        return None
    ws = wb.create_sheet("Renders")
    _state = load_json(os.path.join(run_dir, "state.json")) or {}
    _is_product = is_product_scale(_state)
    r = title_row(
        ws,
        ("Renders — product CAD views" if _is_product
         else "Renders — photoreal views of the plant"),
        6,
        ("Form-factor-approved product views: closed exterior, cutaway, opposing "
         "front-side angles and service interfaces. Only validated, useful views "
         "are embedded."
         if _is_product else
         "Blender views embedded in this workbook: interior hero, annotated plan, "
         "side elevation (ground slab hidden so underground tanks and buried pipes "
         "are visible), and the building exterior. Only these Excel-embedded images "
         "are generated for the deliverable — there is no separate PDF image set."))
    back_link(ws, 6)
    if _gallery_missing_side_elevation(run_dir):
        note = ws.cell(
            r, 1,
            "⚠ MISSING: side elevation (inspect-side.png) — underground tanks/pipes "
            "cannot be verified from iso/plan alone. Re-run Blender inspect pass.",
        )
        note.font = FONT_NOTE
        note.alignment = WRAP_TOP
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=6)
        ws.row_dimensions[r].height = 36
        r += 2
    embedded: List[Tuple[str, str]] = []
    for path, name, caption in specs:
        png = ensure_png(path, run_dir)
        if not png:
            continue
        sub_banner(ws, r, name, 6)
        r += 1
        cap = ws.cell(r, 1, clean_cell(caption))
        cap.font = FONT_NOTE
        cap.alignment = WRAP_TOP
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=6)
        ws.row_dimensions[r].height = 30
        r += 1
        try:
            ds = downscale_png(png, run_dir)
            img = XLImage(ds)
            max_w = 1500                      # gallery views a notch smaller than a solo tab
            if img.width and img.width > max_w:
                ratio = max_w / float(img.width)
                img.width = int(img.width * ratio)
                img.height = int(img.height * ratio)
            ws.add_image(img, f"A{r}")
            # reserve rows under the anchor so the next section never overlaps the image
            # (default Excel row ≈ 20 px)
            r += int(-(-(img.height or 600) // 20)) + 2
            embedded.append(("Renders", path))
        except Exception as exc:  # noqa: BLE001
            print(f"    ! could not embed gallery render {path}: {exc}")
            r += 1
    return embedded or None


def collect_image_specs(run_dir: str) -> List[Tuple[str, str, str]]:
    """
    Return ordered list of (file_path, tab_title, caption) for PRIMARY engineering-drawing
    preview tabs. Plant secondary drawings (P&ID / BFD / HVAC / GA) live on the Drawings
    register only (2026-07-14 consolidation). Handheld primaries stay as tabs:
    Assembly + Interconnect.
    """
    specs: List[Tuple[str, str, str]] = []
    draw = os.path.join(run_dir, "drawings")
    state = load_json(os.path.join(run_dir, "state.json")) or {}
    form = drawing_form_factor(state) if isinstance(state, dict) else "plant"
    instrument = bool(isinstance(state, dict) and state.get("isInstrumentDevice"))

    def first_existing(*cands: str) -> Optional[str]:
        for c in cands:
            if c and os.path.exists(c):
                return c
        return None

    def _add(stem: str, ttl: str, cap: str) -> None:
        cand_png = os.path.join(draw, stem + ".png")
        cand_svg = os.path.join(draw, stem + ".svg")
        root_png = os.path.join(run_dir, stem + ".png")
        path = first_existing(cand_png, root_png)
        if not path:
            path = ensure_png(cand_svg, run_dir)
        if path:
            specs.append((path, ttl, cap))

    # INTENT (2026-07-14): handheld primary surfaces as workbook tabs; plant GA/P&ID/BFD/HVAC
    # are register-only (still listed in _DRAWING_REGISTER + A1 PDFs).
    if instrument or form == "handheld":
        _add("general-arrangement", "Assembly",
             "Assembly — enclosure / optical / PCB layout (product datum).")
        _add("interconnect", "Interconnect",
             "Interconnect — device wiring & signal paths (see also Connection trace).")
    elif form == "sealed_cabinet":
        # Product GA remains a primary glance surface for wall cabinets.
        _add("general-arrangement", "GA — General Arrangement",
             "Product general arrangement / cutaway layout.")
    # Plant: no standalone drawing preview tabs — Drawings register carries them.

    return specs


# ============================================================================
# TAB — DRAWINGS REGISTER (reviewers' unanimous #1, 2026-07-02)
# The seven print-ready ISO A1 vector PDFs (a1_print.py, commit 761ff4608) existed in
# every run's drawings/ dir and were referenced NOWHERE in the workbook. This register
# is the consultancy-standard artefact: one row per engineering drawing — Drawing No. ·
# Title · Rev · Scale · Sheets · Min lettering · A1 PDF file(s) · preview-tab link —
# plus a second section listing the photoreal renders from the drawing-manifest.
# ============================================================================

# The canonical drawing set: (A1 base, SVG master, default drawing no., register title,
# embedded-preview tab fallback title). Register order mirrors the workbook tab order.
_DRAWING_REGISTER = [
    ("ga", "general-arrangement.svg", "FF-GA-001", "General Arrangement / Assembly",
     "Assembly"),  # handheld Excel tab title; plant falls back to register-only
    ("interconnect", "interconnect.svg", "FF-INT-001",
     "Interconnect — device wiring & signal paths", "Interconnect"),
    ("pid", "pid.svg", "FF-PID-001", "Piping & Instrumentation Diagram", "P&ID"),
    ("bfd", "block-flow-diagram.svg", "FF-BFD-001", "Block Flow Diagram",
     "BFD — Block Flow"),
    ("single-line", "single-line-diagram.svg", "FF-SLD-001",
     "Single-Line Electrical Diagram", "Electrical"),   # embedded on the merged Electrical tab
    ("hvac", "hvac-layout.svg", "FF-HVAC-001", "HVAC / Ventilation Layout", "HVAC"),
]

# Drawing cross-reference → A1 base, for appending the sheet range so a bare
# "FF-PID-001" resolves to the actual print set ("FF-PID-001 S1-S4").
_A1_BASE_BY_REF = {"PID": "pid", "BFD": "bfd", "SLD": "single-line",
                   "GA": "ga", "HVAC": "hvac", "INT": "interconnect"}
_DRG_REF_RX = re.compile(r"\b(FF-(PID|BFD|SLD|GA|HVAC|INT)-\d{3})\b(?!\s*S\d)")


def _a1_manifest(run_dir: str, base: str) -> Optional[dict]:
    """The <base>-A1.json print manifest a1_print.py writes next to the drawing SVG.
    None when no A1 set was produced (or the PDF export failed — honest miss)."""
    m = load_json(os.path.join(run_dir, "drawings", f"{base}-A1.json"))
    if isinstance(m, dict) and m.get("pdf_ok") and m.get("pdfs"):
        return m
    return None


def _a1_sheet_range(sheets) -> str:
    """'S1' for a single-sheet set, 'S1-S4' for a 4-sheet set. '' when unknown."""
    try:
        n = int(sheets)
    except (TypeError, ValueError):
        return ""
    return "S1" if n <= 1 else f"S1-S{n}"


def _annotate_drawing_refs(text: str, sheet_counts: Dict[str, int]) -> str:
    """Append the A1 sheet range to every drawing cross-reference in `text` so it
    resolves to the print set: 'FF-PID-001' → 'FF-PID-001 S1-S4'. Idempotent (an
    already-annotated ref never gains a second range); a ref whose drawing has no A1
    print set is left untouched. Pure — proveCatch in _selftest."""
    def _sub(m: "re.Match") -> str:
        rng = _a1_sheet_range(sheet_counts.get(m.group(2)))
        return f"{m.group(1)} {rng}" if rng else m.group(1)
    return _DRG_REF_RX.sub(_sub, text)


def _svg_titleblock(run_dir: str, svg_name: str) -> Dict[str, str]:
    """Parse DRAWING No. / REV / SCALE out of the DELIVERED drawing SVG's title block
    (the generators draw each row as a key <text> immediately followed by its value
    <text>). SIGHT principle: read the artefact, not what the code intended."""
    out: Dict[str, str] = {}
    try:
        with open(os.path.join(run_dir, "drawings", svg_name), encoding="utf-8") as fh:
            svg = fh.read()
    except OSError:
        return out
    from html import unescape as _unesc
    for key, label in (("no", r"DRAWING No\."), ("rev", "REV"), ("scale", "SCALE"),
                       ("date", "DATE")):
        m = re.search(r">" + label + r"</text>\s*<text[^>]*>([^<]+)</text>", svg)
        if m:
            out[key] = _unesc(m.group(1)).strip()
    return out


# Register base → drawing_gates.py scorecard key (G1-G9, scripts/blender-universal/
# drawing_gates.py::run_gates/scorecard — see drawing-gates.json 'drawings' keys).
_GATE_KEY_FOR_BASE = {"ga": "general-arrangement", "pid": "pid", "bfd": "block-flow-diagram",
                      "single-line": "single-line-diagram", "hvac": "hvac-layout",
                      "interconnect": "interconnect"}


def _drawing_gates_for(run_dir: str) -> dict:
    """The 'drawings' block of drawing-gates.json (per-drawing G1-G9 pass/failing_gates),
    {} when the file doesn't exist (a run that never ran the gate scorer — honest skip,
    never a fabricated pass)."""
    dg = load_json(os.path.join(run_dir, "drawing-gates.json"))
    return (dg or {}).get("drawings") or {} if isinstance(dg, dict) else {}


def _drawing_register_rows(run_dir: str) -> List[dict]:
    """One register row per drawing whose SVG master exists in <run>/drawings/: title-
    block fields (from the SVG), A1 print-set numbers (from <base>-A1.json), an on-disk
    existence check of every listed sheet PDF, and (9/10 campaign, 2026-07-04) the
    drawing's own G1-G9 deterministic-gate verdict (drawing-gates.json). Deterministic;
    universal."""
    gates = _drawing_gates_for(run_dir)
    rows: List[dict] = []
    for base, svg_name, no_default, title, tab in _DRAWING_REGISTER:
        if not os.path.exists(os.path.join(run_dir, "drawings", svg_name)):
            continue                    # a class that never drew this sheet — no row
        tb = _svg_titleblock(run_dir, svg_name)
        man = _a1_manifest(run_dir, base) or {}
        pdfs = [f"drawings/{p}" for p in (man.get("pdfs") or [])]
        gkey = _GATE_KEY_FOR_BASE.get(base)
        gentry = gates.get(gkey) if gkey else None
        # Normalise failing_gates to list[str] gate names — drawing_gates.py emits
        # list[dict] ({gate,severity,stage,detail}); legacy fixtures used list[str].
        _raw_fail = gentry.get("failing_gates") if isinstance(gentry, dict) else None
        _fail_names: Optional[List[str]] = None
        if isinstance(_raw_fail, list):
            _fail_names = []
            for _gf in _raw_fail:
                if isinstance(_gf, dict):
                    _fail_names.append(str(_gf.get("gate") or _gf.get("name") or "gate"))
                elif _gf:
                    _fail_names.append(str(_gf))
        rows.append({
            "base": base,
            "svg": svg_name,
            "no": tb.get("no") or no_default,
            "title": title,
            "rev": tb.get("rev") or "—",
            "date": tb.get("date") or "—",
            "scale": tb.get("scale") or "—",
            "sheets": man.get("sheets"),
            "min_text_mm": man.get("min_text_mm"),
            "meets_bar": man.get("meets_bar"),
            "files": pdfs,
            "missing": [p for p in pdfs
                        if not os.path.exists(os.path.join(run_dir, p))],
            "tab": tab,
            "gates_pass": gentry.get("pass") if isinstance(gentry, dict) else None,
            "gates_failing": _fail_names,
        })
    return rows


def _drawing_base_for_title(title: str) -> Optional[str]:
    """Map an embedded drawing TAB title to its A1 base ('P&ID' → 'pid'). None for a
    non-drawing tab (renders, modules, data tabs)."""
    low = (title or "").lower()
    if "p&id" in low or low == "pid":
        return "pid"
    if low.startswith("bfd") or "block flow" in low:
        return "bfd"
    if "single-line" in low or "single line" in low:
        return "single-line"
    if low.startswith("ga ") or low == "ga" or "general arrangement" in low:
        return "ga"
    if "hvac" in low:
        return "hvac"
    return None


# One-sentence reading guidance per drawing type — what to look at, drawn from the
# drawing's own structure, with the cross-tab whose rows carry the same tags.
_DRAWING_TAB_GUIDANCE = {
    "pid": "top band = the process train in flow order (follow the numbered lines left to "
           "right), lower band = utility / dosing tie-ins; line numbers match the Process "
           "schedules tab.",
    "bfd": "each block is one major process step — follow the stream arrows left to right; "
           "block names match the Quantities and BoM module groupings.",
    "single-line": "read top-down from the utility incomer through the main board to each "
                   "feeder; feeder tags and loads match the Panel schedule tab.",
    "ga": "plan view with elevations — equipment outlines carry the same tags as the Part "
          "names tab; dimensions in mm, datum ±0.000 = finished floor level.",
    "hvac": "duct runs overlay the GA footprint with supply vs extract airflow arrows; "
            "equipment tags match the Part names tab.",
}


def _drawing_tab_note(run_dir: str, title: str) -> Optional[str]:
    """The caption row for an embedded drawing tab: where the full-size A1 vector sheets
    live + one sentence of reading guidance. None for a non-drawing tab."""
    base = _drawing_base_for_title(title)
    if base is None:
        return None
    man = _a1_manifest(run_dir, base)
    if man:
        n = man.get("sheets") or len(man["pdfs"])
        sheets_txt = "sheet 1 of 1" if (isinstance(n, (int, float)) and n <= 1) else f"sheets 1-{int(n)}"
        lead = (f"Full-size vector sheets: drawings/{man['pdfs'][0]} ({sheets_txt}, ISO A1, "
                f"lettering ≥{man.get('min_text_bar_mm', 2.5):g} mm) — see the Drawings register tab.")
    else:
        lead = ("Full-size vector sheets: none for this drawing (PNG/SVG master only) — "
                "see the Drawings register tab.")
    return f"{lead} Reading guide: {_DRAWING_TAB_GUIDANCE[base]}"


def tab_drawings_register(wb: Workbook, run_dir: str,
                          embedded: Optional[List[Tuple[str, str]]] = None) -> bool:
    """The 'Drawings' register tab: section 1 = the engineering drawings (Drawing No. ·
    Title · Rev · Scale · Sheets · Min lettering · A1 PDF file(s) · preview link · an
    honest on-disk file check); section 2 = the photoreal renders from the manifest's
    renders[]. `embedded` maps source image paths → the actual workbook tab titles so
    the preview links always resolve. Returns False when there is nothing to register."""
    regs = _drawing_register_rows(run_dir)
    man = load_json(os.path.join(run_dir, "drawing-manifest.json")) or {}
    renders = [r for r in (man.get("renders") or []) if isinstance(r, dict) and r.get("file")]
    if not regs and not renders:
        return False
    embedded = embedded or []

    def _tab_for_path(path: str, by: str = "path") -> Optional[str]:
        """Embedded sheet for a source image. by='path' → exact normalised-path match
        (renders: exterior/00-hero.png shares its BASENAME with the interior 00-hero.png,
        so a stem match would link the exterior rows to the interior tabs); by='stem' →
        filename-stem match (drawings: the register knows 'pid.svg', the embed may be
        drawings/pid.png or an .excel-tmp SVG→PNG conversion)."""
        tgt = os.path.normpath(path).lower()
        want = os.path.splitext(os.path.basename(path))[0].lower()
        for sheet, src in embedded:
            if by == "path":
                if os.path.normpath(src).lower() == tgt:
                    return sheet
            elif os.path.splitext(os.path.basename(src))[0].lower() == want:
                return sheet
        return None

    ws = wb.create_sheet("Drawings")
    set_widths(ws, {"A": 13, "B": 30, "C": 5, "D": 11, "E": 8, "F": 7, "G": 13, "H": 36,
                    "I": 26, "J": 26, "K": 28})
    title_row(
        ws, "Drawing register", 14,
        "Every engineering drawing and render in this dossier. The File column names the "
        "print-ready ISO A1 vector PDF set in the run's drawings/ folder (841 × 594 mm, "
        "smallest lettering ≥ 2.5 mm on paper per ISO 3098; multi-sheet drawings carry "
        "match lines). The workbook tabs embed reduced PNG previews — print from the A1 "
        "PDFs, never from the previews. Gates is the drawing's own G1-G9 deterministic "
        "verdict (drawing_gates.py); the footer row formula-checks that every registered "
        "drawing shares ONE revision and ONE issue date.")
    back_link(ws, 14)
    header(ws, 4, ["Drawing No.", "Title", "Rev", "Date", "Scale", "Sheets",
                   "Min lettering", "File (A1 print set)", "Preview tab", "File check",
                   "Gates (G1-G9)", "Audit: PDFs found", "Audit: missing sheets",
                   "Audit: gates failing", "Audit: gates pass (1/0)"])
    for _c in (12, 13, 14, 15):
        ws.cell(4, _c).font = _FONT_AUDIT
    r = 5
    for rr in regs:
        ws.cell(r, 1, rr["no"]).border = BORDER
        tc = ws.cell(r, 2, rr["title"]); tc.alignment = WRAP_TOP; tc.border = BORDER
        ws.cell(r, 3, rr["rev"]).border = BORDER
        ws.cell(r, 4, rr.get("date") or "—").border = BORDER
        ws.cell(r, 5, rr["scale"]).border = BORDER
        sc = ws.cell(r, 6, rr["sheets"] if rr["sheets"] else "—")
        sc.alignment = Alignment(horizontal="center"); sc.border = BORDER
        mt = rr.get("min_text_mm")
        ws.cell(r, 7, f"{mt:g} mm" if isinstance(mt, (int, float)) else "—").border = BORDER
        fc = ws.cell(r, 8, "\n".join(rr["files"]) if rr["files"]
                     else "— no A1 print set (PNG/SVG embedded only)")
        fc.alignment = WRAP_TOP; fc.border = BORDER; fc.font = FONT_NOTE
        tab = (_tab_for_path(rr["svg"], by="stem")
               or (rr["tab"] if rr["tab"] in wb.sheetnames else None))
        pv = ws.cell(r, 9, tab or "—")
        pv.border = BORDER
        if tab:
            _set_internal_hyperlink(pv, tab)
            pv.font = FONT_LINK
        # honest on-disk check of every listed sheet PDF — the counts + missing list are
        # EMBEDDED (muted cols L/M, computed by os.path.exists at build) and the File
        # check is a live formula over them (never a bare literal, Tristan 2026-07-03)
        _fnd = ws.cell(r, 12, len(rr["files"]) if rr["files"] else 0)
        _fnd.font = _FONT_AUDIT
        _msc = ws.cell(r, 13, ", ".join(rr["missing"]) if rr["missing"] else None)
        _msc.font = _FONT_AUDIT
        _msc.alignment = WRAP_TOP
        if rr["missing"] or rr["files"]:
            ck = ws.cell(r, 10,
                         f'=IF(LEN(TRIM($M{r}&""))>0,"✗ MISSING on disk: "&$M{r},'
                         f'IF($L{r}>0,"✓ "&$L{r}&" sheet PDF(s) on disk",'
                         f'"✗ no sheet PDF found on disk"))')
            if rr["missing"]:
                ck.font = FONT_FAIL; ck.fill = FILL_FAIL
            else:
                ck.font = FONT_PASS; ck.fill = FILL_PASS
        else:
            ck = ws.cell(r, 10, "—")
        ck.alignment = WRAP_TOP; ck.border = BORDER
        # G1-G9 deterministic gate verdict (9/10 campaign, 2026-07-04) — EMBEDDED as a
        # muted sentinel (1 pass / 0 fail / blank = no scorecard for this drawing) so the
        # Gates column is a LIVE formula over it, never a bare literal. The sentinel MUST
        # live in its OWN column (O, 15) — not the display column (K, 11) the formula is
        # written into (Excel repair round 2, 2026-07-05): writing both the sentinel value
        # and the formula into the SAME cell K meant the sentinel was clobbered by the
        # formula before it could be read, leaving the formula referencing itself
        # ($K{r}=1 inside the formula IN K{r}) — a genuine circular reference on every
        # registered-drawing row (5 rows in the v10 dossier), the source of the workbook-
        # wide "one or more circular references" warning. See ooxml_strict_check.py ::
        # check_circular_references (proveCatch on the pre-fix self-reference pattern).
        _gp = rr.get("gates_pass")
        _gsent = ws.cell(r, 15, 1 if _gp is True else (0 if _gp is False else None))
        _gsent.font = _FONT_AUDIT
        # gates_failing is list[str] (normalised in _drawing_register_rows).
        _gfail = ws.cell(r, 14, ", ".join(rr.get("gates_failing") or []) or None)
        _gfail.font = _FONT_AUDIT; _gfail.alignment = WRAP_TOP
        gc = ws.cell(r, 11,
                     f'=IF(ISBLANK($O{r}),"— no gate scorecard for this drawing",'
                     f'IF($O{r}=1,"✓ G1-G9 all pass",'
                     f'"✗ FAIL: "&IF(LEN(TRIM($N{r}&""))>0,$N{r},"see drawing-gates.json")))')
        gc.alignment = WRAP_TOP; gc.border = BORDER
        if len(rr["files"]) > 1:
            ws.row_dimensions[r].height = 14.5 * len(rr["files"])
        r += 1
    _last_data_row = r - 1
    _register_check_range(ws.title, "J", 5, _last_data_row)
    _cf_verdict(ws, f"J5:J{_last_data_row}")
    _cf_verdict(ws, f"K5:K{_last_data_row}")
    n_gate_rows = sum(1 for rr in regs if rr.get("gates_pass") is not None)
    n_gate_pass = sum(1 for rr in regs if rr.get("gates_pass") is True)

    # REV/DATE CONSISTENCY — a live formula-check that every registered drawing shares
    # ONE revision and ONE issue date (a set with mixed revisions/dates is a real
    # engineering defect: it means the drawings were not issued together).
    n_regs = len(regs)
    _rev_date_row = None
    _rev_ok = _date_ok = True
    if n_regs:
        r += 1
        _rev_date_row = r
        rc = ws.cell(r, 1, clean_cell(
            f'="Set consistency: "&IF(SUMPRODUCT(--($C$5:$C${_last_data_row}=$C$5))='
            f'COUNTA($C$5:$C${_last_data_row}),"one REV ("&$C$5&") ","✗ MIXED REV ")&'
            f'"across "&{n_regs}&" drawing(s); "&'
            f'IF(SUMPRODUCT(--($D$5:$D${_last_data_row}=$D$5))='
            f'COUNTA($D$5:$D${_last_data_row}),"one DATE ("&$D$5&")","✗ MIXED DATE")'))
        rc.font = Font(bold=True, color="1F3A5F")
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=14)
        ws.row_dimensions[r].height = 22
        _revs = {rr["rev"] for rr in regs}
        _dates = {rr.get("date") for rr in regs}
        _rev_ok, _date_ok = len(_revs) <= 1, len(_dates) <= 1
        r += 1

    if renders:
        r += 1
        sub_banner(ws, r, f"Photoreal renders — {len(renders)} view(s) from the Blender "
                          f"scene build (drawing-manifest renders[])", 14)
        r += 1
        header(ws, r, ["#", "Render", "File", "Caption", "", "", "", "", "", "Preview tab",
                       ""])
        r += 1
        for i, rd in enumerate(renders, 1):
            ws.cell(r, 1, i).border = BORDER
            nm = ws.cell(r, 2, clean_cell(str(rd.get("sheet_name") or
                                              os.path.basename(str(rd["file"])))))
            nm.alignment = WRAP_TOP; nm.border = BORDER
            fl = ws.cell(r, 3, str(rd["file"])); fl.font = FONT_NOTE; fl.border = BORDER
            ws.merge_cells(start_row=r, start_column=4, end_row=r, end_column=9)
            cp = ws.cell(r, 4, clean_cell(str(rd.get("caption") or "—")))
            cp.alignment = WRAP_TOP; cp.font = FONT_NOTE
            tab = _tab_for_path(os.path.join(run_dir, str(rd["file"])))
            pv = ws.cell(r, 10, tab or "—")
            pv.border = BORDER
            if tab:
                _set_internal_hyperlink(pv, tab)
                pv.font = FONT_LINK
            if len(str(rd.get("caption") or "")) > 100:
                ws.row_dimensions[r].height = 29
            r += 1

    ws.freeze_panes = "A5"
    ws._forge_gate_stats = {"n_gate_rows": n_gate_rows, "n_gate_pass": n_gate_pass,
                            "n_regs": n_regs, "rev_ok": _rev_ok, "date_ok": _date_ok}
    return True


