def _render_cabinet_section(ws: Worksheet, run_dir: str, start_row: int) -> Optional[int]:
    """Render the Cabinet schedule TABLE onto `ws` starting at `start_row`. Returns the
    next free row, or None when there is no `cabinets` block to show. (Was
    tab_cabinet_schedule; refactored into a section appended to "Connection trace",
    2026-06-24 — both read the same parts-ledger connectivity verdict, so they cannot
    disagree.) The cabinet rows prove every small electrical / control device is HOUSED
    and that the cabinet + its contents show their IN/OUT connectors, all connected."""
    pl = load_json(os.path.join(run_dir, "parts-ledger.json"))
    cab = (pl.get("cabinets") if isinstance(pl, dict) else None) or {}
    cabinets = cab.get("cabinets") or []
    if not cabinets:
        return None

    proven = cab.get("all_cabinets_proven")
    sub_banner(ws, start_row,
               f"{cab.get('n_cabinets', len(cabinets))} cabinet(s)   ·   "
               f"{cab.get('n_housed', 0)} housed device(s)   ·   "
               f"{cab.get('n_cabinets_all_connected', 0)}/{cab.get('n_cabinets', len(cabinets))} "
               f"cabinets fully connected   ·   "
               f"ALL CONNECTORS PROVEN: {'YES ✓' if proven else 'NO — see ✗ rows'}", 6)
    r = start_row + 1

    def _join(items):
        out = []
        for it in (items or []):
            s = str(it)
            # ledger strings look like 'Main Breaker (X-123) via cable [electrical_bus]'
            out.append(s)
        return "\n".join(out) if out else "—"

    for c in cabinets:
        # ── cabinet header band ──
        dom = (c.get("domain") or "").upper()
        verdict = "✓ ALL CONNECTED" if c.get("all_connected") else "✗ INCOMPLETE"
        hdr_txt = (f"{clean_cell(c.get('name'))}  [{dom} CABINET · {clean_cell(c.get('tag'))}]   "
                   f"— {c.get('n_contents', 0)} device(s) housed   ·   "
                   f"cabinet feeds: {c.get('n_in', 0)} in / {c.get('n_out', 0)} out   ·   {verdict}")
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=6)
        hc = ws.cell(r, 1, clean_cell(hdr_txt))
        hc.font = Font(bold=True, color="FFFFFF")
        hc.fill = PatternFill("solid", fgColor="107C10" if c.get("all_connected") else "C00000")
        hc.alignment = LEFT_TOP
        r += 1
        header(ws, r, ["Housed device", "Tag", "Function", "Inputs ← (from)",
                       "Outputs → (to)", "Connectors"])
        # muted embedded-operand columns: the parts-ledger connection counts this
        # device's live Connectors verdict is computed from (Tristan 2026-07-03)
        ws.cell(r, 7, "Audit: n in").font = _FONT_AUDIT
        ws.cell(r, 8, "Audit: n out").font = _FONT_AUDIT
        _hd_first = r + 1
        r += 1
        contents = c.get("contents") or []
        if not contents:
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=6)
            ws.cell(r, 1, "— no discrete devices itemised (cabinet feeds the loads directly) —").font = FONT_NOTE
            r += 1
        for d in contents:
            ws.cell(r, 1, clean_cell(d.get("name"))).border = BORDER
            ws.cell(r, 2, clean_cell(d.get("tag"))).border = BORDER
            ws.cell(r, 3, clean_cell(d.get("function"))).border = BORDER
            ci = ws.cell(r, 4, _join(d.get("inputs"))); ci.alignment = WRAP_TOP; ci.border = BORDER
            co = ws.cell(r, 5, _join(d.get("outputs"))); co.alignment = WRAP_TOP; co.border = BORDER
            ok = d.get("connected")
            _n_in, _n_out = int(d.get("n_in", 0) or 0), int(d.get("n_out", 0) or 0)
            ws.cell(r, 7, _n_in).font = _FONT_AUDIT
            ws.cell(r, 8, _n_out).font = _FONT_AUDIT
            # live formula over the embedded counts (the parts-ledger connectivity
            # verdict): connected = at least one wired end
            sc = ws.cell(r, 6,
                         f'=IF($G{r}+$H{r}>0,"✓ "&$G{r}&" in / "&$H{r}&" out",'
                         f'"✗ unconnected ("&$G{r}&" in / "&$H{r}&" out)")')
            sc.border = BORDER
            sc.font = Font(color="107C10", bold=True) if ok else Font(color="C00000", bold=True)
            r += 1
        if r > _hd_first:
            _register_check_range(ws.title, "F", _hd_first, r - 1)
        r += 1  # spacer between cabinets
    return r


def _render_tool_io_section(ws: Worksheet, state: dict, run_dir: str, start_row: int,
                            value_cells_out: Optional[list] = None) -> Optional[int]:
    """Render the Tool-provenance table onto `ws` starting at `start_row` (header row).
    Returns the next free row, or None when no tools ran. (Was tab_tool_io; refactored
    into a section folded under "⚠ Checks", 2026-06-24.) Every engineering tool that ran,
    with where each output's INPUT came from and where its OUTPUT goes, plus a
    USED/STALE/ORPHANED/TRACED verdict — the 'computed by verified tools' proof.

    When `value_cells_out` is a list, each rendered Value cell is recorded as
    (tool_id_norm, value, cell_coordinate) so the CALLER can LINK that Value cell to the
    worked-calc result cell that produced it (traceability; Tristan: "C16 isn't connected
    to B60"). Other callers (the ⚠ Checks tab) pass nothing — behaviour unchanged."""
    import re as _re
    tu = load_json(os.path.join(run_dir, "4-orchestrator-tools-used.json"))
    if not isinstance(tu, dict) or not tu.get("tools"):
        return None
    q = (state.get("orchestratorContract") or {}).get("quantities") or {}
    qval = {k.lower(): num(v.get("value") if isinstance(v, dict) else v) for k, v in q.items()}
    consumed = {v for v in qval.values() if v is not None}
    for r in (state.get("requirementsBom") or []):
        for f in ("unit_gbp", "line_gbp", "qty"):
            n = num(r.get(f))
            if n is not None:
                consumed.add(round(n, 3))
    for v in (state.get("costStack") or {}).values():
        n = num(v)
        if n is not None:
            consumed.add(round(n, 3))

    def _present(x: float) -> bool:
        for cand in (x, x * 1000.0, x / 1000.0):
            for c in consumed:
                if abs(cand - c) <= max(abs(c) * 0.02, 0.01):
                    return True
        return False

    # RIGOROUS field-level consumption proof (Tristan 2026-06-24: prove the output GOES somewhere,
    # not just that its value coincidentally appears): the set of every token any tool declares as an
    # INPUT. An output field is genuinely CONSUMED if its name (or a distinctive token of it) is some
    # other tool's input — a real edge in the tool DAG, universal across archetypes.
    _input_tokens: set = set()
    for _t in tu["tools"]:
        for _c in (_t.get("claims") or []):
            for _tok in _re.findall(r"[a-z][a-z0-9_]{3,}", str(_c.get("input_summary", "")).lower()):
                _input_tokens.add(_tok)
    _STOP = {"from", "each", "total", "rated", "with", "into", "flow", "load", "duty", "this", "that"}
    def _consumed_by_tool(field: str) -> bool:
        f = str(field).lower().strip()
        if not f:
            return False
        if f in _input_tokens:
            return True
        toks = [t for t in _re.findall(r"[a-z][a-z0-9]{3,}", f) if t not in _STOP]
        return bool(toks) and any(t in _input_tokens for t in toks)

    header(ws, start_row, ["Tool", "Output field", "Value", "Unit", "Input — from",
                           "→ Consumed by", "Status"])
    r = start_row + 1
    body_first = r
    for t in tu["tools"]:
        tid = str(t.get("tool_id", "?"))
        for c in (t.get("claims") or []):
            field = str(c.get("field", ""))
            val = num(c.get("value"))
            of = str(c.get("output_field", "")).lower()
            f = _re.sub(r"^calc_", "", field).lower()
            qk = of if of in qval else (f if f in qval else None)
            if qk is not None and val is not None and qval[qk] is not None:
                qv = qval[qk]
                if abs(val - qv) <= max(abs(qv) * 0.02, 0.01):
                    status, cons = "USED", f"{qk} = {qv:g}"
                else:
                    status, cons = "STALE", f"{qk} = {qv:g}  (≠ tool {val:g})"
            elif _consumed_by_tool(c.get("output_field") or field):
                status, cons = "USED", "feeds another tool's input (DAG edge)"
            elif val is not None and abs(val) in (0.0, 1.0):
                status, cons = "—", "(zero/unit — not checked)"
            elif val is not None and _present(val):
                status, cons = "TRACED", "value used in the design"
            else:
                status, cons = "ORPHANED", "appears nowhere downstream"
            ws.cell(r, 1, tid).border = BORDER
            ws.cell(r, 2, clean_cell(c.get("output_field") or field)).border = BORDER
            _vcell = ws.cell(r, 3, val)
            _vcell.border = BORDER
            if value_cells_out is not None and val is not None:
                value_cells_out.append((tid.strip().lower(), val, _vcell.coordinate))
            ws.cell(r, 4, clean_cell(c.get("unit", ""))).border = BORDER
            e = ws.cell(r, 5, clean_cell(c.get("input_summary", "")))
            e.alignment = WRAP_TOP
            e.font = FONT_NOTE
            e.border = BORDER
            ws.cell(r, 6, clean_cell(cons)).border = BORDER
            sc = ws.cell(r, 7, status)
            sc.border = BORDER
            if status in ("USED", "TRACED"):
                sc.fill, sc.font = FILL_PASS, FONT_PASS
            elif status in ("STALE", "ORPHANED"):
                sc.fill, sc.font = FILL_FAIL, FONT_FAIL
            else:
                sc.fill, sc.font = FILL_ADVISORY, FONT_ADVISORY
            r += 1
    apply_col_formats(ws, body_first, {3: FMT_NUM}, r - 1)
    return r


# The MERGED TAB STRIP (Bundle B fix 7, two-reviewer audit 2026-07-02): Exec → Contents →
# Renders → Cost waterfall → Financial model → BoM → Brief → Drawings register → the
# drawings (BFD → P&ID → Process schedules → GA → HVAC → Electrical → Line & velocity) →
# Assembly → Risk → Holds → Quality & Audit → ⚠ Checks → Connection trace →
# Calculations → Inputs → Part names → Glossary. Overview (kept — run provenance) sits
# between Contents and Renders; Sense-check (when present) joins the verification block.
# Quantities / Inputs Master (M0) folded 2026-07-14.
_TAB_RANK = {
    "Executive Summary": -1, "Contents": 0,
    # M0 auditability directive (Tristan, drawer 047565b65ce05148, 2026-07-04): the
    # INPUTS MASTER is "the first sheet after Contents" — literally ranked immediately
    # after it; the Equipment & Dimensions Register is its natural companion.
    "Equipment & Dimensions Register": 0.2,
    "Overview": 0.5, "Renders": 1,
    "Cost waterfall": 2, "Financial model": 3, "Bill of Materials (Ledger)": 4,
    "Brief": 5,
    "Verification": 5.2,                                # governing proof spine (after Brief)
    "Design basis": 5.5,                                # the basis statement follows the Brief
    "Engineering Analysis": 5.6,          # allowables/stress-strain follows the basis statement
    "Drawings": 6,                                      # the drawing REGISTER opens the drawings block
    # drawings: Assembly/Interconnect (handheld) · Electrical · PCB — plant P&ID/BFD/HVAC
    # are register-only (2026-07-14). Prefix ranks in _tab_rank cover legacy names.
    "Assembly": 9.5, "Interconnect": 9.7,
    "Process schedules": 9, "Electrical": 12, "PCB": 12.2, "Line & velocity": 13,
    "Assembly sequence": 14, "Risk & Regulatory": 15, "Holds & exclusions": 16,
    "Questions for the customer": 16.5,
    "Quality & Audit": 17, "Sense-check": 17.5, "⚠ Checks": 18,
    "Connection trace": 19, "Calculations": 21,
    "Inputs & Assumptions": 0.1,  # M0 primitives live HERE (merged 2026-07-14)
    "Part names": 23, "Glossary": 24,
}

# Tab-strip COLOUR GROUPS (Bundle B fix 7): commercial / drawings / verification /
# reference — one colour per group so the strip reads as four blocks.
_TAB_GROUP_COLOUR = {
    "commercial": "2F5597",    # blue — the story + money tabs
    "drawings": "548235",      # green — register + every drawing surface
    "verification": "C55A11",  # orange — risk / holds / quality / checks
    "reference": "7F7F7F",     # grey — the plumbing a reader dips into
}
_TAB_GROUPS = {
    "commercial": {"Executive Summary", "Contents", "Overview", "Renders", "Cost waterfall",
                   "Financial model", "Bill of Materials (Ledger)", "Brief", "Design basis",
                   "Engineering Analysis"},
    "drawings": {"Drawings", "Assembly", "Interconnect", "Process schedules", "Electrical",
                 "PCB", "Line & velocity", "Assembly sequence"},
    "verification": {"Verification", "Risk & Regulatory", "Holds & exclusions", "Quality & Audit",
                     "Questions for the customer", "Sense-check", "⚠ Checks"},
    "reference": {"Connection trace", "Calculations", "Inputs & Assumptions",
                  "Part names", "Glossary", "Equipment & Dimensions Register"},
}


def _tab_rank(title: str) -> float:
    """The merged-sequence rank for a sheet title. Drawing prefixes rank into the drawings
    block (BFD 7 → P&ID 8 → [Process schedules 9] → GA 10 → HVAC 11); unknown tabs land at
    the end of the drawings block so nothing ever disappears off the strip."""
    if title in _TAB_RANK:
        return _TAB_RANK[title]
    t = title.lower()
    for rank, prefixes in ((7, ("bfd", "block flow")), (8, ("p&id", "pid")),
                           (9.5, ("assembly",)), (9.7, ("interconnect",)),
                           (10, ("ga", "general arrangement")), (11, ("hvac",))):
        if any(t.startswith(p) for p in prefixes):
            return rank
    if t.startswith("render"):
        return 1.5                                     # stray per-render tab → beside the gallery
    if t.startswith("isometric") or t.startswith("module") or t.startswith("single"):
        return 12.5                                    # legacy drawing surfaces → drawings block
    return 14.5                                        # unknown data tab: end of the drawings block


def _tab_group(title: str) -> str:
    """Which colour group a sheet belongs to — explicit membership first, then by its rank
    position in the merged sequence (so unknown / prefix tabs colour with their block)."""
    for g, names in _TAB_GROUPS.items():
        if title in names:
            return g
    rk = _tab_rank(title)
    if rk <= 5:
        return "commercial"
    if rk <= 14.5:
        return "drawings"
    if rk <= 18:
        return "verification"
    return "reference"


def _reorder_tabs(wb: Workbook) -> None:
    """Reorder sheets into the MERGED reader sequence (Bundle B fix 7) and colour the tab
    strip by group (commercial / drawings / verification / reference). PURE presentation —
    Excel formula references are by sheet NAME, so tab order never breaks a formula.
    Universal — keys on tab name/prefix, no archetype logic."""
    orig = {id(ws): i for i, ws in enumerate(wb._sheets)}
    wb._sheets.sort(key=lambda ws: (_tab_rank(ws.title), orig[id(ws)]))
    for ws in wb._sheets:
        try:
            ws.sheet_properties.tabColor = _TAB_GROUP_COLOUR[_tab_group(ws.title)]
        except Exception:  # noqa: BLE001 — a colour must never kill the build
            pass


def tab_benchmark(wb: Workbook, state: dict) -> None:
    """The INDEPENDENT SENSE-CHECK (Tristan 2026-06-25: a generative LLM gives a top-down expected
    BoM/process/cost; the deterministic engine is diffed against it; each line out by more than the
    band is flagged). The benchmark net (gate 36) already computes this every run — it was just
    never shown. Renders state.benchmarkExpectation (LLM top-down) vs the engine, the per-dimension
    divergence, and the per-line faults the LLM caught in the deterministic bill."""
    be = state.get("benchmarkExpectation") or {}
    bd = state.get("benchmarkDivergence") or {}
    bf = state.get("benchmarkFaults") or []
    if not be and not bd and not bf:
        return
    ws = wb.create_sheet("Sense-check")
    set_widths(ws, {"A": 30, "B": 30, "C": 26, "D": 18, "E": 60})
    title_row(ws, "Independent sense-check — generative LLM expectation vs the deterministic engine", 5,
              "An LLM independently estimates, TOP-DOWN from the market, what a plant like this should "
              "cost, output and be built from. The deterministic engine builds BOTTOM-UP from parts. The "
              "two methods are diffed: a large gap means one is wrong. This is the engine's own sanity "
              "check — shown here so you can see it, not just trust it.")
    r = 4
    worst = str(bd.get("worst", "?")).upper()
    wfill = FILL_FAIL if worst in ("RADICAL", "FAIL") else (FILL_ADVISORY if worst in ("WARN", "REVIEW") else FILL_PASS)
    # LABELLED as this tab's OWN benchmark verdict — never confusable with the dossier's
    # ONE verdict (fix 2, 2026-07-02).
    vc = ws.cell(r, 1, f"SENSE-CHECK VERDICT: {worst}")
    vc.font = FONT_TITLE
    vc.fill = wfill
    ws.cell(r, 2).fill = wfill
    ws.cell(r, 5, clean_cell(bd.get("summary") or "")).font = FONT_NOTE
    r += 2

    # ---- cost: LLM envelope vs engine ----
    ec = be.get("expected_cost") or {}
    if ec:
        sub_banner(ws, r, "All-in cost — LLM top-down envelope vs the engine", 5)
        r += 1
        header(ws, r, ["", "LLM expected (top-down)", "Engine (bottom-up)", "Ratio", "Basis"])
        r += 1
        eng = (num((state.get("costStack") or {}).get("oem_transfer_price_gbp"))
               or num((state.get("costStack") or {}).get("installed_asp_gbp")) or 0)
        exp = num(ec.get("expected_gbp")) or 0
        ratio = (eng / exp) if exp else None
        ws.cell(r, 1, "All-in cost").font = FONT_SUB
        ws.cell(r, 2, f"£{round(num(ec.get('low_gbp')) or 0):,}–£{round(num(ec.get('high_gbp')) or 0):,} (mid £{round(exp):,})")
        ws.cell(r, 3, f"£{round(eng):,}")
        rc = ws.cell(r, 4, f"{ratio:.1f}×" if ratio else "—")
        rc.fill = FILL_FAIL if (ratio and (ratio > 1.5 or ratio < 0.67)) else FILL_PASS
        e = ws.cell(r, 5, clean_cell(ec.get("basis") or ""))
        e.alignment = WRAP_TOP
        e.font = FONT_NOTE
        r += 2

    # ---- per-dimension divergence (expected vs deterministic) ----
    findings = bd.get("findings") or []
    if findings:
        sub_banner(ws, r, f"Per-dimension divergence — {len(findings)} checked (cost · output · sizing · components)", 5)
        r += 1
        header(ws, r, ["Dimension", "LLM expected", "Engine (deterministic)", "Ratio", "Verdict"])
        r += 1
        for f in findings:
            if not isinstance(f, dict):
                continue
            _dim2 = clean_cell(f.get("dimension", "")) or "dimension"
            ws.cell(r, 1, _dim2).font = FONT_SUB
            ws.cell(r, 2, clean_cell(str(f.get("expected", "")))).alignment = WRAP_TOP
            ws.cell(r, 3, clean_cell(str(f.get("deterministic", "")))).alignment = WRAP_TOP
            rr = f.get("ratio")
            ws.cell(r, 4, f"{num(rr):.1f}×" if num(rr) else "—")
            verd = str(f.get("verdict", ""))
            # LIVE formula (Tristan 2026-07-03, the OK-literal fix — this cell used to
            # paint the bare LLM verdict word, e.g. "ok"). Embedded as its own audit
            # operand (a fresh row per tab — the Quality & Audit BENCHMARK NET table
            # embeds the same source data independently; both are honest, neither repeats
            # a literal) and read back in-formula.
            _sv_op = audit_operand(
                "Sense-check", f"{_dim2} — LLM verdict", verd,
                "benchmarkDivergence.findings[].verdict (scripts/lib/benchmark-expectation.ts)")
            vcell = ws.cell(r, 5, f"={_sv_op}")
            vcell.fill = FILL_FAIL if verd in ("radical", "fail") else (FILL_ADVISORY if verd in ("warn", "review") else FILL_PASS)
            r += 1
        r += 1

    # ---- per-LINE faults: the sense-check flags (the LLM caught these in the bill) ----
    if bf:
        sub_banner(ws, r, f"Per-line-item faults — {len(bf)} lines the LLM flags as wrong in the engine's bill", 5)
        r += 1
        header(ws, r, ["Bill line", "What's wrong", "Magnitude", "LLM-suggested", "Likely cause"])
        r += 1
        for f in bf:
            if not isinstance(f, dict):
                continue
            ws.cell(r, 1, clean_cell(f.get("line", ""))).font = FONT_SUB
            iss = ws.cell(r, 2, clean_cell(f.get("issue", "")))
            iss.alignment = WRAP_TOP
            mc = ws.cell(r, 3, clean_cell(f.get("magnitude", "")))
            mc.fill = FILL_FAIL
            ws.cell(r, 4, clean_cell(f.get("suggested", "")))
            lc = ws.cell(r, 5, clean_cell(f.get("likely_cause", "")))
            lc.alignment = WRAP_TOP
            lc.font = FONT_NOTE
            r += 1
        r += 1

    # ---- LLM-expected bill structure (top-down % of cost) ----
    ebom = be.get("expected_bom") or []
    if ebom:
        sub_banner(ws, r, "LLM-expected bill structure (top-down — what the cost SHOULD break into)", 5)
        r += 1
        header(ws, r, ["Expected line / category", "% of cost", "Note", "", ""])
        r += 1
        for b in ebom:
            if not isinstance(b, dict):
                continue
            ws.cell(r, 1, clean_cell(b.get("item", ""))).font = FONT_SUB
            ws.cell(r, 2, f"{num(b.get('typical_pct_of_cost')) or 0:g}%")
            nt = ws.cell(r, 3, clean_cell(b.get("note", "")))
            nt.alignment = WRAP_TOP
            nt.font = FONT_NOTE
            r += 1
        r += 1
    reasoning = be.get("reasoning")
    if reasoning:
        sub_banner(ws, r, "LLM reasoning (how the top-down expectation was formed)", 5)
        r += 1
        rc2 = ws.cell(r, 1, clean_cell(reasoning))
        rc2.alignment = WRAP_TOP
        rc2.font = FONT_NOTE
        try:
            ws.merge_cells(start_row=r, start_column=1, end_row=r + 4, end_column=5)
        except Exception:  # noqa: BLE001
            pass


def tab_quality_audit(wb: Workbook, state: dict, run_dir: str, report) -> None:
    """ONE 'Quality & Audit' tab (Bundle B fix 2) — the former ⭐ Scorecard + ⚠ Audit tabs
    merged: the ONE verdict (rendered exactly once, at the top), the ≥8-every-section
    table (DETERMINISTIC sections score; the LLM self-audit renders as an ADVISORY
    annotation on the same rows — B3-floor fix 2026-07-03, it never floors), the engine
    quality metrics, the per-tab deterministic scorecard, and the ship-gate audit
    findings + benchmark net. ⚠ Checks stays its own tab (the live-invariant surface)."""
    sa = state.get("selfAudit") or {}
    facts, advisory = _verdict_sections(state, run_dir)
    ws = wb.create_sheet("Quality & Audit")
    set_widths(ws, {"A": 28, "B": 30, "C": 60, "D": 82, "E": 24,
                    "F": 8, "G": 6, "H": 6, "I": 6, "J": 6, "K": 6, "L": 6,
                    "M": 6, "N": 6, "O": 6, "P": 6})
    _sec_first, _sec_last = 0, -1     # deterministic-section score rows (floor range)
    title_row(ws, "Quality & Audit — every section and tab against the ≥8 floor + the ship gate", 5,
              "The engine's own quality surface, on one tab: the dossier verdict (stated ONCE, "
              "here), every DETERMINISTIC section and every tab scored against the ≥8 floor "
              "(the LLM self-audit's opinions render as advisory annotations — visible, never "
              "scoring; B3), and the deterministic ship-gate audit findings. The AIM is ≥8 "
              "EVERYWHERE — the floor, not the average. See ⚠ Checks for the live arithmetic "
              "invariants.")
    r = 4
    # ---- THE ONE VERDICT — this tab's single verdict surface (fix 2, 2026-07-02);
    # identical on the Exec / Overview surfaces via _register_verdict_cell. ----
    _ver = ws.cell(r, 1, verdict_text("line"))
    _ver.font = FONT_PASS if _VERDICT.get("ships") else FONT_FAIL
    _ver.fill = FILL_PASS if _VERDICT.get("ships") else FILL_FAIL
    _ver.alignment = LEFT_TOP
    ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=5)
    _register_verdict_cell(ws, r, 1, style="line")
    r += 2
    # ---- SHIP GATE — THE FIVE AXES (S7, 2026-07-20): SHIPS is not one collapsed word —
    # it is EVERY applicable axis passing (tab floor / self-audit / ex-works vs ceiling /
    # PCB readiness / render vision), each read from its OWN state field. Render them so
    # the reader sees WHICH axis fails, never a single green 'SHIPS' hiding a broken axis. ----
    try:
        _QA_SHIP_AXIS_CELLS.clear()
        _axes = compute_ship_axes(state, run_dir, _VERDICT)
        _all = ship_axes_all_pass(_axes)
        _hc = ws.cell(r, 1, f"SHIP GATE — {'every applicable axis MET' if _all else 'an axis is UNMET'} "
                            f"(SHIPS requires ALL applicable axes)")
        _hc.font = FONT_PASS if _all else FONT_FAIL
        _hc.fill = FILL_PASS if _all else FILL_FAIL
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=5)
        r += 1
        # numeric operand col (B) drives the LIVE verdict formula (col C) — no bare
        # PASS/FAIL literal (the _enforce_live_check_gate contract). B: 1=met, 0=unmet,
        # blank=not-applicable (out of scope).
        header(ws, r, ["Ship-gate axis", "Met (1/0, blank=n/a)", "Verdict", "Detail", ""])
        r += 1
        for _ax in _axes:
            ws.cell(r, 1, _ax["axis"]).font = FONT_SUB
            _apx = bool(_ax.get("applicable"))
            _psx = bool(_ax.get("passed"))
            _op = ws.cell(r, 2, (1 if _psx else 0) if _apx else None)
            _op.font = FONT_NOTE
            # capture APPLICABLE axes' Met cells so the ONE-VERDICT formula AND-gates on them
            # (S7: SHIPS requires every applicable axis met, not open_issues=0 alone).
            if _apx:
                _QA_SHIP_AXIS_CELLS.append(f"'{ws.title}'!$B${r}")
            _vc = ws.cell(r, 3, f'=IF($B{r}="","— (n/a — not in scope)",'
                                f'IF($B{r}>=1,"PASS ✓","⛔ FAIL"))')
            _vc.font = FONT_PASS if (_psx or not _apx) else FONT_FAIL
            if _apx:
                _vc.fill = FILL_PASS if _psx else FILL_FAIL
            dc = ws.cell(r, 4, str(_ax.get("detail") or ""))
            dc.font = FONT_NOTE
            dc.alignment = WRAP_TOP
            r += 1
        r += 1
    except Exception as _ax_exc:  # noqa: BLE001 — the card is additive; never kill the tab
        print(f"  ! ship-gate axes card skipped (non-fatal): {_ax_exc}")
    # ---- SECTION TABLE (B3-floor fix 2026-07-03): the scored rows are the DETERMINISTIC
    # (FACT) scorecard sections — the corroboration-computed numbers the verdict floor
    # actually ranges over. The LLM self-audit's numbers annotate the same rows as
    # 'self-audit opinion: N — advisory, uncorroborated' and NEVER enter the floor;
    # a self-audit section with no deterministic counterpart renders as an
    # advisory-only row (amber, non-gating — its deliverable is scored on the per-tab
    # table below). ----
    mn = sa.get("min_score")
    _det_scores = [d.get("score") for d in facts.values()
                   if isinstance(d.get("score"), (int, float))]
    det_min = min(_det_scores) if _det_scores else None
    n_ok = sum(1 for v in _det_scores if v >= 8)
    if facts or advisory:
        min_fill = (FILL_PASS if (isinstance(det_min, (int, float)) and det_min >= 8)
                    else FILL_FAIL) if _det_scores else FILL_ADVISORY
        mc = ws.cell(r, 1, f"MIN deterministic section score  "
                           f"{det_min if det_min is not None else '—'}/10")
        mc.font = FONT_TITLE
        mc.fill = min_fill
        ws.cell(r, 2).fill = min_fill
        ws.cell(r, 3, f"{n_ok}/{len(_det_scores)} deterministic sections ≥8").font = FONT_SUB
        ws.cell(r, 4, f"LLM self-audit min {mn if mn is not None else '—'}/10 — ADVISORY, "
                      f"uncorroborated; annotates, never floors (B3)   ·   "
                      f"AIM: every section ≥8").font = FONT_NOTE
        r += 2
        header(ws, r, ["Section", "Score (deterministic)", "vs ≥8 floor",
                       "Self-audit opinion (advisory — never floors)",
                       "Top defect (why it's below 8)"])
        r += 1

    def _opinion_text(nm: str) -> str:
        adv = advisory.get(nm)
        if not adv:
            return "—"
        osc = adv.get("score")
        return (f"self-audit opinion: {osc:g} — advisory, uncorroborated"
                if isinstance(osc, (int, float)) else "self-audit opinion: — (unscored)")

    _sec_first = r
    for nm, d in facts.items():
        score = d.get("score")
        ok = isinstance(score, (int, float)) and score >= 8
        ws.cell(r, 1, _display_name(clean_cell(nm))).font = FONT_SUB
        scell = ws.cell(r, 2, score if score is not None else "—")
        scell.fill = FILL_PASS if ok else FILL_FAIL
        # vs ≥8 floor — LIVE formula over the on-row score operand (never a literal)
        vcell = ws.cell(r, 3, f'=IF(ISNUMBER($B{r}),IF($B{r}>=8,"PASS ✓","⛔ below 8"),'
                              f'"⛔ UNVERIFIED (no deterministic score)")')
        vcell.font = FONT_PASS if ok else FONT_FAIL
        ocell = ws.cell(r, 4, _opinion_text(nm))
        ocell.font = FONT_ADVISORY if nm in advisory else FONT_NOTE
        ocell.alignment = WRAP_TOP
        defect = d.get("defects") or [""]
        dcell = _write_defect_cell(ws, r, 5, defect[0] if defect else "")
        dcell.alignment = WRAP_TOP
        dcell.font = FONT_NOTE
        r += 1
    _sec_last = r - 1          # DETERMINISTIC (fact) section rows — the floor ranges here
    if _sec_last >= _sec_first:
        _register_check_range(ws.title, "C", _sec_first, _sec_last)
    for nm, adv in advisory.items():
        if nm in facts:
            continue     # already annotated on its deterministic row
        ws.cell(r, 1, _display_name(clean_cell(nm)) + "  (advisory)").font = FONT_SUB
        scell = ws.cell(r, 2, "— (no deterministic section — the deliverable is scored "
                              "on the per-tab table below)")
        scell.font = FONT_NOTE
        scell.alignment = WRAP_TOP
        # live: an advisory row is ADVISORY exactly while its score cell carries the
        # 'no deterministic section' note (non-numeric) — a formula, never a literal
        vcell = ws.cell(r, 3, f'=IF(ISNUMBER($B{r}),IF($B{r}>=8,"PASS ✓","⛔ below 8"),'
                              f'"ADVISORY — non-gating")')
        vcell.fill = FILL_ADVISORY
        vcell.font = FONT_ADVISORY
        ocell = ws.cell(r, 4, _opinion_text(nm))
        ocell.font = FONT_ADVISORY
        ocell.alignment = WRAP_TOP
        defect = adv.get("defects") or [""]
        dcell = _write_defect_cell(ws, r, 5, defect[0] if defect else "")
        dcell.alignment = WRAP_TOP
        dcell.font = FONT_NOTE
        r += 1

    # ---- engine quality metrics (#92): the dossier carries its own confidence rating ----
    r += 1
    sub_banner(ws, r, "Engine quality metrics — the dossier's own confidence rating", 4)
    r += 1
    try:
        from provenance import audit_provenance
        _trace = round((audit_provenance(state).scorecard().get("traceable_fraction") or 0) * 100)
    except Exception:  # noqa: BLE001
        _trace = None
    # calc-coverage: % of DERIVED numbers whose formula is shown (mirrors check_calc_coverage)
    _q = ((state.get("orchestratorContract") or {}).get("quantities") or {})
    _roots = {"brief", "physics_constant", "constant", "standard", "anchor", "datasheet", "spec"}
    _wc = (state.get("worked_calculations")
           or ((state.get("orchestratorContract") or {}).get("worked_calculations")) or {})
    _worked = set()
    if isinstance(_wc, dict):
        for _cs in _wc.values():
            for _c in (_cs or []):
                if isinstance(_c, dict):
                    _f = _c.get("output_field") or _c.get("field") or _c.get("label")
                    if _f:
                        _worked.add(str(_f).lower())
    # CITED-MEASURED taxonomy (2026-07-05, mirrors dossier_audit.check_calc_coverage): a
    # quantity measured from as-routed geometry (route-manifest segment lengths) has no
    # arithmetic formula — a citation naming the route-manifest + segment count is the honest
    # disclosure, never a fake operator tacked onto the prose.
    _cited_measured_re = re.compile(r"measured from routed geometry \(route-manifest, \d+ segments?\)")
    _shown = _tot = 0
    for _k, _v in _q.items():
        if not isinstance(_v, dict) or str(_v.get("source", "")).lower() in _roots:
            continue
        _tot += 1
        _sd = str(_v.get("source_detail") or _v.get("condition") or "")
        _src = str(_v.get("source", "")).strip().lower()
        _is_cited_measurement = _src == "route-manifest" and bool(_cited_measured_re.search(_sd))
        _tool_shown = _src.startswith("tool:") and (
            _src[len("tool:"):] in {t.lower() for t in _worked}
            or bool(re.search(r"computed by\s+\S+", _sd, re.I))
        )
        _disclosed = _src in ("demand-coverage", "calculator", "derived",
                              "derived_device_scale", "aggregator") and len(_sd) > 20
        if (_k.lower() in _worked
                or (len(_sd) > 3 and any(o in _sd for o in ("=", "×", "*", "/", "+")))
                or _is_cited_measurement or _tool_shown or _disclosed):
            _shown += 1
    _cov = round(_shown / _tot * 100) if _tot else 100
    for _label, _val, _aim in [
        ("Deterministic sections at ≥8 (AIM: all)", f"{n_ok} / {len(_det_scores)}",
         bool(_det_scores) and n_ok == len(_det_scores)),
        ("Min deterministic section score (floors)",
         f"{det_min if det_min is not None else '—'}/10",
         isinstance(det_min, (int, float)) and det_min >= 8),
        ("Min self-audit opinion (advisory — never floors)",
         f"{mn if mn is not None else '—'}/10",
         isinstance(mn, (int, float)) and mn >= 8),
        ("Traceability — every number → the brief", f"{_trace}%" if _trace is not None else "—", (_trace or 0) >= 100),
        ("Calc-coverage — every number shows its formula", f"{_cov}%", _cov >= 100),
    ]:
        ws.cell(r, 1, _label).font = FONT_SUB
        vcl = ws.cell(r, 2, _val)
        vcl.fill = FILL_PASS if _aim else FILL_ADVISORY
        ws.cell(r, 4, "AIM: 100%" if "—" not in str(_val) else "").font = FONT_NOTE
        r += 1

    # ---- GROWING DB — self-building corpus freshness (A4, 2026-07-20). The engine's
    # long pole is BoM DATA COVERAGE, grown by DB-first→web-on-miss→writeback. This
    # surfaces whether the corpus is actually GROWING: per-table row count + the most-
    # recent write (max_ts) + its age, so an operator can see a stale store (e.g. the
    # material_prices seed frozen since May 2026) at a glance. Read READONLY at render;
    # never blocks the build (a missing helper/DB just omits the section). ----
    try:
        import importlib.util as _ilu
        _gdf_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "lib",
                                 "growing_db_freshness.py")
        _spec = _ilu.spec_from_file_location("growing_db_freshness", _gdf_path)
        _gdf = _ilu.module_from_spec(_spec); _spec.loader.exec_module(_gdf)
        _fresh = _gdf.compute_freshness()
    except Exception:  # noqa: BLE001
        _fresh = {"present": False, "tables": {}}
    if _fresh.get("present"):
        r += 1
        _mad = _fresh.get("min_age_days")
        sub_banner(ws, r, f"Growing DB — self-building corpus freshness "
                          f"(freshest write {_mad if _mad is not None else '?'} d ago; "
                          f"materials stale > {getattr(_gdf, 'MATERIALS_STALE_DAYS', 28)} d)", 4)
        r += 1
        _GDB_LABELS = {
            "pretraining_extracted_parts": "Branded parts (existence + MPN)",
            "pretraining_extracted_specs": "Component specs (datasheet values)",
            "pretraining_extracted_standards": "Standards (scope + citations)",
            "distributor_cascade_cache": "Distributor price cache",
            "material_prices": "Material prices (£/kg)",
        }
        for _tbl, _lbl in _GDB_LABELS.items():
            _e = _fresh.get("tables", {}).get(_tbl) or {}
            if not _e.get("present"):
                continue
            _age = _e.get("age_days")
            _extra = ""
            if _tbl == "distributor_cascade_cache":
                _extra = f" · {_e.get('hits', 0)} hits / {_e.get('expired', 0)} expired"
            _val = (f"{_e.get('n', 0):,} rows · last {str(_e.get('max_ts') or '—')[:10]} "
                    f"({_age if _age is not None else '?'} d){_extra}")
            ws.cell(r, 1, _lbl).font = FONT_SUB
            _vc = ws.cell(r, 2, _val)
            _vc.fill = FILL_ADVISORY if _e.get("stale") else FILL_PASS
            if _e.get("stale"):
                ws.cell(r, 4, "STALE — refresh the seed (A5)").font = FONT_NOTE
            r += 1

    # ---- PER-TAB deterministic scorecard (Tristan 2026-06-26): every tab vs the ≥8 floor.
    # LIVE SCORES (2026-07-03): every Score cell (B) is a FORMULA — =ROUND(MIN(...),1)
    # over (a) the tab's own Row-check/Cell-check columns via live COUNTIF arithmetic
    # where the tab has one, (b) its scorer components embedded as muted operand pairs
    # (cols G:P) and (c) the governing mechanism/cap operand (col F, provenance in E).
    # The two MIRROR tabs render FIRST so the non-mirror block is contiguous and the
    # LIVE FLOOR below can =MIN() over it without a fixpoint. The formulas are written
    # by _write_live_scores at end of build (final scores); the LAYOUT + the floor/open
    # formulas are fixed here. ----
    _tabsc = state.get("tabScorecard") or {}
    if isinstance(_tabsc, dict) and _tabsc:
        r += 1
        _su = state.get("tabScorecardSummary") or {}
        sub_banner(ws, r, f"Per-tab quality — every tab against the ≥8 floor "
                          f"(worst: {_su.get('min_tab', '?')} {_su.get('min_score', '?')}/10; "
                          f"{len(_su.get('fail_tabs') or [])} FAIL, {len(_su.get('unscored_tabs') or [])} UNSCORED). "
                          f"Score = live formula; muted 'Audit:' columns hold the embedded "
                          f"score operands (passed/checked per component + the governing cap).", 5)
        r += 1
        header(ws, r, ["Tab", "Score", "vs ≥8 floor", "Top issue / coverage gap (fix at source)",
                       "Basis — mechanism & caps (stated)", "Audit: governing cap",
                       "Audit: p1", "Audit: c1", "Audit: p2", "Audit: c2",
                       "Audit: p3", "Audit: c3", "Audit: p4", "Audit: c4",
                       "Audit: p5", "Audit: c5"])
        for _ci in range(6, 17):
            ws.cell(r, _ci).font = _FONT_AUDIT
        r += 1
        _tab_first = r
        # mirrors FIRST (they render the floor — excluded from the MIN range below)
        _order = [t for t in _MIRROR_TABS if t in _tabsc] \
            + [t for t in _tabsc if t not in _MIRROR_TABS] \
            + [t for t in (CONTENTS_SHEET,) if t not in _tabsc]   # late-built sheet rows
        _n_mirrors = sum(1 for t in _MIRROR_TABS if t in _tabsc)
        for _tab in _order:
            _v = _tabsc.get(_tab) if isinstance(_tabsc.get(_tab), dict) else {}
            _st = _v.get("status")
            _voos = _v.get("scored") is False   # VERIFIED OUT-OF-SCOPE (Option A, 2026-07-05)
            ws.cell(r, 1, clean_cell(_tab)).font = FONT_SUB
            _scell = ws.cell(r, 2)   # LIVE formula written by _write_live_scores (final scores)
            _scell.fill = (FILL_ADVISORY if _voos else
                           (FILL_PASS if _st == "PASS" else (FILL_ADVISORY if _st == "UNSCORED" else FILL_FAIL)))
            # column C: a GENERIC string match on the exact literal _write_live_scores writes
            # for scored:False (never a tab-name check) so the "verified, not scored" case
            # reads distinctly from a genuine UNSCORED gap.
            ws.cell(r, 3, f'=IF($B{r}="n/a — verified out of scope","VERIFIED — not scored",'
                          f'IF(ISNUMBER($B{r}),IF($B{r}>=8,"PASS ✓","⛔ below 8"),"UNSCORED"))')
            _iss = _v.get("issues") or [""]
            _icell = _write_defect_cell(ws, r, 4, _iss[0] if _iss else "")
            _icell.alignment = WRAP_TOP
            _icell.font = FONT_NOTE
            for _ci in range(5, 17):
                ws.cell(r, _ci).font = _FONT_AUDIT
            _QA_SCORE_CELLS[_tab] = f"'{ws.title}'!$B${r}"
            r += 1
        _tab_last = r - 1
        _register_check_range(ws.title, "C", _tab_first, _tab_last)
        r += 1
        # ---- THE LIVE FLOOR + OPEN-ISSUE CELLS — the ONE VERDICT's operands, computed
        # IN-CELL over the section scores + the NON-MIRROR tab scores (cross-sheet MIN
        # feeds every verdict surface + chip; mirrors reference, never enter, the MIN).
        _nm_first = _tab_first + _n_mirrors
        _rngs = []
        if _sec_last >= _sec_first:
            _rngs.append(f"$B${_sec_first}:$B${_sec_last}")
        # VERIFIED OUT-OF-SCOPE tabs (scored:False — Option A, 2026-07-05) are excluded from
        # the floor/open-issue surface entirely. MIN() already skips their non-numeric "n/a —
        # verified out of scope" literal harmlessly, but COUNTA()-COUNT() would otherwise
        # wrongly count that same literal as an "unscored" open issue — so the tab range is
        # decomposed into the fewest CONTIGUOUS $B$r1:$B$r2 spans that cover the included rows
        # (excluding those rows) rather than one contiguous span, since an excluded row can sit
        # anywhere inside the non-mirror block. NEVER a '(ref,ref,ref)' union — see
        # _contiguous_col_ranges (2026-07-05 Excel repair round 2: the union operator does not
        # survive the LibreOffice recalc round-trip). GENERIC: keyed on the `scored` flag per
        # tab, never a tab name.
        _floor_tab_rows = []
        for _tab2 in _order[_n_mirrors:]:
            if (_tabsc.get(_tab2) or {}).get("scored") is False:
                continue
            _ref2 = _QA_SCORE_CELLS.get(_tab2)
            if _ref2:
                _floor_tab_rows.append(int(_ref2.rsplit("$", 1)[1]))
        _rngs.extend(_contiguous_col_ranges("B", _floor_tab_rows))
        _rng_expr = ",".join(_rngs) if _rngs else '""'
        ws.cell(r, 1, "LIVE FLOOR — min of every deterministic section & non-mirror tab "
                      "(the ONE VERDICT's number, computed in-cell)").font = FONT_SUB
        _flc = ws.cell(r, 2, f'=IF(COUNT({_rng_expr})=0,"—",MIN({_rng_expr}))')
        _flc.fill = FILL_RESULT
        _QA_FLOOR_CELL.clear()
        _QA_FLOOR_CELL.append(f"'{ws.title}'!$B${r}")
        r += 1
        ws.cell(r, 1, "LIVE OPEN ISSUES — sections/tabs below 8 or unscored "
                      "(computed in-cell over the same score cells)").font = FONT_SUB
        _opn_terms = [f'COUNTIF({_rg},"<8")+(COUNTA({_rg})-COUNT({_rg}))' for _rg in _rngs]
        _opc = ws.cell(r, 2, "=" + "+".join(_opn_terms) if _opn_terms else 0)
        _opc.fill = FILL_RESULT
        _QA_OPEN_CELL.clear()
        _QA_OPEN_CELL.append(f"'{ws.title}'!$B${r}")
        r += 1

    # ---- the deterministic ship-gate AUDIT findings + benchmark net (the former ⚠ Audit
    # tab's content) — merged below the scorecard tables (Bundle B fix 2). ----
    r += 1
    _render_audit_findings(ws, report, state, r)
    back_link(ws, 5)
    ws.freeze_panes = "A5"


# ============================================================================
# RECALC-AND-CACHE (presentation audit 2026-07-02, fix 1). openpyxl writes live
# formulas WITHOUT cached <v> values, so every LIVE cell renders BLANK on any
# surface that doesn't recalculate (Quick Look, Gmail/Drive preview, mobile Excel
# viewers). Post-write, the workbook is round-tripped through LibreOffice headless
# with a one-shot profile forcing OOXMLRecalcMode=0 (recalculate on load), which
# stores a cached value beside EVERY formula while the formulas themselves REMAIN
# live. Verified by re-unzipping the shipped file: formula (<f>) count must hold
# and formula-with-cached-value pairs must appear. Kill: FORGE_SKIP_RECALC=1.
# ============================================================================
_LO_RECALC_XCU = """<?xml version="1.0" encoding="UTF-8"?>
<oor:items xmlns:oor="http://openoffice.org/2001/registry" xmlns:xs="http://www.w3.org/2001/XMLSchema">
 <item oor:path="/org.openoffice.Office.Calc/Formula/Load">
  <prop oor:name="OOXMLRecalcMode" oor:op="fuse"><value>0</value></prop>
  <prop oor:name="ODFRecalcMode" oor:op="fuse"><value>0</value></prop>
 </item>
</oor:items>
"""

# Formula node (<f>…</f> or <f …/>) and a formula IMMEDIATELY carrying a NON-EMPTY
# cached <v> (openpyxl writes an EMPTY '<v />' beside formulas — that is exactly the
# blank-preview gap, so it must NOT count as a cached value).
_XLSX_F_RX = re.compile(r"<f[ >/]")
_XLSX_FV_RX = re.compile(r"(?:</f>|<f[^>]*/>)\s*<v[^/>]*>[^<]")


# ── DETERMINISTIC FINALISE (Bundle B): two builds of the same run must be SHA-identical,
# so a diff/regression check is a straight shasum. Three volatile leftovers are pinned
# AFTER save+recalc: (1) docProps dcterms:modified (openpyxl stamps save-time); (2) the
# chart axId/crossAx pairs (LibreOffice's recalc round-trip regenerates them RANDOMLY
# each run — renumbered deterministically per chart, pairing preserved); (3) every zip
# member's mtime (stamped with wall-clock time by both writers). Content otherwise
# byte-preserved; formulas/cached values untouched. ──
_CHART_AXID_RX = re.compile(rb'<c:axId val="(\d+)"/>')
_CHART_CROSSAX_RX = re.compile(rb'<c:crossAx val="(\d+)"/>')
_DOCPROPS_MODIFIED_RX = re.compile(rb"<dcterms:modified[^>]*>[^<]*</dcterms:modified>")

# (4) legacy-comment VML duplicate-id corruption (Excel-strict repair-trigger,
# found 2026-07-05 — Tristan opened bess-campaign-v3's dossier.xlsx in real Excel
# for Mac and got "we found a problem with some content ... recover?"; LibreOffice,
# our only automated verifier until now, opens the SAME file cleanly). Root cause,
# reproduced in isolation with a bare 3-comment openpyxl workbook (no ForgeOS code
# involved): openpyxl writes ONE '<v:shapetype id="_x0000_t202">' + N shapes with
# UNIQUE ids ("_x0000_s1026", "_x0000_s1027", ...) — correct, Excel-strict-clean.
# The recalc_and_cache() LibreOffice round-trip REPLACES that file wholesale with
# `soffice --convert-to xlsx`'s own re-export, and LibreOffice's OOXML writer
# re-emits the FULL '<v:shapetype>' boilerplate once PER shape (instead of once,
# referenced by all) and stamps every '<v:shape>' with the literal, non-unique
# id="shape_0" — so any worksheet with >=2 legacy comments ships with N duplicate
# "_x0000_t202" shapetype declarations and N duplicate "shape_0" shapes in the same
# vmlDrawing part. UNIVERSAL, not BESS-specific: Codema v79's already-shipped
# dossier.xlsx has the identical defect (verified 2026-07-05) — every workbook with
# >=1 legacy comment that passes through recalc_and_cache() ships quietly corrupt;
# LibreOffice's own reader just doesn't enforce VML id uniqueness so it never
# noticed its own output was broken.
_VML_SHAPETYPE_RX = re.compile(
    rb'<v:shapetype\b[^>]*/>|<v:shapetype\b[^>]*>.*?</v:shapetype>', re.DOTALL)
_VML_ID_ATTR_RX = re.compile(rb'\bid="[^"]*"')
_VML_SHAPE_OPEN_RX = re.compile(rb'<v:shape\b[^>]*?>', re.DOTALL)


def _dedupe_vml_shape_ids(data: bytes) -> bytes:
    """Repair a post-LibreOffice-recalc vmlDrawing part: collapse duplicate
    '<v:shapetype id="...">' re-declarations to their first occurrence, then
    renumber every '<v:shape>' with a fresh unique id in Excel's own convention
    ("_x0000_s1026", "_x0000_s1027", ...) — the same scheme openpyxl's own
    ShapeWriter uses. A no-op on an already-clean part (0/1 shapetype, unique
    shape ids) — safe to run on every 'xl/drawings/*.vml' member unconditionally."""
    seen_shapetype_ids: set = set()

    def _shapetype_sub(m: "re.Match[bytes]") -> bytes:
        block = m.group(0)
        idm = _VML_ID_ATTR_RX.search(block)
        sid = idm.group(0) if idm else None
        if sid is not None:
            if sid in seen_shapetype_ids:
                return b""
            seen_shapetype_ids.add(sid)
        return block

    data = _VML_SHAPETYPE_RX.sub(_shapetype_sub, data)

    _ctr = {"n": 1025}

    def _shape_sub(m: "re.Match[bytes]") -> bytes:
        tag = m.group(0)
        _ctr["n"] += 1
        new_id_attr = b'id="_x0000_s%d"' % _ctr["n"]
        if _VML_ID_ATTR_RX.search(tag):
            return _VML_ID_ATTR_RX.sub(new_id_attr, tag, count=1)
        return tag[:-1] + b" " + new_id_attr + b">"

    return _VML_SHAPE_OPEN_RX.sub(_shape_sub, data)


def _sheet_file_for_name(z, sheet_name: str) -> Optional[str]:
    """Resolve a sheet NAME to its xl/worksheets/sheetN.xml member via workbook.xml + rels."""
    try:
        wbxml = z.read("xl/workbook.xml").decode("utf-8", "replace")
        rels = z.read("xl/_rels/workbook.xml.rels").decode("utf-8", "replace")
    except KeyError:
        return None
    rid = None
    for m in re.finditer(r"<sheet\b[^>]*>", wbxml):
        tag = m.group(0)
        nm = re.search(r'name="([^"]*)"', tag)
        ri = re.search(r'r:id="(rId\d+)"', tag)
        if nm and ri and _xml_unescape(nm.group(1)) == sheet_name:
            rid = ri.group(1)
            break
    if not rid:
        return None
    tm = re.search(r'Id="' + rid + r'"[^>]*Target="([^"]*)"', rels) or \
        re.search(r'Target="([^"]*)"[^>]*Id="' + rid + r'"', rels)
    if not tm:
        return None
    tgt = tm.group(1).lstrip("/")
    return tgt if tgt.startswith("xl/") else "xl/" + tgt


def _xml_unescape(s: str) -> str:
    from html import unescape
    return unescape(s)


def _finalise_deterministic_zip(out_path: str) -> None:
    """Rewrite the finished xlsx with pinned timestamps + deterministic chart axIds,
    and re-stamp collapsed="1" on the BoM ↳ parent rows (LibreOffice strips it)."""
    import zipfile
    with zipfile.ZipFile(out_path) as zin:
        bom_sheet = (_sheet_file_for_name(zin, _LEDGER_SHEET)
                     if _BOM_COLLAPSED_PARENTS else None)
        items = []
        for n in zin.namelist():
            data = zin.read(n)
            if bom_sheet and n == bom_sheet:
                def _stamp_collapsed(m, _pr):
                    attrs = m.group(1)
                    if b"collapsed" in attrs:   # LibreOffice writes collapsed="false" explicitly
                        attrs = re.sub(rb'collapsed="[^"]*"', b'collapsed="true"', attrs)
                    else:
                        attrs += b' collapsed="1"'
                    return (b'<row r="%d"' % _pr) + attrs + m.group(2) + b">"
                for _pr in _BOM_COLLAPSED_PARENTS:
                    data = re.sub(
                        (r'<row r="%d"([^>]*?)(/?)>' % _pr).encode(),
                        lambda m, _pr=_pr: _stamp_collapsed(m, _pr),
                        data, count=1)
            if n == "docProps/core.xml":
                # carry the namespace declarations ON the element: openpyxl's raw core.xml
                # declares dcterms/xsi per-element, so a replacement without its own
                # xmlns:* left UNBOUND prefixes -> strict XML parsers reject the file
                # (masked when a LibreOffice round-trip re-declared them at the root).
                data = _DOCPROPS_MODIFIED_RX.sub(
                    b'<dcterms:modified xmlns:dcterms="http://purl.org/dc/terms/" '
                    b'xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" '
                    b'xsi:type="dcterms:W3CDTF">2026-01-01T00:00:00Z'
                    b"</dcterms:modified>", data)
            elif n.startswith("xl/charts/chart") and n.endswith(".xml"):
                # renumber this chart's axis ids in first-appearance order; crossAx
                # references use the SAME map so every axis pair stays consistent.
                idmap: Dict[bytes, bytes] = {}
                for m in _CHART_AXID_RX.finditer(data):
                    if m.group(1) not in idmap:
                        idmap[m.group(1)] = str(70000001 + len(idmap)).encode()
                data = _CHART_AXID_RX.sub(
                    lambda m: b'<c:axId val="' + idmap.get(m.group(1), m.group(1)) + b'"/>', data)
                data = _CHART_CROSSAX_RX.sub(
                    lambda m: b'<c:crossAx val="' + idmap.get(m.group(1), m.group(1)) + b'"/>', data)
            elif n.startswith("xl/drawings/") and n.endswith(".vml"):
                # LibreOffice's recalc round-trip re-serialises legacy comment shapes
                # with duplicate ids (see _dedupe_vml_shape_ids docstring) — the exact
                # defect that made Excel refuse bess-campaign-v3's dossier.xlsx while
                # LibreOffice opened it fine. Repair unconditionally; a no-op if clean.
                data = _dedupe_vml_shape_ids(data)
            items.append((n, data))
    tmp = out_path + ".det-tmp"
    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
        for n, data in items:
            zi = zipfile.ZipInfo(n, date_time=(2026, 1, 1, 0, 0, 0))
            zi.compress_type = zipfile.ZIP_DEFLATED
            zi.external_attr = 0o600 << 16
            zout.writestr(zi, data)
    os.replace(tmp, out_path)


def _find_soffice() -> Optional[str]:
    """LibreOffice headless binary, or None (PATH first, then the macOS app bundle)."""
    import shutil as _shutil
    for cand in (_shutil.which("soffice"),
                 "/Applications/LibreOffice.app/Contents/MacOS/soffice",
                 "/usr/bin/soffice"):
        if cand and os.path.exists(cand):
            return cand
    return None


def _count_formulas_and_cached(xlsx_path: str) -> Tuple[int, int]:
    """(formula_cells, formula_cells_with_cached_value) by scanning the sheet XML."""
    import zipfile
    n_f = n_fv = 0
    with zipfile.ZipFile(xlsx_path) as z:
        for nm in z.namelist():
            if nm.startswith("xl/worksheets/") and nm.endswith(".xml"):
                xml = z.read(nm).decode("utf-8", "ignore")
                n_f += len(_XLSX_F_RX.findall(xml))
                n_fv += len(_XLSX_FV_RX.findall(xml))
    return n_f, n_fv


def recalc_and_cache(out_path: str, soffice_path: Optional[str] = "auto") -> bool:
    """Recalculate + CACHE every formula value in the written workbook (LibreOffice
    headless round-trip). Returns True only when the shipped file provably carries
    cached values AND its formulas survived. On any failure the original file is
    left untouched and a LOUD warning states the preview consequence."""
    soffice = _find_soffice() if soffice_path == "auto" else soffice_path
    if not soffice:
        print("  !! RECALC-AND-CACHE SKIPPED — LibreOffice (soffice) not found. The workbook "
              "ships with NO cached formula values: every live cell renders BLANK in Quick "
              "Look / Gmail / Drive previews. Install LibreOffice (brew install --cask "
              "libreoffice) or open + save the file in Excel before sending it.")
        return False
    import tempfile
    import shutil as _shutil
    try:
        n_f0, n_fv0 = _count_formulas_and_cached(out_path)
    except Exception as _ex:  # noqa: BLE001
        print(f"  !! RECALC-AND-CACHE SKIPPED — could not scan {out_path}: {_ex}")
        return False
    with tempfile.TemporaryDirectory(prefix="forge-recalc-") as td:
        profile = os.path.join(td, "profile", "user")
        os.makedirs(profile, exist_ok=True)
        with open(os.path.join(profile, "registrymodifications.xcu"), "w", encoding="utf-8") as fh:
            fh.write(_LO_RECALC_XCU)
        outdir = os.path.join(td, "out")
        os.makedirs(outdir, exist_ok=True)
        cmd = [soffice, "--headless", "--norestore", "--nolockcheck",
               f"-env:UserInstallation=file://{os.path.dirname(profile)}",
               "--convert-to", "xlsx:Calc MS Excel 2007 XML", "--outdir", outdir,
               os.path.abspath(out_path)]
        try:
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
        except Exception as _ex:  # noqa: BLE001
            print(f"  !! RECALC-AND-CACHE FAILED — soffice did not run ({_ex}). The workbook "
                  "ships WITHOUT cached values (blank live cells in previews).")
            return False
        conv = os.path.join(outdir, os.path.splitext(os.path.basename(out_path))[0] + ".xlsx")
        if res.returncode != 0 or not os.path.exists(conv) or os.path.getsize(conv) < 4096:
            print(f"  !! RECALC-AND-CACHE FAILED — soffice exit {res.returncode}: "
                  f"{(res.stderr or res.stdout or '').strip()[:300]}. The workbook ships "
                  "WITHOUT cached values (blank live cells in previews).")
            return False
        try:
            n_f1, n_fv1 = _count_formulas_and_cached(conv)
        except Exception as _ex:  # noqa: BLE001
            print(f"  !! RECALC-AND-CACHE FAILED — converted file unreadable: {_ex}")
            return False
        # Formulas must REMAIN (cached values + formulas, never values-only) and cached
        # values must actually be present now.
        if n_f1 <= 0 or n_fv1 <= 0 or n_f1 < 0.8 * n_f0:
            print(f"  !! RECALC-AND-CACHE REJECTED — round-trip formulas {n_f0}→{n_f1}, "
                  f"cached {n_fv0}→{n_fv1}; keeping the openpyxl original (blank live "
                  "cells in previews).")
            return False
        _shutil.move(conv, out_path)
        print(f"  · recalc-and-cache: {n_fv1}/{n_f1} formula cells now carry a cached value "
              f"(was {n_fv0}/{n_f0}); formulas remain live (LibreOffice round-trip)")
        return True


# ════════════════════════════════════════════════════════════════════════════════════════
# EVERY-TAB CONTENT SCORING + PER-CELL COMPLETENESS CONTRACT (Tristan 2026-07-03)
#
# "All of the tabs don't have a scoring mechanism on them — if they don't have a score how
# can you score it?"  +  "every line and every row should have some kind of deterministic
# scoring mechanism on it… if every cell needed to have something in it and it didn't, it
# would flag it as a problem."
#
# Three layers, all deterministic, all computed from the RENDERED workbook (never intent):
#   1. PER-CELL COMPLETENESS CONTRACT — every table rendered through header() is registered
#      (_RENDERED_TABLES) and must match a DECLARED contract (_TABLE_CONTRACTS: required
#      columns + type rules per table family). The generic walker (_run_cell_contracts)
#      verifies every data row × required column (non-empty, non-placeholder — a bare
#      'TBD'/'—' fails, an honest 'TBD (stated basis)' passes — and type-valid), FLAGS a
#      failing row ON the row (a '⚠ …' cell right of the table) and feeds the counts into
#      the tab score. A table whose signature has no declared contract REFUSES the build.
#   2. PER-TAB CONTENT SCORERS (_content_score_tab) — every tab's score is arithmetic over
#      checks of ITS OWN rendered content, min-combined with any pre-existing mechanism
#      (column contracts / drawing coverage / routed findings). The basis states the
#      formula WITH live counts. Scores are never a constant.
#   3. NO SILENT DEFAULT — compute_verdict(rendered_sheets=…) refuses any rendered tab
#      whose entry lacks a stated basis; _stamp_chips then renders the row-2 score chip on
#      every tab from the FINAL scores. proveCatch for all three in _selftest.
# ════════════════════════════════════════════════════════════════════════════════════════

_CELL_STATS: Dict[str, dict] = {}   # sheet -> {"checked","passed","fails","tables","rows"}
_CELLCON_DONE: set = set()          # (sheet, header_row, cols) already walked


def _norm_col(name) -> str:
    """Normalise a column label for contract matching: lowercase, parenthesised segments
    stripped (class-dependent units live there), '£/<unit>' collapsed (class-dependent
    denominators), whitespace collapsed."""
    s = re.sub(r"\([^)]*\)", "", str(name or ""))
    s = s.replace("​", "").lower()
    s = re.sub(r"£\s*/\s*[^\s,;]+", "£/unit", s)
    s = re.sub(r"\s+", " ", s).strip().strip(".:").strip()
    return s


def _table_sig(cols) -> tuple:
    return tuple(c for c in (_norm_col(x) for x in cols) if c)


_TABLE_CONTRACTS: Dict[tuple, dict] = {}


def _dt(cols, family, required, numeric=(), unit=(), row_rules=()) -> None:
    """Declare one table family's per-cell contract (required / numeric / unit columns).
    row_rules: [{'col','rx','exempt'}] — a row whose `col` matches `rx` is EXEMPT from the
    `exempt` columns (deliberate semantics, e.g. a ledger ↳ fold row priced on its parent)."""
    _TABLE_CONTRACTS[_table_sig(cols)] = {
        "family": family,
        "required": [_norm_col(c) for c in required],
        "numeric": [_norm_col(c) for c in numeric],
        "unit": [_norm_col(c) for c in unit],
        "row_rules": [{"col": _norm_col(rr["col"]), "rx": re.compile(rr["rx"]),
                       "exempt": [_norm_col(c) for c in rr["exempt"]]} for rr in row_rules],
    }


