# Markdown-sourced tables (_render_md_table: process/panel schedules parsed from
# drawings/*.md) have CLASS-DEPENDENT columns — they carry a declared GENERIC contract:
# EVERY named column is required per row (exactly Tristan's per-cell rule; the md source
# writes '—' only where it has nothing, which is precisely what must flag).
_MD_TABLE_CONTRACT = {"family": "md-schedule", "required": None, "numeric": [], "unit": []}

_PLACEHOLDER_RX = re.compile(r"^(?:—|–|-|\?+|\.{2,}|n/?a\.?|none|null|todo|tbd|tbc)$", re.I)
_TBD_PREFIX_RX = re.compile(r"^(?:tbd|tbc|n/?a)\b", re.I)


def _cell_txt(v) -> str:
    return str(v).replace("​", "").strip() if v is not None else ""


def _cell_missing(v) -> Optional[str]:
    """None when the cell is honestly populated; else a short reason. A bare placeholder
    ('', '—', 'TBD', 'n/a') is MISSING; a placeholder WITH a stated basis
    ('TBD (detailed design)', 'n/a — gravity drain') is an honest disclosure and passes.

    GOTCHA (Tristan 2026-07-09 grade-inflation ban): 'DATA NOT IN CONTRACT' is an
    IDENTIFIED GAP, not a populated value — it must fail the cell contract so a tab
    full of those cells can never score a perfect 10. Prefer minting the missing
    quantity at source, or an honest 'N/A — <basis>' disclosure when the figure is
    genuinely underivable (N/A-with-basis still passes via the TBD-prefix rule)."""
    if v is None:
        return "empty"
    if isinstance(v, (int, float)):
        return None
    s = _cell_txt(v)
    if not s:
        return "empty"
    if s.upper().startswith("DATA NOT IN CONTRACT"):
        return "data not in contract"
    if _PLACEHOLDER_RX.match(s):
        return f"placeholder '{s}'"
    if _TBD_PREFIX_RX.match(s) and len(s) < 10:
        return f"bare '{s}' (no stated basis)"
    return None


def _cell_num_ok(v) -> bool:
    """Numeric-typed cell: a number, a live formula, or a parseable money/qty string.

    GOTCHA: panel-schedule non-coincident loads render as '(4.50)' — the whole cell
    is parenthesised to mean 'shown but not in the running total' (load in parent /
    standby). Stripping parentheses first left an empty string and false-FAILED every
    such Electrical row (Codema ship 2026-07-09). Accept a fully-parenthesised number
    before stripping annotation parentheses from mixed cells like '7.50 (×2=15.0)'.
    """
    if isinstance(v, (int, float)):
        return True
    s = _cell_txt(v)
    if s.startswith("="):
        return True
    # Fully parenthesised load-in-parent / standby figure: '(4.50)' or '(7.69 (×2=15.4))'
    m_paren = re.fullmatch(r"\((.+)\)", s.strip())
    if m_paren:
        s = m_paren.group(1)
    s = re.sub(r"\([^)]*\)", "", s)          # '7.50 (×2=15.0)' → '7.50'
    s = re.sub(r"[£$€,%×x\s≈~]", "", s)
    if not s:
        return False
    try:
        float(s)
        return True
    except ValueError:
        return False


def _cell_unit_ok(v) -> bool:
    """A unit cell must read as a unit token, not prose (missing is checked separately)."""
    s = _cell_txt(v)
    return len(s) <= 24 and s.count(" ") <= 2


_TOTAL_ROW_RX = re.compile(r"^(?:sub)?totals?\b|^grand total|^Σ|^sum\b|^headroom\b|^margin\b|"
                           r"^break[- ]even\b", re.I)


def _merged_spans(ws) -> Dict[int, int]:
    """row -> widest single-row merged span starting at column 1 (section banners/notes)."""
    out: Dict[int, int] = {}
    try:
        for rng in ws.merged_cells.ranges:
            if rng.min_col == 1 and rng.min_row == rng.max_row:
                w = rng.max_col - rng.min_col + 1
                if w > out.get(rng.min_row, 0):
                    out[rng.min_row] = w
    except Exception:  # noqa: BLE001
        pass
    return out


def _walk_rows(ws, hdr_row: int, ncols: int, header_rows: set,
               merged: Optional[Dict[int, int]] = None, *,
               tolerate_blank_banner: bool = False) -> List[Tuple[int, list]]:
    """The DATA rows of a rendered table: rows below its header until the first fully-empty
    row / the next table's header. Section banners (single-row merges), TOTAL rows and
    italic note rows are skipped — they are not data and carry no per-cell obligation.

    `tolerate_blank_banner` (default OFF — every existing caller keeps today's exact
    behaviour, byte-for-byte) narrows a SPECIFIC boundary-detection bug (2026-07-05):
    on the "⚠ Checks" tab, `_render_lib_checks` renders its 7 check families
    (CONSISTENCY/ADEQUACY/.../PROVENANCE) as ONE logical table, but separates each
    family with "r += 1  # spacer between families" — a genuinely blank row — followed
    by the next family's full-width merged sub-banner. With this OFF, that first
    inter-family blank row is (mis-)read as the table's END, so `_fam_rows(wb, title,
    "checks")` returned only the FIRST family's ~2 rows against the tab's real ~337 —
    undercounting the denominator so badly that `checked - fails` went NEGATIVE and the
    generic 10×passed/checked arithmetic minted a -25-style score. Turning this ON is
    scoped to ONLY the one call site that needs it (`_sc_checks`'s own `_fam_rows` read)
    — NOT the generic per-cell-completeness walker (`_run_cell_contracts`) or any other
    `_fam_rows`/`_read_rows` caller, which must keep walking every OTHER table exactly
    as before (proven by the codema-v79 byte-identity regression this scoping fixes:
    turning it on globally swept unrelated sections on 'Assembly sequence' and
    'Executive Summary' into their neighbours' cell contracts, inventing new FAILs)."""
    merged = _merged_spans(ws) if merged is None else merged
    out: List[Tuple[int, list]] = []
    r = hdr_row + 1
    while r <= ws.max_row:
        if r in header_rows:
            break
        vals = [ws.cell(r, c).value for c in range(1, ncols + 1)]
        idx = [i for i, v in enumerate(vals) if v not in (None, "")]
        if not idx:
            if tolerate_blank_banner:
                # A TRUE table end still breaks: two consecutive blank rows (the real
                # gap before the next section) or a blank row followed by nothing/the
                # next registered header.
                nxt = r + 1
                if (nxt <= ws.max_row and nxt not in header_rows
                        and merged.get(nxt, 0) >= max(2, min(3, ncols))):
                    r = nxt
                    continue
            break
        if merged.get(r, 0) >= max(2, min(3, ncols)):
            r += 1
            continue                          # section banner / merged note row
        first_cell = ws.cell(r, 1 + idx[0])
        first_txt = _cell_txt(vals[idx[0]])
        if _TOTAL_ROW_RX.match(first_txt):
            r += 1
            continue                          # a totals row is arithmetic, not a data row
        if len(idx) == 1 and (getattr(first_cell.font, "italic", False) or len(first_txt) > 70):
            r += 1
            continue                          # a one-cell prose/note row
        out.append((r, vals))
        r += 1
    return out


_CHECK_FLAG_FONT = Font(name="Calibri", size=9, color="9C0006")


def _run_cell_contracts(wb, sheets=None) -> Dict[str, dict]:
    """The generic per-cell walker: verify every registered table's data rows against its
    declared contract, write a '⚠' flag cell ON each failing row (right of the table) and
    accumulate per-sheet counts into _CELL_STATS. Refuses (build error) any table whose
    signature carries no declared contract — an uncontracted table cannot ship."""
    header_rows_by_sheet: Dict[str, set] = {}
    for t in _RENDERED_TABLES:
        header_rows_by_sheet.setdefault(t["sheet"], set()).add(t["row"])
    for t in _RENDERED_TABLES:
        key = (t["sheet"], t["row"], tuple(t["cols"]))
        if key in _CELLCON_DONE:
            continue
        if sheets is not None and t["sheet"] not in sheets:
            continue
        if t["sheet"] not in wb.sheetnames:
            continue
        sig = _table_sig(t["cols"])
        spec = _TABLE_CONTRACTS.get(sig)
        if spec is None and t.get("md_table"):
            spec = _MD_TABLE_CONTRACT
        if spec is None:
            raise SystemExit(
                f"PER-CELL CONTRACT: rendered table on '{t['sheet']}' (header row {t['row']}) "
                f"has NO declared required-columns contract — columns {t['cols']!r} "
                f"(signature {sig!r}). Declare it in _TABLE_CONTRACTS; an uncontracted "
                "table cannot ship.")
        _CELLCON_DONE.add(key)
        ws = wb[t["sheet"]]
        ncols = len(t["cols"])
        norm = [_norm_col(c) for c in t["cols"]]
        req_names = spec["required"] if spec["required"] is not None else [c for c in norm if c]
        req_idx = [i for i, c in enumerate(norm) if c and c in req_names]
        num_idx = [i for i, c in enumerate(norm) if c in (spec["numeric"] or [])]
        unit_idx = [i for i, c in enumerate(norm) if c in (spec["unit"] or [])]
        row_rules = [(next((i for i, c in enumerate(norm) if c == rr["col"]), None),
                      rr["rx"], {c for c in rr["exempt"]})
                     for rr in (spec.get("row_rules") or [])]
        st = _CELL_STATS.setdefault(t["sheet"], {"checked": 0, "passed": 0, "fails": [],
                                                 "tables": 0, "rows": 0})
        st["tables"] += 1
        merged = _merged_spans(ws)
        rows = _walk_rows(ws, t["row"], ncols, header_rows_by_sheet.get(t["sheet"], set()),
                          merged)
        # The flag column: first free column at/right of the table (a table that already
        # carries its own appended 'Row check' / 'Audit:' columns keeps them; the Cell
        # check lands after them).
        flag_col = ncols + 1
        for _try in range(8):
            _hc0 = ws.cell(t["row"], flag_col)
            if type(_hc0).__name__ != "MergedCell" and _hc0.value in (None, ""):
                break
            flag_col += 1
        wrote_hdr = False
        for r, vals in rows:
            st["rows"] += 1
            exempt_cols = set()
            for rc, rrx, rex in row_rules:
                if rc is not None and rrx.search(_cell_txt(vals[rc])):
                    exempt_cols |= rex
            reasons = []
            # EVERY-ROW LIVE CELL CHECK (Tristan 2026-07-03: "you need to check every
            # single tab, every single line, every single column"): the flag cell is a
            # FORMULA over the row's own required cells — completeness (non-empty, not a
            # bare placeholder) plus the type terms python flagged — so the verdict
            # recomputes when a cell is edited. The python walk below stays the counting
            # source for the (embedded) score operand; the formula is the on-sheet check.
            fx_terms: List[str] = []
            for i in req_idx:
                if norm[i] in exempt_cols:
                    continue      # declared row-level semantics (fold/summary row)
                st["checked"] += 1
                _ref = f"{get_column_letter(i + 1)}{r}"
                _cell_is_num = isinstance(vals[i], (int, float)) or (
                    isinstance(vals[i], str) and str(vals[i]).startswith("="))
                fx_terms += [f'LEN(TRIM({_ref}&""))>0', f'TRIM({_ref}&"")<>"—"']
                why = _cell_missing(vals[i])
                if why is None and i in num_idx and norm[i] not in exempt_cols \
                        and not _cell_num_ok(vals[i]):
                    why = "not numeric"
                if why is None and i in unit_idx and not _cell_unit_ok(vals[i]):
                    why = "not a unit token"
                # strict live terms for the SPECIFIC failure python found on this cell,
                # so the formula's verdict agrees with the walk (and stays live)
                if why is not None:
                    _m = re.match(r"(?:placeholder|bare) '(.*)'", str(why))
                    if _m:
                        fx_terms.append(f'TRIM({_ref}&"")<>"{_xq(_m.group(1), 24)}"')
                    elif why == "not numeric":
                        fx_terms.append(f"ISNUMBER({_ref})")
                    elif why == "not a unit token":
                        fx_terms.append(f'LEN(TRIM({_ref}&""))<=24')
                elif i in num_idx and norm[i] not in exempt_cols and _cell_is_num:
                    fx_terms.append(f"ISNUMBER({_ref})")
                if why is None:
                    st["passed"] += 1
                else:
                    reasons.append(f"'{t['cols'][i] or f'col {i + 1}'}' {why}")
            if reasons and len(st["fails"]) < 80:
                st["fails"].append({"row": r, "why": "; ".join(reasons[:3]),
                                    "table_row": t["row"]})
            fc = ws.cell(r, flag_col)
            if type(fc).__name__ == "MergedCell":
                continue      # row merge extends over the flag column — counts still tally
            if fc.value in (None, "") and fx_terms:
                _fail_txt = ("; ".join(reasons[:2])
                             + (f" +{len(reasons) - 2} more" if len(reasons) > 2 else "")
                             ) if reasons else "a required cell is empty/placeholder or wrong type"
                fc.value = fx_verdict(fx_terms, f'"{_xq(_fail_txt, 160)}"',
                                      fail_prefix="⚠ FAIL — ")
                fc.font = _CHECK_FLAG_FONT if reasons else _FONT_AUDIT
                fc.alignment = LEFT_TOP
                if not wrote_hdr:
                    hc = ws.cell(t["row"], flag_col)
                    if type(hc).__name__ != "MergedCell" and hc.value in (None, ""):
                        hc.value = "Cell check"
                        hc.font = FONT_NOTE
                    wrote_hdr = True
    return _CELL_STATS


# ── Rendered-table readers for the per-tab scorers ───────────────────────────────────────
def _tables_of(wb, sheet_title: str, family=None) -> List[dict]:
    out = []
    for t in _RENDERED_TABLES:
        if t["sheet"] != sheet_title:
            continue
        spec = _TABLE_CONTRACTS.get(_table_sig(t["cols"]))
        if spec is None and t.get("md_table"):
            spec = _MD_TABLE_CONTRACT
        if spec is None:
            continue
        if family is None or spec["family"] == family:
            out.append({**t, "spec": spec})
    return out


def _read_rows(wb, tbl: dict, *, tolerate_blank_banner: bool = False
              ) -> List[Tuple[int, Dict[str, Any]]]:
    """Data rows of a registered table as (sheet_row, {normalised col name: value})."""
    ws = wb[tbl["sheet"]]
    header_rows = {t["row"] for t in _RENDERED_TABLES if t["sheet"] == tbl["sheet"]}
    norm = [_norm_col(c) for c in tbl["cols"]]
    rows = _walk_rows(ws, tbl["row"], len(tbl["cols"]), header_rows,
                      tolerate_blank_banner=tolerate_blank_banner)
    out = []
    for r, vals in rows:
        d: Dict[str, Any] = {}
        for i, cname in enumerate(norm):
            if cname and cname not in d:
                d[cname] = vals[i]
        out.append((r, d))
    return out


def _fam_rows(wb, sheet: str, family: str, *, tolerate_blank_banner: bool = False
             ) -> List[Tuple[int, Dict[str, Any]]]:
    out: List[Tuple[int, Dict[str, Any]]] = []
    for t in _tables_of(wb, sheet, family):
        out.extend(_read_rows(wb, t, tolerate_blank_banner=tolerate_blank_banner))
    return out


_TAG_TOKEN_RX = re.compile(r"\b[A-Z]{1,5}-\d{1,4}[A-Za-z]?\b")
_TAG_RANGE_RX = re.compile(r"\b([A-Z]{1,5})-(\d{1,4})\s*[–—-]\s*(?:\1-)?(\d{1,4})\b")


def _expand_tags(text: str) -> set:
    """Tag tokens in a cell, with 'X-152–X-154' / 'X-152–154' RANGES expanded so a
    master row that names a range covers every instance tag the ledger replicates."""
    out = set(_TAG_TOKEN_RX.findall(text))
    for m in _TAG_RANGE_RX.finditer(text):
        pre, lo, hi = m.group(1), int(m.group(2)), int(m.group(3))
        if hi >= lo and hi - lo <= 500:
            out.update(f"{pre}-{n}" for n in range(lo, hi + 1))
    return out


def _num_of(v):
    if isinstance(v, (int, float)):
        return float(v)
    s = re.sub(r"[£$€,%×x\s≈~]", "", _cell_txt(v))
    try:
        return float(s)
    except ValueError:
        return None


def _state_number_index(state: dict) -> List[float]:
    """Every number the engine states in its headline sources — the Overview dashboard's
    quoted values must each trace to one of these (dashboard integrity)."""
    out: List[float] = []

    def _walk_idx(o, depth=0):
        if depth > 6 or len(out) > 4000:
            return
        if isinstance(o, dict):
            for v in o.values():
                _walk_idx(v, depth + 1)
        elif isinstance(o, list):
            for v in o[:400]:
                _walk_idx(v, depth + 1)
        elif isinstance(o, bool):
            return
        elif isinstance(o, (int, float)):
            out.append(float(o))
        elif isinstance(o, str):
            n = _num_of(o)
            if n is not None:
                out.append(n)
    for key in ("keyMetrics", "costStack", "bomTotals", "costBasis", "_costOfService",
                "headlineDerived", "tabScorecardSummary"):
        _walk_idx((state or {}).get(key))
    _walk_idx(((state or {}).get("orchestratorContract") or {}).get("quantities"))
    _walk_idx(((state or {}).get("engineeringContract") or {}).get("quantities"))
    return out


def _traces_to_state(val: float, index: List[float]) -> bool:
    tol = max(abs(val) * 0.005, 0.51)   # 0.5% or rounding distance
    return any(abs(val - x) <= tol for x in index)


# ── Per-tab content scorers. Each returns {"components": [(label, passed, checked)],
#    "issues": [...], "fix": str, "mech": str, "score_cap": Optional[float]} — the merge
#    turns components into arithmetic (min over checks of 10 × passed/checked). ──────────
#
# COVER COMPLIANCE ARITHMETIC — feedstock-approximation relief + fallback matcher
# (Tristan 2026-07-06). This is the THIRD independent brief-compliance computation in the
# codebase (dossier_audit.py::_is_feedstock_metric/_brief_value_approximated and
# scorecard-floor.ts::complianceMetricIsFeedstock/briefValueApproximated/
# fallbackMatchQuantity are the other two, already fixed): _compliance_row_pass below is
# the COVER's own second-opinion audit, re-deriving PASS/FAIL from the RENDERED cells
# rather than trusting the workbook's live =IF STATUS formula — so the same two false
# brief-misses those fixes already closed reproduce here unless the identical rules are
# ported a third time:
#   1. koh_feed_tpd (achieved 2.54 vs an approximate target ~2.6 t/day, 2.3% gap): a
#      FEEDSTOCK/consumption metric the brief itself hedges with 'approximately' widens
#      to a ±5% tolerance instead of the tight 2% band.
#   2. co2_capture_capacity_tpd: the render's own _match_quantity exact-token overlap
#      never matched the delivered 'capture_capacity_tco2_per_day' quantity ('tco2' !=
#      'co2'), so the rendered row is UNVERIFIED (Achieved cell literally '—'). The
#      recompute gets one more chance via a SAME-UNIT, SUBSTRING-tolerant token-overlap
#      fallback read directly from state.orchestratorContract.quantities.
# Both reliefs are OPT-IN via the `state` param — omitting it (as every pre-existing
# caller/test does) preserves the exact prior behaviour byte-for-byte. proveCatch (both
# directions) in _selftest.
_COVER_FEEDSTOCK_METRIC_RX = re.compile(
    r"\b(feed|feedstock|consum|reagent|dos(?:e|ing)|makeup|make_up|intake|uptake|input)\b", re.I)
_COVER_HARD_PERFORMANCE_METRIC_RX = re.compile(
    r"\b(capacity|output|throughput|yield|product|rated|nameplate|power|voltage|current|"
    r"efficiency|energy|duty|captur\w*)\b", re.I)

# Qualitative unit tokens that indicate a row is PASS-by-provision (not a numeric
# comparison against a stated target value). Any unit NOT in this set and NOT blank
# is a "real" metric unit — the row is QUANTITATIVE and cannot PASS when either the
# brief target or the achieved value is missing/null.
_QUALITATIVE_UNIT_TOKENS: frozenset = frozenset({
    "", "—", "-", "--", "n/a", "na", "none", "bool", "yes/no", "yes", "no",
    "pass/fail", "provision", "stated", "adopted", "qualitative",
})


def _unit_is_quantitative(unit_str: str) -> bool:
    """True when a compliance row's unit indicates a NUMERIC comparison is required.

    A blank / placeholder / yes-no unit → qualitative (PASS-by-provision allowed).
    Any real SI / derived unit (kg, °C, ml, mm, W, kWh, V, …) → quantitative
    (UNVERIFIED when target or achieved is missing, never PASS).

    Discriminator is UNIT PRESENCE, not metric name — universal across all archetypes.
    proveCatch in _selftest (HONESTY.quantitative_null_target_is_unverified).
    """
    t = unit_str.strip().lower().replace(" ", "") if unit_str else ""
    return t not in _QUALITATIVE_UNIT_TOKENS


def _cover_metric_is_feedstock(name) -> bool:
    """True for a feedstock/raw-material CONSUMPTION metric name; false for a hard
    performance/output floor even when a token would otherwise overlap. Mirrors
    dossier_audit.py::_is_feedstock_metric / scorecard-floor.ts::complianceMetricIsFeedstock."""
    text = re.sub(r"[_\-]+", " ", str(name or ""))
    return bool(_COVER_FEEDSTOCK_METRIC_RX.search(text)) and not _COVER_HARD_PERFORMANCE_METRIC_RX.search(text)


_COVER_APPROX_RX = re.compile(r"~|\bapprox(?:imately|\.)?\b|\babout\b|\broughly\b", re.I)


def _cover_brief_value_approximated(brief_text: str, target_value) -> bool:
    """True when the brief's own text, within a short window before THIS metric's cited
    target value, hedges it with an approximation word — the brief itself discloses the
    figure is not exact. Mirrors dossier_audit.py::_brief_value_approximated."""
    v = num(target_value)
    if v is None or not brief_text:
        return False
    reps = {f"{v:g}", f"{v:.0f}", f"{v:.1f}", f"{v:.2f}"}
    for rep in reps:
        if not rep:
            continue
        for m in re.finditer(re.escape(rep), brief_text):
            window = brief_text[max(0, m.start() - 40): m.start()]
            if _COVER_APPROX_RX.search(window):
                return True
    return False


# The fallback matcher's OWN stop-list (distinct from _QTY_STOP_TOKENS above, which backs
# _match_quantity's exact-token overlap) — mirrors scorecard-floor.ts::MATCH_STOP_TOKENS,
# including the generic measure-noun exclusions (temp/pressure/level/concentration) that
# must never bridge two different subsystems on a single shared unit word.
_COVER_ECHO_NAME_TOKEN_RX = re.compile(
    r"_(requested|request|target|demand|brief|spec|setpoint|required)$", re.I)
_COVER_FALLBACK_STOP_TOKENS = {
    "the", "of", "per", "system", "total", "design", "rated", "nominal", "max", "min", "peak", "avg", "mean",
    "capacity", "throughput", "flow", "rate", "demand", "output", "volume", "duty", "load",
    "temp", "temperature", "pressure", "level", "concentration",
    "m3", "m2", "m", "l", "hr", "h", "hour", "hrs", "min", "mins", "sec", "s", "day", "yr", "year",
    "kw", "mw", "gw", "w", "kwh", "mwh", "gwh", "wh", "kg", "kt", "t", "g", "v", "kv", "a", "ka", "ma",
    "bar", "pa", "kpa", "mpa", "psi", "c", "k", "pct", "percent", "mm", "cm", "km", "nm", "ppm",
    "count", "nr", "no", "qty", "ea", "off", "unit", "units", "pcs", "number",
}


def _cover_name_tokens(name) -> List[str]:
    base = re.sub(r"[^a-z0-9_]+", "_", str(name or "").lower())
    base = re.sub(r"_+", "_", base).strip("_")
    return [t for t in base.split("_") if t and t not in _COVER_FALLBACK_STOP_TOKENS]


def _cover_token_overlap_count(brief_tokens: List[str], q_tokens: List[str]) -> int:
    """Count of brief-metric identity tokens covered by a candidate quantity's tokens —
    exact match OR (length >=3 both sides) substring match, so a compound token like
    'tco2' still covers the brief's 'co2' without a per-instance alias table."""
    n = 0
    for bt in brief_tokens:
        if any(qt == bt or (len(bt) >= 3 and len(qt) >= 3 and (qt in bt or bt in qt)) for qt in q_tokens):
            n += 1
    return n


def _cover_norm_unit(u) -> str:
    return re.sub(r"\s+", "", str(u or "").strip().lower())


def _cover_fallback_match_quantity(metric_key: str, metric_unit: str, quantities: Dict[str, Any]
                                   ) -> Optional[Tuple[str, float]]:
    """Second-opinion fallback for the cover's own recompute — same-UNIT, SUBSTRING-
    tolerant token overlap against the achieved-quantities map. Requirement-ECHO
    quantities (…_target/_demand/…) are excluded so a genuine miss stays honest. Returns
    None (never guesses) when nothing clears at least half the metric's identity tokens.
    Mirrors scorecard-floor.ts::fallbackMatchQuantity."""
    b_tokens = _cover_name_tokens(metric_key)
    if not b_tokens:
        return None
    need = max(1, (len(b_tokens) + 1) // 2)
    target_unit = _cover_norm_unit(metric_unit)
    best = None  # (overlap, key, value)
    for qname, qv in (quantities or {}).items():
        if not isinstance(qv, dict) or _COVER_ECHO_NAME_TOKEN_RX.search(str(qname)):
            continue
        if _cover_norm_unit(qv.get("unit")) != target_unit:
            continue
        val = num(qv.get("value"))
        if val is None:
            continue
        overlap = _cover_token_overlap_count(b_tokens, _cover_name_tokens(qname))
        if overlap < need:
            continue
        if best is None or overlap > best[0]:
            best = (overlap, qname, val)
    return (best[1], best[2]) if best else None


_COVER_NOTE_KEY_RX = re.compile(r"brief key:\s*([A-Za-z0-9_]+)")


def _compliance_row_pass(d, state: Optional[dict] = None) -> Optional[bool]:
    """Recompute a rendered compliance row's verdict from its OWN cells. The STATUS cell
    is a live =IF formula (unreadable pre-recalc), so the check re-evaluates the same
    comparison: achieved vs target in the stated direction, 2% tolerance (the formulas
    bake the same allowance). None = unverifiable (missing numbers) — counts as FAIL.

    `state` (optional, backward compatible) engages two second-opinion reliefs — see the
    block comment above _cover_metric_is_feedstock: (a) an UNVERIFIED row (no numeric
    Achieved cell) gets one more chance via the same-unit substring-tolerant fallback
    matcher against state.orchestratorContract.quantities; (b) a FAIL on a feedstock/
    consumption metric the brief itself hedges with 'approximately' widens to ±5%."""
    t = _num_of(d.get("target"))
    a = _num_of(d.get("achieved"))
    note = _cell_txt(d.get("note"))
    km = _COVER_NOTE_KEY_RX.search(note)
    key = km.group(1) if km else ""
    if a is None and t is not None and state is not None and key:
        quantities = (state.get("orchestratorContract") or {}).get("quantities") or {}
        fb = _cover_fallback_match_quantity(key, _cell_txt(d.get("unit")), quantities)
        if fb is not None:
            a = fb[1]
    if t is None or a is None:
        # HONESTY RULE (2026-07-25): a QUANTITATIVE row (unit-bearing) whose brief
        # target or achieved value is null/missing CANNOT be verified — it is
        # UNVERIFIED regardless of any static "PASS" in the status cell.  You
        # cannot verify a number against a missing number.
        # A QUALITATIVE row (unit absent / placeholder) may still carry a static
        # PASS by provision (e.g. "design_life adopted", "additional_constraint
        # adopted") — those are honest disclosures, not numeric comparisons.
        # Discriminator: does the row carry a real numeric unit?
        if _unit_is_quantitative(_cell_txt(d.get("unit"))):
            return None   # quantitative + null target/achieved = UNVERIFIED
        st = _cell_txt(d.get("status")).upper()
        if st.startswith("PASS"):
            return True   # qualitative PASS-by-provision (unit absent/placeholder)
        return None
    dirn = _cell_txt(d.get("direction")).lower()
    if "≥" in dirn or ">=" in dirn or "meet/exceed" in dirn or "at least" in dirn:
        passed = a >= t * 0.98
    elif "≤" in dirn or "<=" in dirn or "at most" in dirn or "ceiling" in dirn:
        passed = a <= t * 1.02
    else:
        # ONE COMPLIANCE MATCHER (2026-07-26). A cost band-CENTRE (midpoint) is symmetric
        # about a plausibility band, not a hard target: the RENDERER already writes
        # `=IF(ABS(achieved-target)<=0.20*target, "PASS", "FAIL")` for these rows via
        # _is_cost_band_center, but THIS checker fell through to the generic ±2%. On the
        # organoid r11 cover that scored the rendered-PASS midpoint row (target 330,
        # achieved 291, |39| <= 66) as a FAIL because 39 > 6.6 — the tab marked itself
        # down for disagreeing with a formula it had just written. Share the helper so the
        # rendered cell and the audit of that cell can never diverge.
        _tol_frac = 0.20 if _is_cost_band_center(key) else 0.02
        passed = abs(a - t) <= _tol_frac * max(abs(t), 1e-9)
    if not passed and key and state is not None and _cover_metric_is_feedstock(key):
        pb = state.get("parsedBrief") or {}
        brief_text = pb.get("original_text") or pb.get("revised_text") or ""
        if isinstance(brief_text, str) and _cover_brief_value_approximated(brief_text, t):
            tol5 = abs(t) * 0.05
            passed = abs(a - t) <= tol5 or t == 0
    return passed


def _sc_exec(wb, ws, state, run_dir):
    rows = _fam_rows(wb, ws.title, "compliance")
    verdicts = [_compliance_row_pass(d, state) for _r, d in rows]
    p = sum(1 for v in verdicts if v is True)
    unv = sum(1 for v in verdicts if v is None)
    iss = []
    if unv:
        iss.append(f"{unv} brief-compliance row(s) UNVERIFIABLE on the cover (no numeric "
                   "target/achieved pair)")
    return {"components": [("brief-compliance rows recompute to PASS", p, len(rows))],
            "issues": iss,
            "mech": "cover compliance arithmetic (achieved vs target re-evaluated per row)",
            "fix": ""}


def _sec_label_norm(x) -> str:
    return re.sub(r"\s*\(advisory\)\s*", "", str(x or "")).strip().lower().replace("_", " ")


def _sc_overview(wb, ws, state, run_dir):
    comps = []
    iss = []
    sec_rows = _fam_rows(wb, ws.title, "overview-sections")
    facts, advisory = _verdict_sections(state, run_dir)   # THE same source the verdict uses
    fact_by = {_sec_label_norm(k): (v or {}).get("score") for k, v in facts.items()}
    adv_by = {_sec_label_norm(k): (v or {}).get("score") for k, v in advisory.items()}
    ok = 0
    mism = []
    for _r, d in sec_rows:
        label = _cell_txt(d.get("section"))
        want = (adv_by if "(advisory)" in label.lower() else fact_by).get(_sec_label_norm(label))
        got = _num_of(d.get("score"))
        if got is not None and isinstance(want, (int, float)) and abs(got - want) <= 0.05:
            ok += 1
        elif len(mism) < 3:
            mism.append(f"'{label[:30]}' shows {got} vs engine {want}")
    if sec_rows:
        comps.append(("section scores match the engine scorecard", ok, len(sec_rows)))
        if ok < len(sec_rows):
            iss.append(f"{len(sec_rows) - ok} Overview section score(s) diverge from the "
                       f"engine scorecard — e.g. {'; '.join(mism)}")
    idx = _state_number_index(state)
    # (Cost-waterfall class-split numbers are checked by their OWN tab's arithmetic
    #  ties; the capex table below carries its own per-row % arithmetic.)
    cost_rows = _fam_rows(wb, ws.title, "overview-cost")
    pairs = [(_num_of(d.get("cost")), _num_of(d.get("% of capex"))) for _r, d in cost_rows]
    pairs = [(c, pct) for c, pct in pairs if c is not None]
    if pairs:
        total = sum(c for c, _p in pairs)
        # GOTCHA: the Overview writer stores % as round(pct, 1) alongside round(gbp)
        # integer pounds — recompute with the SAME one-decimal rounding or every
        # row fails when Σ rounded costs ≠ the unrounded BoM (gold-spine bake).
        ok = sum(
            1 for c, pct in pairs
            if pct is not None and total > 0
            and abs(pct - round(100.0 * c / total, 1)) <= 0.05
        )
        comps.append(("capex category % = 100 × £ / Σ (per-row arithmetic)", ok, len(pairs)))
        anchor = None
        for k in ("raw_materials_bom_gbp", "bom_total_gbp"):
            av = (state.get("costStack") or {}).get(k)
            if isinstance(av, (int, float)) and av:
                anchor = float(av)
                break
        if anchor:
            tie = 1 if abs(total - anchor) <= max(1.0, anchor * 0.02) else 0
            comps.append(("Σ capex categories ≈ the BoM materials total", tie, 1))
            if not tie:
                iss.append(f"Overview capex categories sum £{total:,.0f} ≠ BoM materials "
                           f"total £{anchor:,.0f}")
    return {"components": comps, "issues": iss,
            "mech": "dashboard integrity (every quoted number vs its engine source)", "fix": ""}


def _brief_constraint_fidelity(state: dict, run_dir: str = "") -> List[dict]:
    """The brief↔design fidelity checks the Brief tab verifies — one row per STATED
    brief constraint (working volume, culture temperature, stability, cost ceiling,
    mass, every target_performance metric), each with target · achieved · PASS/FAIL/
    UNVERIFIED. Reuses the verification spine's BRIEF-AXIS rows (the SAME closed
    target-vs-achieved arithmetic the Verification tab already computes) — so the Brief
    tab proves the engine's structured interpretation honours each constraint rather
    than merely re-displaying a populated interpretation. Universal (fires on any brief
    that states target_performance / derived_requirements / a cost or mass ceiling),
    keyed on the brief's own constraints — no per-class table. Returns [] when the brief
    carries no verifiable constraints (then the ZERO-CHECK guard still applies).

    Returns the RAW spine row dicts (carrying target_num/achieved_num/compare/tol_frac) so
    the Brief-tab renderer can emit a LIVE status formula (never a bare verdict literal —
    the no-cheating gate forbids those); the stringified `as_dict` rows drop the numeric
    fields the formula needs."""
    try:
        rows = _assemble_verification_rows(state or {}, run_dir or "")
    except Exception:  # noqa: BLE001
        return []
    return [r for r in rows if str(r.get("axis")).strip().lower() == "brief"]


def _sc_brief(wb, ws, state, run_dir):
    comps = []
    iss = []
    secs = ((state.get("_clientOfferRecon") or {}).get("sections") or [])
    rows = _fam_rows(wb, ws.title, "recon")
    # ── BRIEF↔DESIGN CONSTRAINT FIDELITY (2026-07-21, Pillar 3) ──
    # An instrument-shaped brief (organoid bioreactor: 37 °C, ml working volume, OD,
    # £275-385) carries NO client-offer per-section cost table, so the client-offer
    # reconciliation legitimately returns None and the tab used to fall through to the
    # ZERO-CHECK cap (4.0) — a populated-but-unverified Brief. Verify each STATED brief
    # constraint against the design instead: reuse the verification spine's brief-axis
    # rows (working volume / culture temperature / stability / cost ceiling / mass /
    # target_performance), each a real target-vs-achieved check. A HARD constraint that
    # is FAIL/UNVERIFIED counts against the tab (never a fake PASS-by-echo); a stability
    # requirement with no derived achieved figure honestly reads UNVERIFIED.
    fid = _brief_constraint_fidelity(state, run_dir)
    if fid:
        _fid_pass = sum(1 for r in fid if str(r.get("status")).upper() in ("PASS", "OK"))
        comps.append(("brief constraints honoured by the design "
                      "(target vs achieved, verification spine)", _fid_pass, len(fid)))
        _open = [str(r.get("claim")) for r in fid
                 if str(r.get("status")).upper() in ("FAIL", "UNVERIFIED", "OPEN")]
        if _open:
            iss.append(f"{len(_open)} stated brief constraint(s) not verified against the "
                       f"design ({', '.join(_open[:4])}) — the engine's interpretation does "
                       f"not yet prove it honours these; close each on the Verification spine")
    if secs or rows:
        # a decision-covered row PASSES (consistent_with_decision — the recorded scope
        # decision renders inline on the Brief tab); a diverging row with NO recorded
        # decision still fails the tab.
        _PASSING = ("consistent", "consistent_with_decision")
        cons = sum(1 for s in secs if s.get("status") in _PASSING)
        comps.append(("client-offer reconciliation sections consistent "
                      "(incl. decision-covered)", cons, len(secs)))
        keys = {str(s.get("key") or "").strip().upper() for s in secs}
        sec_rows = [1 for _r, d in rows
                    if _cell_txt(d.get("client section")).split(".")[0].strip().upper() in keys]
        comps.append(("every live section rendered as a reconciliation row",
                      1 if len(sec_rows) == len(secs) else 0, 1))
        if cons < len(secs):
            others = sorted({str(s.get("status")) for s in secs
                             if s.get("status") not in _PASSING})
            iss.append(f"{len(secs) - cons} client-offer section(s) not consistent "
                       f"({', '.join(others)}) — mirrored as HOLDS")
    if not comps:
        # ZERO-CHECK GUARD (2026-07-20, Pillar 3 / Cursor P0.3): the Brief tab ran NO
        # content checks (no client-offer reconciliation sections/rows), so the only
        # thing left is _merge_content's generic "cell completeness+type contract" —
        # populated cells, which would mint a 10 on a tab that verified NOTHING (the
        # 2150 Brief=10/checked:0 Goodhart). A populated-but-unverified Brief cannot be
        # a genuine ≥8 "wow": cap ≤4 with an honest issue so the engine is forced to run
        # a real brief↔design fidelity check to earn the score. Universal (fires on any
        # run whose Brief scorer found nothing to reconcile), no per-class table.
        return {"components": [], "issues": [
            "brief scorer ran ZERO content checks — no client-offer reconciliation to "
            "verify the engine's structured interpretation against the original brief; "
            "a populated Brief tab is not a verified one"],
            "score_cap": 4.0,
            "mech": "client-offer reconciliation (live section mapping) — 0 checks available",
            "fix": "emit a brief↔contract fidelity reconciliation so the Brief tab verifies "
                   "the design honours every stated brief constraint"}
    # Basis reflects what actually ran: client-offer reconciliation (plant briefs with a
    # section-cost table) and/or brief↔design constraint fidelity (instrument briefs).
    _mechs = []
    if secs or rows:
        _mechs.append("client-offer reconciliation (live section mapping)")
    if fid:
        _mechs.append("brief↔design constraint fidelity (verification spine, per-constraint "
                      "target vs achieved)")
    return {"components": comps, "issues": iss,
            "mech": " + ".join(_mechs) or "client-offer reconciliation (live section mapping)",
            "fix": ("close the unverified brief constraint(s) on the Verification spine — a "
                    "derived achieved figure per stated target" if any(
                        str(r.get("status")).upper() in ("FAIL", "UNVERIFIED", "OPEN") for r in fid)
                    else "")}


def _sc_verification(wb, ws, state, run_dir):
    """Governing spine score — HARD rows only; any HARD open caps below the SHIPS floor."""
    spine_d = state.get("_verificationSpine")
    if not isinstance(spine_d, dict) or not spine_d.get("rows"):
        spine = build_spine(_assemble_verification_rows(state or {}, run_dir or ""))
        spine_d = spine.as_dict()
        if isinstance(state, dict):
            state["_verificationSpine"] = spine_d
    hard_total = int(spine_d.get("hard_total") or 0)
    hard_open = int(spine_d.get("hard_open") or 0)
    hard_pass = hard_total - hard_open
    sc = float(spine_d.get("score") if spine_d.get("score") is not None
               else score_spine(build_spine(spine_d.get("rows") or [])))
    iss = []
    if hard_open:
        open_claims = [
            str(r.get("claim")) for r in (spine_d.get("rows") or [])
            if str(r.get("hardness")).upper() == "HARD"
            and str(r.get("status")).upper() in ("FAIL", "UNVERIFIED", "OPEN")
        ][:4]
        iss.append(f"{hard_open} HARD claim(s) open: {'; '.join(open_claims)}")
    if hard_total == 0:
        iss.append("vacuous spine (no HARD rows) — cannot stamp SHIPS")
    # DECISION: return an explicit score (not only components) so a HARD-open spine
    # floors at ≤4 even when component arithmetic would otherwise look healthier.
    # GOTCHA: never put the literal "UNVERIFIED" / "cannot verify" in mech/fix —
    # `_apply_universal_honest_cap` scans those as a verification-gap and caps ≤7,
    # which would Goodhart the governing spine (a clean 10 HARD-PASS tab floors at 7).
    return {
        "components": [("HARD claims PASS", hard_pass, hard_total or 1)],
        "issues": iss,
        "mech": ("proof spine (brief + physics + realisation + holds; "
                 "HARD-only; any HARD open caps at most 4)"),
        "fix": "close every HARD open claim on the Verification tab "
               "(FAIL / not-yet-proven / OPEN)",
        "score": sc,
        "score_cap": sc,
    }


def _sc_quantities(wb, ws, state, run_dir):
    rows = _fam_rows(wb, ws.title, "quantities")
    prov = sum(1 for _r, d in rows
               if not _cell_missing(d.get("source"))
               and not _cell_missing(d.get("where-from"))
               and not _cell_missing(d.get("used by")))
    iss = []
    if rows and prov < len(rows):
        bad = [str(r) for r, d in rows
               if _cell_missing(d.get("where-from")) or _cell_missing(d.get("used by"))][:3]
        iss.append(f"{len(rows) - prov} quantity row(s) missing full provenance "
                   f"(where-from / used-by), e.g. rows {', '.join(bad)}")
    return {"components": [("provenance-verified quantity rows", prov, len(rows))],
            "issues": iss, "mech": "quantity provenance (source + where-from + used-by per row)",
            "fix": "author the missing where-from/used-by provenance at the quantity emitter"}


def _sc_calculations(wb, ws, state, run_dir):
    comps = []
    iss = []
    wc_rows = _fam_rows(wb, ws.title, "worked-calc")
    # BLOCK SEMANTICS: a DEFINITION row (unindented label + formula text, value empty) is
    # resolved by its trailing '= result' row carrying the computed value; INPUT rows are
    # the indented rows and must carry their value. A definition with no valued result row
    # is an unresolved worked calc — the fault Tristan's coverage fraction measures.
    #
    # NO-CHEATING (Tristan 2026-07-06): carrying a value is NOT enough — a hardcoded
    # number in col B scored 10/10 while the tab's own banner claimed 'every value
    # recomputed live'. A result row only resolves when
    # _worked_calc_result_is_live_or_disclosed() is true: col B is a GENUINE Excel
    # formula ('=…', starts with '='), OR the row's own label HONESTLY discloses it
    # isn't (a standards-table pick / non-numeric substitution) via the shared
    # _DISCLOSED_NONLIVE_MARK sentinel — the SAME predicate tab_calculations uses to
    # decide what to write, so renderer and scorer can never disagree. A row that merely
    # LOOKS resolved (has a bare static number, no disclosure) FAILS here. proveCatch in
    # _selftest, both directions.
    #
    # 'formula' / 'substitution' are RESERVED echo-labels the legacy-calc writer uses to
    # restate the title row's own formula text for readability — they carry the SAME col-D
    # content as a genuine definition row but are NOT the start of a new calc; excluding
    # them by literal label is what stops every legacy calc inflating n_def by 3x with
    # spurious unresolved entries (that bug pre-dates and is orthogonal to the live-formula
    # one, but the same audit surfaced it).
    _ECHO_LABELS = {"formula", "substitution"}
    n_def = n_def_ok = n_in = n_in_ok = 0
    pending_def = None
    unresolved = []
    for _r, d in wc_rows:
        raw = d.get("calc / input")
        label = _cell_txt(raw)
        indented = isinstance(raw, str) and raw.startswith("  ")
        has_val = not _cell_missing(d.get("value"))
        if (not indented and not _cell_missing(d.get("formula"))
                and label.lower() not in _ECHO_LABELS):
            if pending_def is not None:
                unresolved.append(pending_def)
            n_def += 1
            if has_val:            # single-row calc: value on the definition row
                _live_ok = _worked_calc_result_is_live_or_disclosed(raw, d.get("value"))
                n_def_ok += 1 if _live_ok else 0
                if not _live_ok:
                    unresolved.append(label + " (hardcoded — not a live formula)")
                pending_def = None
            else:
                pending_def = label
            continue
        if indented and label.startswith("="):
            if pending_def is not None:
                _live_ok = has_val and _worked_calc_result_is_live_or_disclosed(raw, d.get("value"))
                n_def_ok += 1 if _live_ok else 0
                if not _live_ok:
                    unresolved.append(pending_def if not has_val
                                       else pending_def + " (hardcoded — not a live formula)")
                pending_def = None
            continue
        if indented:
            n_in += 1
            if has_val:
                n_in_ok += 1
    if pending_def is not None:
        unresolved.append(pending_def)
    if n_def:
        comps.append(("worked-calc definitions resolve to a LIVE computed result", n_def_ok, n_def))
        if n_def_ok < n_def:
            iss.append(f"{n_def - n_def_ok} worked calc(s) never resolve to a live/disclosed "
                       f"result — e.g. {', '.join(u[:60] for u in unresolved[:3])}")
    if n_in:
        comps.append(("calc input rows carry their value", n_in_ok, n_in))
    tf_rows = _fam_rows(wb, ws.title, "tool-flow")
    if tf_rows:
        ok = sum(1 for _r, d in tf_rows if "⚠" not in _cell_txt(d.get("status")))
        comps.append(("tool outputs consumed downstream", ok, len(tf_rows)))
    # DUTY COVERAGE (2026-07-10 Tristan/Grok false-ship review: 'one calculation cannot
    # score 10 when required duties are absent'). The contract's calculator-sourced
    # quantities are the duties this tab EXISTS to show worked; a tab with a handful of
    # resolved calcs over dozens of calculator quantities is thin regardless of how clean
    # those few are. Coverage floor: >=1 worked calc per 4 calculator quantities (a calc
    # legitimately covers several related quantities), floored at 3.
    try:
        _qq = ((state.get("orchestratorContract") or {}).get("quantities") or {})
        _n_calc_q = sum(1 for _v in _qq.values()
                        if isinstance(_v, dict) and str(_v.get("source")) == "calculator"
                        and _v.get("value") is not None)
        if _n_calc_q >= 4:
            _need = max(3, _n_calc_q // 4)
            comps.append(("worked-calc coverage of the contract's calculator duties "
                          f"(≥{_need} calcs for {_n_calc_q} calculator quantities)",
                          min(n_def, _need), _need))
            if n_def < _need:
                iss.append(f"only {n_def} worked calc(s) shown for {_n_calc_q} calculator-derived "
                           f"contract quantities — the duties exist; render their derivations "
                           f"(need ≥{_need})")
    except Exception:  # noqa: BLE001
        pass
    return {"components": comps, "issues": iss,
            "mech": "worked-calc coverage (every definition resolves to a LIVE Excel formula "
                    "or an honestly-disclosed non-arithmetic pick; inputs populated) + "
                    "tool-flow consumption + duty coverage vs the contract's calculator quantities",
            "fix": "bind the RHS's symbols to this block's own input cells at the calc "
                   "renderer source (formula_to_excel), or honestly disclose the pick"}


def _sc_waterfall(wb, ws, state, run_dir):
    comps = []
    iss = []
    cs = state.get("costStack") or {}
    rows = _fam_rows(wb, ws.title, "waterfall")
    tied = 0
    for _r, d in rows:
        basis = _cell_txt(d.get("basis / derivation"))
        anchors = re.findall(r"[a-z][a-z0-9_]*_gbp", basis)
        step = d.get("step £")
        run = d.get("running total £")
        val = _num_of(step)
        got = None
        for a in anchors:
            av = cs.get(a)
            if isinstance(av, (int, float)):
                got = float(av)
                break
        if isinstance(step, str) and _cell_txt(step).startswith("="):
            tied += 1        # a live link/sum to its source cells IS the tie
        elif step in (None, "") and isinstance(run, str) and _cell_txt(run).startswith("="):
            tied += 1        # MILESTONE row ('= Factory COGS'): running total live-chains
        elif got is not None and val is not None and abs(val - got) <= max(1.0, abs(got) * 0.02):
            tied += 1
        elif got is not None and val is not None:
            iss.append(f"waterfall row {_r}: step £{val:,.0f} ≠ its costStack anchor £{got:,.0f}")
    if rows:
        comps.append(("waterfall rows tie live to their stated costStack anchor", tied, len(rows)))
    cf_rows = _fam_rows(wb, ws.title, "class-factors")
    if cf_rows:
        live = sum(1 for _r, d in cf_rows
                   if isinstance(d.get("assembly £"), str)
                   and _cell_txt(d.get("assembly £")).startswith("=")
                   and isinstance(d.get("install £"), str)
                   and _cell_txt(d.get("install £")).startswith("="))
        comps.append(("assembly/install rows computed live from their factors", live, len(cf_rows)))
        subs = [v for v in (_num_of(d.get("bom subtotal £")) for _r, d in cf_rows) if v is not None]
        anchor = None
        for k in ("raw_materials_bom_gbp", "bom_total_gbp"):
            if isinstance(cs.get(k), (int, float)) and cs.get(k):
                anchor = float(cs[k])
                break
        if anchor and subs:
            ok = 1 if abs(sum(subs) - anchor) <= max(1.0, anchor * 0.02) else 0
            comps.append(("Σ class subtotals ≈ the BoM materials total", ok, 1))
            if not ok:
                iss.append(f"Σ class subtotals £{sum(subs):,.0f} ≠ BoM materials total £{anchor:,.0f}")
    return {"components": comps, "issues": iss,
            "mech": "cost-waterfall arithmetic ties (each step vs its named costStack anchor; sums close)",
            "fix": "fix the mismatching step at the cost-stack source it names"}


def _is_input_fill(cell) -> bool:
    try:
        rgb = getattr(cell.fill.start_color, "rgb", None) or ""
        return str(rgb)[-6:] in ("FFF2CC", "FCE4D6")   # editable input / shared constant
    except Exception:  # noqa: BLE001
        return False


_FIN_FAMILIES = ("fin-item", "fin-lines", "fin-cashflow", "fin-opex", "fin-scenarios",
                 "fin-curve", "fin-chart", "fin-range", "fin-tornado", "fin-recommend",
                 "fin-oppoint", "fin-instrument")


def _sc_financial(wb, ws, state, run_dir):
    comps = []
    iss = []
    checked = passed = 0
    orphan_rows = []

    # ── FRAME-VALIDITY CHECK (isInstrumentDevice — the device-scale-regime leak) ──
    # A benchtop instrument must present the instrument capital-cost summary frame
    # (BoM → COGS → ex-works → list price + "LCOE not applicable" note).  If the
    # Financial model tab still contains a "LEVELISED COST" row or an "Annual delivered
    # volume" row, the plant LCOE frame leaked onto a bench device — FRAME DEFECT.
    # Formula integrity (the only prior check) cannot catch this: cells can reference
    # drivers correctly AND still present the wrong economic frame.
    is_instrument = bool(state.get("isInstrumentDevice"))
    if is_instrument:
        _all_cell_texts = [
            str(c.value) for row in ws.iter_rows() for c in row
            if c.value is not None and not isinstance(c.value, (int, float))
        ]
        _has_lcoe = any("LEVELISED COST" in t or "Annual delivered volume" in t
                        for t in _all_cell_texts)
        _has_capital_summary = (
            bool(state.get("_instrumentCapital"))
            or any("CAPITAL COST SUMMARY" in t or "CAPITAL INSTRUMENT" in t
                   or "one-off build cost" in t for t in _all_cell_texts)
        )
        comps.append(("instrument frame: capital cost summary present (not a plant LCOE)",
                      1 if _has_capital_summary else 0, 1))
        if not _has_capital_summary:
            iss.append("isInstrumentDevice=True but the Financial model tab does not present "
                       "a capital cost summary — the instrument capital frame is missing")
        comps.append(("instrument frame: no plant LCOE / 'Annual delivered volume' row",
                      0 if _has_lcoe else 1, 1))
        if _has_lcoe:
            iss.append("isInstrumentDevice=True but the Financial model tab contains a "
                       "'LEVELISED COST' or 'Annual delivered volume' row — the plant LCOE "
                       "frame must not appear on a bench-scale instrument (category error: "
                       "working volume ≠ annual production volume; fix: _render_instrument_"
                       "capital_section must replace _render_cost_of_service_section)")
        return {"components": comps, "issues": iss,
                "mech": "frame validity (instrument capital summary present; no plant LCOE frame) "
                        "+ formula integrity",
                "fix": "ensure tab_financial_model dispatches isInstrumentDevice=True to "
                       "_render_instrument_capital_section and never to _render_cost_of_service_section"}

    hdr_rows = {tt["row"] for tt in _RENDERED_TABLES if tt["sheet"] == ws.title}
    for fam in _FIN_FAMILIES:
        for t in _tables_of(wb, ws.title, fam):
            norm = [_norm_col(c) for c in t["cols"]]
            money_idx = [i for i, c in enumerate(norm)
                         if re.search(r"£|capex|revenue|opex|ebitda|npv|cashflow|value|swing|"
                                      r"low|central|high", c)]
            for r, vals in _walk_rows(ws, t["row"], len(t["cols"]), hdr_rows):
                for i in money_idx:
                    v = vals[i]
                    if v in (None, ""):
                        continue
                    if isinstance(v, str) and not v.startswith("=") and _num_of(v) is None:
                        continue   # text notes are the cell-contract's business
                    checked += 1
                    cell = ws.cell(r, i + 1)
                    if isinstance(v, str) and v.startswith("="):
                        passed += 1
                    elif _is_input_fill(cell) or _is_tool_node_cell(cell):
                        passed += 1
                    else:
                        if len(orphan_rows) < 4:
                            orphan_rows.append(f"row {r} col {i + 1}")
    if checked:
        comps.append(("model value cells are live formulas or declared (yellow) inputs",
                      passed, checked))
        if passed < checked:
            iss.append(f"{checked - passed} orphan numeric literal(s) in the financial model "
                       f"(e.g. {', '.join(orphan_rows)}) — a model number must be driven, not typed")
    return {"components": comps, "issues": iss,
            "mech": "formula integrity (cells reference drivers; no orphan literals) + scenario arithmetic (live)",
            "fix": "drive the orphan literals from the Inputs & Assumptions drivers"}


def _sc_connection(wb, ws, state, run_dir):
    comps = []
    iss = []
    tags = set()
    for sheet, fam, col in ((_LEDGER_SHEET, "bom-ledger", "tag"),
                            ("Part names", "part-names", "tag")):
        if sheet in wb.sheetnames:
            for _r, d in _fam_rows(wb, sheet, fam):
                for tok in _TAG_TOKEN_RX.findall(_cell_txt(d.get(col))):
                    tags.add(tok)
    n_ep = n_ok = 0
    rows = _fam_rows(wb, ws.title, "connection") + _fam_rows(wb, ws.title, "connection-housed")
    for _r, d in rows:
        for key in ("inputs ←", "outputs →"):
            for tok in _TAG_TOKEN_RX.findall(_cell_txt(d.get(key))):
                n_ep += 1
                if tok in tags:
                    n_ok += 1
    if n_ep:
        comps.append(("endpoint tags resolve to a real BoM/part tag", n_ok, n_ep))
        if n_ok < n_ep:
            iss.append(f"{n_ep - n_ok} connection endpoint(s) reference a tag no BoM/part row carries")
    # Status (col C) is now a LIVE formula (Tristan 2026-07-03 — the bare-'OK' fix), so
    # `d.get("status")` here would be the pre-recalc FORMULA TEXT, not the computed
    # word — reading it for pass/fail would silently score every row "clean" (no
    # cell here ever literally contains "⚠"). Read the SAME embedded operands the
    # formula itself judges (cols G/H, written alongside col C in tab_connection_trace)
    # so this scorer's verdict can never disagree with the workbook's own formula.
    st_rows = [(_r, d) for _r, d in rows if "status" in d]
    if st_rows:
        ok = 0
        for _r, _d in st_rows:
            _unresolved = ws.cell(_r, 7).value
            _evidence = _cell_txt(ws.cell(_r, 8).value)
            if isinstance(_unresolved, (int, float)) and _unresolved == 0 and not _evidence.strip():
                ok += 1
        comps.append(("connection rows carry a computed OK status "
                      "(0 unresolved endpoints, no missing-tie evidence)", ok, len(st_rows)))
    # LOAD-BEARING CONNECTIVITY EVIDENCE (2026-07-10 Tristan/Grok false-ship review): the
    # parts-ledger RECORDS connectivity concerns (an electrical part with no downstream
    # load) + stale topology ties every run, and run 54 shipped 9.1 over 5 concerns + 2
    # stale ties. Recorded-but-unscored evidence is exactly the false-green mechanism —
    # each concern/stale tie is now a failing component of this tab's own contract.
    # DECISION (2026-07-14 colorimeter 1441): score PROPORTIONATELY against the
    # equipment count — never a cliff of 0/N_concerns. One false orphan_instrument
    # on a consumable floored the whole tab to 0/10 while every Status cell said
    # ✓ OK (the concern never appeared as a row). Proportionate scoring matches
    # Part names' orphan/not-found check; the issue text still names the exact tag.
    try:
        _pl2 = load_json(os.path.join(run_dir, "parts-ledger.json")) or {}
        _cc = (_pl2.get("connectivity") or {}) if isinstance(_pl2, dict) else {}
        _n_conc = int(_cc.get("n_concerns") or 0)
        _n_stale = int(_pl2.get("n_stale_ties") or 0)
        _n_fail = _n_conc + _n_stale
        _n_eq = int(_pl2.get("n_equipment") or 0) or max(len(st_rows), 1)
        if _n_fail:
            comps.append(("ledger connectivity clean (no unconnected electrical parts, "
                          "no stale topology ties)",
                          max(0, _n_eq - _n_fail), _n_eq))
            _ex = "; ".join(f"{c.get('tag')} {c.get('name')}: {c.get('issue')}"
                            for c in (_cc.get("concerns") or [])[:3])
            iss.append(f"parts-ledger records {_n_conc} connectivity concern(s) + "
                       f"{_n_stale} stale topology tie(s) — e.g. {_ex} "
                       f"(WHY this tab is below 10: score = min over checks; "
                       f"connectivity {_n_eq - _n_fail}/{_n_eq})")
        else:
            comps.append(("ledger connectivity clean (no unconnected electrical parts, "
                          "no stale topology ties)", 1, 1))
        # INTENT (2026-07-14): gold-spine Connection trace showed ~7 rows while the
        # ledger still carried 52 ghost plant-style connections — scoring 10 on the
        # filtered table alone is Goodhart. Cap when the ledger dwarfs the sheet.
        _n_led_cx = len(_pl2.get("connections") or [])
        _n_rows = max(len(st_rows), len(rows), 1)
        if _n_led_cx >= 20 and _n_led_cx > _n_rows * 3:
            comps.append((
                "rendered connection rows cover the ledger (no ghost majority)",
                _n_rows, min(_n_led_cx, _n_rows * 3),
            ))
            iss.append(
                f"Connection trace renders {_n_rows} row(s) but parts-ledger still "
                f"lists {_n_led_cx} connections — ghost topology dominates; prune "
                f"ledger to gold-spine principals or expand the sheet"
            )
    except Exception:  # noqa: BLE001
        pass
    return {"components": comps, "issues": iss,
            "mech": "resolved-endpoint fraction (every ← / → tag must exist) + per-row status "
                    "+ ledger connectivity concerns/stale ties (proportionate vs equipment count) "
                    "+ ledger-vs-rendered connection coverage",
            "fix": "fix the topology edge / parts_ledger connectivity classifier "
                    "(orphan_instrument must not fire on consumables; device MCU counts as control); "
                    "prune ghost ledger connections after gold-spine bake"}


def _sc_partnames(wb, ws, state, run_dir):
    comps = []
    iss = []
    rows = _fam_rows(wb, ws.title, "part-names")
    tag_lists = [_TAG_TOKEN_RX.findall(_cell_txt(d.get("tag"))) for _r, d in rows]
    all_tags = [t for lst in tag_lists for t in lst]
    dupes = sorted({t for t in all_tags if all_tags.count(t) > 1})
    comps.append(("part tags unique (each physical thing named once)",
                  len(all_tags) - sum(all_tags.count(t) - 1 for t in dupes), len(all_tags)))
    if dupes:
        iss.append(f"duplicate tag(s) on the master: {', '.join(dupes[:4])}")
    master_tags = set()
    for _r, d in rows:
        master_tags |= _expand_tags(_cell_txt(d.get("tag")))
    ledger_tags = set()
    if _LEDGER_SHEET in wb.sheetnames:
        for _r, d in _fam_rows(wb, _LEDGER_SHEET, "bom-ledger"):
            if _cell_txt(d.get("item")).startswith("↳"):
                continue      # ↳ children are components of a principal — the master is principals-only
            if _cell_txt(d.get("item")).startswith("='Part names'"):
                continue      # the Item cell live-references its master row — traced by construction
            ledger_tags |= _expand_tags(_cell_txt(d.get("tag")))
    ledger_mpn: Dict[str, str] = {}
    if _LEDGER_SHEET in wb.sheetnames:
        # a ledger row's Tag/Item cells are often a LIVE '='Part names'!$A$29' reference
        # (traced by construction) rather than a literal tag string — resolve it back to
        # the actual value on the already-built Part names sheet before tag-matching, or
        # every such row's tags would (wrongly) expand to nothing.
        _pn_ref_rx = re.compile(r"^='Part names'!\$?([A-Z]+)\$?(\d+)$")
        def _resolved_txt(raw) -> str:
            m = _pn_ref_rx.match(str(raw or ""))
            if m and "Part names" in wb.sheetnames:
                col, rown = m.group(1), int(m.group(2))
                return str(wb["Part names"][f"{col}{rown}"].value or "")
            return _cell_txt(raw)
        for _r, d in _fam_rows(wb, _LEDGER_SHEET, "bom-ledger"):
            if _resolved_txt(d.get("item")).startswith("↳"):
                continue
            mpn_txt = _cell_txt(d.get("mpn / datasheet"))
            for t in _expand_tags(_resolved_txt(d.get("tag"))):
                ledger_mpn[t] = mpn_txt
    if ledger_tags:
        have = master_tags
        present = sum(1 for t in sorted(ledger_tags) if t in have)
        comps.append(("every BoM-ledger tag present on the master", present, len(ledger_tags)))
        if present < len(ledger_tags):
            missing = sorted(ledger_tags - have)[:4]
            iss.append(f"{len(ledger_tags) - present} ledger tag(s) missing from the master: "
                       + ", ".join(missing))
    # 9/10 CAMPAIGN (2026-07-04): three new checks, min-combined with the above.
    # (1) MPN or an HONEST status on every principal — read back from the SAME ledger
    #     cells the sheet's own live INDEX/MATCH formula resolves to; a bare 'TBD' /
    #     '—' fails, a real MPN or an explicit 'TBD (…reason…)' passes.
    # HONEST-STATUS FALLBACK (codema v74 Z-102/Z-103, 2026-07-05): a principal whose
    # ledger MPN cell is blank is not automatically a research gap — parts_ledger.py
    # already classifies WHY a part carries no catalogue MPN (commit 3dea8ca8a): a
    # MERGED·SYNONYM row is a de-duplicated twin whose identity/MPN lives on the
    # sibling physical part it was folded into, and a 'NOT FOUND' row may carry an
    # honest not_found_status sub-verdict — ARCHITECTURALLY-EXCLUDED (membrane/media
    # class, no catalogue identity BY DESIGN), OEM-PROPRIETARY (a recorded finding
    # that no public part number exists) or FABRICATED (a materials take-off, no
    # catalogue identity by nature). We READ that SAME classification from
    # parts-ledger.json (never re-derived here, so the two surfaces cannot disagree);
    # a bare 'NOT FOUND' with no honest sub-status — the true residual gap — still
    # fails, exactly as it does today (proveCatch both directions in _selftest).
    # 2026-07-04 one-truth name-family split (parts_ledger.py fix 2) adds three more
    # honest sub-statuses, read from the SAME parts-ledger.json field — never re-derived
    # here: COMMODITY-FITTING (a bare accessory/fastener/fitting, no catalogue identity
    # by nature — mirrors ga_massing.GA_NON_MASSING_RE), BOUNDARY-STUB (a bare process
    # connection endpoint, not a catalogue part), SCOPE-DOCUMENTED (a design/system/
    # network LABEL, not a single purchasable item). VERIFIED_NO_PUBLIC_MPN (2026-07-05,
    # the bess-campaign-v11 17-not-found dissection) — parts_ledger.py's _not_found_substatus
    # stamps this ONLY when the row's OWN verification record (state.partVerifications)
    # carries the literal status 'verified_no_public_mpn' — a genuinely EXHAUSTIVE search
    # (never a single rejected candidate) found no public manufacturer part number. Read
    # from the SAME one-truth field as every other entry in this set — never re-derived.
    _HONEST_NOT_FOUND_SUBSTATUS = {"ARCHITECTURALLY-EXCLUDED", "OEM-PROPRIETARY", "FABRICATED",
                                   "COMMODITY-FITTING", "BOUNDARY-STUB", "SCOPE-DOCUMENTED",
                                   "VERIFIED_NO_PUBLIC_MPN"}
    _pl_honest = load_json(os.path.join(run_dir, "parts-ledger.json")) if run_dir else None
    _pl_status_by_tag: Dict[str, dict] = {}
    if isinstance(_pl_honest, dict) and _pl_honest.get("equipment"):
        for _e in _pl_honest["equipment"]:
            if isinstance(_e, dict) and _e.get("tag"):
                _pl_status_by_tag[str(_e["tag"])] = _e

    def _honest_status_text(tag: str) -> str:
        """A short, human-readable HONEST reason this tag carries no MPN — '' when
        the ledger records no such reason (a genuine gap)."""
        e = _pl_status_by_tag.get(tag) or {}
        status = str(e.get("status") or "")
        nf_sub = str(e.get("not_found_status") or "")
        basis = str(e.get("basis") or "").strip()
        if status == "MERGED·SYNONYM":
            return f"MERGED·SYNONYM — {basis}" if basis else "MERGED·SYNONYM"
        if nf_sub in _HONEST_NOT_FOUND_SUBSTATUS:
            return f"{nf_sub} — {basis}" if basis else nf_sub
        return ""

    if all_tags:
        _principal_tags = sorted({t for lst in tag_lists for t in lst})
        n_mpn_ok = 0
        _mpn_missing = []
        for t in _principal_tags:
            v = ledger_mpn.get(t, "")
            if v and not _PLACEHOLDER_RX.match(v.strip()) and v.strip().upper() != "TBD":
                n_mpn_ok += 1
            elif _honest_status_text(t):
                n_mpn_ok += 1
            else:
                _mpn_missing.append(t)
        comps.append(("every principal carries an MPN or an honest TBD status",
                      n_mpn_ok, len(_principal_tags)))
        if _mpn_missing:
            iss.append(f"{len(_mpn_missing)} principal(s) with no MPN and no honest status: "
                       + ", ".join(_mpn_missing[:4]))
    # (2)+(3) CROSS-LINKED, zero orphans BOTH directions — every master tag traces to
    # >=1 drawing/manifest reference (parts-ledger.json's own per-tag coverage), and
    # the ledger's OWN orphan/not-found lists are empty. parts_ledger.py already
    # computes this per-tag; this is a CONSUMER of that JSON, never a re-derivation.
    pl = load_json(os.path.join(run_dir, "parts-ledger.json")) if run_dir else None
    if isinstance(pl, dict) and pl.get("equipment"):
        eq_by_tag = {str(e.get("tag")): e for e in pl["equipment"] if isinstance(e, dict) and e.get("tag")}
        # RANGE-TAG EXPANSION (2026-07-05 valve/instrument-recon fix): a ledger equipment row
        # is often keyed by a COMBINED range tag ('LT-201–213' for 13 physically-replicated
        # level transmitters, 'FCV-201–202' for 2 control valves) — the SAME range grammar
        # _expand_tags() already expands for the Part names master's own tag column. Without
        # this, every INDIVIDUAL tag the master expands from that same range (LT-201, LT-202,
        # ... LT-213) misses the exact-string lookup here and reads as "not shown on any
        # drawing" even though the combined tag's OWN coverage is genuinely True on the P&ID
        # — a false negative in the matcher, not a real gap. Filled ADDITIVELY (setdefault)
        # so a literal per-tag ledger entry that already exists is never overridden.
        for _e in pl["equipment"]:
            if not isinstance(_e, dict):
                continue
            _etag = str(_e.get("tag") or "")
            if not _etag:
                continue
            for _t in _expand_tags(_etag):
                eq_by_tag.setdefault(_t, _e)
        _principal_tags = sorted({t for lst in tag_lists for t in lst})
        _linked = 0
        _unlinked = []
        _takeoff_exempt = 0
        for t in _principal_tags:
            e = eq_by_tag.get(t)
            # PARAMETRIC TAKE-OFF EXEMPTION (2026-07-04, the X-146/X-152 thread): a network
            # take-off row ('Zoned distribution — …', 'Hand watering — ring main …' — qty in
            # metres, priced as an engineered allowance) is not a taggable drawing OBJECT; it is
            # a quantity, not a placeable thing. parts_ledger.py marks every row in this family
            # with the distinct status "PARAMETRIC" (never used for a real discrete part) and,
            # via ga_massing.is_ga_non_massing(), already computes an EMPTY `expected` list for
            # every one of them — "expected nowhere" is the honest, correct state, not a gap.
            # Exempt from the cross-link check entirely (same "out-of-scope, not penalised"
            # idiom as HVAC's disclosed-scope cap) rather than counting "shown nowhere" as a
            # failure the drawing generators can never satisfy. A real discrete part (anything
            # NOT status=PARAMETRIC) is untouched — still expected + still scored.
            #
            # EXPECTED-NOWHERE EXEMPTION, widened (2026-07-05, Part names 7.6 fix): PARAMETRIC
            # status was only ever a PROXY for "parts_ledger.py already computes an empty
            # `expected` list for this row" — but is_ga_non_massing()/is_pure_documentation()
            # also zero `expected` for plenty of NON-PARAMETRIC accessory rows (mounting/
            # termination hardware that lives on an already-drawn parent, never its own
            # object): TX-102 transformer neutral grounding, TX-105 transformer cable sealing
            # end, X-40 fuse holder, X-42 fuse mount rail all landed as false "not shown on ANY
            # drawing/manifest" gaps despite parts_ledger.py's own ledger already recording
            # expected=[] for each. Read `expected` directly — it is the ledger's own
            # authoritative verdict, universal, no per-tag table — rather than the narrower
            # PARAMETRIC-status proxy.
            _exp = (e or {}).get("expected")
            if (e or {}).get("status") == "PARAMETRIC" or (isinstance(_exp, list) and len(_exp) == 0):
                _takeoff_exempt += 1
                continue
            # Field instruments / actuators / commodity fittings / membrane packs
            # are often schedule-only or non-massed. Missing them on a GA/3D view
            # is not a ship-blocker for principal plant equipment. Also exempt
            # tags with no ledger row (accessory masters) — only score massed
            # principals that the ledger expected on a drawing.
            _etype = str((e or {}).get("type") or "").lower()
            _ename = str((e or {}).get("name") or t or "").lower()
            if e is None:
                _takeoff_exempt += 1
                continue
            if _etype in ("instrument", "valve", "actuator", "fitting", "commodity"):
                _takeoff_exempt += 1
                continue
            if re.search(r"\bsensor\b|\btransmitter\b|\banalys|\bmeter\b|\bgland\b|"
                         r"\bfitting\b|\bspacer\b|\bcable\b|\bmembrane\b|\bhousing\b",
                         _ename):
                _takeoff_exempt += 1
                continue
            cov = (e or {}).get("coverage") or {}
            if isinstance(cov, dict) and any(bool(v) for v in cov.values()):
                _linked += 1
            else:
                _unlinked.append(t)
        _scored_tags = len(_principal_tags) - _takeoff_exempt
        if _scored_tags:
            comps.append(("master tags cross-linked to >=1 drawing/manifest reference",
                          _linked, _scored_tags))
            if _unlinked:
                iss.append(f"{len(_unlinked)} master tag(s) not shown on ANY drawing/manifest: "
                           + ", ".join(_unlinked[:4]))
        orphans = [o for o in (pl.get("orphan_equipment") or []) if o]
        not_found = [o for o in (pl.get("not_found") or []) if o]
        n_bad = len(orphans) + len(not_found)
        n_eq = int(pl.get("n_equipment") or len(pl.get("equipment") or [])) or 1
        # PROPORTIONATE, not a binary cliff (consistent with every other check in this
        # file): a design with 1 stray orphan is not equivalent to one with 50 — both
        # differ honestly from a genuinely clean parts-ledger reconciliation.
        comps.append(("parts-ledger equipment free of orphan/not-found status",
                      max(0, n_eq - n_bad), n_eq))
        if n_bad:
            iss.append(f"parts-ledger: {len(orphans)} orphan + {len(not_found)} not-found "
                       f"equipment item(s) — {', '.join(str(o) for o in (orphans + not_found)[:4])}")
    return {"components": comps, "issues": iss,
            "mech": "dedupe + completeness (every BoM tag present exactly once) + "
                    "cross-link + MPN/status coverage (parts-ledger.json)",
            "fix": "fix the master merge / tag registry at tab_parts_master source"}


def _sc_glossary(wb, ws, state, run_dir):
    comps = []
    iss = []
    merged = _merged_spans(ws)
    terms = []
    for r in range(4, ws.max_row + 1):
        if merged.get(r, 0) >= 2:
            continue
        term = _cell_txt(ws.cell(r, 1).value)
        if not term:
            continue
        terms.append((r, term, _cell_txt(ws.cell(r, 2).value)))
    defined = sum(1 for _r, _t, m in terms if m)
    comps.append(("every rendered term carries a definition", defined, len(terms)))
    if defined < len(terms):
        iss.append("undefined term(s): "
                   + ", ".join(t for _r, t, m in terms if not m)[:120])
    # orphan terms: defined here but appearing nowhere else in the workbook
    blob = _workbook_text_blob(wb, exclude=ws.title)
    used = 0
    orphans = []
    for _r, t, _m in terms:
        if _term_used_in(t, blob):
            used += 1
        else:
            orphans.append(t)
    comps.append(("terms actually used somewhere in the workbook", used, len(terms)))
    if orphans:
        iss.append(f"{len(orphans)} glossary term(s) never used on any tab (orphans): "
                   + ", ".join(orphans[:5]))
    return {"components": comps, "issues": iss,
            "mech": "glossary contract (every term defined + no orphan terms)",
            "fix": "drop orphan terms / define the missing ones in _GLOSSARY"}


def _sc_holds(wb, ws, state, run_dir):
    comps = []
    iss = []
    live = _derive_holds(state)
    rows = _fam_rows(wb, ws.title, "holds")
    live_ids = [h["id"] for h in live]
    rend = [(_cell_txt(d.get("hold")), _cell_txt(d.get("item"))) for _r, d in rows]
    matched = 0
    for i, (rid, ritem) in enumerate(rend):
        if i < len(live_ids) and rid == live_ids[i] \
                and ritem.startswith(str(live[i]["item"])[:40]):
            matched += 1
    total = max(len(live_ids), len(rend)) if (live_ids or rend) else 0
    if total:
        comps.append(("rendered holds match the LIVE re-derivation (stale hold = fail)",
                      matched, total))
        if matched < total:
            iss.append(f"{total - matched} hold(s) diverge from the live re-derivation — "
                       "a cleared condition may not still hold / a new condition must appear")
    else:
        comps.append(("live re-derivation agrees no holds are open (0 = 0)", 1, 1))
    # INTENT (2026-07-14, G13 / gold honesty): an open hold register is NOT a clean
    # 10. Matching the live derivation proves the list is current — it does not
    # prove the design is hold-free. Soft-caveat issue triggers universal honest
    # cap (≤8 / never-10) without flooring the tab at 0 via a 0/1 component.
    if live:
        # GOTCHA: do NOT prefix with "ADVISORY:" — _VERIF_GAP_RX matches that and
        # hard-caps the tab at 7 (the Renders false-FAIL class of bug). Open holds
        # are already priced by the never-perfect-10 / identified-failure path (≤9.9).
        iss.append(
            f"{len(live)} open hold(s) remain — never a perfect 10 until every hold "
            "clears at source (does not score: already priced by the never-perfect-10 rule)"
        )
    return {"components": comps, "issues": iss,
            "mech": "live-derivation check (each hold re-derived from the current contract results)",
            "fix": "rebuild — the register renders only what the live evaluation derives"}


def _sc_inputs(wb, ws, state, run_dir):
    comps = []
    iss = []
    rows = _fam_rows(wb, ws.title, "drivers")
    refd_rows = set()
    rx = re.compile(r"'" + re.escape(INPUTS_SHEET) + r"'!\$?B\$?(\d+)")
    for other in wb.worksheets:
        for row in other.iter_rows(values_only=True):
            for v in row:
                if isinstance(v, str) and v.startswith("="):
                    for m in rx.finditer(v):
                        refd_rows.add(int(m.group(1)))
    refd = sum(1 for r, _d in rows if r in refd_rows)
    if rows:
        comps.append(("drivers referenced by a live formula somewhere", refd, len(rows)))
        if refd < len(rows):
            unrefd = [_cell_txt(d.get("driver")) for r, d in rows if r not in refd_rows][:4]
            iss.append(f"{len(rows) - refd} driver(s) never referenced by any live formula "
                       f"(orphan inputs): {', '.join(unrefd)}")
    return {"components": comps, "issues": iss,
            "mech": "driver integrity (every input driver consumed by a live formula)",
            "fix": "wire the orphan driver into the model or remove it"}


def _sc_benchmark(wb, ws, state, run_dir):
    comps = []
    iss = []
    rows = _fam_rows(wb, ws.title, "benchmark-dims")
    if rows:
        ok = sum(1 for _r, d in rows
                 if not re.search(r"radical|⚠", _cell_txt(d.get("verdict")), re.I))
        comps.append(("benchmark dimensions within the expectation envelope", ok, len(rows)))
        if ok < len(rows):
            iss.append(f"{len(rows) - ok} dimension(s) flagged vs the independent top-down "
                       "expectation (gate 36)")
    bd = state.get("benchmarkDivergence") or {}
    if bd:
        radical = bool(bd.get("needs_full_check"))
        comps.append(("gate-36 verdict is not RADICAL", 0 if radical else 1, 1))
        if radical:
            # a failing check MUST say what diverged (flag AND route — the run-13
            # Sense-check scored 0 with an EMPTY issues list, leaving the reader
            # nothing to act on). Name each radical dimension with its numbers.
            rad = [f for f in (bd.get("findings") or [])
                   if str(f.get("verdict", "")).lower() == "radical"]
            for f in rad[:4]:
                iss.append(f"[HIGH] gate-36 RADICAL — {f.get('dimension')}: engine "
                           f"{f.get('deterministic')} vs independent expectation "
                           f"{f.get('expected')} ({f.get('ratio')}×). "
                           f"{str(f.get('note') or '')[:160]}")
            if not rad:
                iss.append("[HIGH] gate-36 verdict RADICAL — see benchmark-punchlist.md "
                           "for the routed fault list")
    return {"components": comps, "issues": iss,
            "mech": "generative benchmark sanity net (gate 36): independent top-down LLM "
                    "expectation diffed against the bottom-up engine, per-dimension",
            "fix": "route each flagged dimension to its source rule via benchmark-punchlist.md"}


def _sc_checks(wb, ws, state, run_dir):
    # tolerate_blank_banner: the checks family is ONE logical table split into 7
    # family sub-tables by "r += 1  # spacer between families" — a genuinely blank
    # row — in _render_lib_checks. Scoped to THIS read only (never the generic
    # per-cell-completeness walker) so no other table's boundary detection changes.
    rows = _fam_rows(wb, ws.title, "checks", tolerate_blank_banner=True)
    # the STATUS cells are LIVE formulas (2026-07-03) — their build-time verdicts are the
    # renderer's own fail tally (_forge_fail_labels); the text scan keeps older fixtures
    _fl = getattr(ws, "_forge_fail_labels", None)
    fails = (len(_fl) if isinstance(_fl, list) else
             sum(1 for _r, d in rows if _cell_txt(d.get("status")).upper().startswith("FAIL")))
    cap = 10.0 if fails == 0 else float(max(0, 8 - 2 * fails))
    iss = ([f"{fails} of {len(rows)} deterministic invariants FAIL — "
            f"score = max(0, 8 − 2 × {fails})"] if fails else [])
    return {"components": [("deterministic invariants pass", len(rows) - fails, len(rows))],
            "issues": iss, "score_cap": cap,
            "mech": "fail-count formula: 10 if 0 FAIL else max(0, 8 − 2 × fails)",
            "fix": "fix each failing invariant at its named source"}


def _sc_contents(wb, ws, state, run_dir):
    rows = _fam_rows(wb, ws.title, "contents")
    names = set(wb.sheetnames) - {ws.title}
    ok = sum(1 for _r, d in rows if _cell_txt(d.get("tab")) in names)
    listed = {_cell_txt(d.get("tab")) for _r, d in rows}
    covered = sum(1 for n in sorted(names) if n in listed)
    iss = []
    if covered < len(names):
        iss.append("sheet(s) missing from the index: "
                   + ", ".join(sorted(names - listed)[:4]))
    return {"components": [("index rows point at an existing tab", ok, len(rows)),
                           ("every sheet listed in the index", covered, len(names))],
            "issues": iss, "mech": "index integrity (both directions)", "fix": ""}


def _sc_quality_audit(wb, ws, state, run_dir):
    comps = []
    rows = _fam_rows(wb, ws.title, "qa-tabs")
    if rows:
        ok = sum(1 for _r, d in rows if _cell_txt(d.get("tab")) in _TAB_SCORES)
        comps.append(("per-tab table rows name real scored tabs", ok, len(rows)))
    f_rows = _fam_rows(wb, ws.title, "qa-findings")
    if f_rows:
        named = sum(1 for _r, d in f_rows if not _cell_missing(d.get("check")))
        comps.append(("findings carry their producing check", named, len(f_rows)))
    return {"components": comps, "issues": [],
            "mech": "floor mirror + audit-surface integrity (rows tie to the live scorecard)",
            "fix": ""}


# Drawing / render sheets: the EXISTING upstream mechanism (parts-ledger coverage, litter,
# typed-shape, vision critic, drawing gates) IS the score — the scorer states it in the
# basis with the live counts rather than re-inventing it.
_DRAW_KEYS = [
    (re.compile(r"p&id|^pid$", re.I), "pid",
     "P&ID part-coverage arithmetic (parts_ledger ✓/✗ vs the BoM)"),
    (re.compile(r"block flow|bfd", re.I), "block-flow-diagram",
     "block-flow part-coverage arithmetic (parts_ledger)"),
    # Handheld reader title for GA (2026-07-14) — same ledger key as general-arrangement.
    (re.compile(r"^assembly$", re.I), "general-arrangement",
     "Assembly (=GA) mechanism: parts-ledger coverage × litter × layout-divergence × "
     "typed-shape checks"),
    (re.compile(r"general arrangement|^ga\b", re.I), "general-arrangement",
     "GA mechanism: parts-ledger coverage × default-size litter × layout-divergence × "
     "typed-shape checks"),
    (re.compile(r"^interconnect$", re.I), "interconnect",
     "Interconnect: SVG present + parts-ledger connectivity (zero concerns, instruments "
     "associated)"),
    (re.compile(r"single.line", re.I), "single-line-diagram",
     "single-line part-coverage arithmetic (parts_ledger)"),
    (re.compile(r"isometric", re.I), "isometric-index",
     "isometric part-coverage arithmetic (parts_ledger)"),
    (re.compile(r"render|interior layout|building exterior|^module —", re.I), "blender",
     "render mechanism: parts-ledger coverage × default-size litter × typed-shape × "
     "vision-critic verdict (render-vision-critique.json)"),
    (re.compile(r"hvac", re.I), "hvac",
     "HVAC duty-scoped check: contract duty signal → drawing coverage; no duty → honest "
     "out-of-scope disclosure (capped 8)"),
]


def _sc_drawing(wb, ws, state, run_dir):
    comps = []
    iss = []
    mech = None
    cov = _ledger_coverage(run_dir) if run_dir else {}
    for rx, key, mtext in _DRAW_KEYS:
        if rx.search(ws.title):
            mech = mtext
            # NA-BY-DESIGN (2026-07-11 run 77: the P&ID's honest N/A sheet scored 0 —
            # _cov accepted the marker but THIS content overlay re-derived coverage
            # 0/8 from the ledger and min()'d the tab to 0). A dry electrical product
            # (sealed sub-1 m³ contract) whose drawing DECLARES the N/A has nothing
            # to cover — the expectation, not the drawing, is wrong. ONE rule with
            # _cov: marker + contract signal → full component, no ledger fraction.
            _na_p = os.path.join(run_dir or "", "drawings", f"{key}.svg")
            try:
                if run_dir and os.path.exists(_na_p) \
                        and "NA-BY-DESIGN" in open(_na_p, encoding="utf-8", errors="replace").read():
                    _qs0 = {}
                    for _ck in ("orchestratorContract", "engineeringContract"):
                        _q0 = (state.get(_ck) or {}).get("quantities")
                        if isinstance(_q0, dict) and _q0:
                            _qs0 = _q0
                            break
                    _encl0 = qval(_qs0, "enclosure_volume_m3")
                    if _encl0 and 0 < float(_encl0) < 1.0:
                        comps.append((f"{key} not-applicable-by-design declaration", 1, 1))
                        iss.append(f"{key} N/A BY DESIGN — dry electrical product; "
                                   "coverage expectation waived")
                        break
            except OSError:
                pass
            if key == "interconnect":
                # INTENT (2026-07-14 Tristan): presence alone scored a bird's-nest 10 —
                # layout_metrics (data-layout-ok + interconnect-layout.json) is required.
                _lay = _interconnect_layout_verdict(run_dir or "")
                comps.append(("interconnect layout glanceable (node/edge caps + "
                              "no title overlap)", 1 if _lay.get("ok") else 0, 1))
                if not _lay.get("ok"):
                    iss.append(
                        f"INTERCONNECT UNREADABLE: nodes={_lay.get('n_nodes')} "
                        f"edges={_lay.get('n_edges')} "
                        f"title_overlaps={_lay.get('title_overlaps_content')} "
                        f"— redraw principals-only (draw_interconnect layout_metrics)")
                try:
                    _led = load_json(os.path.join(run_dir or "", "parts-ledger.json")) or {}
                    _cx = _led.get("connectivity") or {}
                    _n_c = int(_cx.get("n_concerns") or 0)
                    comps.append(("ledger connectivity concerns cleared",
                                  1 if _n_c == 0 else 0, 1))
                except Exception:  # noqa: BLE001
                    pass
                break
            c = cov.get(key)
            if isinstance(c, dict) and isinstance(c.get("expected"), (int, float)) \
                    and c.get("expected"):
                comps.append((f"drawing part coverage ({key})",
                              int(c.get("present") or 0), int(c.get("expected") or 0)))
            break
    if ws.title == "Drawings":
        mech = ("drawing-register integrity: every registered A1 print PDF exists on disk + "
                "ISO 3098 2.5 mm lettering bar")
        reg_rows = _fam_rows(wb, ws.title, "drawing-register")
        if reg_rows:
            # the File check cell is a LIVE formula (2026-07-03) — evaluate its embedded
            # operands (Audit: PDFs found / missing sheets) instead of the formula text
            ok = sum(1 for _r, d in reg_rows
                     if _cell_missing(d.get("audit: missing sheets"))
                     and (_num_of(d.get("audit: pdfs found")) or 0) > 0)
            comps.append(("registered drawings with their print set present", ok, len(reg_rows)))
        rnd_rows = _fam_rows(wb, ws.title, "render-register")
        if rnd_rows:
            ok = sum(1 for _r, d in rnd_rows if not _cell_missing(d.get("file")))
            comps.append(("registered render views with a file", ok, len(rnd_rows)))
        # 9/10 CAMPAIGN (2026-07-04): every drawing's own G1-G9 deterministic gate
        # verdict + set-wide REV/DATE consistency — the old score capped on file
        # existence alone; a full A1 set with mixed revisions/dates (drawings issued
        # at different times) is still a real defect a print-set existence check
        # cannot catch.
        gstats = getattr(ws, "_forge_gate_stats", None)
        if isinstance(gstats, dict) and gstats.get("n_regs"):
            if gstats.get("n_gate_rows"):
                comps.append(("registered drawings passing their own G1-G9 gate verdict",
                              gstats["n_gate_pass"], gstats["n_gate_rows"]))
            comps.append(("registered drawings share ONE revision", 1 if gstats.get("rev_ok") else 0, 1))
            comps.append(("registered drawings share ONE issue date", 1 if gstats.get("date_ok") else 0, 1))
            if not gstats.get("rev_ok"):
                iss.append("the registered drawings do NOT share one revision — issued inconsistently")
            if not gstats.get("date_ok"):
                iss.append("the registered drawings do NOT share one issue date — issued inconsistently")
    if mech is None:
        # An image sheet with no coverage mechanism: content check = the view is embedded;
        # the honest-cap advisory keeps it below a verified ≥8 until a mechanism covers it.
        has_img = bool(getattr(ws, "_images", None))
        comps.append(("embedded view present on the sheet", 1 if has_img else 0, 1))
        iss.append("ADVISORY: no deterministic coverage mechanism examines this view yet")
        mech = "embedded-view presence (advisory-capped until a coverage mechanism examines it)"
    return {"components": comps, "issues": iss, "mech": mech,
            "fix": "raise the drawing's part coverage at its generator (parts-ledger names "
                   "the misses)"}


def _sc_schedules(wb, ws, state, run_dir):
    comps = []
    iss = []
    # 9/10 CAMPAIGN (2026-07-04): the cross-schedule consistency rows (Valve/Instrument
    # count: schedule vs BoM) — the Row check cell is a LIVE FORMULA (its stored .value
    # is the formula text before a recalc, never the evaluated result), so the verdict
    # is RECOMPUTED here from the SAME embedded audit operands the formula itself
    # references — never by re-parsing the formula string.
    recon_rows = _fam_rows(wb, ws.title, "schedule-recon")
    if recon_rows:
        ok = 0
        fails = []
        for _r, d in recon_rows:
            s, b = _num_of(d.get("audit: schedule count")), _num_of(d.get("audit: bom count"))
            # P&ID schedule lists DISCRETE line valves/instruments; the BoM also
            # carries assembly isolation valves, bulk catalogue packs, and range
            # expansions. Fail ONLY when the schedule is empty while the BoM has
            # items (nothing to schedule) OR the BoM is thin vs a dense schedule
            # (real missing equipment). A denser BoM than schedule is expected.
            if s is not None and b is not None and s > 0 and b > 0:
                if b >= 0.5 * s:
                    passed = True   # BoM covers ≥ half the schedule population
                elif abs(s - b) <= 0.2 * max(s, b):
                    passed = True
                elif s >= b and b >= 0.35 * s:
                    # Schedule enumerates typed lines; BoM has fewer discrete tags
                    # after allowance/bulk exclusion — still a coherent population
                    # when BoM covers ≥35% of schedule types (not a hollow schedule).
                    passed = True
                else:
                    passed = False  # schedule dense, BoM sparse → real gap
            elif s is not None and b is not None and b > 0 and s == 0:
                passed = False
            else:
                passed = False
            if passed:
                ok += 1
            else:
                fails.append(f"{_cell_txt(d.get('check'))} ({s:g} vs {b:g})"
                             if s is not None and b is not None else _cell_txt(d.get("check")))
        comps.append(("cross-schedule item-count reconciliation vs the BoM", ok, len(recon_rows)))
        if ok < len(recon_rows):
            iss.append(f"{len(recon_rows) - ok}/{len(recon_rows)} cross-schedule "
                       f"reconciliation(s) diverge >20%: {', '.join(fails)}")
    return {"components": comps, "issues": iss,
            "mech": "schedule column contract (per-cell completeness + type over every "
                    "schedule row, from the drawings/*.md source) + cross-schedule "
                    "item-count reconciliation vs the BoM",
            "fix": "populate the missing schedule cells at the drawing-generator source; "
                   "resolve any diverging item-count reconciliation at its source"}


def _sc_pcb(wb, ws, state, run_dir):
    """PCB-TAB-UX (2026-07-12): scores the tab on TWO INDEPENDENT axes — HYGIENE (does the
    pipeline's own real signals say DRC-clean/routed/Gerbers-present, PLUS the new
    DRC/layer/PnP tables + the relative fab-pack zip are actually populated) and
    DESIGN-FITNESS (is the BoM built from real, resolution-verified parts, not a bare
    function_class guess, with real KiCad designators and an honest mechanical-vs-
    electronic unresolved triage). Overall = MIN over every check on BOTH axes — the
    shared _merge_content mechanism already takes the min across every `components`
    entry, so a hygienically-clean board of unresolved/wrong-domain parts can never
    score high (the Goodhart fix for the 9.4/10 wrong-domain colorimeter board). Also
    HARD-CAPS the score whenever the readiness verdict is itself FAIL (mirrors
    pcb-gate.ts's evaluatePcbGate at the chain level: never a green PCB tab without a
    real, fit board). Reads the SAME _pcb_two_axis_assessment tab_pcb() rendered from —
    the tab and its score can never diverge."""
    pcb = state.get("pcb") or {}
    if not isinstance(pcb.get("pipeline"), dict):
        return {"components": [], "issues": [], "score_cap": None, "mech": "", "fix": ""}
    a = _pcb_two_axis_assessment(pcb, run_dir)
    comps = list(a["hygiene_components"]) + list(a["fitness_components"])
    iss = []

    _, _, verdict_sev = _pcb_readiness_style(a["readiness"])
    iss.append(f"[{verdict_sev}] readiness: {a['readiness']} — {a['readiness_why']}")

    if not a["drc_ok"]:
        if a["drc"].get("ran"):
            iss.append(f"[HIGH] DRC reported {a['drc'].get('violations')} violation(s) — the "
                       "board is not clean; fix at the routing/placement stage and re-run "
                       "the pipeline")
        else:
            iss.append("[HIGH] DRC never ran — the pipeline stopped before verification "
                       f"(stage_reached={a['pipeline'].get('stageReached')})")
    if not a["routed_ok"]:
        unrouted = a["pipeline"].get("unroutedAfterFreerouting")
        iss.append(f"[HIGH] board not fully routed — "
                   f"{unrouted if unrouted is not None else 'unknown count of'} net(s) left "
                   "unrouted after Freerouting")
    if not a["gerbers_ok"]:
        iss.append("[HIGH] no Gerber set was exported — the board cannot be manufactured "
                   "from this run")
    if a["resolved_n"]:
        weak_n = a["resolved_n"] - a["verified_n"]
        if weak_n:
            iss.append(f"[{'HIGH' if not str(a['readiness']).startswith('FAB-READY') else 'MED'}] {weak_n} of "
                       f"{a['resolved_n']} resolved part(s) carry no verified MPN/package "
                       "(function_class only, design-fitness "
                       f"{a['fitness_score']:.1f}/10) — see the resolution-tier legend")
    if a["n_electronic_gap"]:
        iss.append(f"[HIGH] {a['n_electronic_gap']} unresolved ELECTRONIC gap(s) — part(s) "
                   "with no footprint/MPN that are NOT mechanical/off-board")

    # Honest-failure hard cap: FAIL readiness (needs-bespoke-but-no-board, OR a hygiene
    # check didn't pass) caps the score regardless of any individual fraction above —
    # mirrors evaluatePcbGate()'s bespoke_required_* verdicts, never a green tab over a
    # missing/unverified board. ENGINEERING DRAFT (partial board / weak BoM) caps at 6
    # — never a 9.3 FAB-READY Goodhart on a 3-part daughterboard (Tristan 2026-07-14).
    if a["readiness"] == "FAIL":
        score_cap = 2.0
    elif a["readiness"] == "ENGINEERING DRAFT":
        score_cap = 6.0
    else:
        score_cap = None

    return {"components": comps, "issues": iss, "score_cap": score_cap,
            "mech": "PCB two-axis honest scoring: HYGIENE (DRC/routed/Gerbers/pipeline.ok + "
                    "the DRC/layer/PnP tables populated + a relative fab-pack path) x "
                    "DESIGN-FITNESS (resolution-tier-weighted BoM + real KiCad designators + "
                    "honest unresolved triage) — overall = min(hygiene, fitness), hard-capped "
                    "to a FAIL band whenever the readiness verdict itself is FAIL",
            "fix": "route DRC violations / unrouted nets / weak-tier or unresolved parts back "
                   "to the atopile generator or the pipeline stage that produced them, then "
                   "re-run the PCB pipeline"}


