    ("Financial model", _sc_financial),
    ("Connection trace", _sc_connection),
    ("Part names", _sc_partnames),
    ("Glossary", _sc_glossary),
    ("Holds & exclusions", _sc_holds),
    (QUESTIONS_SHEET, _sc_questions),
    ("PCB", _sc_pcb),
    ("Sense-check", _sc_benchmark),
